INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e5da6a7-a8c5-4b99-8894-57505dac8bfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur?', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b757bae8a9c93cd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0d8ba43-a96a-433a-b028-9983d86d301a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet?', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9735dcac8451c1a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69365e79-897a-415b-b084-eb6ab2a4d56b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model?', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '8b77cffd91719a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7bbb680-c5e0-402f-9727-c4357a9af244', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes?', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8041e675bc054421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1a82b9e-db95-436c-9613-8e18d7bc5a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network?', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e296a47a40002234_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f24a3a96-06ad-45f8-8a45-1f7d896ea10b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device?', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a5c5193818cb4a2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d79c8ee3-66f3-434a-ace0-fd8cefc345e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed?', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6918f600c9f3177c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eca5e13-5ff6-482a-aef4-c0f2a55be66f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device?', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec4687053fca239c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e1604d1-c704-4928-b97a-db32ec5a8501', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device?', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '083684daef023c7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('052d6d48-f7b0-4b53-9266-ea0d94101fd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos?', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '87265c0f49b499f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3924495-0c0f-483c-90c2-add11172276b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI?', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4383ac45ee4293ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f272197f-8375-4568-a31b-e784696fbc45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI?', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '248ec996a716c835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715cca9d-7448-46cb-97aa-2fb2ca2b4a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device?', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ea35ad6638d6a1e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb766458-7b5b-47bd-84e4-f3de247309cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI?', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bd983995fdc565cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db192998-27bd-4962-8cff-0167a1716081', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device?', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3370425ac83bff37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('256a5146-0e01-4f4a-a8c3-d4a9914b9134', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device?', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3891a51c596f0a74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1080da43-8616-43e9-b810-cfef960014d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos?', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '494255bca8449819_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25fd0d2f-54a7-4870-82df-69337096a9de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface?', '[{"id": "A", "text": "set ip address 10.221.59.1/24 interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/2 ip 10.221.59.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.221.59.1/24", "is_correct": true}, {"id": "D", "text": "set interface ge-2/1/2 ip address 10.221.59.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '23dad62a7a1b22d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea2aea7d-9d58-471b-bc59-a3bfdf95b96c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos?', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7a0a38b41ffe3abc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bc711d6-7744-46ca-b3a4-f175d555b38c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device?', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9b4f0399c3748ddb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b566dbed-6348-4830-9258-efeae0f97739', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device?', '[{"id": "A", "text": "show interface xe-0/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-0/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-0/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-0/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '566a51fe83e689ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92bda830-a64a-4bf0-ad4a-e20314306395', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS?', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b27c66b56e6d4c3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76089c13-8de7-42a9-851b-f53d17d10885', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device?', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6e25ba6eb653406e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9883a66-71a3-461f-b164-df4d4b23ee9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos?', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c5d8c07e82de87da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('957b6d1a-d4d8-4c00-9226-62e56bfc666b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos?', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2f536f7b059f8bde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81a5992a-9a69-4b58-9f64-f45831acc325', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.52.124.0/24 via next-hop 10.69.160.1 on Junos?', '[{"id": "A", "text": "set ip route 192.182.217.0 255.137.163.0 10.69.160.1", "is_correct": false}, {"id": "B", "text": "set static route 192.52.124.0/24 gateway 10.69.160.1", "is_correct": false}, {"id": "C", "text": "set route 192.52.124.0/24 next-hop 10.69.160.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.52.124.0/24 next-hop 10.69.160.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b0324f2832af8b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('805e4ee3-0638-4ccc-af6f-7b7f299af49f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos?', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1d843aca33e12053_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a95e26d-4056-477c-acb3-6006e7743f00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies?', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'fe185921d4389984_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85f177b3-7d71-4f20-9902-276868bcf18b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos?', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fd1ff974068c5b16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34afc166-fbb7-4242-a399-00ccb85a66b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device?', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1f4f66003ff9146f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b242dc-9b73-4f2e-9ab0-63e78c389896', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 2).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1fa6921ef692510c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d139829d-9496-4a18-880e-02d62278e69e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 2).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a4a0409cc02e7662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9f7578c-d90a-4a88-aa95-0f99cb0e8242', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 2).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c23904855b5875ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc16159c-0c7b-4384-a7b9-d26c64ef8a05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 2).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8a96d03a729b2d1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cca3195b-ef66-469d-8f53-d1d33f1447bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 2).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2ed5cba2cf2829e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fdf0ae9-ad59-4a3b-9a73-9de8c49426f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 2).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e3226574a7ced5e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('333ebdd2-8581-496b-a242-a7c687d9c596', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 2).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5099f69d9e71121a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6191c680-91eb-459c-beb3-338e8fb9226d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 2).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c876582645b6541f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('938adfc4-b75c-4759-bcbf-ec166b9d89d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 2).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'edec8d0b066e24e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c31bc10-926a-4ba4-982d-7c2a3b21e7dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 2).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e4b7c8ea99c5874d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ea20fe-e6b0-46b6-9ab3-d37209810500', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 2).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ec370450cc2862df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b34981f-7ecb-4832-b612-ff3be749c3db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 2).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a9d1e77d1e033f55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('675e4763-68ca-4e18-9d63-dd97db883399', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 2).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5541dafeaca103f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ec0bd6e-f83c-4944-b1de-0b77e7d5436c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 2).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '93cb98150670c1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6de3351c-ad0f-484c-b4cc-7e1c9a4f7a70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 2).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '268d35596b1bdf4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05429b9c-111e-47ec-8eb3-2f21f5c1de7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 2).', '[{"id": "A", "text": "set system name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cd039cd4923daa23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b087c431-3e8c-4d0b-ae72-d51afc76718a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 2).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd52c0688a8666b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('402b6f82-c5c1-4100-bc43-0e6c46086eb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 2).', '[{"id": "A", "text": "set interface ge-1/0/2 ip address 10.122.160.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.122.160.5/24 interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/2 unit 0 family inet address 10.122.160.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/0/2 ip 10.122.160.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '49323b4c06dad503_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f013783-0c50-415a-b4a8-4b28fcbf6bbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 2).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4d17a7031183d1f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87cda54e-dad2-4856-bef0-fd897d113abd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 2).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '70948ac9aa9198de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa2fb8e9-0d0a-4249-91f7-1b87e623fbf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 2).', '[{"id": "A", "text": "watch interface ge-0/1/3", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/3", "is_correct": false}, {"id": "C", "text": "show interface ge-0/1/3 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b456f5f136bf40c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89a5ee10-d513-487a-82af-638112f67934', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 2).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '845f9428243a93b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e61dd47d-6fc5-4ea7-8ddd-c2d5d6fe61d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 2).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c68e695579fe5041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da934248-e5e3-4955-8d5d-e149576c9522', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 2).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a651998bc63e968c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c9acbce-cc19-403b-a550-58eda50aa6ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 2).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f0f76a395de799a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6138b5d0-20d1-43fd-a560-0dc00ffd1792', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.26.238.0/24 via next-hop 10.104.37.254 on Junos (variant 2).', '[{"id": "A", "text": "set routing-options static route 192.26.238.0/24 next-hop 10.104.37.254", "is_correct": true}, {"id": "B", "text": "set static route 192.26.238.0/24 gateway 10.104.37.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.236.83.0 255.252.100.0 10.104.37.254", "is_correct": false}, {"id": "D", "text": "set route 192.26.238.0/24 next-hop 10.104.37.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '236919cab797ef08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('342039b2-334a-4645-b1d7-f8c40df10696', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 2).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '140ed70956ef113b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7d92c7e-e2a7-4946-bb8e-8e0078b1030c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 2).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '79cc4a8a1a8a2b21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a713c80c-f4ec-4a56-a8e7-9cfe31d51766', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 2).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3357c62686b6854c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('804c17c3-7ff9-4b3f-a4fb-991373b8c1e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 2).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '061ea22ad7c4bd7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31128694-6fe5-409b-8b53-dd2e1a814b9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 3).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3f9f3647b5b820b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee50298-0d54-4dd4-ba77-2302d33852ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 3).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '402717814cbfc399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13275bbc-bcee-4d7e-8335-3cd37552d5d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 3).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4beb8719b1883bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4411d73-7ec0-4040-9b41-d9088f611b63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 3).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5889fe50883dc34c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1071f061-98b9-440c-8487-7760950c3eac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 3).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cba7398b86bbebc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de9c9caa-b4fb-46ae-abd9-4013598f5169', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 3).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'febca4ed2d715260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fba526f-faa9-4518-a9f4-ad61e4849226', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 3).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '253f22a78377cc03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae12a381-9c7a-4d1c-a635-269b3e69d3e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 3).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fd725ea004e8faa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf5045ae-fa26-4c39-964d-23f93395796a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 3).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e117292d72134cc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bd42727-6b06-4814-9df4-59445b33c6c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 3).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '88700605f43a6b0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2362339-b4c1-4e8e-81cc-98215e3b3fc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 3).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '359131bda27b6e93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb564b39-b2e7-4de1-90c7-de31457fdb5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 3).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '336610aa242a43cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d9d4f5e-fa8f-4f39-aea2-e49bc94c6938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 3).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ec5b9cc564afcf2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f719c90-6746-4ca9-944c-2a9c0f4f75c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 3).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9f0fe7045c2a98f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('078badeb-8076-4a9f-86b4-ee737184cc61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 3).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32e049b12a9e700c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d30372c3-c85f-4689-8d77-339fd90356ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 3).', '[{"id": "A", "text": "set hostname R4", "is_correct": false}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set router-name R4", "is_correct": false}, {"id": "D", "text": "set system host-name R4", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '509d923e0db67971_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b62586d-acc1-4bee-88e6-57c23907578b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 3).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '66ea1ca59d5ac770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42d4a775-7986-4630-9dc8-e0929bc6ed38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 3).', '[{"id": "A", "text": "set ip address 10.236.8.5/24 interface ge-2/0/1", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/0/1 ip 10.236.8.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.236.8.5/24", "is_correct": true}, {"id": "D", "text": "set interface ge-2/0/1 ip address 10.236.8.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b3f1149823e28370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab0a1909-c134-4154-94ce-5eafd165b8c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 3).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '91f4a05af6ee0e75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f8f0eef-01ce-435c-9385-93406e09f0c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 3).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7430783d022795f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c69f28-c01a-45f3-9d4a-6127964d1a57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 3).', '[{"id": "A", "text": "watch interface xe-1/0/1", "is_correct": false}, {"id": "B", "text": "tail interface xe-1/0/1", "is_correct": false}, {"id": "C", "text": "show interface xe-1/0/1 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface xe-1/0/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7af31a76d5a83281_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b8e115-fba6-4681-93e0-ac94150cd595', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 3).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f1a80a0157840fe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f8dc023-3bd6-4e57-9ca7-0ade9b107423', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 3).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '18cbd5530fb21ad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71306cc4-b083-4cea-990d-60f4288aaca0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 3).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4dea8b449d24564c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2435a9f8-8263-43e3-9c4b-faf7651a1f85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 3).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2a996cf7bbdcb811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f714251-57b3-4ab8-9fab-94067883e62c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.143.115.0/24 via next-hop 10.130.78.1 on Junos (variant 3).', '[{"id": "A", "text": "set route 192.143.115.0/24 next-hop 10.130.78.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.199.66.0 255.49.41.0 10.130.78.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.143.115.0/24 next-hop 10.130.78.1", "is_correct": true}, {"id": "D", "text": "set static route 192.143.115.0/24 gateway 10.130.78.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e1b1fb49c5ada3fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5fc3cb-6593-472a-a0c8-3dc27988d3fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 3).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '867d4611f8ff92ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13b43e03-5f28-4e9c-a53a-207d4f0f48b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 3).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5012f39697276668_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1d3d93f-7ad6-43d8-a4f8-93021b514305', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 3).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b3553e9bb7f3a96e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f33d994e-182e-4671-b110-5a8aa7b0e21f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 3).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f7a1e5b841e3934b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eb81930-482b-4f85-87d7-e0d4a22eb203', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 4).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'cd1d25c55c76ff45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c98846c-27ee-4fe5-a12c-ad655dcd1d9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 4).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f441cebb419c8b1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c19baee-3a49-4afe-b7af-76ff63033841', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 4).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ab677b0f6d70ba31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ca1f3f-54cf-44b6-9d53-480b3cf3134c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 4).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '3bff5f1bd16a8830_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b0c32e0-b490-4659-b21d-9b3627b9f4ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 4).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '966df94076b3e40c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13457a3-d2e0-41de-910b-9876788efdcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 4).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '87e83fa94318636c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f07849cd-22ff-452d-bfe6-8b62436d0d7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 4).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0f15b1bab38ac633_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9bf8da2-e961-4ea8-9011-70419da8fa98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 4).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd6585b78c892b408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02ce1777-0031-4b6a-ab51-9c4de311ebd3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 4).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8cb616d4f6284adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('951e4d55-ef6f-4374-96b2-6b104591323c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 4).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '325f222f3e8ef552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0d62319-4766-4a78-b13c-287e3ae84f22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 4).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f7c52eb2b04b65a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba94d8c-f7e5-4b17-b0b3-61b631daa7f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 4).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8052915a6ed9afa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b2c2fd4-ae06-47c5-9393-364222ef7b3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 4).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fd3cb21bdc862fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e328bec2-0dc1-4d67-b379-2b211d795602', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 4).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a1ad008b9cbf0bdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('767761a5-2748-45f3-9882-cc20cfb25ec8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 4).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '241e8b109c463da8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e8da1e-e578-4892-8a6f-69ea9f7f74fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 4).', '[{"id": "A", "text": "set router-name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set system name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9ab75767de8fcde9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('527ec08a-8d42-481d-a0e1-36a206e27319', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 4).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd9cd3fcc03770364_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f6d5fbd-84fa-4fb8-bb86-2c0a398f869b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 4).', '[{"id": "A", "text": "set interfaces ge-1/0/3 unit 0 family inet address 10.51.67.1/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.51.67.1/24 interface ge-1/0/3", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/3 ip address 10.51.67.1/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-1/0/3 ip 10.51.67.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7c835cfd0d637900_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('842fa87f-e01c-4a48-aefd-9e9fdf64f42c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 4).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3303571384a2461f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed2619a-748e-4d29-a33b-4f01b6d7ee03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 4).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '395b0148ddca6b4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('301f0027-2ec3-47b9-a743-9d4d568e0db1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 4).', '[{"id": "A", "text": "tail interface xe-0/1/0", "is_correct": false}, {"id": "B", "text": "show interface xe-0/1/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-0/1/0", "is_correct": true}, {"id": "D", "text": "watch interface xe-0/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ae287f308abf76bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdb30355-dcd6-4db5-a997-f574f308ea2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 4).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c6556013299711a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4cff8f0-3354-469b-b283-2a5053733c6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 4).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3e480bd5a021d00a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3671ae61-c7c3-4ae8-9884-2fcd5f897655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 4).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '28086f573e0cdd1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d4be5c7-adec-4ad2-80ad-ba2948ce5959', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 4).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e2a1f773df5ed110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e6100e0-782c-4848-a8dc-05029226b633', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.2.20.0/24 via next-hop 10.56.252.5 on Junos (variant 4).', '[{"id": "A", "text": "set ip route 192.68.58.0 255.42.44.0 10.56.252.5", "is_correct": false}, {"id": "B", "text": "set static route 192.2.20.0/24 gateway 10.56.252.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.2.20.0/24 next-hop 10.56.252.5", "is_correct": true}, {"id": "D", "text": "set route 192.2.20.0/24 next-hop 10.56.252.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cbd1abf7815d7f61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f122aef-45c4-41ae-8dd5-a9c513726a22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 4).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ffdee47edf811409_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38a1a1cd-7ef4-4ac1-9aa3-5c63d040fd45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 4).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5eba56171b7284b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c53550-5961-498e-a54c-fe6d6437a686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 4).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c5a7db283d8d0106_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a193cdb6-e8f7-4c3d-b362-fd6d0af2ff55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 4).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3d328626a2efe3af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de763bae-78f1-4c1c-9f42-b350dac8e7fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 5).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b30a49bd1307392e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efe14f1c-5a95-4ee5-bc1a-0c6333d69f47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 5).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6406bbca44fc8057_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b16078-d556-466b-b24b-17b7f07801f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 5).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b0c40e69ea21ca99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('048079f7-02b2-48f6-996b-db8c51b7e8e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 5).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a5fad9fd931d0535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d64661c6-3ef6-4583-81bf-a2b8ca39c578', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 5).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2577474771ea3881_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3347c402-b670-48c8-9ba1-72e4c3383f19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 5).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a99578f3ee9a0241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1a22d7a-329d-49a2-a2d6-41b103fa07ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 5).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fc6c35a4f7552771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf760267-f889-4784-979a-9021421c0307', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 5).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '754c3788d14e6f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b115c94d-4e50-48df-8d13-2a56b2c4fc7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 5).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a8fb1867d12c5d9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec06ce4d-3c5a-4455-b32c-afe99f848f38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 5).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ddc1fed4012ee701_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f20fbb4-c958-48cb-a641-e3d8c83293c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 5).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '38f4de618c57e724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b917683a-ff0a-4b78-9602-a7078649c3f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 5).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1ac0f28ae586eed8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b75d7b1-63a5-45c4-953b-76e5d069c4da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 5).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '91bd73057bd9f319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76c7e346-d583-4708-aa18-44e5ba1e69c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 5).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '42534e2433fa545d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93daa6fc-fe77-41f5-b570-c69c3f9b04b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 5).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd596ab11a759e7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bae9d580-bcde-47d0-b61a-0b274c7b042c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 5).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cbe0880daffd91b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47ff5404-093b-4566-8ad6-315d25dd3425', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 5).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc98c998fbefeba1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0830a0f4-bd3f-4e07-af18-ab602218f936', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 5).', '[{"id": "A", "text": "set interfaces xe-2/0/3 unit 0 family inet address 10.47.33.5/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-2/0/3 ip 10.47.33.5/24", "is_correct": false}, {"id": "C", "text": "set interface xe-2/0/3 ip address 10.47.33.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.47.33.5/24 interface xe-2/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'dc9ed580c7609bc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82a48349-550a-4f8d-a572-f3658ea0e270', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 5).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b09581d95cf0211_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aab909c-6b69-4416-ade0-e53f51ace84d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 5).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fbc9a0fe9d8099fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80049a0a-2089-4999-addb-8d2f932376f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 5).', '[{"id": "A", "text": "tail interface ge-3/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2c83ec24d8e443b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a4f79c1-1f4a-4a03-b478-f82a79d3b656', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 5).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'db4d5cce83ac3d50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f0890a5-657f-4fee-a575-5baf8f185fa5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 5).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2e403fd58457821a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa4070bb-f487-4cd8-8f6b-26a8a086a3d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 5).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '758812db07e0f15a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05b5aba-14d2-41ad-8c6a-3abc559d6f97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 5).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5e1855f45f62a00c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76c8c219-1484-4c78-b592-09a16308bd53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.149.244.0/24 via next-hop 10.116.165.254 on Junos (variant 5).', '[{"id": "A", "text": "set route 192.149.244.0/24 next-hop 10.116.165.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.171.245.0 255.175.180.0 10.116.165.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.149.244.0/24 next-hop 10.116.165.254", "is_correct": true}, {"id": "D", "text": "set static route 192.149.244.0/24 gateway 10.116.165.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '59f68f0619da4e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a8e18a-0b0c-4213-92ae-471c4457512c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 5).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'bdeb40cf1472d480_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7984084c-4921-4ef0-87d3-7d03a14799bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 5).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6703e3e1f6be8e11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68c94379-3555-43a3-bde6-b7fcd6c2be58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 5).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7bd10387e215fbbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59c464e5-1824-423f-bd7a-67a9922e9869', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 5).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd94806a15a31ea0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f2e3403-c292-484b-a46c-1cee6d74b9f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 6).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '48b9f373d99f388f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3c8fbb7-4dea-47de-841f-420219a05493', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 6).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd6d68ab0d7baca75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e78d7bf5-948a-43f2-a6c2-3e3603d29dcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 6).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '422285da0efa9980_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22c7823a-1265-478b-8f95-5b34bba8c520', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 6).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ba72272da6bddbf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93d49cae-f47d-4e7b-8c97-dca729cbc041', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 6).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b9b0f2484b2821b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266c617b-a45a-4f50-bf27-c60f0010c4f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 6).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5ce42ba9113d00b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68b7916e-7a46-496d-9522-3dfdeb841aaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 6).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3ec29fc935213a58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d855f0a1-abb7-4eb2-942f-b4ce94870931', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 6).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f5a9e471891d6e6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ff786d-2c0a-421d-accb-e5c8f0085cc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 6).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5bccc5e59eb10886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1a9aebf-3a62-42e5-b720-8e1a657dd336', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 6).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1e139637ff42d0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7af8dadb-d4bc-41f6-b42f-eeb530dcc5af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 6).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5a430a65ec63d59f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c89c179-d4f3-4d9e-aaf2-39dac2621abf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 6).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f3b666498af249b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94edd14e-f2d3-456a-94d4-fa8faa42b30d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 6).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a2d36e7db1b1ce24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da8b7640-e96f-47cb-b9da-0bc894303fad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 6).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5521c46dc252b91c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('686feb2a-c95f-4ff1-b89b-089b31391810', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 6).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '559f57d77be00a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c20e127-d684-4efa-8cf7-fd52418ad33c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 6).', '[{"id": "A", "text": "set system name R7", "is_correct": false}, {"id": "B", "text": "set system host-name R7", "is_correct": true}, {"id": "C", "text": "set router-name R7", "is_correct": false}, {"id": "D", "text": "set hostname R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '604aa891d816404b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f61d9f23-e338-4b02-ba23-7742f8c8f95c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 6).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9ce4a6be6f2e4f21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('165721e4-d12d-4a7e-8ef4-342b5deb18fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 6).', '[{"id": "A", "text": "set interfaces ge-1/1/1 unit 0 family inet address 10.188.249.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-1/1/1 ip 10.188.249.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-1/1/1 ip address 10.188.249.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.188.249.1/24 interface ge-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '967c639969e059e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38f2d5c7-906f-4e50-b945-ab31f27be336', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 6).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c15ec04d86de119c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e85e4602-c7df-4ad2-8457-d59b141378fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 6).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '21b91ed2866b4a0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8af90c02-5c74-423e-b150-0d7595460bad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 6).', '[{"id": "A", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "B", "text": "watch interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "show interface et-0/1/1 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7f8bbb215ef65d29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9952a74-dbdd-49fc-a4b9-9cd8fd095734', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 6).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '162e48478fcc30b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea5037f-5401-411a-9e79-9efa51ea1cb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 6).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bf3bd4779a7fa3d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c4b63d-f53c-45ca-86f5-3df4b491f8f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 6).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7fe7140066ca062f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a629152d-3cce-4ab0-bee2-e867cd7f866b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 6).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c8f4181cdcdb110a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47c6a5d6-69b4-4c84-a5d9-761623d86405', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.9.225.0/24 via next-hop 10.249.59.5 on Junos (variant 6).', '[{"id": "A", "text": "set routing-options static route 192.9.225.0/24 next-hop 10.249.59.5", "is_correct": true}, {"id": "B", "text": "set route 192.9.225.0/24 next-hop 10.249.59.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.16.204.0 255.83.113.0 10.249.59.5", "is_correct": false}, {"id": "D", "text": "set static route 192.9.225.0/24 gateway 10.249.59.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '43db14840fb697cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289b00fa-15e9-4c7c-b6a4-d48678de38f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 6).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c490069d0955997f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e93d91e-a0a4-43d0-a091-2a644de6c771', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 6).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '918f3c0b61d5e58f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7619a53a-48cf-4950-a0b1-0c1df816cbb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 6).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f85ef6887a68a7fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b6403dd-1c06-4197-b835-c563a7d28f10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 6).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '36c7817a48f6f8c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dbdbfbd-60ff-431f-bd1c-ffcb962d4608', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 7).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '37737d25975d8bf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55d6fe9a-b222-4872-87b6-125260901f88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 7).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'eb9b5f7a4dc59ae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a518a79f-7568-4ecf-be5d-5a33d6976dcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 7).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '0b21c48770a5f02f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42881023-21c0-4651-bf55-8c07605603c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 7).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a4ba7bbf70866426_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b603a6af-a513-481e-9f98-7f6632fc003c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 7).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'a4017e8399eb4620_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23bdbaba-ddfd-40e1-81d7-d78dd18a513a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 7).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3296775eea07aae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5841354-47eb-4abb-8925-c49b6a631b57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 7).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f359ea4e2e7df0fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a3a77ce-6d51-432d-81c3-a60220f57041', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 7).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b7fcc39f575ffdbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b20ad42-42e5-4efd-a28c-c24f753bccea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 7).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '79d9aeec8d916149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad411907-de44-4e37-b2a8-9a0bca93cd70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 7).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b81ce8a0616d527e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4682883e-b1bd-469c-bf8f-c9eb9a533123', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 7).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aa6b65b717cb7ad9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bbac831-1c52-4228-8c42-b5bde6df2032', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 7).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bc38f1506dbbfd61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e91e9242-f0de-45f0-a656-e2ca0c377b65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 7).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'df224c3ed40cdab1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('921b45f2-ee65-406e-9e84-8ecc5fcd8aac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 7).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '524e5d4206329ceb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a34f205-98bb-46f1-b8a7-f3b69c5d7583', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 7).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8923efed75c03722_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87a3d050-35c3-4362-81b4-9249bc7d991c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 7).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set system name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bc76aed2890e0644_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8fd53fb-7d3a-4ad0-bd55-2f421d0d180d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 7).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cd931aa617472bab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f41931-be7a-4437-b349-671b000f26f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 7).', '[{"id": "A", "text": "configure interface et-0/1/3 ip 10.103.191.5/24", "is_correct": false}, {"id": "B", "text": "set interface et-0/1/3 ip address 10.103.191.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.103.191.5/24 interface et-0/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces et-0/1/3 unit 0 family inet address 10.103.191.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '47a2519758cd192c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('862155be-3517-42dd-aef9-79c6bc2a7724', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 7).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '38949f48fd943101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f508458-5d85-4a00-bfce-f9ad24db99bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 7).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '64cd3afe7b68d8fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b75c64c-50bb-4a7a-a540-05f8e7482a45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 7).', '[{"id": "A", "text": "monitor interface xe-3/1/2", "is_correct": true}, {"id": "B", "text": "show interface xe-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-3/1/2", "is_correct": false}, {"id": "D", "text": "watch interface xe-3/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '772b854f8cd38bdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6605d855-ef19-40fd-a570-7b0c4b7f0742', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 7).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b60daf423f23db82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19070b87-571d-4ea6-ae43-a85bbd73e1b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 7).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3538b462378ec8d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b6222d6-b255-492f-9bc8-b4daff891af8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 7).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'cdfa20ef25324ac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4bf2149-fc1b-4297-a9eb-7aa7e4c8b20c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 7).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4675244513450704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a75c8ae9-1a99-4bf8-8ddb-1459724dc9e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.22.103.0/24 via next-hop 10.181.249.1 on Junos (variant 7).', '[{"id": "A", "text": "set ip route 192.3.2.0 255.214.102.0 10.181.249.1", "is_correct": false}, {"id": "B", "text": "set route 192.22.103.0/24 next-hop 10.181.249.1", "is_correct": false}, {"id": "C", "text": "set static route 192.22.103.0/24 gateway 10.181.249.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.22.103.0/24 next-hop 10.181.249.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '44606875104dbc93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1f33b85-1c7c-4241-968a-5b2b700633d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 7).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8f0a3243ade0614c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9e22845-be31-4576-8213-770a9d0f6799', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 7).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f240c8b0b89a9575_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec66f58-f782-470d-b1e4-c7a8a89ebade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 7).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0116691a096ad425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61a6f370-54bc-46f0-8a27-b39cccc40dd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 7).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '04d2681d9b92aca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0356e003-cecf-453f-b78f-1de3a7075403', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 8).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ec78b348afbb6f0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06d28a43-9301-423a-8c25-49ddbf54a427', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 8).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd59d21cfe354d747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f4c855f-7ccf-4023-be26-6347b2625ee9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 8).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e71e1fd689477811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00ed9673-3974-4881-b65a-db03a49535f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 8).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '3123f9276fcd22c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee6dfeb-4ef3-4c93-8d24-a2c9066c8652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 8).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '091257a20130c6bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d293d6b6-441a-49e7-bde5-3687b6d34b8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 8).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '596380f492b70749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6efdebc6-74be-4cdd-bd16-af0d1183a068', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 8).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f44a52cffa79309b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012a5b64-45ce-4e21-aeee-a43c1687ec80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 8).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ca6aad5d8cf8ab60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51361c12-4561-4b17-b527-ad3d659e4eee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 8).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e8e157f0e593f1db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a89f364-27e4-409e-a3d7-3f49b659d977', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 8).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f97110d233681c8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4ba3f90-9c3b-4d4c-a992-9072a0c8600c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 8).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '190eb080e7295577_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('832867da-c61d-4f84-beee-5b86c08c6c4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 8).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a7647f5ab1508465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80381386-4a47-4702-bb33-58612db2c486', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 8).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b57be4eaeec69b0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73dfb5e6-b275-4978-8e0d-6dcdef080bdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 8).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '37adbdc1d6fffd71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34a4709c-4ffd-4261-8384-a4d7e55f3ce6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 8).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6eacaf2e11626940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42891bd8-209e-4849-9629-1f595883c68d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 8).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f19f3fd8257e376d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12aef4b3-776b-4b1a-97c3-bd33ab6adf5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 8).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b96dd774c4c9dc38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73132f4-24ac-4edb-97da-00e2e30c1e4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 8).', '[{"id": "A", "text": "set interfaces xe-2/0/2 unit 0 family inet address 10.229.50.1/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-2/0/2 ip 10.229.50.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.229.50.1/24 interface xe-2/0/2", "is_correct": false}, {"id": "D", "text": "set interface xe-2/0/2 ip address 10.229.50.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1d2f1f7b832566d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44df105-c8f5-4e41-9f70-dc42c356b15e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 8).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '94126f83b162165a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08fba83e-0c43-4446-8c13-991e24945d32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 8).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'deff4095a19dc33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47c8727a-4881-4075-bfe0-a7a01418a9aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 8).', '[{"id": "A", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "C", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '616b9816f9c3fd3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01780f45-49d3-4876-b70a-84f37dce0e04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 8).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c6a89f7a827acd75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fffbe6b-c5f4-433b-8d87-c5184697a109', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 8).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4512008e81978da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb3f3ccb-7dfc-4bce-9c53-0bff042301d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 8).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '513f408b2b8edc11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60679f02-5c6a-4696-8952-f3d5c3ff98c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 8).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '950c4618f77703bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea27ea52-f0ad-4593-9c62-0a54a673ab68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.133.168.0/24 via next-hop 10.154.48.1 on Junos (variant 8).', '[{"id": "A", "text": "set route 192.133.168.0/24 next-hop 10.154.48.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.130.90.0 255.219.99.0 10.154.48.1", "is_correct": false}, {"id": "C", "text": "set static route 192.133.168.0/24 gateway 10.154.48.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.133.168.0/24 next-hop 10.154.48.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4ccd0da825e1e43e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4ba9d54-c452-4d37-87d5-1b1771824204', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 8).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '6c42ec7755995643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8304aadd-6bf0-49bf-b995-ffbd3e348ea3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 8).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e61aa357e500944d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887a8521-537f-4d44-9d86-9a79736226cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 8).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '48ec6caac9c351b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3351d117-6743-4e15-845f-6e1a1336f699', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 8).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '923e1504fd4222f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b36ec22-86ce-48d8-b7b2-ea0f57b2a5b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 9).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8e40d6348bcc829e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7a1b090-0543-45cf-89e2-53b0ac011a7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 9).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3d3cd50e7d2c727a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20796040-454f-447a-872c-476417063282', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 9).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e75ccd07ad5928a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5d40694-61d3-4602-9905-9e33be2f99c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 9).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7b886a473310654e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('360574ff-5707-47d3-895e-cd22aa259520', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 9).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd4a38a79f87eb9de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d09e151-6933-421a-ad2f-050e16f369f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 9).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b1dc582c5930b7ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e89aed5b-b1ef-47c7-9cf8-c985c2de0931', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 9).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '96dbad256ad10a37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3dcc424-5210-4700-a1c4-6da64f43bbfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 9).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6ba8cd5e70bb23b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59e0060d-a445-4b83-a0bc-2ae710a1d79b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 9).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f2c178593944eb92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1adaea7-a851-4eb1-889b-5b7cbce6710d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 9).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e9dd407a65d9cb03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e83dc27-df3b-43e9-90f6-e6736f072929', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 9).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57a16349aa9f92cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('474e1891-84b8-4b33-9fb2-8d7240907e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 9).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '55ec5f29588038c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de30696-d0a2-4539-839a-658469ac0688', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 9).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7f54cf92a9ca967b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('681ce086-cdbb-4d81-adef-412bd16afb2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 9).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '95af15375a994de7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f74552-30a2-4df8-81e3-4de6dfe3a21c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 9).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6fd8a52aae6ad0aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d96e3f16-69ae-46d0-8b0b-09105e12affd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 9).', '[{"id": "A", "text": "set hostname R7", "is_correct": false}, {"id": "B", "text": "set system name R7", "is_correct": false}, {"id": "C", "text": "set system host-name R7", "is_correct": true}, {"id": "D", "text": "set router-name R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d66f4e1f8bf7b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f1f3c7f-3909-47df-a9e5-d3c28ed4273e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 9).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ef991f6dcec010c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8293e09c-09c9-47d1-b8fa-aa7b4a79f038', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 9).', '[{"id": "A", "text": "set interface ge-1/0/1 ip address 10.26.110.254/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/1 ip 10.26.110.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/1 unit 0 family inet address 10.26.110.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.26.110.254/24 interface ge-1/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c9ddb60c1e71747a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fe61f5c-bf90-4c55-a578-f599f3e68ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 9).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3fd79900edc88868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f2d0638-0a27-4269-8951-d7c64c10e42a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 9).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f53eac5a4da8e4fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7b9331a-8c80-4b49-8032-288537b644ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 9).', '[{"id": "A", "text": "monitor interface xe-0/1/3", "is_correct": true}, {"id": "B", "text": "watch interface xe-0/1/3", "is_correct": false}, {"id": "C", "text": "show interface xe-0/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-0/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '533c642557f5979c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcc6e6f1-63ed-4f6b-b5f4-76d15a0d5b8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 9).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '214e446055a15e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b7f915e-f047-4b0e-bfb3-fc707d08e343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 9).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f044e3f5393c6fdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37116af1-19a1-4cf7-8cc7-742efef65828', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 9).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '247632f39b8dd6c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc48b872-65d5-44a9-a644-3b807b4b01f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 9).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '610b1eab81dba292_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e0bba22-b5c6-487f-ade1-63308788d880', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.105.56.0/24 via next-hop 10.69.139.1 on Junos (variant 9).', '[{"id": "A", "text": "set ip route 192.165.127.0 255.148.123.0 10.69.139.1", "is_correct": false}, {"id": "B", "text": "set route 192.105.56.0/24 next-hop 10.69.139.1", "is_correct": false}, {"id": "C", "text": "set static route 192.105.56.0/24 gateway 10.69.139.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.105.56.0/24 next-hop 10.69.139.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fc7f3740849f6553_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63fdd161-47ad-4a74-bc4c-a5b6f1c6c2d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 9).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a68ab5e1bec96068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f31fe8c5-3f72-4c5e-958b-6f3b7d923821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 9).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1f337f020248ced4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0caf2ed9-d3dc-4f5b-9399-fd5fef2c2f7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 9).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'dfd0dc82dbae45ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04fc67f1-2b55-46c5-a533-80d2fe508362', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 9).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6d6ed59c18370913_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84615a1c-3c9f-4370-9ff9-a444d8c48b0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 10).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '04170f3179d9cea8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb5c6a8a-506a-4cd5-9ad4-5391ebf030eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 10).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '959c02fae753a7b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34456259-8f24-452f-9a49-ce5ec0fcc338', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 10).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ad3d0c5d509ad0b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d85b0368-0324-4a37-a310-0d1e463720f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 10).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c16c250b7a0b7c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69f9f762-1866-4f3c-9176-7d59640342c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 10).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '15dd695d2f5b3b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('744c3327-4d04-40cb-a926-26f33e630f26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 10).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '11be5c514a7b1376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f11eae-7816-4ef3-9cfc-6a4d7fcec18a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 10).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b6083680cf015f25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e184e860-6311-4a1a-9376-f53d318f4104', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 10).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd2c24e9755dbeda3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f489838-8c36-4b6f-97ae-91c3a929e8c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 10).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a361d5b57597c337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b56df8c5-326c-4439-ac31-105e77eec66b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 10).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '367e9180343c4e29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15e0bbf-a9df-4e0a-b7d5-ac5e46589234', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 10).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6d7299f4ccf91c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daefcd8f-696e-4a6e-8e74-691bebf13aaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 10).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2b2198ba05029154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ca05a4d-35da-4b80-906d-343bfd799b23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 10).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f14ad967de447045_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8823eea-d1d6-4cd9-98ac-043c48f86f2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 10).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e68ab5a0bb937054_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8377d02c-8606-4736-ae12-48b870c02219', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 10).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e23c1dfefe18d09c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4ea54ea-a186-48f5-b894-5b2863ba923e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 10).', '[{"id": "A", "text": "set system host-name R3", "is_correct": true}, {"id": "B", "text": "set hostname R3", "is_correct": false}, {"id": "C", "text": "set router-name R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9ac2ed13188185af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce56ae55-b065-4c97-be9f-8141a8688817', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 10).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ca103e0916059765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6778fbfc-7b47-4b56-8a48-ccc0f6509ff6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 10).', '[{"id": "A", "text": "set ip address 10.105.217.254/24 interface et-0/0/0", "is_correct": false}, {"id": "B", "text": "set interfaces et-0/0/0 unit 0 family inet address 10.105.217.254/24", "is_correct": true}, {"id": "C", "text": "configure interface et-0/0/0 ip 10.105.217.254/24", "is_correct": false}, {"id": "D", "text": "set interface et-0/0/0 ip address 10.105.217.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '89fd2558427ef751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('741d05f6-1a99-430e-8b22-3ee42fd82898', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 10).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '26346eb108c37bf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bdf513d-84d7-46b8-8bf7-38b2c0179133', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 10).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '906cb238bb604ca5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28b84d20-f049-4da4-b9a5-f32aba9ad846', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 10).', '[{"id": "A", "text": "tail interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/1/2", "is_correct": true}, {"id": "C", "text": "show interface ge-2/1/2 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2decd610f2ad294d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a54d58bc-fe3e-489d-b9d4-19534b9e2741', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 10).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0008b40df08cc9d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5aa1955-cf76-4c08-a491-ba88057cb372', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 10).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '20e0dddc09dcd737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5c36a0a-bb66-45ca-a045-c0ac3d9a2f59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 10).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd30373a2b53bc4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e866079-16c1-4ea5-a25c-3104ccef0bcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 10).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0e86436ad7a98f5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84fba2e3-9628-4982-bb89-e6f0966ffe47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.30.150.0/24 via next-hop 10.203.152.1 on Junos (variant 10).', '[{"id": "A", "text": "set ip route 192.81.144.0 255.172.227.0 10.203.152.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.30.150.0/24 next-hop 10.203.152.1", "is_correct": true}, {"id": "C", "text": "set static route 192.30.150.0/24 gateway 10.203.152.1", "is_correct": false}, {"id": "D", "text": "set route 192.30.150.0/24 next-hop 10.203.152.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '58d66ede0efd9ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb5b8031-92de-4112-aa97-6ad0397a378d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 10).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c3b3cbf0b87658c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd1f0804-546f-41fd-bd50-aa185d3500b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 10).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da19bdb89ce4aa1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070e768f-73e4-4c17-ad3c-a7d53e171043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 10).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '58de885c7f3e40e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9df48695-521b-4e2a-b94f-1e4dbfd799d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 10).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '941ccdb83c5d4d39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3136c95f-0022-45d6-a1b2-d44af6d1cca3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 11).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6061ab52cfef8a14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99995ccd-6618-4e5f-a161-bd1894747af4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 11).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9780bcef1c0405ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4ec4b7b-0c4d-4f43-bd0b-4718699b67a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 11).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '34ebb8c38d86690d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1dda2f6-7aa6-40e4-b963-3a149252cf22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 11).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ffb8a34022a3262d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc73949f-eca1-4b21-b8c5-339efc1e08b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 11).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cb3f0c995e276185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3948cd27-7aaa-40a5-bce4-cfb6a708b881', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 11).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1bdf91a32e654143_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddf24d3d-9727-4b9c-85d9-69228dd1fec2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 11).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e58cf02ebcf75183_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78c4aaa4-dfd9-416e-b947-229050181207', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 11).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9fee4b165e6b701b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53c240a2-2ab5-44b0-beba-35883dfa6f65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 11).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '19e6c72281ebf1a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c2b3f7f-2e24-4143-8270-eae4eadc607b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 11).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2d17c8252c275d43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72e89180-8973-4754-aab6-0f049e913a07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 11).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ad330ddde858c021_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c832be4-88be-4dad-9320-bb0a7b81df04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 11).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c363a17950e14b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3aab620-e40f-4e38-926e-1d8818fb083f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 11).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1d4961fd1c056fe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dbe0d25-fef6-4bf3-8c47-9a47c496683f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 11).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '31bea975922c2225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('556dfcc9-b3f1-4a88-8557-968e4b868961', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 11).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8c72e76a2b7f8229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('877299ad-d60b-4822-858f-8cd32be62b7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 11).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system name R3", "is_correct": false}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '497cc65e8c34d2c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21813cf1-6339-47e7-a57c-e2394861091a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 11).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '86cc7024660aa264_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aafec141-6251-4ffb-86b4-dfea0b45dc95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 11).', '[{"id": "A", "text": "set ip address 10.60.69.5/24 interface ge-1/1/0", "is_correct": false}, {"id": "B", "text": "set interface ge-1/1/0 ip address 10.60.69.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.60.69.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/1/0 ip 10.60.69.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0a0439f2824abc53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4d14e4f-95b9-4380-8016-377c2e113424', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 11).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '24c4032764f9f358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd5076cc-7219-4430-a708-6506eac25fa2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 11).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '42b1435ba8c312be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b1d4e6-e043-4f7d-bba7-71df8032bfe1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 11).', '[{"id": "A", "text": "monitor interface et-1/1/3", "is_correct": true}, {"id": "B", "text": "watch interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ce2443d86c53ecbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12f82927-c5bb-4cb3-8b49-6a5b2d85fc24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 11).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7c855d2ad0d1e8dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c38870e-8796-427d-85c3-ac2921b2e200', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 11).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '03c3c33dcabac3be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b01b91-f34f-445a-8bf5-5a70aad741a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 11).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '50e3ed3459886726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa53506f-1cfc-431a-b489-d6788fb83961', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 11).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'aa1198df8c04edae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba10fd76-3f0d-4fb3-8a74-b59b50b89bf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.99.166.0/24 via next-hop 10.6.227.5 on Junos (variant 11).', '[{"id": "A", "text": "set ip route 192.134.195.0 255.67.140.0 10.6.227.5", "is_correct": false}, {"id": "B", "text": "set static route 192.99.166.0/24 gateway 10.6.227.5", "is_correct": false}, {"id": "C", "text": "set route 192.99.166.0/24 next-hop 10.6.227.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.99.166.0/24 next-hop 10.6.227.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6d3569595d45473b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a090028-2a56-44db-be5b-48c803400a5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 11).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c7b7b955c59fda0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d503f93-5b7e-4bba-9cea-3b2e278dcd9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 11).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1ecca8914e0995d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa3f2aab-2fd3-40ed-8142-5e9292c496e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 11).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3cccbbb7e0b66922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7caf39bc-5630-44c8-be4a-6d5d97174442', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 11).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '13730165acafb484_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f5072f-6f8f-4992-a108-8d0103584ee1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 12).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b8574606d34f7a65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350ce19f-2d7c-4e99-a47b-e1a8859af1d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 12).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f9903de7c83cff54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('367e4514-522d-43e6-8b79-dab8fadfc560', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 12).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'bf6b6d0bf494ee53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afc26283-4fcb-4f95-87e7-0807cfdbac60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 12).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd557c541117b9838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f3b0d9d-5599-464a-ad0d-43c0bb1bb0e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 12).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '74a67be4d14ba844_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16b77089-5872-4017-af09-040726ceeed1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 12).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ed2a016243b6a877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79f897ad-c96d-4cff-a4f4-2e77e96e79ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 12).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'be4912863a89a3d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e3a6872-f829-46ef-9dcc-b0b1bf73e7b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 12).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '489414d435365c0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2841c623-421e-47ef-b58b-6a71dc1df744', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 12).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4aff42186e55def0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f2693e-8cb8-4c27-b89d-22bb862a93b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 12).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7f367efcacd99bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7248e3dc-e17a-4522-b9ef-0ed8db3b3989', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 12).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '977c96dab006db78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('147c120c-8bb5-47c9-a356-e17058e50293', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 12).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'df1b86c3294d8998_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e5b0802-c43c-4dc4-a0b5-68d093037b71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 12).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4e9078bcc2c1f9a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('137d4fe0-c2b7-43d4-8bc1-07adb358952c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 12).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5cce2cb3fd740321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afdea63a-6a8e-46d0-a6d3-58a66c9d24ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 12).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '218e3bc940b9679c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6a85eff-fb67-41f7-b5cc-cc05d4b77b5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 12).', '[{"id": "A", "text": "set system name R11", "is_correct": false}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set system host-name R11", "is_correct": true}, {"id": "D", "text": "set router-name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'aef8565173c29767_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bf127b1-cccb-434a-b852-0e8ca68b0ceb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 12).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0598087c6fd9f9e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6facfca4-7be7-41ee-8372-951178f8d539', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 12).', '[{"id": "A", "text": "configure interface ge-2/0/2 ip 10.67.177.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/2 unit 0 family inet address 10.67.177.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/2 ip address 10.67.177.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.67.177.254/24 interface ge-2/0/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4ac0c57893ba2226_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61c160a8-6fc9-4f35-9a69-a9ad1e704729', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 12).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6f4418c96cf0a712_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('997c8219-2ee1-41b7-b7bf-091547d68abb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 12).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'aefcd8948437d966_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d953365-8f14-44a6-b4f0-262afc970659', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 12).', '[{"id": "A", "text": "show interface ge-3/1/0 monitor", "is_correct": false}, {"id": "B", "text": "watch interface ge-3/1/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-3/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a49628f9681ff008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a91025b1-e136-4187-b021-5fa4119b3779', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 12).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39b048570202558c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43ffc74c-5162-4a39-906c-14727b9ec47c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 12).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd4068881ec41e0e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('052bf17a-ba58-4626-9fc2-944e79d37921', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 12).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '70cc54245e8479b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('486a899f-910c-4b8a-a33d-71800c296788', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 12).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee379dcb5b90590c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09db9585-70d6-4a71-80c0-8b134b37db14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.18.35.0/24 via next-hop 10.17.48.5 on Junos (variant 12).', '[{"id": "A", "text": "set ip route 192.117.56.0 255.46.236.0 10.17.48.5", "is_correct": false}, {"id": "B", "text": "set static route 192.18.35.0/24 gateway 10.17.48.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.18.35.0/24 next-hop 10.17.48.5", "is_correct": true}, {"id": "D", "text": "set route 192.18.35.0/24 next-hop 10.17.48.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2829f11fd263f792_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f48e87a7-906c-49ce-b593-fed84d72dd0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 12).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b749c7eaf9319a58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebc1220a-30eb-41b6-83d2-91d971f03fff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 12).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f90034e32f948a57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23181940-023f-4f5b-9a77-d9c0e3790aee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 12).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '116213d1c20e8ad1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a3f7a0e-3709-4e2a-8b57-4059bf0a7828', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 12).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a72f45a9167a6401_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb3a35b4-d023-4618-bc25-aac990bd0ffb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 13).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd533debc90c1db04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f389b7ab-b600-4e85-9be5-0d706340c201', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 13).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ca777cae9e64478a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d8abbb-680b-4bd5-af50-6ac60beb1d5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 13).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '2cd3f79fd1c81561_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a857b6-6f86-401a-a928-127cc09a976c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 13).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '962222e60d43afe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6096025-cb62-43a5-84c1-e13c26d095f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 13).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '030f071dd79d7ff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12436702-4185-44aa-a6a5-7802ccb7c36b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 13).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd192ec0d13449a90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0be0f0bf-319a-4371-b961-6da6075f67fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 13).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '05b536b71b6f666d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb7dc087-93c7-456b-a573-eac1e4b2117e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 13).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '03a85ff05697c2e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2196ceb3-b797-45b5-822e-11eb4731a697', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 13).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fda7126141bede9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd07ec74-0e92-4d19-abf0-84939e2fa8f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 13).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '88b5be82672f7a3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c44fbdd-808e-47bc-a011-fbc6bba41ad8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 13).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'eb494525219c1538_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2357374d-4a2d-4995-9e46-cb9f55efb511', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 13).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c401a11d798043d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('116d38fb-105a-423d-acec-651d01ab7f7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 13).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70929ed536d6186a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8383672a-b052-460e-a6bd-dcf01c222862', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 13).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd0a6ad9855e09280_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb4bd29e-a7ef-4eab-8686-9f5b549d6294', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 13).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a8678d48b58ba1b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e118f42-0bb7-4763-bc3d-89818b6d2030', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 13).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a7ce4d85371c2ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3a68326-c139-4cdf-bd6c-6ac89dd72940', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 13).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3eee8e65655e39c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efb638d6-46f4-4d1a-86d0-b0ec14d4deff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 13).', '[{"id": "A", "text": "set ip address 10.17.43.1/24 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.17.43.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/0 ip 10.17.43.1/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/0 ip address 10.17.43.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '77e137ff57f74207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed7e4b5e-4c94-4e79-8b60-86a6bf156913', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 13).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6a230823d7362d3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeb183ce-0188-4811-ab50-c2c32025696e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 13).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3de534da1cfd1b64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf992a85-0960-4062-8465-6bc7c3fd3e02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 13).', '[{"id": "A", "text": "show interface ge-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/1/1", "is_correct": true}, {"id": "C", "text": "watch interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a4c5666e7a9886fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fe4dc51-12ed-4d39-b571-d2867378085c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 13).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '87c2f172ba588ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95b65b06-3ce4-4f75-85a9-f3e38561939d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 13).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '48ea9013a8c4dd86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a13b15a-faa2-43fb-8e41-eff9e18ca51b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 13).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '74fe52005e21975c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6640c7e-33ef-4616-a84d-47fde63aea43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 13).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '88a4249970b899d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a7cc9ad-f8d9-4c35-b525-d888752ccafc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.175.152.0/24 via next-hop 10.237.142.254 on Junos (variant 13).', '[{"id": "A", "text": "set static route 192.175.152.0/24 gateway 10.237.142.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.175.152.0/24 next-hop 10.237.142.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.214.10.0 255.138.134.0 10.237.142.254", "is_correct": false}, {"id": "D", "text": "set route 192.175.152.0/24 next-hop 10.237.142.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b3651b130dea857_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c80124-ec0a-4687-afdb-39dd9707a2e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 13).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '02f45156eb90505a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca25898f-5b86-4508-8834-3d8b0f3f5af9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 13).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6664636cb112f572_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e25a5fc-2ff9-47c0-a4c4-0297ae1a8296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 13).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7e7554667a79937e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e461fa5d-6d8d-4a79-89ee-812a39d1c413', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 13).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '315a9452430e43e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8686df3-33a2-4999-a685-02a8de88d375', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 14).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '35d4e95318798305_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bae3088-c2e6-49bf-b3df-81ba39a4d7b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 14).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '1ed8f94ad859d27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f928093a-bf8e-4d96-baa7-b1f934c2cf9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 14).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b0695a12a67c519f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47581b14-3ef4-453d-965d-096f3a0f4a68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 14).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd932d9ca628db8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c083dad-a4d1-4f10-b455-cf0b0e013dab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 14).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '8b3f46e3016b6b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68ae3de2-7f50-4900-86d5-1b49cb0e0eec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 14).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '09c723838e5716d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7514bb71-c212-4f70-bde6-b42f59631459', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 14).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '063027b465fe1337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d55ab57b-6171-4d97-a2d0-4c6cf0e30a92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 14).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad2a4013c199c412_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4162c78d-bf0e-4b97-b6b2-50a73a023800', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 14).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a10f6cedbdf807a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('201e2a04-6eb6-4a95-bb2e-c1da344face2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 14).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '288debc80293631b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab8b0c5-8c71-4985-b5ca-a5e7a248be1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 14).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '51ddfa71cb555080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54a2e732-4bc0-4170-a2f3-5f39d50a0fe5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 14).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'adf9efa250b469d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79ca4ea6-9127-48fd-960d-33104d4c1ec7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 14).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '878ad259a7a1e8f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbbb1a9f-3f6d-488d-8ec3-7c0d0a7eb644', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 14).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1dad5ba70574950e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('615384bf-ea72-4606-9d58-3a180ac7df4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 14).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9255fffcb056729c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffadc779-47bb-4c6a-9757-243bc1c166e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 14).', '[{"id": "A", "text": "set system host-name R2", "is_correct": true}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set router-name R2", "is_correct": false}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7e07c5f3bf9003aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66f3b049-f063-4154-b6e5-46978b6dd6a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 14).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9827891fb3db59e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f84051-778d-41d4-82e9-33129c598ce2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 14).', '[{"id": "A", "text": "set ip address 10.180.204.1/24 interface et-1/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/3 unit 0 family inet address 10.180.204.1/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/1/3 ip address 10.180.204.1/24", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/3 ip 10.180.204.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ccc064fb97431f4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02cc0afb-44d5-4a14-ace2-4c0858484cac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 14).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6fd274a5113df2eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('260d8924-ce23-4528-9033-9f8c7fd170b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 14).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd5225bee83d22991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cda63d2-e402-4761-93f1-f3ab96644da9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 14).', '[{"id": "A", "text": "monitor interface ge-0/1/1", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/1/1", "is_correct": false}, {"id": "C", "text": "show interface ge-0/1/1 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd29a9efa255c1b12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f22efdc-b715-4309-9d98-e117039f7be2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 14).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '31c668521433f25d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e993d955-5797-49e3-8e73-5b257260c8d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 14).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '28315ed00db6d394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcd821ee-30c0-4334-a666-9aaa44c1f0a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 14).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fc29fc7fd2579027_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b910cb9-d1a6-4756-927f-f370bee77ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 14).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2d1d7f27f6625445_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b14e8c54-e081-4841-bd70-5cb74ef3a73b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.226.0/24 via next-hop 10.61.1.5 on Junos (variant 14).', '[{"id": "A", "text": "set static route 192.21.226.0/24 gateway 10.61.1.5", "is_correct": false}, {"id": "B", "text": "set route 192.21.226.0/24 next-hop 10.61.1.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.21.226.0/24 next-hop 10.61.1.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.38.35.0 255.35.85.0 10.61.1.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '07c894e5888c2668_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b374b9ac-bbeb-4662-80a3-16260a26d93e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 14).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ad9e69318d7fb5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f03af6-bc30-4d7a-8d9e-4a3bbcd5f3d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 14).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a5e76d5eb4048300_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b2f3232-0d1c-4993-970b-b595a1c87602', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 14).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c145d65b628ccaab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00b91fe0-64d5-4175-b388-d9dc0bc5c5e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 14).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f09eea4c0427adcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fc0cac3-4423-4a4a-86be-9f5e056cabb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 15).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd75e9143eb1f2567_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c6347b-1d24-4021-ac2e-a51f710afcd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 15).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '46ac180dcd1a0f65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1276835a-87ce-4497-be2c-5641a0a7f825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 15).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '422da67df0eb6956_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f95d053-fe70-4e5d-9df4-d45ab0127615', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 15).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6b3a7411fd49343a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb437ee0-869d-446b-a136-23274958f923', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 15).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c6c1453fadc8d6da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5ef7075-9cca-4c33-b678-31346b90ad37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 15).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9c5422eee1100468_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58d52523-e214-4910-a252-7eede16292ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 15).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b5fd437fb84c6e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a84c3ce-ccd4-4a6a-b770-d1725fb38717', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 15).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f08776e6cf3b3260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e7fa62-b614-4a9d-b27a-d82318085564', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 15).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a9d389a39e77235_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07b13f4e-6777-49fc-9242-fa397b171933', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 15).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '5c897f679f44fdce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29c488ae-b84b-41ac-8625-3c4df8eced63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 15).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2ab23c1cfb57de26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7a666ee-30aa-49a0-90d0-7f549bd898bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 15).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a79c873110cf810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('583688d8-73da-4f44-9a98-f0a0839132c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 15).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9770efd965ad8763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('593ac735-91e6-4410-9ba5-06b3d72887b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 15).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'def9c663a159b265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21515f1b-4f48-4e0f-8051-c4b50131848a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 15).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3febafad079287fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82eca127-ea48-4b4c-8b7f-de451eccd12c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 15).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system name R3", "is_correct": false}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd75d2e762dfac541_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1936a65-821b-4a29-9641-08dcb5d1375f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 15).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '74d8566745fd85e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6ba300e-7037-4f16-802e-da7a58d2d6ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 15).', '[{"id": "A", "text": "set interface ge-2/0/0 ip address 10.117.223.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/0 unit 0 family inet address 10.117.223.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/0/0 ip 10.117.223.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.117.223.1/24 interface ge-2/0/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f7c92b84eccb9f38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d493196-6071-463e-b31c-f6a24b250014', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 15).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9244f3020f15c368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc273395-42af-49f3-a721-ee24e88641f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 15).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd0e84b4d169ffcde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c624c33b-ddec-454d-a95d-d31e525a9fea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 15).', '[{"id": "A", "text": "show interface et-0/0/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-0/0/1", "is_correct": false}, {"id": "C", "text": "tail interface et-0/0/1", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/0/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '981d9abc5b18b41e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec8bfd98-60c7-47d7-85ef-fff68ed10a50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 15).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3cbc5dc4af8e9ca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914aac2d-9152-4a79-939f-4eb7e28e9adb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 15).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44f5dc098c52f7b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6780961-2427-47cd-8160-77a0470a3c83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 15).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '04e5338ed65d61c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd4d531-4556-4aa7-82f1-8a4f1877a98c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 15).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '48fa04822488db63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5078e36-7bd5-4e8e-b480-27d610382c59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.90.184.0/24 via next-hop 10.241.220.254 on Junos (variant 15).', '[{"id": "A", "text": "set routing-options static route 192.90.184.0/24 next-hop 10.241.220.254", "is_correct": true}, {"id": "B", "text": "set static route 192.90.184.0/24 gateway 10.241.220.254", "is_correct": false}, {"id": "C", "text": "set route 192.90.184.0/24 next-hop 10.241.220.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.197.187.0 255.159.199.0 10.241.220.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3f372623481d9249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec8bf367-6f49-4f88-93d8-274538315c05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 15).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'edd6a286a02937eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c32a700-693c-4896-9cf5-7886d7172bc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 15).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '14193df1be4f68f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe2cc67f-6dad-4a63-a463-f4822fa30587', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 15).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6ffbb9758219d7dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('498b169b-4cbd-445a-8e0d-b06540622f0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 15).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'edff8767be549192_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c40dea56-9015-4e4d-90f4-ed58e49dbe79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 16).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6fb0833f4a3f5cfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f301dfc4-395e-4d69-bd90-f270d5b5e349', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 16).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd3ed4ad35047f3bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e30a11ee-0d23-427a-8025-dc5f8a0b5b06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 16).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c5f6f865c378f462_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d802d9-9e7b-4517-be73-dea8a4fcdd7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 16).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd2c1f5fad9f3c428_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42dd4aba-e2da-460c-9b91-11cb1cd40628', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 16).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cdae82ee56b8e941_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cad70f58-faaf-4f5a-88da-bcf9b53a368f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 16).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4773d28add2de1f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c506e86-1799-44ce-ba3c-09a6b41e4d77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 16).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '98e56bae3010d879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d59e5aaa-c1d5-4242-b2b2-90b315340b49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 16).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cd4dc61e650a4189_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaa50b73-90ed-4d89-b3b6-ed4f222b12f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 16).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41c38fd1f4026c7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80a87441-f390-4f2e-9a81-883da057a98b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 16).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '124f813ace9b6421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53e904e0-3c74-4d03-a9f7-7b8b0dfd7bae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 16).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '84a353a457f9c3c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0f1121c-3441-4064-ac86-b973b18408c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 16).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4ee7c10b55e6cc0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c24023e-354b-4e6c-9088-e3a4b4e81793', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 16).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'adda44e139d52d2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42f9b72d-f677-4534-85b4-444c765c1607', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 16).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fe59f42d8a8e2265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('458e8376-95b9-4e4d-a7d2-200d722ccb4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 16).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '330872c0a2107600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b09a1fcf-5ce9-47ab-a9bf-4ce4e57875fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 16).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set system host-name R6", "is_correct": true}, {"id": "D", "text": "set router-name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '40bbabd3d57d2c49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('217d8915-aba5-4937-ab93-34676979df81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 16).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '96a0e6a7ab368aca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0b879fa-786f-41bd-9950-f1d5d461af27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 16).', '[{"id": "A", "text": "set ip address 10.10.231.5/24 interface xe-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface xe-3/1/2 ip address 10.10.231.5/24", "is_correct": false}, {"id": "C", "text": "configure interface xe-3/1/2 ip 10.10.231.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-3/1/2 unit 0 family inet address 10.10.231.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '93cea1e3394666dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('195fbbd3-9b7f-4c55-90e0-b94991a342c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 16).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4fa6075fe6e52fe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38abdf6f-daee-443f-99e2-fd5a80075979', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 16).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c889482502405c94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09a574a4-247c-441c-8cb4-d125c88c16b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 16).', '[{"id": "A", "text": "monitor interface ge-3/0/3", "is_correct": true}, {"id": "B", "text": "tail interface ge-3/0/3", "is_correct": false}, {"id": "C", "text": "show interface ge-3/0/3 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '98924a2e3e9db6cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af8a0a33-a374-487c-802d-cecbec4d4a88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 16).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f231538e7456bd80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87a81e1e-ec44-411e-b7fa-d367fc8fc87f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 16).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e591adac4e16e811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcb9ab7c-4c22-426d-a19b-fe9c301eff99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 16).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3db9a9c3d9d4def4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa47de45-c929-4ea9-8de2-4aab84196635', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 16).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8be480180d487881_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553facb2-3483-4b8b-a4df-26b19f6ba126', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.123.116.0/24 via next-hop 10.196.145.1 on Junos (variant 16).', '[{"id": "A", "text": "set ip route 192.24.47.0 255.107.75.0 10.196.145.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.123.116.0/24 next-hop 10.196.145.1", "is_correct": true}, {"id": "C", "text": "set route 192.123.116.0/24 next-hop 10.196.145.1", "is_correct": false}, {"id": "D", "text": "set static route 192.123.116.0/24 gateway 10.196.145.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a13b626664478e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3d8b583-5fc4-4c83-9caa-5f83beb64b5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 16).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2e4dd288fbdabf7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b96d5484-8e74-4bc3-a4ea-e60905f30bcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 16).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a234a1607b951064_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac260051-0104-479f-916a-e968c3f6682d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 16).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f02d91368275ac80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9763429a-daaf-4ecb-9efc-ef71a6a466e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 16).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '73ffa758d3540dfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7738f60-d56f-4995-bbd9-4a90ad9be338', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 17).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b478bdd62ef06aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d310cae7-fd79-4d07-9ae5-b3ee06dd7a19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 17).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c2cf6e80b1eb347b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d8a763e-2c44-4345-a9a9-8acbdc9ebeee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 17).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a4be10333abd5729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39c273d1-1682-49d5-9268-c3509cc4b6fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 17).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4d8b682104d6ca86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eac127ff-c1b9-4d6d-a99e-33f92b7b1da4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 17).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c832b0d9ce8b8a6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f572354-441b-4e7d-b6ac-244109fbbac2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 17).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '31a43c8626d3c42d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0216a270-9cdc-43e0-b73a-9eef9dbca585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 17).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '52654f120694faa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28278e84-853e-4c09-aa56-a1e5e021d71f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 17).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c1bdff117ab5e66f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c74fb93-bf76-4589-9a9d-dab914ae07d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 17).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b7b93e4eea08a18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('272f237c-0956-4046-be27-a4a4388fe156', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 17).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fa9c93f4f70e3b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b196863-fd61-41a2-8071-9c5970c3021f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 17).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '285aeee078ac9bfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6dba53e-eb23-45de-b276-b97495238670', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 17).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '742e628521f2cd1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c90e984-5603-4631-b28f-184e45dfe589', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 17).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd2ea12a78879c408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef10f73c-230e-4f4a-a0c1-3b387e8e33c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 17).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f759b38e8058d640_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9052706-64fa-42d1-b60b-950b0293ab6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 17).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f7c421a612db0341_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80004a5d-9a31-4824-b0d9-0af55068f4dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 17).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'aef0629f8f5f7460_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59f04ed2-74a2-45db-b01d-db3a44c4e152', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 17).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '133209e4416bd1d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38788692-b405-43d4-8d89-13c6eaa6d68d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 17).', '[{"id": "A", "text": "set interfaces ge-2/0/0 unit 0 family inet address 10.8.131.5/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.8.131.5/24 interface ge-2/0/0", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/0/0 ip 10.8.131.5/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/0/0 ip address 10.8.131.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2e064c0f4a066587_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd489d6c-0e70-4c24-851d-733c8f8df305', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 17).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a6d30c64b9f192f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5375dc-26c8-4c1a-aa4f-649342f17dca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 17).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '238dfaed06bc8d9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3c18731-d235-4d1e-aa4d-0655cc7b8ef5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 17).', '[{"id": "A", "text": "monitor interface ge-0/0/2", "is_correct": true}, {"id": "B", "text": "show interface ge-0/0/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/2", "is_correct": false}, {"id": "D", "text": "watch interface ge-0/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '333d5a8ab0dac9cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7c2e562-f635-4a91-a6f3-6e7ee67168ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 17).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc02c9d49b6f414c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f64e74f1-2746-4c8b-b149-00386dd3198f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 17).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6e0af297cd489582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20855650-68da-4ba6-a7c9-ea47adb7f155', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 17).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9b4db7da07b7a7d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39d3758d-fd16-41c9-9d86-36fa11eebb89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 17).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6fd3cf5f2953ca25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74bf8074-6381-419e-aa87-87a5e8f89514', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.255.120.0/24 via next-hop 10.27.113.254 on Junos (variant 17).', '[{"id": "A", "text": "set static route 192.255.120.0/24 gateway 10.27.113.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.255.120.0/24 next-hop 10.27.113.254", "is_correct": true}, {"id": "C", "text": "set route 192.255.120.0/24 next-hop 10.27.113.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.185.113.0 255.178.63.0 10.27.113.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5ad69af444179e42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17a00497-c7e4-4119-970b-4bd73d2e3917', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 17).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '595457fa240f0be7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d1dd328-c916-49be-92c3-35a3767366b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 17).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '48a38c1fa7d40aaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db5a66f0-3460-4df7-80d3-f52c449dba65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 17).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'db43081e1c0b26c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc416c8-8545-4d6c-9d86-30fd729767e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 17).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd219cb0020746aed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f607fc8c-8b6d-4450-b029-7f46e84a3b11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 18).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5fe225019348b7b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3351696d-1815-4d57-866d-f0b8840fc00d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 18).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ae20c6c46ffd3adb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8978e47a-4020-40f1-a078-1ec31b4d31fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 18).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '3fa558fb18ee8f5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a3e6afa-23a5-4676-be7b-e93987373649', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 18).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a109370de4784b29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d774250c-01f6-4c2d-be5c-8c1539b15896', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 18).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '912c48ae75a5b84d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ad33828-66d7-494d-9638-5fb5af0d863c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 18).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f443383fe07b43c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78a417bf-9d1d-4184-8668-522cb9057f8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 18).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '40b22c20cf978bc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dedd783b-f3db-4ee5-b103-b5cadcd71602', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 18).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7d1a4ea6880e7ce4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('128688ae-c98a-4c94-8e63-e8205db3c80c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 18).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3040be9153adfb3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc272e13-7d8b-4b99-8c80-8d7a40f08f5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 18).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2d17c236396c77b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96db9b69-71be-4cc0-b685-fb1e54ad45f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 18).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '328e5e09bb4630d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e942902-0717-4cd7-a4c6-25ed53a0abb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 18).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '582a5070bd1a4936_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac4b653-dc4f-4d86-a443-5d27e63f3585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 18).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0fcbc6d10fe39359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebcf125b-b52f-42ec-8c66-b390eaa23e5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 18).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ee7292e68b51b8b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('432b1422-221d-4cf9-a006-a7042cd7b8d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 18).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7649ec28d5f74ead_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca1954d-db94-430d-a42b-15970be9063d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 18).', '[{"id": "A", "text": "set system name R1", "is_correct": false}, {"id": "B", "text": "set system host-name R1", "is_correct": true}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set hostname R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '418a2734abf1d866_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1536f36f-df84-419d-ba64-ef747354231c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 18).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3ee2edae920fcef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1585339c-13b7-4f94-b934-7a7779a57f34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 18).', '[{"id": "A", "text": "set interface ge-3/0/3 ip address 10.147.71.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/3 unit 0 family inet address 10.147.71.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.147.71.254/24 interface ge-3/0/3", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/0/3 ip 10.147.71.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '3c59cd68feea0bc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('020e2164-96bf-4b6f-9a6a-8e3d19b60b7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 18).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a98fa83d253264d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80b6f301-e472-4ccf-811f-f5d3f4c1bef7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 18).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1f2cf27c533a2c18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2be248f9-c9bd-4d8b-ae25-804a325bb566', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 18).', '[{"id": "A", "text": "show interface ge-1/1/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface ge-1/1/1", "is_correct": false}, {"id": "C", "text": "tail interface ge-1/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface ge-1/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e229b4b65d2f949b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50fa77cc-c608-43ae-8c52-e873b1473262', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 18).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d523447d8c93b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3716928-ce40-410d-8b95-b0b09ade8937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 18).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c9b91ea6a3f84cf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('488916f7-29f3-4c85-81d8-2ab93a81e3ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 18).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e96b98fa1bb06858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11b9fdeb-50f8-4622-8d93-c8f727fda393', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 18).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd2fef8aed65987af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e0c9fe8-2ef6-4613-9083-c014e98436eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.49.83.0/24 via next-hop 10.107.45.5 on Junos (variant 18).', '[{"id": "A", "text": "set static route 192.49.83.0/24 gateway 10.107.45.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.179.95.0 255.108.217.0 10.107.45.5", "is_correct": false}, {"id": "C", "text": "set route 192.49.83.0/24 next-hop 10.107.45.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.49.83.0/24 next-hop 10.107.45.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97bd1d252e7dff45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e90c6021-9231-420d-bb47-5480209d1f5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 18).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f5fc5182db45cb91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a79cbf5a-79da-4537-89f1-c3e3b24d83a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 18).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'eb95f49588fafd0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('302d5e71-9845-4f04-b7c0-98cf1d0fe61a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 18).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4ec7a39b65771ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('551a5ecb-5c67-43bc-8ed7-c5e4dd2f7a6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 18).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '32d6ebd7fe5222da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3da0095d-061c-4703-9722-64af1a29dff6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 19).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '94ce886fa7cb40af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f0d0727-8434-4abc-891f-160966dc7304', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 19).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a3085be8a5cf4241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d158e1db-79c8-40ab-aa58-a945afe420e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 19).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f589ba7a8d10b44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd34ad4c-0c64-46d8-9b6a-257f840066d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 19).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'cf0240e03d329f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cda9a1ee-b12b-4909-bdc8-47b18609e861', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 19).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5bf529a75c4ba9c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3c02f09-b7c1-4441-ac27-39a36a8b8a8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 19).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '70cf1681cd8e8e35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d7172fa-45f2-4fae-a558-510d31e82fe1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 19).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'be6e7cc06a695a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e93c616-6e03-483f-a970-aea716e0edc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 19).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '20c638cad1eebd1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3478889e-92ca-4ccf-a326-b5ac818d73e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 19).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f56f4ac201a355f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4aaa3ad-2831-4ff8-b9f0-b1a3185d9532', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 19).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '5c454f674e2a2716_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c34743d-17db-482d-bba2-01737a668686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 19).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cc04eb5af5ee101f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25930518-4e54-4b45-bca3-32030f1039c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 19).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '913762cb2f6ba228_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('399cee4e-0e03-46ed-92fd-54ebab514fe2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 19).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0e780498e2d6dd19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c286b16e-8f4c-4618-9049-78f9335be096', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 19).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '517fa7f788dd1886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a5ed4e6-7003-4f0b-bdd5-4650b16e3a22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 19).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ce29199854561dd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8beaaec2-35b8-4d88-92e7-532c786e35ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 19).', '[{"id": "A", "text": "set hostname R11", "is_correct": false}, {"id": "B", "text": "set router-name R11", "is_correct": false}, {"id": "C", "text": "set system host-name R11", "is_correct": true}, {"id": "D", "text": "set system name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '578729df27a765bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f51d1a5c-474b-4ccb-b5d1-873488da233a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 19).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9ed72dae87918c43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('285fa276-4358-4949-99d5-e91e6cae9d97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 19).', '[{"id": "A", "text": "set interface xe-1/0/0 ip address 10.2.88.1/24", "is_correct": false}, {"id": "B", "text": "configure interface xe-1/0/0 ip 10.2.88.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.2.88.1/24 interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "set interfaces xe-1/0/0 unit 0 family inet address 10.2.88.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f6af7799eacf3be8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c25c504-7f5c-4dbd-a10e-89026de10757', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 19).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd78bee210c7d946d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0fbca42-11b7-4004-bb8d-5f21037e9a3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 19).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2530db139fa9b8ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a0dca07-6b7a-49fd-87c3-8c979b893054', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 19).', '[{"id": "A", "text": "show interface xe-3/0/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-3/0/1", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/1", "is_correct": true}, {"id": "D", "text": "watch interface xe-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '459dd0c97f414b75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('925f1384-412b-4f68-b786-46cbdf12aaab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 19).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1593b9c10042f68b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('974f939e-f23c-461f-b07a-fa0928367697', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 19).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8b3988744d913b44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af495852-bf17-479a-b0c6-561026c7e4de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 19).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '12c2625873d6343c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cdc6db0-ee7d-40ee-a2a4-bb2fab04b07a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 19).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4d490365b91111a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6bba8e2-48e9-4e5c-a056-d2d6777ec1e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.177.242.0/24 via next-hop 10.206.81.254 on Junos (variant 19).', '[{"id": "A", "text": "set static route 192.177.242.0/24 gateway 10.206.81.254", "is_correct": false}, {"id": "B", "text": "set route 192.177.242.0/24 next-hop 10.206.81.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.251.84.0 255.238.29.0 10.206.81.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.177.242.0/24 next-hop 10.206.81.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a5b01a8562577d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3f529d4-4f5d-4866-a24d-cd831bfbd3d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 19).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e6ed7580f6efe3dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3aa212c-ebde-4300-a29e-81feefb4f5a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 19).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '602fc47255afa3b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d83597bb-b434-4bf3-9888-c335a4d7f97d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 19).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '84b62d673bf2d8d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f41fd384-b02c-4f00-8018-776659aef183', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 19).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e724357677f9464a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5cc70a2-d425-4865-a6bf-c23ebb06e22c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 20).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '958eb7fd945adab0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('460ba4c5-16a7-46ef-8604-36b99d4b58bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 20).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '95e900e22afb55b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('580e298e-96a5-447a-b67a-03537e8c2cce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 20).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a8c2a02e06910efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a9a06a-90fc-470b-a7d0-894e7464c9bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 20).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '67ce818f2884e6b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff5e7fd-0cb8-45b1-9307-abbc5f8d4bd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 20).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2684f3e2d0c33225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d19dd34-1d5d-4cd3-9f5e-8f57141794b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 20).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b6d04ba251a2d8f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c27415ac-fe0d-4662-8c61-1f08bf21d4ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 20).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba58d69c804f0dc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c79a0f9d-14d4-4f67-80f9-9deea05c4ee1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 20).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '72cc3fc6451b56a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75c17fc0-8754-46bc-bc77-9e54fd244321', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 20).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd6950aa1ed63dd6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f882bf8-4b10-4df1-b3c5-9d917a7f5de3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 20).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9f63d5a47e9bc495_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb2c8f14-54f5-4934-8976-ca91c889bf62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 20).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a845c7a19e7adfa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea40771-28ea-4a98-b47e-1001b0529dc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 20).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5fe84c68805fc95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3cd734-076b-4333-8a99-121f53d47d15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 20).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '930f98eab477aa66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b3655e4-b36a-4f49-a0c2-7d332c2a5f1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 20).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8ef85239ac004b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c0fafde-f572-4323-8141-ad895f4dfec9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 20).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '38984658f3f9c41b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1418c93-dbd1-474e-b0c1-3820cf07ffd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 20).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '77c6736035247101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a61121b9-79dc-40e5-b34e-5b6b4c4b2143', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 20).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2243ea69276f627f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cccd2120-dc8d-4244-b97f-90625145f14c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 20).', '[{"id": "A", "text": "set interface ge-2/1/3 ip address 10.4.160.5/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/3 ip 10.4.160.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.4.160.5/24 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.4.160.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '938b587cfe21160a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('826ad3b6-ecc3-4774-b369-0f1e21eef2db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 20).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5d26bac47fc6f268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c0fbc95-8d0b-427f-b652-7bad919ca6e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 20).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd3466e9b4cad2e33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aff19b07-0f9d-4cc4-9209-a0eb20b10202', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 20).', '[{"id": "A", "text": "watch interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-1/0/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-1/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-1/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '871610993a7501e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caa37cbb-0b6b-4747-837d-df903a46b4d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 20).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6919cfba0ac33dc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99b6a78a-919b-4c85-9533-f1fbe307f099', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 20).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '22d5c0ab3d64ae40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6b5aaf-b869-4325-89e3-a5dd50603785', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 20).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9fc55c4105f085ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('401b7450-3c77-4a70-8027-e2fa57f25fec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 20).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6b57438abfc1e8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbe86ce4-8ca0-4436-b264-e5c81bcad56b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.177.165.0/24 via next-hop 10.205.68.1 on Junos (variant 20).', '[{"id": "A", "text": "set routing-options static route 192.177.165.0/24 next-hop 10.205.68.1", "is_correct": true}, {"id": "B", "text": "set route 192.177.165.0/24 next-hop 10.205.68.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.198.142.0 255.138.79.0 10.205.68.1", "is_correct": false}, {"id": "D", "text": "set static route 192.177.165.0/24 gateway 10.205.68.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'df78adca19e6c351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d278476-094b-40e3-a750-1884e9410ae3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 20).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a5c1cd12af661a9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77e3541e-f21e-406b-968a-c1e7e85b328f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 20).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f710eb06905b68e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5fd5d23-01a4-4c6b-81aa-55ff72a91122', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 20).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a085876094ab59ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20d5045d-7ae5-4f0a-96e1-28a73f79c238', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 20).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b79059d18f7076f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7718a923-c3b7-41a8-888e-7c36081fd027', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 21).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'af8030ea241fe816_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2828555b-c477-43e9-beda-5696713f2713', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 21).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '540ec9eddd851260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('833f9070-cd3c-4a2a-be5a-bf9db8245db1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 21).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '604024a0d02ba15b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('163035f0-f55b-4991-8540-1f77b85aff39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 21).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8136d318a78f7975_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('295a1b73-0c58-410f-b05f-22386dd96bdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 21).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1520ad45a9cd616d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284e9652-002a-40e6-97c9-1c96005729db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 21).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e3efbe2e85086342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e015103-9582-4f17-b4df-ddd8ef0024a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 21).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f01f8eeaa9b60de9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('848868b0-78da-4be9-8fc5-ed28ce55fbff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 21).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fa33ea0d994a7912_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df389d31-6070-4fb4-ae80-e623c0fa965e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 21).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1f623ff2372e2165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc64892e-a87b-4c73-868e-c5008d7ca323', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 21).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3e25af960ea09b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('181af7cf-e837-4972-ba01-d5f50e54bbdf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 21).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f445a85fbf3ce47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('478cc283-16ae-4121-b09e-ccf5226cab7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 21).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a0180cfc32a44770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47ed1005-7b21-4aa6-9e15-790c5c918f28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 21).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '00c92a5aaa6f9f41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a538f4b-89be-4178-a9cb-96865e3c26fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 21).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a17388c108824a78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed3d85da-6974-4213-bd7b-d5c43267429c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 21).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cbf321149a5a4a5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6ccf6a3-4586-4f9d-a2e1-81221a87070b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 21).', '[{"id": "A", "text": "set hostname R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set router-name R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1f447aadcdb31466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96dfe0c0-2843-4e9e-94f2-c6f3c4a06027', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 21).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b027c7f34f5a17e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d37e940-378b-42de-b498-5b2393763e3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 21).', '[{"id": "A", "text": "configure interface et-3/1/1 ip 10.174.127.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-3/1/1 unit 0 family inet address 10.174.127.1/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.174.127.1/24 interface et-3/1/1", "is_correct": false}, {"id": "D", "text": "set interface et-3/1/1 ip address 10.174.127.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '61302ec1a69c8d9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a98cd8a-e030-4d57-918a-9ac5fc265859', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 21).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df5778bbfe03b891_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46c38490-c57e-471c-a856-d011f6c15ee0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 21).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fcd2e574d0666560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0855689-387c-4985-984d-fce14a4405fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 21).', '[{"id": "A", "text": "show interface xe-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface xe-0/1/1", "is_correct": false}, {"id": "C", "text": "tail interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '287ef970089827ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c83d3663-bb5b-4b25-84dd-b152c7859bdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 21).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8cbfa157c98c34d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bec9e5dc-f3b5-4918-ba9c-389bce2bb40c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 21).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2ac18a9b49206197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6140176f-c585-4310-855b-efb6cad03358', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 21).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3c9a3fc3de4e11a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2bef311-c574-4d02-a1ab-33ce091f060c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 21).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dff020e9d800cc90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e19da3-4725-4390-9b58-9109a62e8d5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.139.162.0/24 via next-hop 10.33.87.5 on Junos (variant 21).', '[{"id": "A", "text": "set route 192.139.162.0/24 next-hop 10.33.87.5", "is_correct": false}, {"id": "B", "text": "set static route 192.139.162.0/24 gateway 10.33.87.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.139.162.0/24 next-hop 10.33.87.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.222.219.0 255.196.32.0 10.33.87.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5b2f1c4860deed6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8760ca98-c951-4529-9171-6dc93f2765b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 21).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4991a4f5f112765b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da8f48c-875a-48b5-8abd-bb091b471773', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 21).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c9bd4401e957ec50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8da049d-93bd-47f0-bdc6-b222cbfd4eee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 21).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5a3a263ed9d65737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d8b6aab-65ef-4328-9935-1c0d6c843e03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 21).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0484d30d6e3fe266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0282d157-002c-4406-8e5e-abb216aa8798', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 22).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0c93a38958c33b1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7fd5573-03d6-4c8a-8a5a-7eb4e0170329', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 22).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a79555a4878370ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23cf5087-a026-4543-b600-6344732b3e53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 22).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e04bb24faeccd71f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dcf5b3f-be4c-4d60-b479-66d871a4af9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 22).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a15cfd779925bf15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f00e518b-2986-4d0b-bb9b-cdfc43cb5216', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 22).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c84b90d3d3ea40fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b30aecda-6a27-4c8a-ad88-e45244ed61b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 22).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '232c0e358742be64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e34bfb0c-84a7-4b99-91ff-c93fa4f45d2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 22).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cccd3d05efb88706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb620523-56aa-4a18-9501-1a05a04042d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 22).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41af7b186e9fa7ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75ab4a75-fb0d-43e4-b33a-3a8606f2d46b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 22).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9d7e157c76d9d8ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('643921e2-8b52-427d-849a-3b1947e4305e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 22).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '81432bd719787219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cf6b607-b788-40bc-b492-54418d5297b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 22).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5142ffde6568aa71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7826e60c-8756-4194-bcd6-8664cd3e6585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 22).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b934397a5598be85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43259980-8455-4f6a-a9bb-edc54bd770ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 22).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd4885ae9b69cd23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efcf11f7-73af-492b-a8d0-2d80dd401970', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 22).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '544e580c94281db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('603b0a9e-f52d-4310-bcc5-bf67b23c23d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 22).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '63863745ece36cb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42d666a9-89c3-4e32-8003-45e11ad3a147', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 22).', '[{"id": "A", "text": "set hostname R10", "is_correct": false}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set router-name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2fffe07dd7d553d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b9bc4fc-2f41-422d-82f1-77e47e7ade33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 22).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a5c3b6d0a6ca168d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d819ac2-26f3-4756-a90d-5cd113522c1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 22).', '[{"id": "A", "text": "configure interface ge-1/1/0 ip 10.214.64.1/24", "is_correct": false}, {"id": "B", "text": "set interface ge-1/1/0 ip address 10.214.64.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.214.64.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.214.64.1/24 interface ge-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7ea5a7f309be0c60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e47d900-2fae-40cc-a3a4-5d875a50f641', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 22).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1664a1ea471f1ef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f104c278-0cd2-4f90-941c-ff496419b8f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 22).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b69f9c8c8278c13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86df70fd-c894-45a9-a3b1-70e3d0aaed26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 22).', '[{"id": "A", "text": "tail interface xe-2/0/3", "is_correct": false}, {"id": "B", "text": "show interface xe-2/0/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2c11590b9c3c3397_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b897fdd-1008-41f8-a36c-88278b5dae05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 22).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39fa084f57f9b6de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e0278ba-375a-47b9-80a3-34a352c08561', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 22).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4bb78d172a05b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d762629-0883-456e-9f3e-8bb2def17245', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 22).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '47657fcf6dde55a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7472358-ac78-4f16-96d2-8cf6af0e5a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 22).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5dcd0a899ff50a5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('099e2496-9465-43ce-8f73-61371a6ce949', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.54.96.0/24 via next-hop 10.242.183.1 on Junos (variant 22).', '[{"id": "A", "text": "set static route 192.54.96.0/24 gateway 10.242.183.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.234.40.0 255.164.21.0 10.242.183.1", "is_correct": false}, {"id": "C", "text": "set route 192.54.96.0/24 next-hop 10.242.183.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.54.96.0/24 next-hop 10.242.183.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'be0caa4e367f827e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc3dade-2267-491d-bc73-abd6480af6e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 22).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'da135ecdd858a9ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('421b8667-9c32-4e7a-ae85-177f50e0fdd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 22).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6598faf9d3f73e85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a172c0b-2c6b-475c-9c5d-583f4a90ceb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 22).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '44d550790e6890cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaf3945a-ff46-4ba1-8cb3-df9a6f0c2a57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 22).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0409c7894513a3c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('048c18aa-7b7d-46fb-8342-86a20538e20c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 23).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '13d13f720d17f778_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70eb0d92-ce19-4714-bba5-bd15210f3cc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 23).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6f0c20159d487154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa7df729-f08c-4162-87ab-8ccdc4b14bbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 23).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'fc0c78ba046f75ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('056ad9e4-0412-4b82-8d90-9dc732919b43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 23).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '24fdebd364b4109d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c4c4ed4-ecd1-45fe-b491-8f4171598bcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 23).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '332472822da0da9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('def1bae8-5cd8-4e5d-b77e-902d730fd2bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 23).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '158e41378fc2807b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('738d738f-c220-40ce-9562-c97d64bf1cec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 23).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5c2e77943ddaec11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44335449-4d85-4078-b4ac-641083ac310d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 23).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5ea11af0116aa649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ee78c7c-90e9-4e9b-a899-af449c2e06be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 23).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5d2b1b4e65639522_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5118532f-68ca-4caf-a45d-422d0dbf1771', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 23).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e232a8b4142ad6c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('186e1615-517f-45e7-bb32-4dba19ac09b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 23).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ef3a1c093dda985b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233ee268-b603-4d11-abc9-0a29db5ab798', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 23).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c7d3060b95a10f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7019c921-98f4-4fda-8d72-2288fe917969', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 23).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d029aff7dcfa11f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10a81c15-8b7d-4c0b-802d-dee2413ba8b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 23).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a815c114db3a794c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b035ab61-334b-4379-97af-24806f20dc09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 23).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '83fd63ddf2640c40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27421657-be49-482e-964c-cd3eb402a136', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 23).', '[{"id": "A", "text": "set hostname R12", "is_correct": false}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set router-name R12", "is_correct": false}, {"id": "D", "text": "set system host-name R12", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a4dde80df877c92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de2e2ad9-d42e-4cc2-adcd-e7c0cd9bf44a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 23).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd18046160e2727ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eff711e6-7cbf-4c3a-bd4e-ba5656dcdadd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 23).', '[{"id": "A", "text": "configure interface ge-0/1/1 ip 10.248.227.254/24", "is_correct": false}, {"id": "B", "text": "set interface ge-0/1/1 ip address 10.248.227.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.248.227.254/24 interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/1/1 unit 0 family inet address 10.248.227.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '058cbbc235bd6e1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b8e94cb-6a4b-44b5-9fda-33f4d1ea6893', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 23).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da014a659ff05276_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e20d035b-7324-4306-8e5a-dd6489d5c069', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 23).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6754923ea4823ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f18256b-39c2-4261-87ae-9cb6a5c68f93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 23).', '[{"id": "A", "text": "show interface xe-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface xe-0/1/1", "is_correct": true}, {"id": "C", "text": "watch interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "tail interface xe-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c5e3c640242a80d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c12c7b8c-a34c-4fa9-95c3-d638f02304b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 23).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e1f687aecc0d2833_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('506e3103-bb6a-4f2e-8fc0-d2f4b1fde413', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 23).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e458580eed798e6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce5ddb3e-cb28-4fa9-854d-a4ab5ada9371', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 23).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f72c619e2139f52c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68783e7f-e852-4493-b447-a43821898ca1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 23).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cdd2bfece0731825_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0293fe90-1db4-4bb8-a842-b81331056068', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.1.230.0/24 via next-hop 10.22.217.5 on Junos (variant 23).', '[{"id": "A", "text": "set ip route 192.79.110.0 255.171.16.0 10.22.217.5", "is_correct": false}, {"id": "B", "text": "set static route 192.1.230.0/24 gateway 10.22.217.5", "is_correct": false}, {"id": "C", "text": "set route 192.1.230.0/24 next-hop 10.22.217.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.1.230.0/24 next-hop 10.22.217.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '433dc4c248041b87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade4b147-bd40-4c6e-b917-a245b844885a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 23).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '641326a2dca1209e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8547ed82-5605-4497-be8c-09595f829660', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 23).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd8004e1902e8d669_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59fe74ce-ec58-4a3a-a5f8-b020fc53714c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 23).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fc51d667fd829c3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e1be56-d50e-4419-9f60-513bcedb07a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 23).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2236c3b45b0872d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58d1b268-7891-4661-a10b-b3faa5642cc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 24).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b39d1595daa19b2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ef56e33-2a42-48ff-b2d4-a9aad914f5d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 24).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'df3d607bc04d7b76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae07c0ce-d83c-4f27-8541-b1588d28ceb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 24).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd76a6bde242178ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac6c0dcd-5a58-4ce3-863e-6fec517f8d25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 24).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'df3db42ff6d63bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f42c080c-fa58-4d27-80c7-aa0a44e7ad46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 24).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '693c67a9495f1429_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b9448c-e1d8-4d9c-a824-719247ec220a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 24).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f65af3be700671a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8043945d-39ac-45f8-ad82-370f678aaa79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 24).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '67358ae1c36ed843_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9092f31a-3be4-4254-bbf8-55109bf9d80f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 24).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9dd66a24ae1ab319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42978931-0fdf-484a-9a9a-f47666e6fa6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 24).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bff7c5fa8a6e6bf3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b003741b-7f31-4a75-a651-d3043a9bf1a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 24).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e14885f0bbad48d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8587efe-e2e3-4c06-b91c-bec5d0c2dd9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 24).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d7422b40546b17a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dbcb58d-a51d-4702-95f7-6b5f23bfe3c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 24).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '701ae674b5c6f8f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2e1cece-1c8c-428c-95a9-de7fead33400', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 24).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '73c32e81732e4c62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89cb39fd-30bd-4f9e-9311-4aa9c52f2bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 24).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f4699c76e14bfbc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54dc727a-b644-4ce9-83f3-3be11a11be31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 24).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '254aabae7b1faa68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28884edd-ca5c-4e88-a78d-6c7e5baf70c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 24).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2499644a9e088bc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d249d91e-c0ff-47f6-8c12-254dd4595d24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 24).', '[{"id": "A", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '08ac60142c69bc07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d4aaa26-bc00-423e-bc39-84ceb14d6a4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 24).', '[{"id": "A", "text": "configure interface ge-3/1/3 ip 10.219.18.1/24", "is_correct": false}, {"id": "B", "text": "set interface ge-3/1/3 ip address 10.219.18.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.219.18.1/24 interface ge-3/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/3 unit 0 family inet address 10.219.18.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '03ee051ac64a1bdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb8161ba-ade3-4877-907f-0aeb99a634ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 24).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0671b44ce21efd94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b7a807e-ebdd-47f9-94f4-c2e2723bd260', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 24).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cd758cdcdc4d2ec0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74d05c43-cf60-43ec-839d-4ee6904aae17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 24).', '[{"id": "A", "text": "show interface ge-3/1/0 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-3/1/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-3/1/0", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4ad2efe9ef477796_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ad6f2be-dd74-468e-a628-4c925b8df350', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 24).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4bf36bafe85192f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('448d39a1-de39-48cf-ae74-114e6215c0d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 24).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2e48adddc3e7ef04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2e4e73-85ab-4f4a-bcd6-3f8dc47eae72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 24).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '82d8aa42b75d2f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('508192a3-2a03-41db-83ff-2a4f98488223', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 24).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a900758682e5b79c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d5d15c5-ec92-425b-931e-66d4ba500bd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.187.69.0/24 via next-hop 10.25.67.254 on Junos (variant 24).', '[{"id": "A", "text": "set ip route 192.120.91.0 255.20.252.0 10.25.67.254", "is_correct": false}, {"id": "B", "text": "set route 192.187.69.0/24 next-hop 10.25.67.254", "is_correct": false}, {"id": "C", "text": "set static route 192.187.69.0/24 gateway 10.25.67.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.187.69.0/24 next-hop 10.25.67.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7d44eccfdef20307_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09f27c69-6a85-4892-87b1-e6dee9fbd47c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 24).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0b50baa38aad58ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aa75625-7c0c-4a8c-859b-07649f6b48aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 24).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd17d22333307ef11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feed4228-5222-4696-b2b5-c8f09fbe32c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 24).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0d7f9cc82876c834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45a8fb41-8f96-4c1e-a32c-e21cd16325fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 24).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4b46adae7cba627e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3503708f-4fac-4391-9c63-82816319ca25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 25).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f27e23b6b1a79ec7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3da25139-d040-4b67-9a2a-4f9cfd6138ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 25).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4093d585d8564b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d94b484b-f0f7-4424-a0df-142815015bb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 25).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '2b444e36802d0e40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d662a4e8-9e59-4d37-93a8-75b36bd28922', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 25).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4a0ec3fb35ce17d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('848a041c-8f85-4940-84d2-5ecfbb7d1e15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 25).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd841e274fb6af836_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd8a76db-e454-452f-ba12-cbe85f5ec562', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 25).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f927031207239ee8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbad0293-59ea-408b-9839-b22649f422bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 25).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a90aa143e125fa62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('538c5898-cfae-47c6-b827-9b9e8f9d5c59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 25).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2c5b688028104f14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad728cd-1cb3-4141-ad58-e78f5dd66deb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 25).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '48894db026c0ff2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('689d2132-3ae5-4446-bd4e-ded82a767ba7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 25).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '414d0d68f6746fcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5a299cd-7cad-459b-b268-27b9f0d76020', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 25).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6751da5fdeb9dce8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06014325-0bf0-4929-9312-22e515ac74b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 25).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c37878333ff8f23c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d245401-99b4-4ed4-8070-727e731e8140', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 25).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c49710c24884cec5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f9088f5-1474-4cb1-81d1-4add20e0a86b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 25).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9d7aa965d166421b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb1ca09c-3d44-4997-a7a3-fa19c64b0f28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 25).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c547dbd244a73249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50461a25-eb30-4440-bc9c-f18a23572864', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 25).', '[{"id": "A", "text": "set system host-name R3", "is_correct": true}, {"id": "B", "text": "set router-name R3", "is_correct": false}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set hostname R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4183b90e735fed34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8357d4f8-b466-4273-86bf-09fa08154ee7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 25).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0d6e93c022f4d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('234ee146-0ae6-4320-a6f0-9822b5aa4ae6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 25).', '[{"id": "A", "text": "configure interface ge-2/1/2 ip 10.40.163.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.40.163.5/24 interface ge-2/1/2", "is_correct": false}, {"id": "C", "text": "set interface ge-2/1/2 ip address 10.40.163.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.40.163.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f87c271aef4f1568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01857960-7f38-468b-b08f-9d8e15568b42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 25).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a233f662c22966e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac38fc62-74b0-4f98-a0ed-a4dc3bab310a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 25).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd469fb89d8cd3ea1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93814ab2-13f4-4c5c-b3ca-ae159d9fad77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 25).', '[{"id": "A", "text": "watch interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'add22793114e96c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c973233-65b0-4d24-ba0a-39ae336293fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 25).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8358882cb5a23048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd229ab-34a1-48a9-906e-b8eb5c9b0e2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 25).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f28a8ed45d7777aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5047a8a8-d71f-4741-81ec-03d98bd47cca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 25).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '46f0efa4c247a4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bcfea7e-b316-486d-a4a1-826e6a536e2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 25).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '59586431fd7fd4af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f9b0e78-ab5b-414a-9e2e-4efda4c99ea9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.234.75.0/24 via next-hop 10.179.13.254 on Junos (variant 25).', '[{"id": "A", "text": "set routing-options static route 192.234.75.0/24 next-hop 10.179.13.254", "is_correct": true}, {"id": "B", "text": "set route 192.234.75.0/24 next-hop 10.179.13.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.86.119.0 255.31.105.0 10.179.13.254", "is_correct": false}, {"id": "D", "text": "set static route 192.234.75.0/24 gateway 10.179.13.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'deeb0234da5e7622_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6228140d-91e6-4072-a226-3a505f0ef708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 25).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '64e351ac281c01f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688892aa-44a2-41a6-9de4-d5613a500e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 25).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b14e243663e7709e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adef809e-97be-459e-8514-a8e2bfc4a65d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 25).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '125e4acc3728cfbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f980a7-d2e9-4502-b771-a232788836ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 25).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e61ec97e10bd1810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('990813b4-c61a-47ec-9642-739aa61ca3fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 26).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '217443f465c7a14b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bbc35d9-78bd-46e8-9b51-926df83743d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 26).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '714a2f83c346ae06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8306ae8-e443-4194-ac66-d7ce6f162f6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 26).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '98448f12d3e3b5f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04d2250f-e6e6-4564-aeab-e6f40ee9401b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 26).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c6b6ad4b8296a27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96563f55-2dd1-44b6-92d3-abe31be99d2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 26).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c15475d5ba6538fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('306cebd3-bcca-4c54-8a12-7a09cc4155d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 26).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '80ef2cef9adc95ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('211acc2a-a4e5-4eb7-8199-407292ae7a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 26).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '67eea50855f375d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('908867a4-1455-4658-b578-6db89309c0cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 26).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8305c5d8042ec7ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5756abfd-df63-4e56-92cb-8703bfecc085', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 26).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6310363a28fd49c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c0526e4-89d7-40bf-9d3e-27a21adb11b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 26).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ad0f1bd62537a7b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cd7d4d2-02f8-411a-bf50-a3fa384e8df2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 26).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8a0fa6ff1895de83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c14fa9b-2558-4d94-a0ba-9e94f7296f45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 26).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'be4ad724e0910bff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('947fb601-5c4b-4fe9-8cff-28053cdbae0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 26).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f46264ce3e19fd6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e87fb554-b72b-407e-8522-ff99ab88b6f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 26).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b0db290ad7dd55e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('534a6e24-5993-4eec-b4dc-27c836cb1da5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 26).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cd87f49ffdb41aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('022c4b49-d7dd-41d6-9a93-4dc0f62c7606', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 26).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set router-name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fa4e225c0b08a888_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12bfbf95-1b93-443e-af6a-1dd873b9e9f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 26).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dd91681c1f04fdba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e85c66c-f466-4674-b3b8-6d82120ce2b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 26).', '[{"id": "A", "text": "set interface ge-3/0/1 ip address 10.86.236.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.86.236.254/24 interface ge-3/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.86.236.254/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-3/0/1 ip 10.86.236.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2c2a2c3c4177dcb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f2ed267-33c6-4a6e-83f5-db9086cd24aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 26).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2fec94b99eb9ea79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be972785-f328-402a-a9c4-f6583d214b0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 26).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '65f789535779ecec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79386f08-9b0a-4f87-86f6-57a174d58808', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 26).', '[{"id": "A", "text": "watch interface ge-1/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-1/1/2 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-1/1/2", "is_correct": true}, {"id": "D", "text": "tail interface ge-1/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2bbc5e45a03a96af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ef0486d-2d2f-4580-b3f1-891b9fd85192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 26).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6177f3aa63f5d1a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2348414e-4642-434e-8572-dfd4f39e5e34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 26).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '771956e669d92a70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f59c1c-09b5-4bd5-b8aa-746919ce9513', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 26).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '83adf9694243decb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3277fd0-f5f1-422a-a349-b8084fe41c26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 26).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3a45f5f4d9480ac0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3329d86c-dc3f-4ef2-9730-e812347494bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.223.78.0/24 via next-hop 10.224.29.254 on Junos (variant 26).', '[{"id": "A", "text": "set static route 192.223.78.0/24 gateway 10.224.29.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.223.78.0/24 next-hop 10.224.29.254", "is_correct": true}, {"id": "C", "text": "set route 192.223.78.0/24 next-hop 10.224.29.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.12.250.0 255.91.48.0 10.224.29.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '56c6ef1c2a4038d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5523a5ab-6121-4449-a512-733c929b9183', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 26).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd1550713ffc7a388_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada6fdb6-de96-4b77-9632-8560de072532', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 26).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3f63167bf16b94d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09a7e6f8-5d5b-49cc-9376-7b29fde399d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 26).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f9a3c3ab5b6d312e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('207817b3-bd5e-47e8-be8c-17da3907e1f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 26).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '63d3393b4687b74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ac4416f-e4da-4757-8758-9a21828c48e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 27).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3d2827998eb3e05c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba34d7b5-11bb-4024-b27f-203ed7294a74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 27).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ed5903a8881c7793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe2f1fc0-2eea-4a93-a045-31bc6f291f24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 27).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '158a6af0b490c7f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25b1dc34-4d97-45da-a53b-251982694a8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 27).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '48cd810efea15435_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e8b857b-4d3c-47a7-aebe-276a1fbc19a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 27).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '138f2e5f84d92fee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47f1c64c-888e-4c80-8e32-e9b66941c511', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 27).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '669b57c9afe8313c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17df8989-ca64-480c-a72a-5a4c54e43049', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 27).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec0f05c649019d60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a328bccb-9186-420c-a445-98c84e214278', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 27).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e7c6636e8cfc9a19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887a40f7-735a-49e9-bee6-7ec317f2e0e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 27).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6c5d9e71071d182b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82871e18-c6d7-4b4f-bccc-2482e4b6bb02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 27).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '83eae72663b2e4a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75f13e8b-974f-4d9c-871c-cf17ada3852b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 27).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '74b2b246b23d86cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cfb01e3-6c7a-4c60-873a-1ddcfdef3123', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 27).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '015749863946a725_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('678ec6b3-3081-43b7-8845-2acde6a7aa25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 27).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '30b13dc4af17690d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55a092e9-49b8-4e47-8a34-91a6578e7381', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 27).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '67ec40c030d46979_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15963eda-b201-4607-84cb-9fa53f82c593', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 27).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '21a03a20c5b652de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47abf85f-8001-4ffc-b284-70f9529804ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 27).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set hostname R8", "is_correct": false}, {"id": "C", "text": "set system host-name R8", "is_correct": true}, {"id": "D", "text": "set system name R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3bcf0cab6c4772aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d684461e-c662-4ef8-bc3a-90a41721feeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 27).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '422ab59a2c40e14a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f48552d-4264-4e9c-b77d-3b71ef9d3149', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 27).', '[{"id": "A", "text": "set ip address 10.214.31.254/24 interface et-0/0/1", "is_correct": false}, {"id": "B", "text": "set interface et-0/0/1 ip address 10.214.31.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-0/0/1 unit 0 family inet address 10.214.31.254/24", "is_correct": true}, {"id": "D", "text": "configure interface et-0/0/1 ip 10.214.31.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '866a83a2f9e41904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfe478e9-a4f3-459e-9cdb-02af2463c0b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 27).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ce6ca403f4a1065a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c348e61-9795-46ba-a2c4-9e2b6941674a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 27).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bddeff61199507dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5867503-14f9-4249-a259-23f2eefb9e42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 27).', '[{"id": "A", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface xe-2/0/0", "is_correct": true}, {"id": "C", "text": "show interface xe-2/0/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e6b790f6bd7af73c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56795dd9-3c44-4403-893d-bb7ef4e9d914', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 27).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '86fe4507147ea136_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13d030e9-28dd-45bb-af77-d69f54d1efd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 27).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b7bf9a1c112d7d6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('956b4f30-41e4-4fbb-bc4f-9a790b2aa189', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 27).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '81686accb554c4e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d5160ee-199c-45d5-af9f-58d1d5c86282', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 27).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '53047c0fb83ee924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0736a941-ae6e-4f18-8819-e6ce228e7f09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.95.113.0/24 via next-hop 10.4.76.5 on Junos (variant 27).', '[{"id": "A", "text": "set ip route 192.18.71.0 255.127.1.0 10.4.76.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.95.113.0/24 next-hop 10.4.76.5", "is_correct": true}, {"id": "C", "text": "set route 192.95.113.0/24 next-hop 10.4.76.5", "is_correct": false}, {"id": "D", "text": "set static route 192.95.113.0/24 gateway 10.4.76.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '715eaa5ac8f20b11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e7521fe-59b2-425b-b527-a423a7e27ba2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 27).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c57cefe2af2fbb9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d30e348e-c649-450f-be08-7336f7a676d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 27).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3806ae5e26c75729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b39848ea-78ae-40f3-b79f-875897c1bb2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 27).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '81f6dd3d9510d20b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b03110c-6a8a-44bd-93c3-4dc7ad1c5b23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 27).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '36ab819c9fbff736_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070d29ce-c610-490e-940c-9484b2d9fd95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 28).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5ca7121b40c62493_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ef2c708-30ab-4b28-8a8a-10a4638bc663', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 28).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'fefb938f7fb44c28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('281058cb-96fe-4dde-bfb2-956a8a8a9663', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 28).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b95e3eb36a443bb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba9f108-b5f6-43a8-9394-e2203eb5f306', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 28).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '88302fd6cea25c0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65101baa-da79-4e86-84dd-d508a8393118', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 28).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5bc3f39cffdd3601_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7ff58cb-b983-40da-acea-29e22cf8f32c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 28).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c7c2cd4cfc078cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fda643e-ef63-40fb-b09b-e76b9b3a74ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 28).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c64c936f9d519890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fb797f4-c984-486d-9674-4dfb506485b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 28).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '93ac75272e379c07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7000cfe7-e368-4419-a588-452253235afa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 28).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8d6fa67d0fb5610f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80e8e316-e639-407e-96fb-81a956bf3b46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 28).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '839c8af38c7d80df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d1ed9e3-ff53-4f2b-b89d-e81c71006153', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 28).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1f7988739eaf861_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b4fdd78-91e2-441b-a4d9-b69d01f432e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 28).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fd790595c9ec3f40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea8994bd-449f-41db-b03f-a57e0e58ba76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 28).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06fc7713c930a8d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('868f8782-ce6d-4bd8-86d0-b8146a9f8249', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 28).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2cdea044837271f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('090f2601-4015-4877-9a63-e879c9513444', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 28).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '802d1c0c6ea22524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('156a1beb-9340-4629-b935-2f86b255d3b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 28).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set hostname R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set system host-name R8", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0dd2dd2d947eb9d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f10a7a2-6a24-4442-aacc-9c7c184cdf43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 28).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e2bf1e8443b539ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aa7cf50-52c4-45b7-aa66-3981953e061e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 28).', '[{"id": "A", "text": "configure interface xe-1/0/3 ip 10.178.83.1/24", "is_correct": false}, {"id": "B", "text": "set interface xe-1/0/3 ip address 10.178.83.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/0/3 unit 0 family inet address 10.178.83.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.178.83.1/24 interface xe-1/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '904309b77e1c6ba2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('856a9f1c-0ebe-403b-beb3-8eb3396803a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 28).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5575a30b4d88aa84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b166fb-2e8c-49d7-8b0b-89e542e673bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 28).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '93578574342c1e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7cd0b9c-b120-4efb-a98b-27697c9b318b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 28).', '[{"id": "A", "text": "watch interface xe-1/1/0", "is_correct": false}, {"id": "B", "text": "monitor interface xe-1/1/0", "is_correct": true}, {"id": "C", "text": "show interface xe-1/1/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-1/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3f841402d7d5257d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c2492b9-8f72-4418-bc7d-53405a4e41b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 28).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fcd6373f49741b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f98420d-8a5b-4228-9c0f-56d637966d56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 28).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a0c45176c5bc79ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('300a829e-9e20-4aca-b507-d3a3972939d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 28).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '61c5814fd1fa517d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e6f012-f0e7-4fcd-8525-ba8c5fb4b081', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 28).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd42819d5e5bb64d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b6e6258-03f3-49af-b762-2c4f954ee149', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.84.106.0/24 via next-hop 10.106.73.1 on Junos (variant 28).', '[{"id": "A", "text": "set route 192.84.106.0/24 next-hop 10.106.73.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.22.211.0 255.255.56.0 10.106.73.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.84.106.0/24 next-hop 10.106.73.1", "is_correct": true}, {"id": "D", "text": "set static route 192.84.106.0/24 gateway 10.106.73.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '683ca4934193f0bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0db2cbfa-ff37-43cf-845f-e73fb3d3cf84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 28).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5afa465941e3d3dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('958f3f93-2d9f-4010-a6f9-08c9eb225083', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 28).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a35e51864184ed84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb56777f-2a29-40e0-9d01-7443f5900523', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 28).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e663c90851f4d565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53712890-622b-4325-ae60-609466996585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 28).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9329c09abad56d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b070858-db2b-4fbd-8f4e-a8892c00ade0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 29).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2354f68c964ca868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8563fdcd-c634-4d36-9a77-0a0a1b208dd9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 29).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a03643dc5c91a8b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e5f00bb-fd22-473c-a05c-f14fe8d8a38d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 29).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '58af97b717a47b9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ac1b9d5-a098-412c-b6a9-bda6bf6f645b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 29).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '70362951c6d161a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24548b96-5c83-4881-80b9-ea7a5036b60f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 29).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '4d51fbe4e88afa52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dbe4dec-52d3-4894-b637-d4183a4540a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 29).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6fcb0f1e9b2be93d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3d4ef8-a1f2-41c4-8178-a2eea51eaab6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 29).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '640298fec44c5116_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b9bbfa-4261-4531-adde-9ed2ae444a84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 29).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b94598b7b5603233_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6b194a5-fd99-492c-ae4b-fc7445d63123', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 29).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cf837c33b25175f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18a4fb8d-8cbb-470d-81af-265156695ba0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 29).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'cfdb451e92ff6514_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af866f75-bd8a-428f-8112-45390ff93e41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 29).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '954c59a7c1d28ba3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2185a4af-5b32-4e21-9dda-7736b66c9fb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 29).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2df6f493a985d8c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('668cccd6-f140-4312-845b-450ac2ef560d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 29).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0a18229be4f7b8c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a643343-cf48-4457-b696-41abf403ee46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 29).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5e5aa92055c4ca3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d4ae5e3-2707-4184-bdb1-862e0a26ce95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 29).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3130c0dfc39b1a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c90cea56-c3c1-40a2-aba6-f056c4ebd9be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 29).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set router-name R11", "is_correct": false}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set hostname R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '68bc3cebbfe3d8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1555bb3b-218d-42e9-9ab2-2a031212baf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 29).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0be52c3be5bb2cb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09b4cc6b-6386-453b-a10e-4dba3c3063f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 29).', '[{"id": "A", "text": "set ip address 10.113.18.1/24 interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "configure interface xe-2/1/1 ip 10.113.18.1/24", "is_correct": false}, {"id": "C", "text": "set interface xe-2/1/1 ip address 10.113.18.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-2/1/1 unit 0 family inet address 10.113.18.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f35d1aebed068cd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a0e5851-e44f-4c02-8541-fb38b377d2a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 29).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4a05716bb5e21818_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aa24451-c8d9-494d-9aa3-7dc485be0153', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 29).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2b1ade25fcfa3d32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e87cabd0-cc62-4d57-8451-7e4ddd5e2367', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 29).', '[{"id": "A", "text": "show interface et-3/1/3 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-3/1/3", "is_correct": false}, {"id": "C", "text": "monitor interface et-3/1/3", "is_correct": true}, {"id": "D", "text": "tail interface et-3/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8b60c12fcdb34088_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52017473-3580-4f6f-92f2-3654b58ffb2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 29).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '10f670e0554129b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('768c8433-d514-4941-bdb3-493bd49cd275', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 29).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '89ba872cee5530fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbada704-ca46-4e3f-bef0-ac4f2b72f647', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 29).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3f59a77abf963eb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6920582f-1f91-475b-b7c6-199ad12414a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 29).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '805f7d077e3232e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a137296-ecd6-4416-8b1b-84f0adaebaef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.183.150.0/24 via next-hop 10.118.91.254 on Junos (variant 29).', '[{"id": "A", "text": "set ip route 192.51.116.0 255.242.101.0 10.118.91.254", "is_correct": false}, {"id": "B", "text": "set route 192.183.150.0/24 next-hop 10.118.91.254", "is_correct": false}, {"id": "C", "text": "set static route 192.183.150.0/24 gateway 10.118.91.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.183.150.0/24 next-hop 10.118.91.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '804c38ce711ae404_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47397c30-6c3b-4f42-80a6-70269c52201f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 29).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '399ee39c5fffd068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcc7b1a1-fafa-4b04-a225-017578c07f62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 29).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd12b07f4b37ba45b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1caca19-b65b-46c6-b90f-0082bc85bab7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 29).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0ea964074e516599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6d1e17e-e90b-4025-9ffd-dcb3eee1e18e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 29).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '24bca668d3537105_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d1fe36-b568-4581-b4dc-c9575864a5c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 30).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fc60134dfe95550b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd9c20b-6884-453b-b181-3197b6743008', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 30).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ab7288178abc8147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71643c91-d615-40d4-bb1a-5c1ccdff7043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 30).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7cf2565b0876af68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93163a22-8d23-4c97-bd9d-23e49dbc4d20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 30).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '261924c70260934e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6950324e-c093-4227-8875-5fd29ffc469c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 30).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e692f542f1093d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f0e119-dd3c-49bc-930e-97762d1d926c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 30).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3efcee009a7c02a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aead4838-0558-45d8-a54b-9a6240fab042', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 30).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b03b9f835ccc6b9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8287dcf1-0175-4b2a-ae16-ca18ca2d912d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 30).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f5ad31d03d02f423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b475ba0-6979-4d19-9ea7-d782120155d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 30).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7357f90ce373ada7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e2dde4-a826-4fba-aa7d-5d608488b432', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 30).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fc026aa444a6374a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2053f8af-fff2-4cd3-991b-7703223dfc7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 30).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '98be4ec33d4736b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47497762-98f8-48b4-9166-beca5e416553', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 30).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2a62894834631542_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb9120d-33c7-438b-8aeb-f84d8055adda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 30).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0748b5ddcc673d7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ca6465-2ae3-4089-b78e-11f8473e5f69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 30).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a05fa77c810d99c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ba5504-2b3d-4a16-b2af-4bfcced360f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 30).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '496bdaa87270baca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a12a0c8b-e4e0-4c46-9da1-74c56561250a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 30).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set system host-name R2", "is_correct": true}, {"id": "C", "text": "set router-name R2", "is_correct": false}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17b1d45448cad955_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28150c01-aff2-40ce-bdb8-b4835f2013ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 30).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc127ba76e62c2db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82fa3838-eeb4-4600-8895-907c4277fadd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 30).', '[{"id": "A", "text": "configure interface ge-1/0/3 ip 10.128.17.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.128.17.254/24 interface ge-1/0/3", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/3 ip address 10.128.17.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-1/0/3 unit 0 family inet address 10.128.17.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e4f0fac30f0f966e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53d38745-2e9d-42bc-a801-44a13312740d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 30).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '416433361c7d6b3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3804fd5-d48e-40d5-8b11-155cc7a9c9aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 30).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '87371444b4137485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2fec3f3-c79c-47d6-b29a-b4f5b307d669', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 30).', '[{"id": "A", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b5bc3e4dbdcae03f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6695a724-c9db-4130-ab32-e376e1991ceb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 30).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d332cf7851d98ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81ae1c09-5010-4c51-a7f5-dbfbeca30937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 30).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2314fe32755ab182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddecb1eb-5b65-4fb5-b4ec-41a2efbab856', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 30).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7183c5d69a5770b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cfb6af9-1d16-4728-b718-c76cc6d006d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 30).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '00868b6458dec7ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('200e3f18-c3a2-4987-9cf9-5a75d3dc1495', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.90.0.0/24 via next-hop 10.194.6.5 on Junos (variant 30).', '[{"id": "A", "text": "set routing-options static route 192.90.0.0/24 next-hop 10.194.6.5", "is_correct": true}, {"id": "B", "text": "set static route 192.90.0.0/24 gateway 10.194.6.5", "is_correct": false}, {"id": "C", "text": "set route 192.90.0.0/24 next-hop 10.194.6.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.193.195.0 255.153.227.0 10.194.6.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1b9b12b24ad30ad0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaec6930-f96b-4ec4-b9b1-88f62615be9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 30).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a95eea6655439cc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('830ab313-c2d0-4d6f-8301-a7d9e3b83b03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 30).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c8081e29e66ded77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7614dc6-7ca0-41d4-92db-f0eec8e37be7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 30).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '369da84dfe92c59f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ecf43ca-2d98-4344-80f3-cc7ca4033e78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 30).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '99bfe08303b0a296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('036045af-3c26-4d0d-ae1b-5207bf16be30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 31).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1535e7a15525757d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57eed7e6-7aee-47b2-8839-0919339bc3cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 31).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '294300cf3a726b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6103956-b521-4afd-b9d8-80009e8185ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 31).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd8d510b21f61bc14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a233de40-40ac-4055-8582-9a3b7af3f40a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 31).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4de9fcaf8601e620_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbc1f8c8-98f5-4e95-a926-2e48be593cb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 31).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3e0cd8715f75d03a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cd1feb8-95c6-48aa-bb21-1d0a1aae132e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 31).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '06f5e7eec53f5737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('496c47c8-36f6-4b80-9464-107c5afae0c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 31).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd504b411025140b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('395db78a-877a-4139-92a7-1110df88fb69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 31).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '39a549eb31a0616f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f6c1e8-6683-49c8-bfbb-0cfc933b6825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 31).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '783cb3b41d8d2c53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc3dfb7e-773b-406c-a87d-e62fb9801a9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 31).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e1457971f4cebeda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beb41cb7-45bd-4a8b-9fb2-2d9bf9919f89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 31).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bbd5bf21bb15744e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e668cf2-eb14-4e6e-bcc4-f78754938f05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 31).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf74d82f5dcbebc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4d798b6-05b9-49e8-b156-78651be3754e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 31).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3e622541711b9a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26eb4464-80ad-4b9b-9c45-3dd05a73b4e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 31).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca7eec3cc65d05d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9d28dd4-6e2d-408f-9cb1-6b7864b471c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 31).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3f2589f694ef0356_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('982ae733-97bc-4d85-ae26-71b60799f4e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 31).', '[{"id": "A", "text": "set system name R12", "is_correct": false}, {"id": "B", "text": "set system host-name R12", "is_correct": true}, {"id": "C", "text": "set router-name R12", "is_correct": false}, {"id": "D", "text": "set hostname R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '508100aedd567c29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f30e512b-809d-4cc5-a9d3-16e17aa765be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 31).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd9ab62f9c3c2c6de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931f0c73-5f87-4fc9-924b-dc57c1230c35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 31).', '[{"id": "A", "text": "set ip address 10.172.114.5/24 interface ge-2/0/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.172.114.5/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/1 ip address 10.172.114.5/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/0/1 ip 10.172.114.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '12a16facee0c9e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0510444-3002-4279-a591-1a19ea6fec1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 31).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '69af4f68fa479762_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4b25f40-e597-4fb5-86ed-bbfe0ac8f286', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 31).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb7ec28de1609724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3510cd65-53f6-4456-b9db-33198b03ea8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 31).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "C", "text": "show interface ge-2/0/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '40f59bad7fcb5d91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56bd599d-fc81-47ed-a241-68e33fc3bcc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 31).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44651c065abd7eb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82519c8b-5363-48fe-94ab-11daa3676828', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 31).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f0c0a386dff3bbce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('448ece0f-4855-4972-afb1-b571f431255c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 31).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fa8ce2683033e19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f311d629-1ec8-469c-aec8-8cf54142ad50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 31).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '48b7429e10d54cc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae380042-3994-432e-930e-a9a521708bae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.220.172.0/24 via next-hop 10.244.106.1 on Junos (variant 31).', '[{"id": "A", "text": "set route 192.220.172.0/24 next-hop 10.244.106.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.220.172.0/24 next-hop 10.244.106.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.94.150.0 255.151.204.0 10.244.106.1", "is_correct": false}, {"id": "D", "text": "set static route 192.220.172.0/24 gateway 10.244.106.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1cbb0e93e6fb642a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67d5fc30-f0c0-42c3-8d78-d6aac024eb2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 31).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f864bf772e2cb514_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c72fc17a-535e-48b6-8e0c-988c420d99dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 31).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f6f82618b5484047_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00624771-c1e3-47f4-bb96-45722af4eb01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 31).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '40954b69fb59be53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6b9a5b2-0e17-47d9-87c1-a8f86b89526d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 31).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2afaf80f76b32d41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('053ca514-ea83-4773-b037-ae1cd29ad590', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 32).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6a8cb6c0219ec466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e06c1fc8-2b28-408c-bf1a-c30223cb4d83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 32).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9895e7232d2e88bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96daf5d6-6a44-48bd-bf57-f87030edede3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 32).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '29b62f7264338f41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d9b35b2-bd6e-44df-b144-db629fd21f5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 32).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1e5e9f3774ad6993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('164e3a07-0d74-48a4-a59a-d9ca34924351', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 32).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '73ad4f65972bcb6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4ca778e-ab84-4d29-a746-089aaba48a8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 32).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '863d39f884b81110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2fe6bde-77fe-477c-bba4-14a66c31ccca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 32).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '387ad9749de61193_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce4f49b-efe7-4d82-8553-d5a83b6087fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 32).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '749e641febcec93c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab29426-3920-4e4f-b47f-fd524c1f6d9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 32).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '98d205b122cba6e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ce66b09-6189-4e8e-a807-510fbc48501c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 32).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8d0b9901c878cbd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbb09c69-b51d-4752-a570-06f5d4f7a5b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 32).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '90646ae1d15d72b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66736b0d-8c52-4631-9bbd-d89bf8e56a89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 32).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5077571ab96e8b78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4aba236-2b9a-459d-8654-d750fcf41329', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 32).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '08926e859d3c5a2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3ffeea4-6f28-4465-97ac-9d2ec648bba1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 32).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '23cba49879ff8a08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16e0166c-abc1-496e-a7e1-4825963b556c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 32).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fd3beedc8043061_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db53ecbd-1f25-4eed-af05-a0e927034589', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 32).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set hostname R7", "is_correct": false}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32343b9f8bc4985d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebcbb3bf-b563-4d84-a3aa-b99a7329c23b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 32).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '321cbb2332503dd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b37d9e6f-c120-4dc5-9086-4c155a7c3a64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 32).', '[{"id": "A", "text": "set interfaces xe-0/0/3 unit 0 family inet address 10.90.223.1/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.90.223.1/24 interface xe-0/0/3", "is_correct": false}, {"id": "C", "text": "set interface xe-0/0/3 ip address 10.90.223.1/24", "is_correct": false}, {"id": "D", "text": "configure interface xe-0/0/3 ip 10.90.223.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '23dc57fa0296a2a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61cb4c91-db8c-4d6d-b906-130b3968066a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 32).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a30edc79648a8530_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('030c252a-8197-4004-a9f5-6ba8e01d2438', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 32).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ab0e9c0e600ef1c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('025fe895-518f-4b30-a658-9ff0ead23481', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 32).', '[{"id": "A", "text": "watch interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "show interface ge-2/1/3 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/3", "is_correct": true}, {"id": "D", "text": "tail interface ge-2/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7f501bfe14b1520e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7261e525-f80d-41ef-ac10-65d22b989027', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 32).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cab335aba5b87cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8c39f3d-62a6-4261-b2a5-7e6626278ac5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 32).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '72672208d8dcc5fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('184a99f8-eeac-498c-85dc-40c350b0b16c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 32).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '20740becc719a074_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11ecf9dc-a515-4880-b21d-30ff933ffa7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 32).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a15a93310c081048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b07d600-b571-48e6-ba63-7a4f647b9d2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.161.146.0/24 via next-hop 10.91.121.5 on Junos (variant 32).', '[{"id": "A", "text": "set ip route 192.95.6.0 255.170.176.0 10.91.121.5", "is_correct": false}, {"id": "B", "text": "set route 192.161.146.0/24 next-hop 10.91.121.5", "is_correct": false}, {"id": "C", "text": "set static route 192.161.146.0/24 gateway 10.91.121.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.161.146.0/24 next-hop 10.91.121.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dbc506cdefcee9ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('921fd8e3-a673-414e-a151-cdeb15b52763', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 32).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b4f35ae3c2aedd7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3488cbb8-7228-436a-ad9b-47a1db937d56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 32).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a74587b4b4593f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba6abdc5-4315-4f32-a788-21a7ff641351', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 32).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b47765bcafa9af31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('313ac18b-1b89-477c-842e-fb33420b92eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 32).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '44c763c8fb113903_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a78d73a-34e2-409d-b387-614a8123a28d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 33).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ff1474ee7f437d3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9620528b-d327-4ba4-a406-98c6c63169c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 33).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3edc702a29c4c755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('478eaf23-4f87-40d4-ac68-16010b89d360', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 33).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '729f0e1f1172b69e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d05caa4-edf9-4af2-b0e5-a2073ee0ca5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 33).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '9ffc1e19f2eb9150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e220dd60-e6bb-4988-bd96-10f31f9a4e49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 33).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5b8598daafedb4c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36d66cb1-bbe2-4be7-a7fd-49e7accde63a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 33).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b3f435a5e4d0fb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb8c1b08-ad04-466f-987f-e8bc448f8e59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 33).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cb21cc38147e3f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd856112-d5a4-4a75-b5d7-35f82dcbf614', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 33).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'af6e2758393bba3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34bf43d4-4e0b-4471-9f26-13ffdb59f9fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 33).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e7e59ef30a8ad45f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ff8d0ac-cea1-459d-ab4b-ff42096431d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 33).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '71d5bd0cb7e68eec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48561412-714c-424b-8a25-c8ce919dbd8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 33).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1d128684539a2f64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0855fbb-48a4-424d-b0b2-a9367dc27eae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 33).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ccc7c6b7c998760d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('390a86ff-63b4-4d3f-8629-c4c500c0d4f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 33).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f68e6cf75bf9822f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bad9318-8663-49fd-8c73-e7d69e3afc56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 33).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fd152cfa848ea9c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a2d97cb-1ff0-43bb-a32d-677749788173', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 33).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6a9b3f95ae6ff309_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c7866a5-e777-4ade-8b29-b3c24d5e0938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 33).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set router-name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ae871d1335de9433_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d0347e3-190a-4753-8a37-5c410ad4b4bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 33).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '102fbb460f5e347b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db1d7d4a-6922-4830-8828-9bd7fbddc234', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 33).', '[{"id": "A", "text": "set interfaces xe-1/1/2 unit 0 family inet address 10.219.63.1/24", "is_correct": true}, {"id": "B", "text": "set interface xe-1/1/2 ip address 10.219.63.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.219.63.1/24 interface xe-1/1/2", "is_correct": false}, {"id": "D", "text": "configure interface xe-1/1/2 ip 10.219.63.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '64af6b136249994e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93af602a-ec14-48e1-9c5a-ec93a0cd6ac8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 33).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '515e35b99ef22d09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2445269e-77bf-4614-a8c5-6997cd3d62fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 33).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'eab63df9d169d115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3c82afb-7552-415f-ba3c-a824f4a44efc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 33).', '[{"id": "A", "text": "tail interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/2", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '996c576fa9c52e29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1545ab45-0519-4f67-bdbd-d740553814d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 33).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b9cbaf1efdd39594_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90e707ac-ad3c-4b4f-9bcc-425e5c5018b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 33).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd8c74e6ca2d66c27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83755edd-2317-4843-8206-4bf0e04f8567', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 33).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'befa6b3d3c801005_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd360710-1d33-4185-9895-e43c24ba23a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 33).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fcfacd4a50b1be70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('575d175f-5df0-4afc-ab01-9bd6dd999fb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.76.93.0/24 via next-hop 10.39.204.5 on Junos (variant 33).', '[{"id": "A", "text": "set route 192.76.93.0/24 next-hop 10.39.204.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.25.6.0 255.252.203.0 10.39.204.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.76.93.0/24 next-hop 10.39.204.5", "is_correct": true}, {"id": "D", "text": "set static route 192.76.93.0/24 gateway 10.39.204.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '287af1bfab87a54e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56d609f0-988f-45e1-a78d-16b904fae848', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 33).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5614da9faec31a29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc1c522-a4dd-4cf3-92d5-dba59c92ba8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 33).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0420a1b38d1fe311_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('550298f2-82bb-4317-a9a9-369ee4a100d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 33).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4aaee16882ba15f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d462425-7ce0-42e5-9d59-23c590f6569a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 33).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '08060b7811af7ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8209758f-b41f-4c8b-b0a5-d14eede95ccf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 34).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '564fe0ff76e3d602_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96542dc5-dddc-4c37-9348-7425846fc554', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 34).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'be285d862c3f63ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b965dca0-5dae-48bc-a010-8178e5d9dafa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 34).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4e38d281fb2ebe41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f963a0a-e0ce-4d22-b3ce-6036d6eeb569', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 34).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '18ab0163a7bc666e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('869b6a83-59fe-4449-9dd0-55fd8c0640f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 34).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '7dd11fb53e67cf52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd655950-83e2-43ee-95af-7cb3983b0b30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 34).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'aebda6367b806471_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec5621e8-8d09-416e-b394-b413c2895ec3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 34).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f31619aa614abad5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e112fd81-915e-4fdf-83dd-18d09ec5414e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 34).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '07fe46d234fd02e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4edb5f1-2124-4e1a-9f2c-6d97afae2bc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 34).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dd4fdf4192d3bd20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af28694d-3d76-44a6-b9c2-e91ea832ed49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 34).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '407ca22c1eb9c9bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b9551b8-e2ea-48d2-8576-1dc477f0c5c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 34).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '64f4f0546d29e599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68290432-92f0-439f-a5db-7ae11a33107f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 34).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2c37321674577d2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6898b3c9-5e6f-43e8-8116-8b6c526ee82c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 34).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b9b0a9f772b27007_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33a73b51-cc8e-4e68-87d9-d5b566213040', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 34).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '70d59b4f336211e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccfd4d32-1da0-4df8-87c8-d831005bbefb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 34).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20bb7644d675c3c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6fc35a9-0c61-4056-b348-32ad49948503', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 34).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set system name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a79ae9c2762b5c0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84358e2d-0073-4230-b8d9-6a6e23d3307d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 34).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '534390411855801f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c55ee6f0-f4ba-4b5b-b1f9-03ee92941c5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 34).', '[{"id": "A", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.19.196.254/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/0 ip address 10.19.196.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.19.196.254/24 interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/0 ip 10.19.196.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '921f3f8264482645_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8205b5f6-e145-4b06-9634-32a478ffcc17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 34).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd76bd9f283079b58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9090bf66-16c9-405e-8023-3bec8f187566', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 34).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f0f7a6fccf707dc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f139bd18-0f7f-4240-af53-27efecf04b39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 34).', '[{"id": "A", "text": "watch interface et-1/1/2", "is_correct": false}, {"id": "B", "text": "tail interface et-1/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface et-1/1/2", "is_correct": true}, {"id": "D", "text": "show interface et-1/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '85a2b5c705e2745b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be300c7-c933-46ef-8de9-53c653338b55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 34).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '57a388b85d1b6993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a985e24-2ba1-4d31-a867-76a58aa6673e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 34).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '159c5e68a20a4f4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d2c221c-cb2b-455e-9e05-bbeac4c2ac79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 34).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '38fd701e0bcd81e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3cedc90-39ae-4c63-a9c5-e103097baad6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 34).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'af5be16d4d14eb9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f45a9e0-56d3-4d91-ac52-c04693361bf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.224.148.0/24 via next-hop 10.133.236.254 on Junos (variant 34).', '[{"id": "A", "text": "set static route 192.224.148.0/24 gateway 10.133.236.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.195.194.0 255.48.65.0 10.133.236.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.224.148.0/24 next-hop 10.133.236.254", "is_correct": true}, {"id": "D", "text": "set route 192.224.148.0/24 next-hop 10.133.236.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7b38185e8e396499_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5571bd0-d39e-4f72-8fd2-79450f9f7026', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 34).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9f2e20da40494d58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9714a2de-9526-4c99-968c-b7a88618c7ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 34).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a3aeb7f2150a2f22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1b54538-4269-42f0-9595-8a35b2e95ff7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 34).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b4f10cc898031689_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7602453-e9ad-433c-b6e1-296c947a51a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 34).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2ecfda554cb415b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b5db229-5ac7-48d7-94b0-c3dee46536ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 35).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f0fa3ce2027f3b8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('890e448d-ad5f-4f72-ba75-84188390c202', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 35).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '58656857d07f2339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65c4e479-732b-4633-b061-8d0c9370bc5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 35).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '08a03b2c75c0b110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f90da9d3-a6ae-489a-8e19-2b161f552efc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 35).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '9c707cccc5286d36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02209aa8-fa3f-4e25-bd3a-56a352cb5bdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 35).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '47f5ee6c733bdf36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0a3d843-ee5b-45bf-841d-7896e4ac94c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 35).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f8aaa581169609e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf6a859d-0f96-4497-9ad4-72db0a881aac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 35).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b968b263fdc500c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a77793ae-731e-4896-9a06-433e4369068a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 35).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8c893d120957d31c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3956e93b-f95f-498d-9063-14b3a7c76731', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 35).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e988f58b6f25fbbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d52eed-ad64-459c-9da5-98acba9e90cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 35).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7588c0d360aa26c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c34c36b-5727-4979-824c-b2cf1ed57e09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 35).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2f64883a89d52449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c2ca402-3106-431f-9489-b859bf08b026', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 35).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6b584925040f531b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dcdc526-a586-4b0b-ac5c-18293aac201a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 35).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1081fe516f791c29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c32a7f1-0797-4a30-9970-4cbd3996704b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 35).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bd408b226b0f6c36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93fb8087-cdb9-43ef-a814-b57ee833f9e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 35).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'eb2bf2feb130f573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d234f76b-0c98-4f60-9ca2-cfa46756c712', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 35).', '[{"id": "A", "text": "set hostname R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1441152a933af566_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe1b1190-f89f-4b12-b387-97a19d11d2d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 35).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '467cb3d312b854e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fec4f04-3a01-4440-beaf-0830d5bf4e9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 35).', '[{"id": "A", "text": "set interfaces et-2/0/1 unit 0 family inet address 10.153.218.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.153.218.254/24 interface et-2/0/1", "is_correct": false}, {"id": "C", "text": "set interface et-2/0/1 ip address 10.153.218.254/24", "is_correct": false}, {"id": "D", "text": "configure interface et-2/0/1 ip 10.153.218.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f5947872736eae76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('006b0c3c-3467-47a7-8d50-76bb03caef03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 35).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7d7d8f5eefcadc10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4818fb89-dc14-4b1f-99e8-01567b67c148', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 35).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6577bf7da6c2f583_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58f21235-87f7-49ad-aeb3-9ae885d0e952', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 35).', '[{"id": "A", "text": "show interface et-2/0/3 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-2/0/3", "is_correct": false}, {"id": "C", "text": "tail interface et-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '007eebed71b20d0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c527b99a-b030-4cdf-9e42-0421b4a79d8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 35).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '92b2284d6ffaf909_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7788c958-7d7a-4783-9a46-5a59eab322ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 35).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5be83123ae4ad9d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3437393b-9a59-4161-9525-0cef4565d0a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 35).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'faa9f9d28bdd9420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd95b0f1-6656-47ec-b9d9-dd5bedb0e3ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 35).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '001f38f35e317116_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a007bfaa-9ec0-4883-82ce-76fffe567544', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.25.186.0/24 via next-hop 10.24.34.5 on Junos (variant 35).', '[{"id": "A", "text": "set static route 192.25.186.0/24 gateway 10.24.34.5", "is_correct": false}, {"id": "B", "text": "set route 192.25.186.0/24 next-hop 10.24.34.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.25.186.0/24 next-hop 10.24.34.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.25.65.0 255.95.208.0 10.24.34.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'db6377bdda1c663a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0f4942d-5e23-4fd8-b333-b9ba159987d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 35).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ee7fcbc4e3bd8b88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c638666-2358-4eb2-a649-4cb9706a35ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 35).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '207d4a0cbf424a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58412647-e463-4f28-96aa-02b80dc6486f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 35).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8030bda2b11e3a0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('219c9f81-56c6-4b32-98cf-b4b9c6a65376', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 35).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '32a7f10fa0e1d246_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb40895-484a-49c0-9f48-d3ce175da1b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 36).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'daaf44fb3155175e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c67f258-cf69-4771-84ea-31bd8a3a7871', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 36).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'b30437989b32d77e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdd46399-1e89-4b4e-a0e0-c5a2f8bd84ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 36).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'eee17eb3802e030d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('670904b4-b44c-45c8-9dac-7c0eaa362007', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 36).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1396673ca03a45c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d694e4cb-a136-4473-9e25-91cc7cedac7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 36).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '40cefa61fc525573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070acdb2-67d3-4327-9972-a6077bb3b15a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 36).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2dc6207fc9959a41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('402a43a4-605f-4640-8e50-ee602ff3453d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 36).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '66ead7dd74009041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40a60889-a9dc-457f-a217-0646f33b19c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 36).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b6411dd0410d199e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('115232d0-482a-4a0a-b612-2c28941ed455', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 36).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba70be45fcadbb8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccff4a0a-8408-4877-87ea-9cc2cf04f211', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 36).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c2a0d88b8cc0c0f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbf26b0f-e6e8-4fdc-ab2c-29c431d9c27e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 36).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b36bc107887221d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94373bf7-21f1-4d79-abf5-461abbc019a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 36).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15de4e57fb6ef643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78851997-e508-4a56-81d7-e556960dd3f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 36).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd2b2d153c49e82d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c9c9fe9-1750-4659-b16b-a52489b15025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 36).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1438b5584f1de85a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbd06685-2b8e-4170-a08e-38f3df4b5195', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 36).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a06ed4fe6510199_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b5f2f7d-402a-434b-818a-ae6d6d475488', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 36).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set router-name R12", "is_correct": false}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set system name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '52c157c809893b90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('974f4dbb-0d55-4853-bcfc-c5ac18708ff1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 36).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6e00c98964af6889_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('283b8789-017a-4fef-992d-b12fe7361474', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 36).', '[{"id": "A", "text": "set ip address 10.148.13.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.148.13.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.148.13.254/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-2/1/3 ip 10.148.13.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6a4c90b7594ed2e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91695fee-50e7-48a8-a86a-10e5d6b5418a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 36).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd3061cf1b4bb1f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dc26d53-e3ec-462b-8360-8cef24e00ba5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 36).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '51bdaf780f4e30da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dad608c9-5797-485f-817a-be838f5ee1ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 36).', '[{"id": "A", "text": "monitor interface xe-2/0/0", "is_correct": true}, {"id": "B", "text": "tail interface xe-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "D", "text": "show interface xe-2/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c36641536142317c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c44bd4-d8bd-4799-94c6-ba5bd3f79591', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 36).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2294bf994feee263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea73d020-0d59-4a85-8e99-35d49238a26b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 36).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '74916cf230f3b894_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('780cfa79-2206-405e-8e27-f2168622a3ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 36).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e6eaf8c8b48a8ee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d721ca-5323-4438-9ff7-372627571950', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 36).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7c8caf96e6e16296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1ff6de9-41a2-43b1-929a-690ed6d21bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.160.187.0/24 via next-hop 10.195.104.254 on Junos (variant 36).', '[{"id": "A", "text": "set static route 192.160.187.0/24 gateway 10.195.104.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.160.187.0/24 next-hop 10.195.104.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.229.178.0 255.198.224.0 10.195.104.254", "is_correct": false}, {"id": "D", "text": "set route 192.160.187.0/24 next-hop 10.195.104.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e785d9b2775c5c77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f55046cc-d8bd-44ed-baef-ccff61027db1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 36).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '6c328bb0651609d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ad2abbb-d87f-4f80-846c-ad6d37734479', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 36).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f492bcca3c143917_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66742832-3069-4b78-bba8-ae7495a054c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 36).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ed7a900a27e8b313_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a160ae1-25ae-4c57-a158-0788e74293b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 36).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'aa1629018db1c969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcf6ed26-d8ec-41b9-9e69-b800ed3a8b1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 37).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1bb51b5dd7a8beb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b317ac81-55eb-4bf2-a05f-6c195919c7bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 37).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '051825ac1054cb6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('603d8b15-c613-41d9-a62a-1d99f0fd1d84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 37).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6260aafd9ea2cc8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('878bc2e5-3091-4aef-bbf7-4b0e0081e4b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 37).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b00740ae390c840b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5986c79-1cee-44c7-90dc-26314dc62b12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 37).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '50be4f6fe7a97580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6659d63-dcc9-497e-8562-319862f0dbaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 37).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '607ed4cd00e3a05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7883b16e-3098-4b9f-99c0-604a2f176658', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 37).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8cdd3bd16bfb5ceb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c1f2871-0f23-4f4b-b170-b06e0cf40364', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 37).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '68112a676c7bc251_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c261ab2f-4bf2-40e6-84f7-8c90191ef6e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 37).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f6c9900cfdedf11a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('002cae40-2afb-480b-b345-363ab209621e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 37).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8b8428dfe4daa457_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03cb130f-4936-4798-9887-5c0fd3060259', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 37).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a4b3d3efe2bf305c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31ae86d5-8b5d-4b7f-b7d9-f692bd5d260f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 37).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7b827f0449b6d691_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58150f73-ea40-423a-be3c-fcba37d050f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 37).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a9b353dd3b7e3d89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9807d14a-7639-4d25-8363-fc3b847e96d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 37).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf6805dd094c776f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaaba940-1ab9-4a7e-8abe-4a30b6d464a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 37).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '22dd93ba7527aca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f87047-7838-4a18-a739-32cc82c9b906', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 37).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set router-name R11", "is_correct": false}, {"id": "D", "text": "set system name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5a3c674e1ee11094_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa5c50f4-982c-4fa2-abfd-9fb3c6e1df58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 37).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '322d6300210c707e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a84ed35-5dc7-43d6-b277-c40bfe0c9681', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 37).', '[{"id": "A", "text": "configure interface ge-0/1/1 ip 10.156.222.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/1 unit 0 family inet address 10.156.222.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.156.222.254/24 interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "set interface ge-0/1/1 ip address 10.156.222.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8bdf34d055f45b57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('811c1697-7454-47d6-8bc0-a4a0ad993943', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 37).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1a6370b2038b3a0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7ca2a90-f17d-4e3c-abe4-22f2ba6be6df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 37).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5280a891dfb13649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0daad0eb-95e1-4661-a0c3-46c6ed4f6160', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 37).', '[{"id": "A", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-2/1/1", "is_correct": true}, {"id": "D", "text": "tail interface et-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd3af8656a0182f72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05df297b-cc3b-4aca-b173-4d6babb81293', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 37).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ecf08d018e33a342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e09b960d-3b6d-4664-adc8-25bb73e12e45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 37).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a16f6f41da0c5db1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a18ce6-6609-4d37-83cb-8fc7d8ddc8c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 37).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8b53fa8cf28d31f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17e991ee-ca3a-45b6-bcfe-7a9c28baecd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 37).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fbf6b9319987694c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('162cee31-47ef-4160-944a-54bacbf1b796', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.7.137.0/24 via next-hop 10.32.96.254 on Junos (variant 37).', '[{"id": "A", "text": "set route 192.7.137.0/24 next-hop 10.32.96.254", "is_correct": false}, {"id": "B", "text": "set static route 192.7.137.0/24 gateway 10.32.96.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.11.127.0 255.232.165.0 10.32.96.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.7.137.0/24 next-hop 10.32.96.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ed18c4bfdbf0ff36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f55a667f-af89-4d81-b9a2-edab1a14af1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 37).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c25d5c5fb6525c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33cdac88-e302-4344-b6eb-2d6aa62f8ab9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 37).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9cb82954699d25b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ac5cb52-cf0f-407e-a32f-641c5ffb3794', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 37).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '60f45cfe63ad86a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e86fca8-b9dc-43c3-86d1-f5b4d0f6bd7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 37).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2c9c3144ef29bff4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b81b214-0b14-4271-a11c-9be77669252c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 38).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ad1fdb74db6b04d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f23818a-a542-40bb-bd76-08befb43fbc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 38).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'de2015168105fe31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e544a64c-dcc9-4090-9c46-91633424ff48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 38).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '77533efadfc4bb3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c024302d-572b-4ef6-8266-75c24b210174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 38).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd0bbbc1412195a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae2d5c45-96c8-4a6f-9252-b55e3501b459', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 38).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5a823f10c58bf619_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e00f4bdf-8ab8-4838-90bb-d609ea797715', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 38).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ed65a80c125501cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ceb36e-95f8-4e07-9570-3e5b56f6b1a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 38).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd8dfb5fe231246f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe376ea2-fba9-4b03-a327-f2fcc4852388', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 38).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34e8fbb0569c1587_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30231ad5-6031-4777-93f2-26586107afb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 38).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eab66ca1465b1939_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec23ba0f-ef6e-44ff-bc5e-eead40e5a5a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 38).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a73ce5bf2f8bbade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('933e7e26-f635-4ce5-a955-1af3a880f481', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 38).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd898290f848d97d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8cc4f43-2739-48e2-a8aa-2bfdbe396a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 38).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dc0dafc73b4dde4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43230501-2ff5-421a-88b2-5a9e59496091', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 38).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'affa9a8acd678e2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2648cef2-08eb-4818-ad95-f6211bc65245', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 38).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e618d750f29f2212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c52a268-5806-4c0b-bc6f-9ccd4569c003', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 38).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f2ad38a9e3dac1f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01f79b34-a556-4632-ad3c-d32325f8cb22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 38).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set system host-name R4", "is_correct": true}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17b20c87f936c7c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a89a319-451f-46cd-996b-407cfe2fe025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 38).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0ccfb1e643ff8fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08429c5b-b2b3-4d01-89e6-b010b77e3d56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 38).', '[{"id": "A", "text": "set interface ge-1/1/3 ip address 10.109.156.1/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/1/3 ip 10.109.156.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/3 unit 0 family inet address 10.109.156.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.109.156.1/24 interface ge-1/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bc0b4914224ee117_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dc287c0-8008-41ef-bd7b-32d27f57dee1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 38).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '28326929eae5ed1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b54b65c-b318-4d6e-aa59-90ff847c75f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 38).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bdd0c0e7264a0110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78813535-9b2d-4ba1-b73a-be43c438edc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 38).', '[{"id": "A", "text": "watch interface xe-2/1/2", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/2 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/2", "is_correct": true}, {"id": "D", "text": "tail interface xe-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a4dc24f2a3748150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14cad7ed-0272-407f-81e3-edeb7f0431a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 38).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5d9897ad674eb27f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8c0f5c3-e5a6-49de-ae71-351332f915fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 38).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4c508ffe8e426e17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('176aa3a4-af68-4756-a205-97530b3dcd61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 38).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f0b7b038cad129e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9df36dd-e8d7-440b-b4a3-11bdfb200e29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 38).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2c28d9eaeef16d8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00da3d4f-b7fd-4e07-bda9-8d6e023ff7b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.250.173.0/24 via next-hop 10.21.95.254 on Junos (variant 38).', '[{"id": "A", "text": "set static route 192.250.173.0/24 gateway 10.21.95.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.96.170.0 255.26.198.0 10.21.95.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.250.173.0/24 next-hop 10.21.95.254", "is_correct": true}, {"id": "D", "text": "set route 192.250.173.0/24 next-hop 10.21.95.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd92002b0fb4c53d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18954183-aba3-4c97-9bab-3802ac3ba0ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 38).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3b985d2315f0766f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('701b2c2f-ca58-4a4b-a040-3d659cc5a694', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 38).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0bf60ec9784d5985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('042f84f4-fb01-459e-b9ef-9132e1257a80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 38).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7de09488f1313aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4a2397f-ad2d-4775-a70a-50224866d475', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 38).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '239c5c089251723e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee8e6e55-2c2a-480a-9da1-edf9b87834b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 39).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f43e35618b219b76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c8fd2c8-42e8-496b-adc7-41b6e0e663f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 39).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a113e02eaad904c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6b961a9-882d-4500-a5b1-33464b1f0785', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 39).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e1259211cf0a87c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daced8ca-73f6-4c5b-8f13-7ec9f6d2354d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 39).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '60777cb0020fc2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a433bca-68a3-4457-a5f1-d549ace9420a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 39).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2d8d26d9dce245db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('399f93bc-f4e4-4cae-b9c5-9e6e92048e42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 39).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '997e72fce7553261_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e724e0-f04f-4a76-95ed-f737ff8a8325', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 39).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '045627b406ab063d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda259f8-14d2-4e2f-8e3a-ab5cb96334b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 39).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4deb11e67d5eae7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7667df33-c683-46f2-8e6e-2afb1085649c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 39).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7cbd78c48506de43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eaa9340-f444-4f2c-97e2-f13a8d0e0c62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 39).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3004cdd30c7434ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('955fb7e4-691a-49e0-b16f-5fe9a864e8ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 39).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'da64dc6aae93b91d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3744d77a-7406-4f1b-90b5-8c730254d44b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 39).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0e54e44ffbfae9ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ad8eb1-c280-45fd-b7b7-d58e86671a8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 39).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2b4ddacab07c74eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5e02e81-4fe4-4b65-b30e-80eb4dc759be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 39).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'adc59d05af30189a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ece04f68-cfed-4d8d-bf55-499201af3904', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 39).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5ad95c90b466aeda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7b02170-8589-4aab-9dcb-7aee771eccd3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 39).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set hostname R7", "is_correct": false}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'baf3b3280125c4a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a28b112-d69a-4c8b-87af-ca3e0288bd59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 39).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0e38448fc9087fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b060eb8f-8436-42b3-897f-8d34a17afd1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 39).', '[{"id": "A", "text": "configure interface et-1/1/0 ip 10.12.11.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.12.11.1/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/1/0 ip address 10.12.11.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.12.11.1/24 interface et-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9680762027b50423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd9f729a-ba67-40f4-bab3-ba3c51caa3cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 39).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b30793b6a39a2f0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58879137-4118-4f9c-9548-39c46b42dfdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 39).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '344092ce475c9895_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b6ea37e-f885-415d-9e18-dc81997edd29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 39).', '[{"id": "A", "text": "watch interface ge-3/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f517cd0b499b8d70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9085ee4-363e-4531-af3e-907e86ba99c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 39).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5abe88b2a75d8e01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59daa32b-f34e-498f-961e-24f0f5062e94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 39).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc1cf97828dd5da9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d326473f-9c7c-46cf-bf5b-98eb589dff7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 39).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '84467fb9bf05a639_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44a00df2-b84e-471c-8299-85762863d739', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 39).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '33cb2f41ed726e72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30cbf426-c618-42dd-994a-7d959415a0e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.41.118.0/24 via next-hop 10.10.254.1 on Junos (variant 39).', '[{"id": "A", "text": "set ip route 192.6.6.0 255.158.76.0 10.10.254.1", "is_correct": false}, {"id": "B", "text": "set route 192.41.118.0/24 next-hop 10.10.254.1", "is_correct": false}, {"id": "C", "text": "set static route 192.41.118.0/24 gateway 10.10.254.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.41.118.0/24 next-hop 10.10.254.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6f87259f5dfcf0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625b8180-e65f-4bdd-a2f1-e871d99d0fa8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 39).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a28099b2a2a6e8d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d3eb5ba-77a6-42a3-9e2e-a32b3e2b9bc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 39).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '7c96f9e3e8e933e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aa8f463-9bec-48e9-aa53-2ad4ac7c9c5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 39).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f1762f4e657e653b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7273992-87af-41db-bbf6-0c863059346b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 39).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8a323d70f8e2a83e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eec3ef36-0241-4a02-bdad-aaea460be6a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 40).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c67695e769433041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be896a86-d9ce-4344-8457-c32d88e1bb06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 40).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9f1e559e7eee1ab6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc1cbd6d-f97c-479b-bc8a-f232ea75089b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 40).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7ace83e4701d3db5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cb732bb-9f34-47d0-be85-33fb59cdf843', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 40).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b322dd87967dfc13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3c42414-c885-4d3a-a79c-68c5b3859422', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 40).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '110f0dd524297fd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6640f9b3-a9a4-4876-8daa-430fc4ab1ed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 40).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5948fcd48c14bc49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06f36054-8659-43a9-aacb-25a924e8da7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 40).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1623497d369491c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbfd38dd-6297-4d04-9623-4bec9c27b50b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 40).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '10443c257dea3749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78e57c9f-fa24-467b-851c-ca015867e400', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 40).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4dd5b130d02295ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de91aa78-fc8d-465c-9b59-5ae4be365198', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 40).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e68724940846026d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec95f57-4509-4790-9a27-dbe31bc79a55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 40).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '704896b4ff6cc4ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ac813b5-2eb1-4e9c-87fe-b8b8a5d68356', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 40).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8ca005e23feb646e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c8c008e-5361-4207-be27-90f26d015c3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 40).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f410097ced2b0915_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05e67121-9e20-4766-9297-f72a5a6f29a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 40).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '54c7529617a7cc2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b368d7f-bf39-4f6e-a906-22f11836b93f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 40).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bce561aba65fc1a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd9e5f3e-0527-4eeb-bb93-804c3a248dcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 40).', '[{"id": "A", "text": "set system host-name R2", "is_correct": true}, {"id": "B", "text": "set hostname R2", "is_correct": false}, {"id": "C", "text": "set system name R2", "is_correct": false}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8d523dc447c1d805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6b883cd-3c6c-42d2-8794-45081ba56460', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 40).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ed176c77e6e52b21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70df3f21-8e38-43bf-a2c7-575294d4cee7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 40).', '[{"id": "A", "text": "set interfaces ge-0/1/0 unit 0 family inet address 10.164.68.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/1/0 ip address 10.164.68.1/24", "is_correct": false}, {"id": "C", "text": "configure interface ge-0/1/0 ip 10.164.68.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.164.68.1/24 interface ge-0/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1cc497c215c99504_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d296431-1980-452c-ad19-1fb7120f8581', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 40).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '30b55deefef93e86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5735c8-6a56-41c3-8485-041927413489', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 40).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1ef88f13e1fb1011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5c3c39b-59fa-4e94-8fdf-7b888713a699', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 40).', '[{"id": "A", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e829a11669294103_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('974cb3c3-465d-42e4-bac0-8df1d4023fec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 40).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '20ccaa603e8310d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bc1c110-1eb8-4af0-a5c5-8cbcecd2f645', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 40).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'da39f4d3c2f59882_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fc6b37a-c770-4fa5-b7de-c3d1e346233a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 40).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '64530b7463107975_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99841856-8d7f-4dfa-bc9f-20c489a481de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 40).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '37975d669a4bd950_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ec66bca-6da0-4daa-88fb-cff4e8ec42f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.231.57.0/24 via next-hop 10.27.255.254 on Junos (variant 40).', '[{"id": "A", "text": "set ip route 192.209.172.0 255.130.111.0 10.27.255.254", "is_correct": false}, {"id": "B", "text": "set static route 192.231.57.0/24 gateway 10.27.255.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.231.57.0/24 next-hop 10.27.255.254", "is_correct": true}, {"id": "D", "text": "set route 192.231.57.0/24 next-hop 10.27.255.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3954f7e8de57af28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c529649-49c9-47b2-bc5a-bd30f68d0e86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 40).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd3597b4a3eeda5b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08b0d75f-064a-40a8-b3b1-eb895c6f3b52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 40).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6201a7f33f0bdf51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715ede38-4da4-4da6-8490-bdacacd661fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 40).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e6097baf54ad8458_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39432a60-e2bd-447a-81e6-59eecab3412a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 40).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e2df41d6c55d6d81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bfcf581-a2c4-4550-aac0-1f84a354018d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 41).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'aebd68137927eed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d54e7e1f-8633-4ffc-983c-367597a2eb54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 41).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'b4d973aa1b585294_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9672134-3bb8-4af8-beda-276c49a2be7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 41).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'cb60fbf26c563964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('053de511-7807-4944-a95e-9e5368dab485', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 41).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6ecd8eacfeb0bc75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('213b9f8e-d0a1-491b-bbe2-a26a90107fed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 41).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6b2423ff55e8c90c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e1f7f5-0e69-4e3b-9525-26a392b1aaab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 41).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '34aa67d036a0555c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('597fd60e-bcf1-4344-9003-35d5c6267e55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 41).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8250d96e60091323_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58185c1c-9fea-4ceb-8b3e-f08bc57247e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 41).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b2cfd9f942fa4011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1192b460-37a6-440c-b0ef-2102b1c78b39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 41).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '96671a638571b1c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5476b1d-6a3f-47ae-b971-b9ab62dc3210', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 41).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8ffc2ed80063a3a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7f54c09-0b14-449b-91d0-da63666cde46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 41).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'be9927412217fc52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4985560a-a147-4d5f-a2a2-23cd21be8b1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 41).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8e9ced2631d63e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('439eb348-2aff-4460-aba0-bf136ca2eede', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 41).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd517e983aae983bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21e59957-6167-4c31-b9bb-91a6a65be5bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 41).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bbd6ed80aac1daf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('430497b9-ddf8-4ef9-861e-407f739eef3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 41).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7419d2b6340e3661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f1050a9-da9d-4386-be79-a4f33ca8e9bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 41).', '[{"id": "A", "text": "set hostname R12", "is_correct": false}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set system host-name R12", "is_correct": true}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2390b2f926be3ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca4a1bc3-10c7-4de7-96b4-7f93330e3c26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 41).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b601c882c8e8cb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14c20aae-bcc6-447b-b1ea-2b72e266d684', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 41).', '[{"id": "A", "text": "set interfaces ge-3/1/1 unit 0 family inet address 10.133.161.5/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-3/1/1 ip 10.133.161.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-3/1/1 ip address 10.133.161.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.133.161.5/24 interface ge-3/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'be7ee7f9073de416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2525e68-813f-472d-a446-13f053ebd53c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 41).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '350087234d4cf3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('409b2a8e-6c7c-4a6d-86e2-eff732bf41ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 41).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '55822f325328b8f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18450c8f-96e2-44e9-9ce9-442f24649153', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 41).', '[{"id": "A", "text": "monitor interface ge-2/0/2", "is_correct": true}, {"id": "B", "text": "tail interface ge-2/0/2", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/2", "is_correct": false}, {"id": "D", "text": "show interface ge-2/0/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cc8c86c188c1ecd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4542655-5376-4801-a790-0ce0266ebbe7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 41).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6c934ba6595e4d7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd732cae-7670-4580-9366-3e51d8f4f042', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 41).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'abced0798b45bb3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64400a6d-d7c2-488f-b9c4-b1c1e9bf6bc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 41).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '71d6c8ff51ccd2e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc9cd6ff-52b8-4246-8acb-d1f626c75dd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 41).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6b6832d315ba24a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1022256e-ae75-4faa-89c8-0b8c8aa362ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.99.224.0/24 via next-hop 10.139.150.254 on Junos (variant 41).', '[{"id": "A", "text": "set route 192.99.224.0/24 next-hop 10.139.150.254", "is_correct": false}, {"id": "B", "text": "set static route 192.99.224.0/24 gateway 10.139.150.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.99.224.0/24 next-hop 10.139.150.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.117.74.0 255.245.118.0 10.139.150.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f67b62e51ff1698c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df9147f1-59fb-4d23-81e3-f34b47d9b014', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 41).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0c4b8cfd9f5b0e62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53677a91-b583-4307-bfbf-0eccaef27ab5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 41).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '88879aec03812863_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69842e88-e39f-47da-bd71-d187a613d99b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 41).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fe32a057b295c61a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('184f158b-3082-4db2-918e-7f1efcdbf559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 41).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f6389a3619c17665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a94f2295-0204-4e7a-bb7d-8aed2eba8fcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 42).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2826bfdbc7bcd222_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aa958b5-eb9c-47c5-82e1-e97f72db74ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 42).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '57c45f386dbce644_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e45d487c-018c-4977-9688-0b887bfa2f51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 42).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '3972323e747a5de0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ac56a62-821c-4475-9bf7-3caaa30b9fdf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 42).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '055d56f2b3bd1a3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8150bc02-bead-4847-ab55-0fcc8a2d019f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 42).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6fc706ac58568f6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9012a96f-9a16-43dd-bb13-e3a5d0591e8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 42).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '843261f3c1792923_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5755df8f-185e-4b92-be9f-a02519030ac3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 42).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1419bd2527557d03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e59789fc-58d9-4a12-bcb0-b51c191bc9f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 42).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bd32d7241db202fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afe853ce-f24a-4797-9a11-fff1a20785dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 42).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '74f06ae2eca3bd07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e37a6004-3f40-4e90-959c-c028e624294f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 42).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '730cfbca75a4f9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bdfc420-b4db-4587-b400-eb17d669ff8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 42).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '669354e2668b5d41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e48ac4d9-5598-4bcc-8726-8e8efd5d3d69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 42).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f9fe23b9072b343d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f4b6fdd-fd44-4b60-af97-68218f97ff12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 42).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e392866268acf149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4355fe55-d0b7-4722-8768-b8cfd85469b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 42).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7482be5700a69614_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2f09ac0-3a40-4510-a1eb-9fb005adbe7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 42).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f9735eeac2c0ba53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba4cba5-0686-4cfa-9ad8-e9850c34c4b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 42).', '[{"id": "A", "text": "set system host-name R8", "is_correct": true}, {"id": "B", "text": "set router-name R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8926f5f38dc0929d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac39f957-f1bd-4d2a-bb76-03f104746d74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 42).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5670bfd35887c4bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33d14c06-5726-430a-94dd-184ac725ad0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 42).', '[{"id": "A", "text": "set interfaces ge-3/0/0 unit 0 family inet address 10.104.138.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-3/0/0 ip address 10.104.138.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.104.138.254/24 interface ge-3/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/0/0 ip 10.104.138.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8cdb2875dd47863a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b2c99f-27f6-4b99-b32f-7786cec19bd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 42).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6ac322d296231148_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33e97326-ad36-4ca6-bab7-f0ae0ee193a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 42).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '556fd4f31b6c5ca1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a42e7d9-e4a4-425c-be7f-3bc1ed34764c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 42).', '[{"id": "A", "text": "monitor interface ge-3/0/2", "is_correct": true}, {"id": "B", "text": "watch interface ge-3/0/2", "is_correct": false}, {"id": "C", "text": "show interface ge-3/0/2 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-3/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '606daab09e15e05e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5ad0d96-fa99-49e7-ad8e-4f36aad3b4da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 42).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9ebd55837d9a2bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43a7dd48-5ee8-4c38-96e6-7fdb45216b0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 42).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '27a6bfc08ff116d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d06cc37-76a4-4c91-8c50-419a7943225a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 42).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '75d533ad0796e238_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd25c4b2-3d8b-45c3-b31e-81cf16c51cb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 42).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8c63bb13ed23d4ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdd56f99-9105-4baa-8ecc-aa7e34a026b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.63.234.0/24 via next-hop 10.106.161.1 on Junos (variant 42).', '[{"id": "A", "text": "set route 192.63.234.0/24 next-hop 10.106.161.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.90.7.0 255.169.227.0 10.106.161.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.63.234.0/24 next-hop 10.106.161.1", "is_correct": true}, {"id": "D", "text": "set static route 192.63.234.0/24 gateway 10.106.161.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'aed395f9a7a3a256_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab169583-8e6d-4abb-96e7-068b535d423d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 42).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f891736c44195132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df672642-dad7-4990-8066-634b55166ca8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 42).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6ed8a142a22d32e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76f8cba8-aec5-4582-83aa-94a576e1244e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 42).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd2b4e44fb2e1f560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24f58c44-a74c-43e9-96c3-28db7c128086', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 42).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '509f4792a5a0ece9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfcd52f6-0a58-46ae-8cbf-2af79f3cbff2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 43).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e80c207fdf1136c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b29acb43-e9cd-4db3-a247-5f081ce3a1d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 43).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '78c7e2b40223115e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb7d959e-4614-4aaf-b104-1e8e543eb0ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 43).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '8f5adb79d4c25a4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3141a5a6-dfab-4841-b05f-885c9176e74e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 43).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4dad89e80aa6f56f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('538789fd-5f29-479e-95b5-5c748977811c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 43).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e390d3e7c29009a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f3433f2-dd2f-4333-920a-bd7c854d5eec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 43).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '99b98c2388d31147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06572e50-32aa-4a0f-a77f-71a7dcfddc99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 43).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '09bdd4a57699f02b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('670dc819-588b-49af-9cda-195d6fa76ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 43).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad91fd69d4e6a6f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3f8ca3e-79e5-4260-ab5a-cbb4dc112f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 43).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2fd795081c52da99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a172a606-efd5-4eab-88bf-8a6be0ebdfee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 43).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8593b0bd9314d4bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf682bb2-6955-491c-8f0a-373582ee48e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 43).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1583fb204ee0ff2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01acb6d8-6338-4607-8d6c-cf782205e09f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 43).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '16b231bd6b03e5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6532d4a-f607-4f3e-9db4-faa36e9cdd65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 43).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '757ca1ee51ce3bbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b14c3969-3c85-4955-924f-136ca5e73968', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 43).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8858d7a1846bd46e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c372299-085d-4622-9cdd-117719a2f99a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 43).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5f4b97ab0a1e473c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2abfbf58-2d3e-47d4-9758-e91a0e58a7c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 43).', '[{"id": "A", "text": "set router-name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set system name R6", "is_correct": false}, {"id": "D", "text": "set system host-name R6", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0c64a7ab327c8544_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eebe5eae-c299-4e4e-8084-32eaf22a2c74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 43).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4cf37adec7ae83f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ff8b5db-5f94-4019-b326-fc32846da33e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 43).', '[{"id": "A", "text": "configure interface ge-3/1/2 ip 10.41.187.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-3/1/2 ip address 10.41.187.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.41.187.5/24 interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/2 unit 0 family inet address 10.41.187.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e154d4cb91d14875_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0abb52-39d3-4692-b1dd-14f3564a19d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 43).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '502c40319dde2ca6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5118ec8-d3b5-4c8e-8049-5019917ca381', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 43).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2a41870b12900601_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12c33e37-8f13-46c6-ae2c-867821c52fc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 43).', '[{"id": "A", "text": "monitor interface et-0/1/2", "is_correct": true}, {"id": "B", "text": "tail interface et-0/1/2", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/2", "is_correct": false}, {"id": "D", "text": "show interface et-0/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '32196056a4ae3b4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dcff02d-8bba-4d6e-8971-ac04882c81be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 43).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c816e2dfb03c42d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16f8e3ed-71aa-4021-92da-ae7bcb505ba4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 43).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2d020e1b18cfda36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fe8db1-bca4-4443-9390-45172bd40195', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 43).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8ce8d68505013ae7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73417147-fa90-4607-827a-f80506f7eed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 43).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '51b30deaf4b9011c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca57ad9-ccf5-4ef8-b961-916ea57d5c24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.13.65.0/24 via next-hop 10.165.30.5 on Junos (variant 43).', '[{"id": "A", "text": "set static route 192.13.65.0/24 gateway 10.165.30.5", "is_correct": false}, {"id": "B", "text": "set route 192.13.65.0/24 next-hop 10.165.30.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.13.65.0/24 next-hop 10.165.30.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.225.202.0 255.96.9.0 10.165.30.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '18eda53d959da50a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b5ef21-3133-4f7d-95bb-8e8e49b188fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 43).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '775bb822c81a1164_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9689a1fd-1d4b-48f7-aead-5c0ec06fa28c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 43).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4e07025a39e97478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('717601b8-1cc4-445d-97c7-2e99b0d6c2a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 43).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6fa22b8914e4841f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a35216-d8bb-4acb-b7b5-be65d5065f67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 43).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5df02dc87a254cb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09ea1efa-ed8c-45f8-aae3-05b193ff0af4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 44).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b8072222fa30fab1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('922c4d42-f346-4afa-9a0b-aaec3ebf441c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 44).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9adcd118049dec91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de696115-91a0-4e86-9235-65617e507eee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 44).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '87e2102bb58aa216_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666f4797-3ba0-4637-98ef-e10e79300d16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 44).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8c60e265f8ef5b42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41496519-7541-4553-a1d7-6805e8131a0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 44).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '9c2857010168bcdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c71dcc20-e2f8-43c5-b767-6ac8b566eb10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 44).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '42a6f517105e6b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d70fe5dd-1d7c-4985-ae6b-8da73e37e810', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 44).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '58799e4862e40cdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf50494c-7d9d-4d11-930e-914b29d664c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 44).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ae5bdf69ec63c919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38210a3d-fa30-4270-9fe2-e666661b4062', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 44).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd8fe7a1fc445f88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94797108-60cb-4417-bc76-9ce06cad7bca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 44).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '53743739cbd404c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93ca4cc8-4a9e-4c9c-b75c-b10fa5936c6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 44).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2a0d78e0c4931fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8615556-89a6-4054-85a0-49fd7fb372bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 44).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '31473b0f546c2656_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f236e89-c26f-425b-8365-056566c121f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 44).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '73ef5b5d96fa3ad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23dfefda-8af3-4bee-ac26-239020af4455', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 44).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '780444381d636568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('646aa704-d65f-49fe-b563-778f2c9fc701', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 44).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9eaa7793a2221972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f15e90f9-a145-4614-8b29-b027617e29c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 44).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '60c3c397ed12a6b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11947078-306b-429f-91f5-63ee505831e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 44).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '49432ff79ccb1687_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('badd7ec9-9381-481e-bb92-3492bc9d3a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 44).', '[{"id": "A", "text": "set interfaces et-0/1/1 unit 0 family inet address 10.111.144.1/24", "is_correct": true}, {"id": "B", "text": "configure interface et-0/1/1 ip 10.111.144.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.111.144.1/24 interface et-0/1/1", "is_correct": false}, {"id": "D", "text": "set interface et-0/1/1 ip address 10.111.144.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'aa4cfe75fc0d85c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0dc713b-d785-4795-82f6-08ad9c1b57e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 44).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '21590eb4f81d8079_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7bd93b5-468a-446a-b96a-6ef3d32dd2a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 44).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6675633d9f18036b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84376072-25bf-42fb-9044-1b89def28319', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 44).', '[{"id": "A", "text": "monitor interface et-3/0/3", "is_correct": true}, {"id": "B", "text": "watch interface et-3/0/3", "is_correct": false}, {"id": "C", "text": "show interface et-3/0/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-3/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b2a5243525681e9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5ab9d98-2365-40a8-b308-50b5963425f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 44).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '62e202330666b725_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779da877-c0d4-4fe1-a561-f905ac67709a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 44).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc162e1387148cbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c47172d9-047b-4fc4-86db-528e768d6dbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 44).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '59a7e5ddcfaa2710_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33395aea-0a83-479e-b906-d71c0cf6a902', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 44).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cd1f76cf1594f1c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55f02a79-e375-4ce1-aebc-78aaf21843fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.251.169.0/24 via next-hop 10.32.252.1 on Junos (variant 44).', '[{"id": "A", "text": "set ip route 192.105.10.0 255.89.194.0 10.32.252.1", "is_correct": false}, {"id": "B", "text": "set static route 192.251.169.0/24 gateway 10.32.252.1", "is_correct": false}, {"id": "C", "text": "set route 192.251.169.0/24 next-hop 10.32.252.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.251.169.0/24 next-hop 10.32.252.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '641f773ece75e21d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('978cbd75-f167-4169-97f8-4bca69b88e17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 44).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '511ec671eae7778f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dd20ad6-1a01-4717-9819-a3cc1052ef4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 44).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '61eadf30d4ad2911_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e64e2371-3895-4f72-b753-2d0b5b5cbd39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 44).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f6a964d406e81577_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7539cb0b-2f6a-4310-bff4-263ed77796ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 44).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ef3e7cca6c1b6e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4f43dc4-9310-495c-ba3b-39e3f29ed47b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 45).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '44f1c3e0f03d645c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be43247-3452-4b8d-8056-27b61dd98514', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 45).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4594fac049bce26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdad6bf7-ea97-4c82-9fb2-1cb8f7563e67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 45).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '19d8076e880e16bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f06972b6-2b3e-4f11-9cbd-fd0af1a2a4c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 45).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'beaac2189f7505a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eb32dea-5f26-46c7-a0af-e7b09c2a9fe0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 45).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '515048d9758e906f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b85a0fb-0df7-43c3-9e60-02a7774ed825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 45).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '472cb45ab035f432_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d23990ed-2351-4bd3-8976-98815631fd49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 45).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4f73db379962b175_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5ebedb-80a1-45e9-88e0-0361b7596159', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 45).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0e1c9b481d4848e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b9c4e6-5576-4ab7-a858-5069dd915023', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 45).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4570a13f47eee6d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1540e560-ccec-41ea-a4f6-55894c1d42b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 45).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '656add1834e09075_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4500a90-d0d1-41db-bf00-5b89d4aa55ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 45).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70a6476c3c2d23ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bcf45a0-b18e-439b-810a-ad25c1cbf66c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 45).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '231928b714037319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3c1fdbd-1566-4e71-a778-5c446cd74e9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 45).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e38b729b3d2be819_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b262b0ce-38e4-48fb-b4de-e5dd161a6f0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 45).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0022508636d6b2b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('044bbd3d-83bd-43a0-897c-7729f7dbd24d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 45).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9b6d962b1b9b4697_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d59f25f-2d9c-4728-a988-da40ba7cca37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 45).', '[{"id": "A", "text": "set system name R1", "is_correct": false}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system host-name R1", "is_correct": true}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f0f77a12067b24bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2030edb6-697e-4fe9-8171-8bc9aa47947c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 45).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '57c3cd59a919438f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2b54b7-ee00-4a02-abb1-d5e12fbd81fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 45).', '[{"id": "A", "text": "set ip address 10.105.49.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.105.49.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.105.49.1/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.105.49.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a1b985016267af94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2677e3a-605f-40f7-aadf-3c4882f169a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 45).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '83837b4817494452_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb727e8-9b6a-4d56-8721-4f6675d41f4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 45).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2e8f869c54bc99c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5169ce-59a1-4ec6-adfc-b4c229efb79a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 45).', '[{"id": "A", "text": "tail interface ge-2/1/1", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/1", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5a5474f8d4666465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3b25b4e-8b8a-4ac5-b7e1-af4192cd069f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 45).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '96dfb1343df68729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cfcf8e6-714e-4558-8211-fec5637e60f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 45).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bb2f618798b74c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c75ba53d-57af-4a5e-a8e8-30c2ea64e8d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 45).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'cf4073ac95f0187a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c5f38a7-6bb8-4036-9433-c156095d965a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 45).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9a2ef8fe68bf01b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45a79578-2d09-49e6-ba32-f5f363034081', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.60.169.0/24 via next-hop 10.115.67.1 on Junos (variant 45).', '[{"id": "A", "text": "set static route 192.60.169.0/24 gateway 10.115.67.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.200.173.0 255.163.93.0 10.115.67.1", "is_correct": false}, {"id": "C", "text": "set route 192.60.169.0/24 next-hop 10.115.67.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.60.169.0/24 next-hop 10.115.67.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8dd7c639cb1a1e9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08247c77-0f0b-4253-b958-1987cd5ecc4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 45).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd10fbe47081e18b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e1c45ca-482d-44aa-97b9-7dafdfc1fead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 45).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '45f325b212bf3596_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fed0d45-a1a0-4db1-981a-dba731251468', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 45).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7fda4a7a7c42d4fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f18cacc-7828-4a12-9b3f-870dbf19855d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 45).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5e2e2674dfb50da8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a74ce68-4e52-49d6-86c1-d729fd44007a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 46).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '16c6d847ede6b034_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddadd432-f314-4de8-aa35-b250685d704c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 46).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '522e4246c05262ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df2cfe1d-d9cb-4bd5-801b-d0201eb717c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 46).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ae8b585d14658d8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbb09dc3-2510-4216-a585-e5bf24ca29c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 46).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0afc42a44ae886dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d2b901-4047-4525-814f-e5ce35071876', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 46).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '380db82c2448c7d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f0394d5-ca5b-49ce-b9f0-471cd7e0cd06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 46).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '969442802cdd129b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b7d7513-bd72-4979-98f3-8bd50c96835c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 46).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b45ec243820d2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef73b1b-0a8b-4673-81d8-cd0bf292db42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 46).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ac0496731c8c8054_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfd9a6b8-ee33-4e51-8015-44e9087f2f31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 46).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c25fcd8c5ba2c3f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ce010d1-c80b-441c-b9aa-cc7414bf9766', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 46).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'dcc0fec77655face_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6052eef-334f-4e78-9b1d-ca500e5acb5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 46).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f27771910da00635_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d47e6ae7-102f-4d53-a0f2-31b4b0b7a856', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 46).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f498176c875ac388_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13d7e9d6-7657-49c4-9bb8-7029c6b431bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 46).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e8fcf2c15a178ccd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77bd7db9-0591-420c-a467-cb1eb5fe9af6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 46).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '69ac9a68ec24cf17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e50acbc-c0d1-4530-93a9-efe8d974453c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 46).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '807a084252a6afc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f821c5de-1e29-4b60-ae83-9db80efd743e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 46).', '[{"id": "A", "text": "set system name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set router-name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8a338d914da10199_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75d2047c-ef2d-4e4d-8555-9e3ba66b5a3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 46).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ceb223adc84e42ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df66fce0-7d86-43f0-903d-cd4546c6c912', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 46).', '[{"id": "A", "text": "set ip address 10.79.144.5/24 interface xe-1/0/0", "is_correct": false}, {"id": "B", "text": "set interface xe-1/0/0 ip address 10.79.144.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/0/0 unit 0 family inet address 10.79.144.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-1/0/0 ip 10.79.144.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '13946cbe54d56022_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c3deb2-aaef-486d-89c2-be0e7b18445a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 46).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '536c601819afde3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5882bd00-09aa-452a-91ae-17abac7a015e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 46).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd6e182735a7ea858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77e63ea9-d178-46ca-b2ea-c965007b82f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 46).', '[{"id": "A", "text": "tail interface ge-3/1/3", "is_correct": false}, {"id": "B", "text": "monitor interface ge-3/1/3", "is_correct": true}, {"id": "C", "text": "show interface ge-3/1/3 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb75e0f65e949e99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade6d2cd-4fda-490c-9a08-8b38f3b54a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 46).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '343812b5c5432296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6841ae1d-c7a2-48a4-a696-5749235605ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 46).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1619bd7346049085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4f6c4e3-bd39-4fa7-ba13-66ece6d10716', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 46).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '33929b97eb9b3c97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('559f6ecd-fd30-43a7-a1cc-d721dbff8231', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 46).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c1674ef11d889cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91872c2c-1f98-4aec-a635-8069ac82eff5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.219.115.0/24 via next-hop 10.216.246.254 on Junos (variant 46).', '[{"id": "A", "text": "set static route 192.219.115.0/24 gateway 10.216.246.254", "is_correct": false}, {"id": "B", "text": "set route 192.219.115.0/24 next-hop 10.216.246.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.25.21.0 255.28.155.0 10.216.246.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.219.115.0/24 next-hop 10.216.246.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd2cc3adff8df5692_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55b3128a-8ca7-4a31-8b18-aa852ccff5a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 46).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b808678fcd57fef8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0a0614c-97ef-426e-bef2-e189f43631e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 46).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0dd438fe6cec807b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f77c63cf-11af-4bb6-9c6c-87c5c16a2d79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 46).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '022e1eff7d8e3c3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0526ee5-6424-47cc-a11c-32b7b698e793', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 46).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9e1497fae1ea7eb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2dd48c0-551d-41a3-a988-d23ba3aa66cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 47).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2d4c9cdcee2859bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a4fa707-68e0-43c4-aaa4-5d33b165a687', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 47).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '02868800f9fe8c33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a833c4a-28fb-4cea-b36e-db432991ed9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 47).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7362757678cb0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7d7034d-0684-48e8-a73a-2bb64c80cede', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 47).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e944e7168c8ef261_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19d487e0-d671-44cf-abd7-1dea0cec344d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 47).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'dfb7b7b559fffeaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('579c6189-5f28-465d-b202-827190c363f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 47).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c6c22d6aa03bbeb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523865bd-cb67-4ea3-8ac5-4cd0fb002a44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 47).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2c9255b45a79a617_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('175dcb6c-4faf-4f2b-b3b8-4017bc413d7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 47).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65329453e5e5da23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1903395c-b850-4a62-8d5f-db10ccd26c65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 47).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4c805b7a985c3372_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0703e17d-50c6-42d2-8f0a-ea6838c8abe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 47).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e1de42fd24c5dd14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('187e5d95-4aad-4f28-b4b8-0a2566a6178a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 47).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '115f62e3aa894b51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4bdd1c4-4ea4-43fb-987d-98d7962eb8a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 47).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a720b8d9c4d33e14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ddc2526-e844-40b3-86a8-ec27c70b2ee6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 47).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9cc599154d0a5a41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92be22b8-122a-44ec-803e-e6d5c13adad5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 47).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f7e155242adda584_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('154b393c-3ff9-4582-9b13-e718f6ed51f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 47).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '58bf11c536bcea88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea0f5373-0482-41c9-b209-e99e200c1770', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 47).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '497583c7018e2bb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7987404f-ec1f-4052-9f33-3c1b03d580cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 47).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '133a8263219718f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e200d99b-e4a1-49a9-8c55-79e4535e6d05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 47).', '[{"id": "A", "text": "configure interface ge-3/0/0 ip 10.54.23.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/0 unit 0 family inet address 10.54.23.5/24", "is_correct": true}, {"id": "C", "text": "set interface ge-3/0/0 ip address 10.54.23.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.54.23.5/24 interface ge-3/0/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '289ba17afc20c2e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b5b6c01-eff9-4f4a-85a0-c1e46b3d7619', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 47).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7f48e70d52dae27b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68dc5a73-0fea-42f5-8d41-4e0a6544a56c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 47).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c463b595ce81929f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed567085-9a82-47f4-8d9d-bbeb32944d9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 47).', '[{"id": "A", "text": "show interface et-0/0/2 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-0/0/2", "is_correct": false}, {"id": "C", "text": "watch interface et-0/0/2", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5bf95a26a21f23a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf9c33c8-7ded-4ddd-b1f4-14a68be36aaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 47).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8d51c044c13a8eb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6d7529a-00c2-4f26-aceb-d09055f15073', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 47).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '316a0065ffa952ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dae1fd0-f5ec-410d-a3bc-1af4b9d995af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 47).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a3c32763d6e723e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f30859f-7e6c-4e0b-ac28-8bd4bb473a33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 47).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e82553dbb7adb597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2297712-4a37-4a38-b03d-308e975f1cff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.3.114.0/24 via next-hop 10.95.248.1 on Junos (variant 47).', '[{"id": "A", "text": "set ip route 192.127.139.0 255.92.160.0 10.95.248.1", "is_correct": false}, {"id": "B", "text": "set static route 192.3.114.0/24 gateway 10.95.248.1", "is_correct": false}, {"id": "C", "text": "set route 192.3.114.0/24 next-hop 10.95.248.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.3.114.0/24 next-hop 10.95.248.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd42c76edfd0c3e48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39e79c57-f4bb-4c67-9825-96e9153b6dcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 47).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4214c57457cd772b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f164a89-8605-46ff-9536-1e5c5fd94248', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 47).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cdb161d1ab2f4cdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfce569b-b635-4dd0-bbd9-52f600ec641f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 47).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '79f0743d8ba4bac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62c0a981-6b54-47d0-9a41-e3bf05452ea8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 47).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9f6bbbe4dc37c4d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1134c40d-d136-46a7-88e5-6880ea41c46b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 48).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd6c9958448155770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddb67356-20b8-4e99-957d-2c93f2be119a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 48).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '87c769d80a67273b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bffaf39d-f662-4879-b6bc-7343071831b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 48).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '00b945511a8cee07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a92b4a1-d960-4356-abd5-50e314b93ef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 48).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0e51cfb4014ef643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c00b33f-7531-4b4b-be04-6236204e066c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 48).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '702e0df0d97676ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4aeb63c-1c10-4ff2-8997-45f7d760d862', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 48).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2db9b26a155d8f37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb7a880f-aa74-4179-9e41-40c2d8159d20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 48).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2a6e3133c81349f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92c760be-fa7a-4fb3-8c53-8f0c35871f2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 48).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f6868318c993d0f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83f7f90e-a276-4d82-94b6-14576cd85a6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 48).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a252556fdd41a4f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9cbe70b-f289-48af-9872-eb805ebb1ae8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 48).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4ede5528caa1a031_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34917784-d1e1-44b0-8f81-9d96716e43a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 48).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e24ee5604434d00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1514b93-85d6-4509-8817-5d2d29eccb65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 48).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd754787184d27eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4d51684-5f3e-4b9e-ad57-075e5bc75545', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 48).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cb163dd084396e48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20041c33-008c-41a5-a62c-b5b136c89151', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 48).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b00ba8290e78eeba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e415b39b-e23f-421b-898c-fea571b98c06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 48).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '524a9e2670871cf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe00b71-f170-492d-96f4-2df0308922ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 48).', '[{"id": "A", "text": "set system name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set router-name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a349b0147ee1d322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4292e86b-eb10-41f0-ad16-b724dcd99317', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 48).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '05a9110cf3f6127f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b7e35ff-5f41-4cf6-be70-55aafd65d7f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 48).', '[{"id": "A", "text": "set ip address 10.108.167.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.108.167.254/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/3 ip 10.108.167.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/3 ip address 10.108.167.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f751caf50425b425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0f81708-bfd5-4c45-96a6-95bc303ca05e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 48).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8b7a696de68db6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85742d26-e3b4-4b7b-8647-83116da13a4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 48).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1fbcbb8e3709eeb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a93bee-aaaf-4990-8774-7ef844172b2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 48).', '[{"id": "A", "text": "watch interface xe-3/0/1", "is_correct": false}, {"id": "B", "text": "show interface xe-3/0/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/1", "is_correct": true}, {"id": "D", "text": "tail interface xe-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd7e33e52f1a0ab14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b2d7984-bfdd-4df0-9f92-2e0593d806c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 48).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '24b1ac6fd0ef0a1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa855857-154b-4a6a-98fb-b0f1f011a4de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 48).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '713c11800ae3b3e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4263e537-5d2d-4593-8981-9867558122af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 48).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4d8ad1f50df64f05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('432c3adb-d717-441a-862e-80f3498749ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 48).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7777eb3d25d3a38c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52b3cab-5990-46b8-9b6a-5e2b1e7a78e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.246.221.0/24 via next-hop 10.22.209.5 on Junos (variant 48).', '[{"id": "A", "text": "set route 192.246.221.0/24 next-hop 10.22.209.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.77.45.0 255.116.20.0 10.22.209.5", "is_correct": false}, {"id": "C", "text": "set static route 192.246.221.0/24 gateway 10.22.209.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.246.221.0/24 next-hop 10.22.209.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd88ec2ee3d9a9e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c42d70d0-c2a0-47b6-aeb2-f0d502836a1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 48).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5221c5ccf624f545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('166e2deb-2eab-4e15-b7ae-b91e9e3936b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 48).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a147157fde5dd3ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04d3166-190f-40ab-8fc0-a2ce2cd5c05a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 48).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9e2d2f6354313034_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59f6b429-7cb4-441a-b77e-baa72c311757', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 48).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '488096cf7e0529d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c269242e-348f-49d1-8d50-31936efcf2a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 49).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '960dcb2d7fe92b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cd51f9f-7e31-4bfe-95f8-8a94481706fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 49).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '87f151f2f24ab163_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc487cd6-e736-4a98-b008-8d6943dd382b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 49).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'bc8b7b9b9ff3552b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad2d6f40-6d5c-41b5-9b50-b8ed0b6a87b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 49).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f8f8e0c12ec4e3dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45fbc22f-2fc5-4b37-a1a9-8a3729f0b3d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 49).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cc44128d7404aec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70b1cd68-13a0-45bd-bdba-2db4bf11e350', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 49).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9fb8a74f23c40a7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54677844-237c-445d-a35b-ea5ae4aa3ffa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 49).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '54225d53d37c60d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb22b1de-8c6b-4323-bfaa-822120d3a14d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 49).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7667a5599ede9f36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b787693-45b9-4cb8-8ac7-231319f55396', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 49).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e0851f7ffaf46793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2f4f548-2756-4b1f-bd4a-4511e12f88e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 49).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '23344a7f624d9a09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779eaf85-616e-463f-b930-a832de792083', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 49).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0981e4248d858dc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12860d38-9033-430e-b285-91d4ff7b8dc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 49).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '16bcb165e2505322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17ab673a-b571-4e85-b743-69d18134da9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 49).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0da274aec2b3adb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8fc5985-3c95-43a3-b61f-0263d50a67ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 49).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca97bd6cf88354ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40947c26-2083-41b9-a817-179815f432a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 49).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a38357f0e9656206_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bb20d54-b2da-4ebb-964e-06a2a169c8fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 49).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17db3af3b4033c18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a53603ed-fa4a-4d24-89b8-fe3416904b9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 49).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9a57f6437fb53896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7104280c-0303-4929-88ea-bd857ce83b50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 49).', '[{"id": "A", "text": "set ip address 10.52.105.5/24 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/0 ip 10.52.105.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/0 ip address 10.52.105.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-1/0/0 unit 0 family inet address 10.52.105.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd8aa0a7625680bcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbd42ab8-acd1-405a-9b58-e601ce73d544', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 49).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b5b0360bdb7880fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7791c84-4ca5-4206-bcd8-3e1aaa5d1f01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 49).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dd10ca1263adf3cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f310c021-d0e0-4072-ab7a-036b8fbc918f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 49).', '[{"id": "A", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/1/1", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '957d0035a4959801_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f6f47b-5434-4702-96ca-7a8e4d1bcbff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 49).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '92a8f402cde9ecde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4d817b4-adab-4549-b52b-c683f51a2726', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 49).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e9a4dcdd1b7604a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('639afd3b-0854-4f8c-b47f-7b110b6043ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 49).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e4c98974416ca25d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc391a47-1347-4cf1-a659-100f800fa015', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 49).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0f8e4c1e7bd2d2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3918c681-b19c-4fba-991e-ff441669f649', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.115.121.0/24 via next-hop 10.39.36.1 on Junos (variant 49).', '[{"id": "A", "text": "set routing-options static route 192.115.121.0/24 next-hop 10.39.36.1", "is_correct": true}, {"id": "B", "text": "set ip route 192.9.153.0 255.247.30.0 10.39.36.1", "is_correct": false}, {"id": "C", "text": "set static route 192.115.121.0/24 gateway 10.39.36.1", "is_correct": false}, {"id": "D", "text": "set route 192.115.121.0/24 next-hop 10.39.36.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7b8ad35dacd6c196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc337a01-13ce-4d99-93e9-c035e8eb971e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 49).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f38cb30806f9e1b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('457e1030-cbda-4d14-81f9-86ff0d8ee8d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 49).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '949c61df87cd3f06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e42a5349-507c-439d-9607-50f34a559c90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 49).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '85e168a47284aef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a536618-7042-4bd1-8e40-2ac38388aa22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 49).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4a733437c972d0e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1f6007-d3a7-4512-b4f5-13c41f085127', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 50).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5cb9ce7e16e58bac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70da7900-a5aa-4395-9882-bc0b59bce7e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 50).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'cbe5a9d153f54caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdeba412-003c-427c-ba17-0993f07b729c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 50).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '02bed67229d0fb87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5371286d-c08e-452b-aee1-4f7e263c790a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 50).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '38fe5b679999e5ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5904e9b-b3ab-470d-a2db-4a84799bead9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 50).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '940e30d6f390130f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ddf7e45-aef0-43af-8a9f-faf7b148427b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 50).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b24aa80e7133183b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bffd122-f854-4c99-bbd7-3d28ce94afd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 50).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6b02b2988444b933_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a379d27c-5e8c-412b-a4de-8d8e92aa7b4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 50).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '521a0cabaee9bf35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c8ef38d-b99c-4eb5-b988-4d35c8ce6505', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 50).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '151bf40b29420896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be40f91e-a001-4216-b127-9f82f8ff5011', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 50).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7977fbe54d27a37f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('109c380f-7dbf-4e13-9552-38f96bbc67f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 50).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6cf6dc0ee14a6788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bea4e4d-c9ae-4767-a7a0-58dc638883ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 50).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '60358c8fe121f5b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b9665eb-1bfb-44ac-902c-d97aae1d3524', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 50).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ca74a08d256ac528_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('800a1265-88cd-4fb5-a02e-b1e8cd005b7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 50).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e8458f8d45af9eab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb9bfdfe-94c6-4752-adda-80fdf76a2fb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 50).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '948cb0b82a75d464_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92110213-80cd-428a-a958-2f62a29df5ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 50).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4dc8a6a0ebda73fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('710968b3-001f-4e26-ba0f-368471ede301', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 50).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'effcdd668e9e6185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ba57f67-02a3-4f33-adb3-c4b48634c60d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 50).', '[{"id": "A", "text": "configure interface ge-2/1/3 ip 10.174.139.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.174.139.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.174.139.5/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.174.139.5/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fbb2957730f8e321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b8f302c-d70f-4519-877f-a6c988400035', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 50).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '261a3fe5d6c2f7e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d05051a0-9f7e-43f7-ad5c-af0e600a2c11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 50).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8a902c1ac4d2a3a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2febb285-98e8-42f1-a1f2-88b5fb314f2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 50).', '[{"id": "A", "text": "show interface et-2/1/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/1/0", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '00edc48d54e1d188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('429d57e9-d1b1-407e-a0f9-54d1bd404197', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 50).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6dc8c676ba3e2692_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe363e50-14bb-4b34-86a0-c76dbcb7d786', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 50).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '37e9fbcb7b0a741c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cfa880b-6d85-4bb1-95e4-142bdd74fb04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 50).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '68d4c435543d8242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a56eb9c-bd36-4b7c-8235-95407f25c50d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 50).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e84592d33fbda333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be751c13-f059-4037-84fc-015599ef1fd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.101.68.0/24 via next-hop 10.60.237.5 on Junos (variant 50).', '[{"id": "A", "text": "set routing-options static route 192.101.68.0/24 next-hop 10.60.237.5", "is_correct": true}, {"id": "B", "text": "set ip route 192.251.116.0 255.252.179.0 10.60.237.5", "is_correct": false}, {"id": "C", "text": "set static route 192.101.68.0/24 gateway 10.60.237.5", "is_correct": false}, {"id": "D", "text": "set route 192.101.68.0/24 next-hop 10.60.237.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bad9c14dc4be598e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bca16dc7-eed9-45a4-b19d-8177cda70009', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 50).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4f3b78af872a3767_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28d40deb-4079-468c-9025-2e1e8c9522f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 50).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '408376c0e3560c82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df7aef12-6108-4904-94e1-a481608de853', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 50).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fba54a086c0f0a32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adcea490-f568-4ed2-bfa4-97193972adb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 50).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '369d00d48d63cfb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b86ee504-3857-451e-b97f-ada149e4d15f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 51).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f137779ca826d9d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('279b5b75-8fec-4da1-8ac2-889c30525a90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 51).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '780b5e56e514ee5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c61c30ca-bd9c-4b82-ba38-eff65aef091b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 51).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '512398e668dba1e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88722b83-99d7-4bb1-b81f-dbbc83a31c74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 51).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '02b36bc68120327f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc44d171-ea9f-4245-bce5-fb45de34c503', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 51).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '766c09173ac6f597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bba7780-71f8-48d4-8ea4-e637fc18882c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 51).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'aa9044209454358e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30ef867f-62d7-4398-8885-7cf06c4b9451', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 51).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3e67a362ab9c57bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ffa8a09-8fbb-40d7-9035-40cc91708fb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 51).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7dabea334638c338_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df15493-c43e-4e3b-9a7b-69f7e77b4244', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 51).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '76b49a319751f47b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935403a1-40f9-484f-94f2-aca0408bfbc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 51).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '952e705208c8dfbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50fd258d-8a3f-4a92-a801-bda0a2ede6f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 51).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '43de7a2a5f70cde6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf0157e-5620-4a6d-8e08-228f34bce6f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 51).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8b1afa7874040332_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1719628-2bb1-437e-8937-0b24675ad808', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 51).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '40a031b3a9340e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3023c5a-7abb-4475-92f2-777220e85102', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 51).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '07b5405761fcbe04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c03d0e-ff03-4005-98ac-40ef705561ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 51).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fe85d5a1a5dad84d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d51a924b-d231-474b-9946-0bbe7336d993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 51).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set router-name R4", "is_correct": false}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set system name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5c716fa07bee799d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ec5ca2f-a88e-481f-bb4c-d60a68b70d07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 51).', '[{"id": "A", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1466b54d0a599d30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cffd4322-cfcd-4c10-8e32-735af1d97f5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 51).', '[{"id": "A", "text": "set ip address 10.75.231.5/24 interface et-2/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/1/3 unit 0 family inet address 10.75.231.5/24", "is_correct": true}, {"id": "C", "text": "configure interface et-2/1/3 ip 10.75.231.5/24", "is_correct": false}, {"id": "D", "text": "set interface et-2/1/3 ip address 10.75.231.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8353321f8a01900e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8e41e8e-b20e-4dbd-ba18-b86322c6d36a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 51).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f4227e922d3d8311_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80c95289-0f16-488d-9d90-a8d9923f0269', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 51).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7dc3ad807800c65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0de52d8-48b7-4749-9d90-f01ccc976cee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 51).', '[{"id": "A", "text": "tail interface ge-1/0/2", "is_correct": false}, {"id": "B", "text": "watch interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "show interface ge-1/0/2 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface ge-1/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1ae48c943451ef2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64a07dae-eb85-407a-a4c8-96efec46a012', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 51).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ee311755a7034389_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2873aa59-1980-4ce5-8e10-b34dad036000', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 51).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c518a42b9ba43f5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f8b62a-0021-4afe-ac41-150686b1af4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 51).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fdb1b247c64737c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed48d0e-74eb-46f2-b5b7-011387eae5a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 51).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee27da184b4d9f55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4334dee1-13ca-4030-afc1-8660eb8e9d27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.87.198.0/24 via next-hop 10.98.33.254 on Junos (variant 51).', '[{"id": "A", "text": "set static route 192.87.198.0/24 gateway 10.98.33.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.87.198.0/24 next-hop 10.98.33.254", "is_correct": true}, {"id": "C", "text": "set route 192.87.198.0/24 next-hop 10.98.33.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.104.19.0 255.130.59.0 10.98.33.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '20b5a009daa4b4e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('632834ad-cf32-4a5e-a701-6525f5570729', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 51).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c31710f9663e85fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00315523-c2ba-47b5-9d7a-2dbf120a721c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 51).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'eea2122f4f1f466f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f52f9b8-6395-4810-aca9-74a40c0265ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 51).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '10188bb37c1f1916_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b1fd445-8ca1-4588-9365-d7f100b4fbc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 51).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8bece52db91bd6ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20d6dd5e-5ab8-4255-b49a-022664d328fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 52).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b48b2332ccc672f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80742571-81ed-4265-b7a7-47a7ac6873e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 52).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '586c4966a4b8585d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6796c0ee-beb1-41cf-9c6c-49e345008f84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 52).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'de7aa7b209e58e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f47366a-2657-4511-9113-f180c762b1fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 52).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1c59ea91b002f158_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15e6a9c4-da44-45f0-8a5f-2acdb159ce64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 52).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6cb013cea4a5e931_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f180273e-e971-478e-a736-13c7a56064c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 52).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1a5ea0334df65d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f8ae243-6a4e-4a0f-b9b5-ee5faebdb970', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 52).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8003fc4e02a42037_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acb27329-fd81-4b1b-9145-eacf862e9040', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 52).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9483d6cf2dda74e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af0afedc-fbbf-4961-8ca0-52bf85befe2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 52).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f1d8a5d26b7bcc0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ece46c7a-b30d-4196-b574-db237d3680f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 52).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6053c709e4785af3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ddbdc7f-bd37-4d55-9671-5874cf1f4aa9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 52).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2d798984c46eb016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('809dae82-8d60-4e0a-bbc6-b774740686b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 52).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '62b4b971a3bdf9b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98d7748c-ed85-4d77-a65a-23c34d4f6ddf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 52).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7cfa6b510c5ae74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fad25b0-6f8f-4daa-90a7-0282448d0aa9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 52).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6f46f6126378d006_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52f67b8b-41d0-4bfb-a6a9-266223f04bc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 52).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b450216116b3ffb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05213e54-2e43-4377-9f33-ff3054f91410', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 52).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set system name R7", "is_correct": false}, {"id": "C", "text": "set hostname R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cf4796ef729394f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76ba4c96-3b5a-4f8e-9fdc-de7270522c9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 52).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd79fa895b4b4117a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f32e66fb-41ea-4eb0-bbd6-36e15094017a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 52).', '[{"id": "A", "text": "set ip address 10.110.125.254/24 interface xe-3/0/1", "is_correct": false}, {"id": "B", "text": "set interface xe-3/0/1 ip address 10.110.125.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-3/0/1 unit 0 family inet address 10.110.125.254/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-3/0/1 ip 10.110.125.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6201acf93358b03b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f32dd2-9c8f-48ec-acb2-ccc840c9d7f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 52).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8bea4c20625da24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6b66015-3e1c-4313-8066-135299e155ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 52).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fa5e213c6df4d745_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d824d320-d348-438e-8551-ce02eaad213a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 52).', '[{"id": "A", "text": "monitor interface et-1/1/1", "is_correct": true}, {"id": "B", "text": "tail interface et-1/1/1", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-1/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '342a0da1ad548ad8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('331d51f4-4402-4507-8cc0-dc69fdc74993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 52).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fa365bdcb13a8b25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5510dc32-9d0f-4a81-b0da-890a25580b05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 52).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '69afef905e3e5771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee26900f-8f08-4bc2-ab1a-f1f86a575e45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 52).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '24754788dfecc66d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a9d6545-66b4-4a7a-9950-ac0ec9ef15b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 52).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9878dd6b97a97d19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca628623-fc63-4971-9fef-96addd805192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.8.167.0/24 via next-hop 10.181.59.1 on Junos (variant 52).', '[{"id": "A", "text": "set ip route 192.190.99.0 255.246.4.0 10.181.59.1", "is_correct": false}, {"id": "B", "text": "set route 192.8.167.0/24 next-hop 10.181.59.1", "is_correct": false}, {"id": "C", "text": "set static route 192.8.167.0/24 gateway 10.181.59.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.8.167.0/24 next-hop 10.181.59.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e55afe6660dac5bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2325a41-35ea-422f-86bc-2a07628d28bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 52).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '32c3b1a702c8531b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8fc4ab3-169e-46cb-b44d-8a32d03fd16e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 52).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e54bfa7f4ca6b1b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('198065b4-6164-4115-9a6d-bcf1f47b5256', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 52).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9dc2dba15179ca89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db27c2fc-cf56-495f-be19-a24761ae9448', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 52).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ad15ec589dcc414c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40edb481-1392-4cab-99f7-211783f7f957', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 53).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '465857c5d8c86556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('296c0267-0afc-4b96-95ee-e6fa8d041046', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 53).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '504281be9c9683fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dc798ca-3530-4ce3-903e-15dc55da4755', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 53).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9b6f0ac7602651d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa09868a-5142-4481-aeab-5fe68a7e1cf5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 53).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c16b51af7398e763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fddfffa1-6a32-4aea-9c36-6fdb53934045', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 53).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '91f87071a0532d88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c597b9d-6f9d-4012-bf85-426fe288ac92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 53).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '44568e0427eaecf4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc362d63-dde9-44b4-ac92-e22c7e245a0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 53).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '208a077edbd338f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae26f475-1af0-4e6f-ab0a-5bc565aa98dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 53).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '653ecf84abd762e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd45b01f-3921-49f1-9d34-6355bfbf0e91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 53).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f7030b7035ab2343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e50f15e-224e-4eed-a3f0-80848bf3be9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 53).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c5b56ff37e470c2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96c8bc7f-446c-45e4-bcbb-d5700fcdd2eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 53).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dc3a4c8ac5bf0221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c63e508d-b4d8-4a1f-9e27-a58d32b2d0dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 53).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dacb6eff5313183a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f333e71-0e6e-4807-a2a2-ff1b103a101d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 53).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '88ccc126dc273ed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37d4b37d-7737-48d1-a155-143a7b4beb49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 53).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fb2fbb1711419b10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84291b01-2f43-444a-ad7b-a9c567b10bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 53).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '788e4b312f7566a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('938996f6-3728-4b40-a33c-6c14faf6174a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 53).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set system name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set router-name R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a24c3ee33eeeb97e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b28cd46-d45c-41e9-bc76-f433ca71d55a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 53).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6bf014206569dac7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dbe3eed-9b63-4beb-bcf8-9eb14f1a5c38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 53).', '[{"id": "A", "text": "set interface xe-2/1/2 ip address 10.122.105.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.122.105.5/24 interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "set interfaces xe-2/1/2 unit 0 family inet address 10.122.105.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-2/1/2 ip 10.122.105.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1681b71db46ee144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01dd76c2-d31c-47e4-bc62-51f35feb1dd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 53).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9603f629f8d9cd86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80ee6c45-83a4-42ec-8294-e7d3b86d2b0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 53).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '650b51ff03cf4df6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dbcf29a-b2c1-455c-a87e-7e1a8b4efe23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 53).', '[{"id": "A", "text": "tail interface xe-3/1/3", "is_correct": false}, {"id": "B", "text": "monitor interface xe-3/1/3", "is_correct": true}, {"id": "C", "text": "watch interface xe-3/1/3", "is_correct": false}, {"id": "D", "text": "show interface xe-3/1/3 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '567fee456e39a3bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('905858ef-7a6d-4866-9049-0c6d2d808fe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 53).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c9e20beeb26ef891_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1faa0033-fc14-401d-b0fb-6b79a6c9c874', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 53).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e684bb206aeea48d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d2c7518-99b5-4f96-a601-2e44462e349e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 53).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '93210b1ab7cf1445_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284f7a46-ec15-4214-a276-e5d7f50c3ad8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 53).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5c7b921ac2db9c04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae81c4e7-016e-4282-95d1-5a9fea59331a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.140.130.0/24 via next-hop 10.80.112.5 on Junos (variant 53).', '[{"id": "A", "text": "set route 192.140.130.0/24 next-hop 10.80.112.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.138.137.0 255.36.100.0 10.80.112.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.140.130.0/24 next-hop 10.80.112.5", "is_correct": true}, {"id": "D", "text": "set static route 192.140.130.0/24 gateway 10.80.112.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '61209c21c0b72870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada58489-cfdb-4a41-8c3c-db90db4757b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 53).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e9d2df517e668965_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('765ad60f-0005-4f6e-ad36-6effe8fdb82f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 53).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cfb385e35e8a955f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46c44c68-25ff-454a-a0b2-5cab84f9883b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 53).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4d9426f08e96f55f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf9490ac-184c-442c-832d-d2979502092e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 53).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '34d7e419acc94efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9572641b-acda-4add-9e07-fbd97bc49dfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 54).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'eb0f99b2ad2e80e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0e54207-12b3-4fcb-b6c0-bbdda83143c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 54).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '95f6bf9fcfa0e755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69ca18b2-bda4-4685-9706-051f1795e5a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 54).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6fc490290601cd15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b420825e-80ab-4fab-8306-3a6b105cd0cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 54).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4b7831a3f25ea8c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d7c364c-933c-4275-8886-d2e576b99be1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 54).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1b26ee36a563241a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcb26ddf-c961-4566-b8f3-f593076bf16e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 54).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ff2cf68ec797e4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('346a9c22-dae9-4e0c-8453-fa7cd7b1bdbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 54).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '02b24d5b8d1e590d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d7303b1-5dec-4a5b-b974-638ff7bb2f16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 54).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1f72374c7406b5d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b495d4b5-f357-4b92-9597-9ea23bffa060', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 54).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5a95f6568db1583f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce633cc6-d9a1-435d-9eb1-892795800eac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 54).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '472809528e6b88e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71def3e2-1485-469f-8d46-c7254dab1247', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 54).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ded707963ff23e9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79ceb3f2-2fe3-448c-a13c-a6cfd7390d4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 54).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eaf6e47749c9d8e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78b237fe-a8cb-413b-a7c3-c6bc2c40fca0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 54).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8fe69d01a00f9ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2233f8a2-78c4-4487-afb3-85cc8dbbd50b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 54).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6da0ec9d9e7dd518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07397328-bbe0-4a6a-b56b-75d688a7d8b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 54).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4010383d835fb3d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7edd07ce-9ae3-4a4c-8149-017be0d5a8e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 54).', '[{"id": "A", "text": "set hostname R3", "is_correct": false}, {"id": "B", "text": "set router-name R3", "is_correct": false}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a8e404e66af755ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53dd1506-6893-4bc2-a974-d997f05e73eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 54).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f41a0c9232e4e592_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a1a2d85-cfa2-4429-b684-24e24ec34882', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 54).', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.186.224.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-2/1/1 ip 10.186.224.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-2/1/1 ip address 10.186.224.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.186.224.1/24 interface ge-2/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '90deede92dea1d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe86284-03c7-4f95-a2d0-cf985fb26c5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 54).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '90afada29910360a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60527c40-325b-4d1f-a442-e9298c381d33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 54).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8c6d0a3da306457b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdbaaedd-3cec-4156-b157-6d583b295207', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 54).', '[{"id": "A", "text": "watch interface et-3/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "C", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "D", "text": "show interface et-3/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ac788e46c74afffb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cdb40ae-7ea5-445b-845b-ceaab42d0eeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 54).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '74afd4c504adf51f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c7905e9-6e5b-4700-8252-a31d5745fb6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 54).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b1ef2c6d9a3ec27c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc326d5f-e5a8-4cc0-98a4-5a1409c2c9f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 54).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ee29ea4b3ec3d55d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3018f5d3-5a88-4b41-98cf-9d8afe441d1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 54).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '365f50463de485db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('274c0be5-8e36-4350-ba1b-7a277d6fe40e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.141.94.0/24 via next-hop 10.30.233.1 on Junos (variant 54).', '[{"id": "A", "text": "set static route 192.141.94.0/24 gateway 10.30.233.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.141.94.0/24 next-hop 10.30.233.1", "is_correct": true}, {"id": "C", "text": "set route 192.141.94.0/24 next-hop 10.30.233.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.35.14.0 255.103.252.0 10.30.233.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6052b8cb00e9a89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd09060-3afc-48f6-bd9a-818ce1901374', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 54).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5b0492d808c5af04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbf9ca28-6c9c-4713-aa69-8cc45352dbd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 54).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8dc57116750c8c65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1b4b6ba-310f-4efe-8ec7-3dac17309d3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 54).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b5dbd8996cfa1291_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a8cc70e-ccee-4af2-b8c9-71b36178815f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 54).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '038411c05bb5d3a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d95e963-53b5-4f95-adb2-fd79e08d43c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 55).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b5ec99f894f3e138_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74cc316b-cf72-46fc-a4b0-de561eebc065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 55).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'e28d15a46f15267d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d07591c-395c-43db-8a71-9ac816c88402', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 55).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '73d9a706aeae85de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c121343a-faea-4e79-a3bf-bc7e8b1bc6ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 55).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1b641acb8e8ba76a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf1e5d4e-e204-43c7-818d-3a718b432c89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 55).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '8f0da22abb1b9144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a2af5ba-7ea6-4453-ab1f-30a9eca239b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 55).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '53cc95208eceb536_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a253191d-0531-4c6a-a2fd-e7c916edf820', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 55).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a8ab1b91e8cc5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d83a067a-5a3d-48ea-bd2a-ea1920b06335', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 55).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '771a9ce3c8998e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad7f236d-2ff7-46da-9b82-4b489ddf1d28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 55).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9f537b05f09022a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5489f0c-f8e8-464e-baeb-9df43840f664', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 55).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f1d4a05d1794b794_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('597e6444-24bf-449f-9ef2-f0ec1a12224c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 55).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'db6ffeef34777a90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5420c9f-37a2-4482-aea0-0290661a4ecb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 55).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f0aab7af327f4f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8a3cfe8-991c-46f8-bf78-c69069d9f471', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 55).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8b1c46bc7021129d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd4f2588-b044-4ff4-aab7-f0f6e7c6b7ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 55).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7a02ba1c60ec69ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('934e9c03-70ed-4b6e-bbcc-73130740a033', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 55).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fbea241370b5d99f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50e0f3ea-d573-434e-9723-2ab7d1205f19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 55).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a41de81026dcb0d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f3080a7-7372-4ec8-8245-959739bdb403', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 55).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'acbb5207c8cce013_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16729ccc-93ac-4d30-aedb-266cc00f226b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 55).', '[{"id": "A", "text": "set interface xe-3/0/2 ip address 10.177.235.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.177.235.5/24 interface xe-3/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces xe-3/0/2 unit 0 family inet address 10.177.235.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-3/0/2 ip 10.177.235.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fd76457b30fd7c14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47fb05fb-d7f6-45f8-8653-988b6cd20e0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 55).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '63d56bd2241f83f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f724b99-46f0-4be7-9b97-b5f8ffb4536a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 55).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0adc1d67afcb42b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82d42bda-ff19-4e73-8b50-779fcbf19418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 55).', '[{"id": "A", "text": "tail interface ge-3/0/0", "is_correct": false}, {"id": "B", "text": "show interface ge-3/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-3/0/0", "is_correct": true}, {"id": "D", "text": "watch interface ge-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'def1645d20dd5fdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc2d63d4-e1f9-4452-acac-49f04ad5fc9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 55).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e0f99239ca73fa9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b3ed818-025b-4592-94ba-9be6e6897caa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 55).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '321d9d13eae12b6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c25bca5e-2985-4b56-950e-1220e9c69fb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 55).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '69752ea3f45f3af2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a6a101c-e39a-4621-81ff-7adfaad85478', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 55).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9fea9048f7786ec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15dd0839-9a99-40fd-81ce-b67efa520e40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.248.56.0/24 via next-hop 10.55.225.1 on Junos (variant 55).', '[{"id": "A", "text": "set ip route 192.163.160.0 255.245.126.0 10.55.225.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.248.56.0/24 next-hop 10.55.225.1", "is_correct": true}, {"id": "C", "text": "set static route 192.248.56.0/24 gateway 10.55.225.1", "is_correct": false}, {"id": "D", "text": "set route 192.248.56.0/24 next-hop 10.55.225.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '800672628b5b81f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbcb6c17-ad34-4a87-9a6a-a3a69e1140bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 55).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '71e3564680d7e121_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9feca895-6776-41b6-a5ec-a9b7d354ffa2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 55).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9a8a546658df2d7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d51ffb5-7f06-4f48-a024-79176f846d4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 55).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd23c664b7954799d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e2bea5f-1b01-465d-b146-1faefb8474e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 55).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0a7174c3d2233053_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b1fda16-481c-4f33-b22c-ed2455d11107', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 56).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8309a634142077d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9923e0fc-bd23-47eb-8442-ee11cc4f5ecd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 56).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4ae1fc4b8ffc2864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c7ef9fe-fbde-4083-a508-07018072a736', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 56).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '5aa9e34dc219e869_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74dd3bf6-a489-45b1-95c8-ece18e53e070', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 56).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4ed941a3dd2d7f0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a3f174b-9a1e-4e50-9f7f-39a580709068', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 56).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b537ddc338277324_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cccbed46-6966-4c12-960d-08ac6560ee98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 56).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6d55e199b7b38caf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('734f601d-8029-47cd-81bb-4775a0a8ab30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 56).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b58bc87de21e440_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ddaaf68-02c8-48f1-a214-134ad9150147', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 56).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1a3f3d5ab9ac7afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('208a30fe-c8bd-4f27-93c5-3f971ac70f11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 56).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7ddc8eaa261eabb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('081dca43-e334-4abc-ab72-aa318f66b2a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 56).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0dd5d2492709b080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1726935-54d8-462f-9ce1-fb5bf4b0531a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 56).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '373fdbbcb0a64858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3037ad93-32d6-446d-b46b-3a6ac323be94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 56).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ff25e41a26ffeaab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84ea78ae-45e7-43ab-a884-6bdfc02254c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 56).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '37f382d99741e1ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c84df48-5674-48a5-b57e-4fac18c9c887', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 56).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c674f758a33afc90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e48e76c3-e11c-4355-9d39-226f16a6c2f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 56).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f00a514139e82e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610f3ebd-f5f0-4b23-990d-a74b84ecfbe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 56).', '[{"id": "A", "text": "set hostname R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '38c6067d0d52c386_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d1489af-f4b7-40b9-ad13-9f6101918bf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 56).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd80d37a548dd8cc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0836206d-dc25-4c87-b025-1c8da68a04e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 56).', '[{"id": "A", "text": "configure interface et-1/0/2 ip 10.27.35.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/0/2 unit 0 family inet address 10.27.35.5/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/0/2 ip address 10.27.35.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.27.35.5/24 interface et-1/0/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '04f4f12dab2b224b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('960f0222-e250-4178-808b-6c0e2dadd63e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 56).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a2237bff6296fa32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f4f5e6-8e7f-4bd9-9ea7-98a58c471f75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 56).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '312924ecba2f65a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('794eed0e-7061-49d4-a647-c41ebbdbe453', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 56).', '[{"id": "A", "text": "show interface ge-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7d2ee3d56c9ad35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17f0aa77-ad54-476e-9de6-5b187ce26096', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 56).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b597d26bebac54dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5504730-7703-4341-989e-8d7d03e7e931', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 56).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '649f8166e7c216f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eb67c0f-c56e-4e9b-bb40-1e4b5480919c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 56).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b8efa3663907a650_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3380ca5c-4a09-4d8e-9cc2-70656d366ed0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 56).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'da24736a0a963c70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe759ee4-e820-4d6f-8ad3-04066a45a294', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.63.113.0/24 via next-hop 10.115.3.254 on Junos (variant 56).', '[{"id": "A", "text": "set routing-options static route 192.63.113.0/24 next-hop 10.115.3.254", "is_correct": true}, {"id": "B", "text": "set route 192.63.113.0/24 next-hop 10.115.3.254", "is_correct": false}, {"id": "C", "text": "set static route 192.63.113.0/24 gateway 10.115.3.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.217.151.0 255.46.241.0 10.115.3.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b015eac3f193698_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5a5fc49-0c78-458e-9c98-eb761c8d6f65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 56).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd8a597416b901ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b87fec2-d113-477e-8b56-0189d9b47623', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 56).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '295006abf550cdce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e0271ab-210e-4e47-a10c-3bbfcc0b35ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 56).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '349ebba719ee7f9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e67ae07-86f3-48a6-87d8-e0021627553c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 56).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '05357bbd96a5be99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8e8dd11-6dd1-41cd-9c3a-1ebda110a174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 57).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '59fffb19c28c1125_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('834c7e0f-0548-483e-abd2-e77b06116237', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 57).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'bfca893c6010bf95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('522cc2b1-a61c-4771-86e5-d186e1649d31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 57).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '110108498c0d07d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0fbbeaf-8771-42f8-9956-1bcec38e1821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 57).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '784bb804a9288270_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('318d831f-1957-4576-ab7a-095cefe42d66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 57).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c4a2a8f5123b1a72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3c74f1d-1399-4195-b9f2-43f1c0ff703d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 57).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a43f47dd5978297c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d2ee7b1-9bb2-4fb0-b6d4-3f4b2f221de5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 57).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5ff7af0474e59d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67828d60-407d-4be4-9bab-ab4439cd27cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 57).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '869c180c3b84b4a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5748f0bd-959e-4507-b483-d729ee4fc857', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 57).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bde9f08cceab91d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d5d3b34-50fb-486b-aebd-35765999c663', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 57).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a4e690f9914ae041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('161c69f4-7abb-426a-845b-c57cd7c5722b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 57).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2300cdb448ec1196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ad96597-aa02-47bb-a2da-765665e95fd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 57).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '454414a9a900f4dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca183d16-42cd-48ff-8d33-1c09d94a89ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 57).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cd13a476ec5c527e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4934c1e4-fb18-44a3-8812-56fe8f1efc4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 57).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd4f9f53fe38e4bb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65ba444e-6e22-436e-b908-bfead233b7ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 57).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9d692db0a2a784e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f88cd08b-0790-404e-a7af-8d45e93f9a9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 57).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set router-name R6", "is_correct": false}, {"id": "C", "text": "set hostname R6", "is_correct": false}, {"id": "D", "text": "set system name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9365600429c56eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('888bbe34-202e-46ba-85aa-14c216cdcb45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 57).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df262bf4c412bb99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf010078-106e-4136-96bb-7e3001187cf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 57).', '[{"id": "A", "text": "set ip address 10.41.110.1/24 interface ge-3/0/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.41.110.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-3/0/1 ip 10.41.110.1/24", "is_correct": false}, {"id": "D", "text": "set interface ge-3/0/1 ip address 10.41.110.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '10b4fb31f859b9c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96c213fa-8247-4940-8a77-9469baff8456', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 57).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fddcfbf70abaefc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a7f3f77-0127-484f-92a4-3c9f4bb65fa4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 57).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd332fbc70c697744_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cba3dd3-7000-40d9-b883-09c0cfc5d1fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 57).', '[{"id": "A", "text": "monitor interface xe-1/1/3", "is_correct": true}, {"id": "B", "text": "show interface xe-1/1/3 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-1/1/3", "is_correct": false}, {"id": "D", "text": "watch interface xe-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f551a7d43c52f0c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc465fa5-928a-448f-a876-e993f9014571', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 57).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b21c69994f46e77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd8d7540-b141-4972-9f72-6b0115e10b77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 57).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '22bdcdfbfe0409a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7a7ee54-4b70-40a1-97cf-851aee2bf221', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 57).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6996464880f658a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('275456a0-b5a7-40ab-b16c-a4e56fb25e8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 57).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '742d50ba357c3ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cd9296d-236e-47a0-bd48-4f8e6efb09a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.175.79.0/24 via next-hop 10.164.248.254 on Junos (variant 57).', '[{"id": "A", "text": "set ip route 192.165.11.0 255.74.128.0 10.164.248.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.175.79.0/24 next-hop 10.164.248.254", "is_correct": true}, {"id": "C", "text": "set route 192.175.79.0/24 next-hop 10.164.248.254", "is_correct": false}, {"id": "D", "text": "set static route 192.175.79.0/24 gateway 10.164.248.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6baa17f709d489eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdcdd972-923d-4bad-bfb0-d0e3907fc472', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 57).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '27fb80f3fa64c370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9240d689-1a53-49f6-8df1-bdec145550c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 57).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '768cbd8f59719419_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9bf5a4e-da2b-4777-a73e-9bb7a1d21a35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 57).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '296450775c9327a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('669e8f5d-94c1-4375-98a5-599d25a09da9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 57).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9802cd8fb36d771d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85a007c3-7526-46ba-9edc-e20529dc5134', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 58).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1bd0d7d00320d33e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef08a51b-916f-4641-ae6b-4a70fbcf8dd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 58).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'fe114650ce04ebe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef9d8995-68c7-4aa9-9011-3cd1005a000d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 58).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '30644ac86f9916db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fbcb250-4f84-4f33-b9f5-060c08e9297e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 58).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5e49884c3cbb2924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae37b59c-e8c9-4bb1-afb5-097a24743696', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 58).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '86cc1119bd3005e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce3637c5-3a6e-415d-9707-4345824b9dad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 58).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '50cc41b6a7ad77ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0df29b84-41dd-4d59-b853-9b8971f3d7d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 58).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e6f968350bc91ed7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7e9c13f-8974-4b99-908a-aee8095e0049', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 58).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '63f7b061fae656e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6414e3d6-55ec-459b-a048-a60c63496faa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 58).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28f337359763db1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e464f846-4834-4f43-ace9-a0686e30be25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 58).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2bf242d8ddb87835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('214e903d-8465-4ca8-947d-a489b0e02496', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 58).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9cd413e6c3e21d40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d99bec88-6a6f-4474-9fbf-5a486f2e15a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 58).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a2f3429db5bd199e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08a34aaa-105c-4ee5-8d05-2705075c119e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 58).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '77dbeada22ab8977_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a13d2b05-c456-4f97-877b-fc6a85d3054e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 58).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'aa1e3c1d6cfc0a91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba34763-767c-4363-b0e4-b78f9663ee68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 58).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4df5afe6c830be4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('476d2d3b-c1c7-436d-8a46-12a530940a35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 58).', '[{"id": "A", "text": "set router-name R11", "is_correct": false}, {"id": "B", "text": "set system host-name R11", "is_correct": true}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set hostname R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '75cd49c53b552c4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5862d57e-801f-45fb-b45d-9d770f265836', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 58).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '45ad7629d0cd37c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d928d8-5855-4c13-8d5b-4066a7102d1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 58).', '[{"id": "A", "text": "set ip address 10.162.123.254/24 interface ge-1/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.162.123.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-1/1/0 ip address 10.162.123.254/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-1/1/0 ip 10.162.123.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9770afb5773a3e44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f08420cf-919d-4387-a50a-4a1ce6f51f67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 58).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cfd6c53caf5bba20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc1284d6-3f93-44bc-b9cd-04e0f30df629', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 58).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '489dd92849c00c1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cd28ac7-a3b6-40da-884c-47086347b5c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 58).', '[{"id": "A", "text": "watch interface xe-1/0/0", "is_correct": false}, {"id": "B", "text": "show interface xe-1/0/0 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-1/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e8b1facb934ccd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fb52de-af7c-420c-9c15-2e444ff2873a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 58).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8cde564899f889a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34b49ce5-1226-42f5-a1a7-6e712a771fc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 58).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1c6a13041bc868da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df2fdccb-3904-427c-a956-39a45d24eac3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 58).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bbf5019cbd99f8fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('373a92e1-d6db-4732-8027-b7a4c443a489', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 58).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7d3679a0881f12ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5237147-1af7-4552-8865-0e57d0fbc4bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.57.128.0/24 via next-hop 10.86.37.254 on Junos (variant 58).', '[{"id": "A", "text": "set static route 192.57.128.0/24 gateway 10.86.37.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.57.128.0/24 next-hop 10.86.37.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.187.192.0 255.40.79.0 10.86.37.254", "is_correct": false}, {"id": "D", "text": "set route 192.57.128.0/24 next-hop 10.86.37.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '70fe7c77a1f886f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51bfb28d-ff9d-4287-8bbe-bb3074628089', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 58).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7a7e27b3236a8e72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a0ad45-c77e-4b71-921d-70468feedcc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 58).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '574fb24a0c95abe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b884c86e-1e7f-4097-851f-83c2ba20a67f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 58).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '35a1119ed98a5b7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1638583-5770-462b-943b-284dc221da1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 58).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c2577d4344ba32e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('685f3ebc-897c-4147-aa6c-0655068bfb57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 59).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7c9f5156a19ad5a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d47d75c-f746-46fd-af9f-8efae50e4b04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 59).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '50678b9d22fc3171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec1802ed-7195-44a6-881e-046238cd8713', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 59).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b639e8f0b9260086_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aea96826-889d-4918-8d99-16b8fffa7a05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 59).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e33e09dac3bf19fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e674956a-9b1c-4dc0-ab74-d6c9cc72e26f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 59).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '42520189973921b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54f1d409-a74a-480c-a623-a69c31949f8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 59).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b330e2b16586e073_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a68e7e5-036f-4cc8-8958-d309a0f69dec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 59).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44164ef67f053ee6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a2e2e0-dc5e-4e97-a5c2-64f928d239ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 59).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8a24415668c79a1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c837e7d5-fada-46cb-94f9-becf452a590f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 59).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eefe6fd507ebb306_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65897acf-f235-48e0-8531-f2ffdb8aa832', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 59).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '957528447c701a11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec70d7d9-6a81-487b-a321-872fdfe6f631', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 59).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '09732794f601d67f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8a2667a-50a9-43db-b153-c5959b46c16c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 59).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'af643c79058aa665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b3a27f1-eaec-49c2-b3e9-f908f55fa51e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 59).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '03c002e02d308168_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1795af7d-98c2-4331-9196-21a4b878cc02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 59).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7df4f32d2c7b7e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4bfe432-dc62-4274-8eed-9327d74772b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 59).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ee594147709537af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd84ecf3-9d68-4bc0-ba37-e7fc20542ade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 59).', '[{"id": "A", "text": "set hostname R7", "is_correct": false}, {"id": "B", "text": "set system host-name R7", "is_correct": true}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set router-name R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b7e0a2634bccc85b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df737931-8763-436c-91bc-a63900487b0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 59).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1652625628ae4453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae88f12-7ccd-4029-aa7f-adabd741e28d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 59).', '[{"id": "A", "text": "set interfaces et-1/1/1 unit 0 family inet address 10.115.249.5/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/1 ip address 10.115.249.5/24", "is_correct": false}, {"id": "C", "text": "configure interface et-1/1/1 ip 10.115.249.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.115.249.5/24 interface et-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a851ffdc223c215f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4612ca01-fd8d-4074-9129-97e1363cdbd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 59).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '013ca71c1e768c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0334eb0b-e619-4ab8-bb69-9589399c0a1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 59).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5122959b2a1b95c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14cc2ee3-249f-47c0-9c74-b7224934b085', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 59).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "show interface ge-2/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "D", "text": "tail interface ge-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9c030ad72937b325_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc5b9018-1e64-4ef4-930d-ed90ea828043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 59).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a2fa09b21d26a492_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab95913-d73f-40f9-9a30-78552b21f626', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 59).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1da3e844312464bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d016d7e-ceac-4562-9644-e133cbfe0b25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 59).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '80e9c8056241924c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc3464f5-0a8c-4f71-b3fc-ff456a1edb42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 59).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e2d11ecd626b0c67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7f6d9c8-73b7-4904-9766-d3190b30b07d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.172.70.0/24 via next-hop 10.129.75.5 on Junos (variant 59).', '[{"id": "A", "text": "set route 192.172.70.0/24 next-hop 10.129.75.5", "is_correct": false}, {"id": "B", "text": "set static route 192.172.70.0/24 gateway 10.129.75.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.172.70.0/24 next-hop 10.129.75.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.200.155.0 255.236.215.0 10.129.75.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '177a360e28208f0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d746e201-efca-482c-b91d-32f77d285f8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 59).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7bcc854a4deb7f7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dabf083c-8f75-40ed-9337-1c228e05d64f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 59).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b83f848eb039e2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a7d2fe-c268-4abf-822c-a00d52319f43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 59).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b84303c9967f37a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f6e7ad4-6e12-48bc-b982-a67661fd3e90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 59).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1143689699d98ab5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada713b1-51a5-4fa8-a359-22006ed67ecd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 60).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1031b9a084ac6db0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ce8b623-8500-4564-bcc6-770f1b4f53b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 60).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '2ebcb2701aef40e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccf62b32-3a6b-44ad-a5b0-1ce96d544ab3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 60).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7e418454b586e238_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2199a15f-bb78-42f7-bd5a-3a9193f90993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 60).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '093fe960c38b7efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f44e36-4402-448a-b5cc-25edbbcab795', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 60).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'ed3f07e0807a92fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a2e0382-a939-4ffb-9e0d-9af6b3ab466b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 60).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '96636b29f4b0a871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbf638a0-fa6f-4253-82b3-7c5ce7384834', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 60).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f7f5939e38b2fc5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('359f18dc-d7b3-48f2-865b-2edd94b1bc09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 60).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7e6bb27f95e45964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30042a12-0d4f-4c30-abb4-77fdf143cf4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 60).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c8358f7065d4b0e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc9453f0-8dd0-4b74-b02c-a936c563e512', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 60).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f73c0e30046c8e14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b177f83-0828-47f5-bd6b-8c7bcc9fb324', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 60).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b8b10e93dd0f9090_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6455cf98-465a-468c-b0c4-e927d7c5f2fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 60).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fff16dd56d44c4ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69664934-3e72-4e89-8e7f-5dec3bff6491', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 60).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '28783951c3f0eac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0fc2845-d97d-4dbe-8469-dee8041d297f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 60).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cbe3ebc97ce21919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b7cdb4-f30e-4c3f-aa1f-8c9f7a547244', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 60).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '652664bd478a7c96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfa790d9-53c5-4bd9-bbf7-3471ae148016', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 60).', '[{"id": "A", "text": "set hostname R8", "is_correct": false}, {"id": "B", "text": "set system name R8", "is_correct": false}, {"id": "C", "text": "set router-name R8", "is_correct": false}, {"id": "D", "text": "set system host-name R8", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7bfba884a2f1f9e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713159ed-3e11-4b72-ac9e-807304b7d464', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 60).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'efb938cc9744b5a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a99ac380-c15d-4fbe-b510-9fdca4aaef00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 60).', '[{"id": "A", "text": "set interface et-0/0/1 ip address 10.196.82.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.196.82.254/24 interface et-0/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces et-0/0/1 unit 0 family inet address 10.196.82.254/24", "is_correct": true}, {"id": "D", "text": "configure interface et-0/0/1 ip 10.196.82.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'cc6a4b9f8552c930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed8863aa-502a-4c89-b915-ae07a9e46a02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 60).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bf5a744461f320cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e8a15f7-53be-45e5-9349-b2ec2a2f7d59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 60).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e00b8b3c18682d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ab7161b-2f44-446b-8490-38a07c179e21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 60).', '[{"id": "A", "text": "show interface ge-2/0/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/0/1", "is_correct": true}, {"id": "C", "text": "watch interface ge-2/0/1", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4c4e3522108e7339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b1fc8f8-0594-43ca-890e-e9c0d7ff0096', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 60).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5a1e06b3107858ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee45e385-a151-4a4d-bf90-26bb84167016', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 60).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7366b7429b6649af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25204f46-a056-42b9-8fee-6402a2b922e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 60).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0267335b488f16be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9729e413-d067-4076-8a27-c39a87cf199a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 60).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '20c07b3593a61ff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f20d4e3-fb86-4695-87f4-fa8361c01902', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.122.124.0/24 via next-hop 10.223.171.5 on Junos (variant 60).', '[{"id": "A", "text": "set route 192.122.124.0/24 next-hop 10.223.171.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.240.255.0 255.212.88.0 10.223.171.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.122.124.0/24 next-hop 10.223.171.5", "is_correct": true}, {"id": "D", "text": "set static route 192.122.124.0/24 gateway 10.223.171.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a9d1f0adeb0e806d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd8f73d7-0a74-459c-a1b7-7da17325fd36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 60).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8d0184f978c51902_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7253c4d1-ed8d-48f0-8f54-0061037a2620', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 60).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b67fe0c676858aca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbffde0b-a0b8-4b16-b76e-297bff9190b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 60).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e7d540a90e96f6c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1137f632-10b6-4c81-84f4-c7353ae1050c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 60).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1acd914b2e6a8e98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada343f6-ecbe-4bb0-9a47-c9dd484fb113', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 61).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c4c48eba22154815_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1880d128-fee7-4cf7-bb77-baae0bd1fe32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 61).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ebca3a6341267727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31ac4d36-ccc6-42ac-bb67-df30dc09d77c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 61).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'af7ba7e77520a301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb006e80-4b11-4531-a574-4aee4af14928', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 61).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '12e6b70c3148aabd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d661f33a-9d68-48d6-8ca2-12b9642f7278', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 61).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '4578cea18f9c53c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05e70c09-9c89-47c4-88f3-0032a76b95a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 61).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd85701b80ac1e6a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5ef0762-694f-47c8-b38d-c0629eecf2b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 61).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e22bc5e402a30545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a78a6bab-65e0-4662-bf9d-6090e3dfee4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 61).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f31564c9c574be7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93db9f0b-e745-4d0c-b3a4-e27f45951634', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 61).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec0781a51cc5cae9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bd9834d-01a8-48ac-ab6b-aebe3f870ba8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 61).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8cc6633160ab5468_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13659050-fa1c-4018-bbf4-d532ea4fa183', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 61).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a67fd43cdda2c80d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b9f6dee-0f45-4a8c-8f7b-52c06c115a82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 61).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eb6c1db541f89ad1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e24f42-b639-49c6-b14c-1e1a3b88305c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 61).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aad3544edcadcddf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef21394f-e399-4c8c-8d86-3c10967ae438', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 61).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e0301725685374d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d79ad1a-fabf-44aa-ba76-97adbc503f2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 61).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd6a1cbcbaf192580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0395840-1f57-4a22-95d1-6d57e4e24639', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 61).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set system name R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6c3aa936ff77cc95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd0639ba-4f34-47b8-b7b3-9cfc618c4dd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 61).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '230a279ab6d05700_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27f2619e-fde0-489d-bc8a-21ea17129c0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 61).', '[{"id": "A", "text": "set ip address 10.192.150.254/24 interface et-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface et-3/1/2 ip address 10.192.150.254/24", "is_correct": false}, {"id": "C", "text": "configure interface et-3/1/2 ip 10.192.150.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-3/1/2 unit 0 family inet address 10.192.150.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ff8c685d75a08795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18a648d7-84b4-4958-82cc-80c73175ad67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 61).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'de0865e41ebecfdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49b4ac70-9f4e-4e5f-9877-c68015751033', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 61).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '011b7518f5d8dfd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a70dcaf6-df83-44b4-8be7-fe5ba7149fc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 61).', '[{"id": "A", "text": "show interface et-1/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-1/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-1/1/1", "is_correct": true}, {"id": "D", "text": "watch interface et-1/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd8530159d3ff5506_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e534ca2a-9475-4e69-b83f-8df8ef92f69c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 61).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8399c6ea0a797833_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4175b7bb-7649-43a6-a655-416c18fd9ed0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 61).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c672dc73603b9f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a78d0cac-b9ae-4941-aad6-2220ac7265ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 61).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4e8915ea04f31bfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc8a2352-ef61-4546-9ce5-64fd6834e07b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 61).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2a1ed1dda7fe2e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('874ff351-2b16-4d12-9751-1215ba73fe75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.6.72.0/24 via next-hop 10.84.91.254 on Junos (variant 61).', '[{"id": "A", "text": "set static route 192.6.72.0/24 gateway 10.84.91.254", "is_correct": false}, {"id": "B", "text": "set route 192.6.72.0/24 next-hop 10.84.91.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.6.72.0/24 next-hop 10.84.91.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.125.119.0 255.182.28.0 10.84.91.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3021026fe87c5123_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bf21213-b309-41fa-91c0-b90bbb0df482', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 61).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7546b15726bc698e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('989d5380-076a-4ded-85af-577373cc4296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 61).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8487bf6b5f9a5ae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a7ad44-9ed1-4aa9-ab68-3227664a3d11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 61).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f0a2aa69f5cf09c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('446d60aa-3a96-4fb9-8626-dc79077a0747', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 61).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8b6bedd92777f1ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3a23446-5dd7-4bbc-bed6-6094e80e17a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 62).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '26ee8285899e42c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04dc8c88-c95c-458b-8026-bee94ef4b04b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 62).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '36263943298f21be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6e4b90b-f795-48a2-a606-bd10bbe37229', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 62).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '002577bb4008606e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('317e4d3f-1762-46ea-87a4-a996312c9704', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 62).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b1e00ab060696b83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d12a4374-1671-4485-bd7e-dfbd81c09102', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 62).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'eaf08adff8835d00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d542c2ef-c882-4190-b9f7-d90a745540c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 62).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '574f021769b52caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc6cd3d-8d2b-4392-9a02-6103610687d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 62).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '927c96e1a2436989_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4bd9fe6-ed64-42a1-8230-851f33a598aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 62).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bca0048a0be11b07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81d1f03c-8ba1-4e4b-991c-7e89c231c21c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 62).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '50bdb48196d19d07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3c3d62f-226c-408a-b17e-a5ece9250fe0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 62).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8a34e3d95787bd3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97cbecb5-01a8-4c3c-837c-6fdc49b87349', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 62).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '16c25e8c4b252ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d208852-4a34-434f-9be4-0e84d5a8def3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 62).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf4a01884d28e2a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42bb7da3-adfe-4b2f-a4ce-bfde564c5252', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 62).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c3e2dd9eba595f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f676d71e-5839-4f52-af9a-5391979fb83b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 62).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15804a673615df32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5310e259-4e1c-4224-acbd-1355022c136d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 62).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ecff5ef7219496d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dfb696e-e3c1-4d99-84f0-16af2b47f563', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 62).', '[{"id": "A", "text": "set system name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set router-name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e7d773d4a1f45f7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb559a3-f211-4c61-839f-eddd9627816a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 62).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ce0759f89e23f016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd7e6d15-a393-4cc2-bbf2-6798e3c4ea27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 62).', '[{"id": "A", "text": "set interface ge-1/0/2 ip address 10.224.106.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.224.106.5/24 interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/2 unit 0 family inet address 10.224.106.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/0/2 ip 10.224.106.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c7269f0dd81e795c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8861005-4cf9-4039-a4e5-e408d8b4fdb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 62).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ef1aeeb46259d162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b16acb6-ffc4-4e84-adc5-9ba5770e1df1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 62).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5a92cc6a8375c5de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed6af148-8c4b-4cff-9078-594b2dd5b151', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 62).', '[{"id": "A", "text": "tail interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-1/0/0", "is_correct": true}, {"id": "C", "text": "watch interface ge-1/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-1/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4902051f1e719890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('545aa5ec-e72c-4bed-8c84-9a0f7667a8f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 62).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '450a1157282c96f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef73b9cc-297a-478a-94ab-925eaef9cc4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 62).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8e404325e9956549_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d6624d-fa6d-4ea7-a682-09cca6d49600', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 62).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c674c29d5c278c9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bae368b-c1ed-4c81-a69d-1fb11b0b9156', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 62).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '33e84654f120f83a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2f5cfee-0688-4d52-8fa1-c75739183c84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.134.10.0/24 via next-hop 10.129.192.1 on Junos (variant 62).', '[{"id": "A", "text": "set routing-options static route 192.134.10.0/24 next-hop 10.129.192.1", "is_correct": true}, {"id": "B", "text": "set static route 192.134.10.0/24 gateway 10.129.192.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.146.134.0 255.77.108.0 10.129.192.1", "is_correct": false}, {"id": "D", "text": "set route 192.134.10.0/24 next-hop 10.129.192.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5bf382d5bd874ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f4c62a1-8dca-4f00-b293-0576af1721e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 62).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9aa94611e463f685_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdad7704-7897-4578-a6ff-bc9a29fee0c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 62).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '29515b31c1048678_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c06c424-2ebb-4bdc-bf38-48c5fa6982d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 62).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '94ead76dd1afd49e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3a9a547-5c6f-4b2a-b2b1-378c18abce53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 62).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6c6b596f7baf86f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13860750-1cb1-44d7-92d5-5f8def7a3356', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 63).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8ae48e28f9b1965d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc6d1c76-77fd-42b1-86ad-2ce59b83fc4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 63).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7f1e0130c8c4e2c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('088272dc-6187-4aec-ad23-585048d5d0be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 63).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '516d1bed3b5156b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('959f11cb-bbba-44bb-83f2-18d44bb01860', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 63).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'dd1f509ddee328c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33c2e3b6-b9b6-4363-a204-15cbc5523945', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 63).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5476a362a482940b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa744a14-9632-48ed-a1bf-91a5e1bc7bf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 63).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '26371ca0fceae6d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe01a7f3-61a5-47c5-8875-1d0bf6eb2ef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 63).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c3a4c60503362b96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4d8101e-cd33-40e8-9fe2-a8df77d81988', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 63).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '780cab67fc84e7f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec5149a9-6a3e-4ab4-808c-cdf49687c775', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 63).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a3c3131a90547eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fb41d57-351c-4c10-a4fd-9d8d673c5bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 63).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '28ea61843800320b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d8ee32-cd56-417a-8fdd-b26f8f903c41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 63).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b4e4704b2f286bb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b6c88b-bf01-44b4-a1b7-2cb547833c49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 63).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5730a35c4d770fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11ca4472-f05c-421d-9361-875a9bb4cb71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 63).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a6f35100833cd5f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39c0766c-a63c-4a17-9980-2c23999e0322', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 63).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3e2c7133707cda20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19a0f535-8685-4369-b579-cad077e4e3a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 63).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a966e8fa01780655_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe02961e-7548-40e7-8704-365f4e2c085f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 63).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set router-name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5fbf97c6e5f53c54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5e77e1b-a37d-4093-9730-0e9fb7be709d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 63).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '453ef630254a467e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b88cab2a-58cf-4879-a645-9b52978d8a81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 63).', '[{"id": "A", "text": "set ip address 10.143.73.5/24 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/0 ip 10.143.73.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/0 unit 0 family inet address 10.143.73.5/24", "is_correct": true}, {"id": "D", "text": "set interface ge-1/0/0 ip address 10.143.73.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '895c14dec7857a4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53c93b7c-bad6-4b46-8b8b-3cd4a85c5a98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 63).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a1f32a07359fecea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03591bd1-7d1c-4ec3-8284-5255b8155401', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 63).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7bdcc9837fa151ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb2f46f-2144-47c3-86db-f8406b24ba7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 63).', '[{"id": "A", "text": "monitor interface et-2/1/1", "is_correct": true}, {"id": "B", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "D", "text": "tail interface et-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cdc7ffc5535aa600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c12be608-4d03-4725-b9e1-f841f2cbd81c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 63).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2495ddbd35208c47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('184cdc61-c786-4f33-9dcd-2d68b88f4d70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 63).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ebd55b224fc34a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42a5d4bc-ac19-4d93-8a7f-788530680901', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 63).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0bd3d687d8051548_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb4809a-0662-413f-91ed-c18ea3496db8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 63).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6eea648cf435ecb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c278dedf-7242-4448-971e-1006eb283354', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.190.244.0/24 via next-hop 10.74.139.5 on Junos (variant 63).', '[{"id": "A", "text": "set static route 192.190.244.0/24 gateway 10.74.139.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.190.244.0/24 next-hop 10.74.139.5", "is_correct": true}, {"id": "C", "text": "set ip route 192.182.210.0 255.7.205.0 10.74.139.5", "is_correct": false}, {"id": "D", "text": "set route 192.190.244.0/24 next-hop 10.74.139.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1e59fcb2d9fceff6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a136b73d-402a-444c-8ccc-063bf7100768', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 63).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '53b725c9584551b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afcfaafa-37a8-46a1-811c-16f484c09274', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 63).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0a01b19ae3e148a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77b004c5-f1ca-4225-b68f-cb4c3b8d3a96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 63).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1f5053cfd8865491_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74bbd334-9b48-45bc-bc25-390128f79f3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 63).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '093a5056af945210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f10b3cf5-cb9d-442c-86a2-a5324c1b7fb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 64).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '89556f90cda506a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c71ab41-9990-4917-8c7f-1a1249845b6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 64).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5757a952e8737a40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ae733ee-5157-4c1d-970a-3a4bf12d7c0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 64).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a2ba9cf94fc37c93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce96b2a-31c6-4f8b-a612-870a4efe6145', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 64).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5cb5b5eab0d2321d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f63705b-bafb-4a7e-b8bc-c24040e7cff0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 64).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd9dc98e6b3775a87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2bda16c-8e34-4ede-a481-3f227c609688', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 64).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3515f3796348f752_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7e79615-fe80-436d-91db-ff4b21feb28d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 64).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41ca9b51089aa2e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f9e313-1823-438f-8845-bc008aaf6909', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 64).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '18723c0b861f5cd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9761199f-50c5-4c9f-92fa-11e881d0a2f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 64).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44b18003c2c68ccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('010926f1-315b-4ce2-910e-6cb334f21da8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 64).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '50c34184a096d6a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64e404b2-319e-475f-ad97-e6ff075f35da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 64).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0b093ce22effdc55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a840e8f8-8935-4159-8e5e-e9c9b47751e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 64).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7621a8d680c3df55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cfb3382-7b79-44df-8847-f912fdee70ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 64).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '998a8458f3398e36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b34978a-14c3-463b-a3b5-b77cf5a6ae83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 64).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f61042e92e48305_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5294157-f768-46d9-930f-67fc489e83f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 64).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bea78df2b8198b48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b571f6c1-dad4-49e3-ba6f-890a08d35d71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 64).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set system host-name R6", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0f7dd46fff21867a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa16d60-c7e6-48d1-8cdc-2253c65ceb7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 64).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '570db709d00e4dae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6990d43d-af5f-4d62-b66f-c59f8c58032f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 64).', '[{"id": "A", "text": "configure interface et-2/1/2 ip 10.1.4.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/1/2 unit 0 family inet address 10.1.4.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.1.4.254/24 interface et-2/1/2", "is_correct": false}, {"id": "D", "text": "set interface et-2/1/2 ip address 10.1.4.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '762c599e01983e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('248c8a8e-9dda-48ea-bf71-1da9638cfb47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 64).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6589ac1e2afd54b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff280b71-7da4-4590-8f68-507a5bd3bb62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 64).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a80e1746fb440b90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('720f3d8d-ab17-428a-a85f-b65409a82e07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 64).', '[{"id": "A", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "B", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "C", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '612d5ed973654f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d10ec53-c760-454d-8933-145b8bd02fdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 64).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3dc3075776ca12d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('706d573e-17e8-4d6e-be85-ef0e0222e943', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 64).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'be3c860b592fedaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b2c8b8c-604e-4cc3-8dce-519f98b28b49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 64).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'dd62765d4c6432c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c8eede-df05-4d42-b1d8-c37a91f11df8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 64).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dc0d638f2c289169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141faabf-2b8f-4956-a5f7-a398864b96c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.222.126.0/24 via next-hop 10.189.237.254 on Junos (variant 64).', '[{"id": "A", "text": "set static route 192.222.126.0/24 gateway 10.189.237.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.222.126.0/24 next-hop 10.189.237.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.114.97.0 255.8.22.0 10.189.237.254", "is_correct": false}, {"id": "D", "text": "set route 192.222.126.0/24 next-hop 10.189.237.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0533fa307c20d6a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a99c3c-1a1d-47d0-a4db-b958930b4a51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 64).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8b37287d1786235a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d02d9a7-6126-48cc-8ab8-e61b038d87be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 64).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8ef4c625a57b7399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c58082d8-f9ed-4d3b-8fd3-bc3015a90b7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 64).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c3d56f50d8712485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e8b39d1-124e-430e-930e-89a8fdf0d975', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 64).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0940392085f48008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf568189-f135-433d-a40c-d3d4e88f5ca3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 65).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '4d4a839123a725ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d37ee883-9a0e-4476-97b4-2228ba043b02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 65).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c2074e407e0dd2e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e97b1249-4e5f-4869-9dd7-d779b7fb9c42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 65).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd9900f777078b4a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aca508c-fcce-474f-b33e-d9ada8c06273', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 65).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ded9f73b6ed2b532_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b60f041-4349-4787-9463-64893d8f9778', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 65).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '19da512d417d0999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bb1a443-3283-49bc-8d92-93d24405e748', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 65).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'bf3f3411b1a5546d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af24ad23-44c2-4418-8a39-0bb70ddac227', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 65).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e4cce41b4ad75b4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d6d2e23-7307-4c28-a0f9-5f15fc805bbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 65).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1abe2bb3d4f193ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f2978b-5d70-4f98-a09f-f42e7c4de878', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 65).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1d813bdf0785596c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8ff5137-c158-445b-8a7d-6c0f456124af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 65).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '005e0e8b008b0bb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99c48fdf-d426-456c-be7b-5b1212cc0ab5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 65).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '846228c166b1793b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee2c9e38-e4d1-4c80-a07a-21c362b12937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 65).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd57c6a8debe8be3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c91f2aca-aa52-48e2-a64b-a80552afc49e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 65).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '20dff6ee824b24fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d612e748-3046-445d-9311-64c8c383fa82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 65).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '44b118dc2771e77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b31e3ff8-1bf8-4d51-b4ca-23062d59c2e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 65).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b5c750882d0e1472_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53ac91d7-f260-46d4-98af-25693d6fadfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 65).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set system name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '794d77dd601ffd78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7e33fa6-2cb7-4a52-965e-de4921c660ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 65).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b27154d2a7cf66c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fad2abd-2996-4c5c-9890-89bad43e4a6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 65).', '[{"id": "A", "text": "set interfaces ge-0/1/3 unit 0 family inet address 10.147.10.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-0/1/3 ip 10.147.10.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.147.10.1/24 interface ge-0/1/3", "is_correct": false}, {"id": "D", "text": "set interface ge-0/1/3 ip address 10.147.10.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ad845d9c4e594a73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc42ff52-125b-4010-84ca-676a2d2b2599', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 65).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a6159cdcded0bd92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15b1c6b-b5c5-452c-adb9-f7442b3fde8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 65).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3034361d8524a4d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7d55e52-9c4f-45ad-8ef3-212fdb5a5bb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 65).', '[{"id": "A", "text": "tail interface et-2/1/2", "is_correct": false}, {"id": "B", "text": "monitor interface et-2/1/2", "is_correct": true}, {"id": "C", "text": "show interface et-2/1/2 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d62229373b51ca1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fac3216-2e3f-483d-b7f2-fea02932786b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 65).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '032bb4625a6fa36f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb946230-8dfd-4b6c-8fe6-ee3dfffab092', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 65).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '52e5e05d684cd4aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5e2f414-bd43-4b1d-964d-ef13a1c159fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 65).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f8874024989b1c47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb71564-f42d-4d01-a51c-a8c1f6ce9ab9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 65).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8848107651dd943e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b42ba67-7b20-4c5c-9d7f-f0776fa7a451', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.115.85.0/24 via next-hop 10.163.31.254 on Junos (variant 65).', '[{"id": "A", "text": "set routing-options static route 192.115.85.0/24 next-hop 10.163.31.254", "is_correct": true}, {"id": "B", "text": "set static route 192.115.85.0/24 gateway 10.163.31.254", "is_correct": false}, {"id": "C", "text": "set route 192.115.85.0/24 next-hop 10.163.31.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.75.127.0 255.200.50.0 10.163.31.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '98705cb03f95866c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c78716-bd9c-4516-b901-183ae9300426', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 65).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4139b19df58002e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81f62172-40c1-4331-8beb-db7d55b1b323', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 65).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '7dceb81840cd1ff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b587a56f-b600-4654-bfcb-07ee7c4f11ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 65).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd0f08e2d235afc28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fc4e21a-5ff1-4cd9-a846-922029700d3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 65).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '96f5f21dab39b918_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321fe909-5fd0-473d-8851-c71c3a0aad15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 66).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5a0beebacd7b8877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda5607d-7277-4f8d-81b1-2128e24ee16b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 66).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'bc69dec75dca9c4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cfc9fb9-f2dc-4370-abc2-43eb0c68e253', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 66).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e5b375fdd0f6ea5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1d58fbf-2440-40ec-9402-0b88051475ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 66).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd3c97db1483a4121_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02229a74-0910-4e98-a988-5d89f318f4ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 66).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '7f2efa8b75daf727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2e87f47-56e2-4e07-9162-0c40165b58ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 66).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '09fbce4f096a9ee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4e3f697-042e-4958-9032-09ddbe1258b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 66).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8849cd60b71c49ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17084da1-cf3e-478d-9938-6975ca67b8f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 66).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '47c90c705295575e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('698fdd55-1c27-47a6-8908-5a0c820420ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 66).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1ac1802114c1b6bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44a9b939-291c-44bb-81b6-eb73b346afef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 66).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3806548c8c75953f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('237e7cbf-82d3-464d-9e16-794bde9d9bab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 66).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cb69c2b766fe6735_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7b80cdc-0fd0-4eac-a533-cfe1ae4ce5d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 66).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '02681c5838be9302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88618122-ad0c-4a73-94b2-fb399f92c724', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 66).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e804af16fa934070_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f65b1f7-cfe2-4e7d-a3ad-58a193fa04b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 66).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '67884c2853580c6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f067737-b9bc-4cb0-8631-3aac57c79a73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 66).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '439fbae56cb19252_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a29a01b2-980a-45dd-806b-d157be009c33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 66).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set system host-name R9", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '06f5a56fac538f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c122ab-6eac-4272-8f36-7a113320fd39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 66).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc095db95c46de94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24013102-59cb-4745-b8f5-7a9d81a819bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 66).', '[{"id": "A", "text": "configure interface ge-0/1/3 ip 10.196.67.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/3 unit 0 family inet address 10.196.67.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-0/1/3 ip address 10.196.67.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.196.67.254/24 interface ge-0/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f2535508b324dc60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7d45d0e-aec4-49df-8c7f-e55989352100', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 66).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cf5caa41177091a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff9c5147-abfb-4fc2-8c93-4d681607599e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 66).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '352d0682a7179460_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aee20a24-cd93-4e04-9463-480892852230', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 66).', '[{"id": "A", "text": "monitor interface et-3/0/1", "is_correct": true}, {"id": "B", "text": "tail interface et-3/0/1", "is_correct": false}, {"id": "C", "text": "watch interface et-3/0/1", "is_correct": false}, {"id": "D", "text": "show interface et-3/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '019ea8666da51686_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33b5f384-1200-47bf-82b7-d421c5d2ee2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 66).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1489e75d730b76d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3774a643-d0e5-4563-a94e-e5b655ca9106', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 66).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c89f135dc785b0f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6338290-0bf4-423e-aa9e-1b931948e37d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 66).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '774ae10711c07e52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6c98eb3-47c6-495d-8074-809f0304f00d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 66).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f77d05d2331590bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('220df545-7546-438a-96be-654a945afce8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.108.201.0/24 via next-hop 10.118.0.254 on Junos (variant 66).', '[{"id": "A", "text": "set static route 192.108.201.0/24 gateway 10.118.0.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.243.65.0 255.106.182.0 10.118.0.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.108.201.0/24 next-hop 10.118.0.254", "is_correct": true}, {"id": "D", "text": "set route 192.108.201.0/24 next-hop 10.118.0.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd9ca985812732bb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a72fe255-c83d-4a9a-9513-67f3453b458a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 66).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e846a6964710c016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b65870f9-672c-4720-92ec-0d84935df4a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 66).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '926a3e07e370e624_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84130cf0-c14c-42e2-911d-bf5294051df7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 66).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8d16bd5930878bb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d3e1fa2-c51f-44b9-9d4d-830b89877d0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 66).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'df4c089532a4dfcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2371868a-07d4-4366-ac8f-c24474bff9bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 67).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '33b7b81ead39f29b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2cf0dd7-184a-4c2d-9b34-4ca10e22776f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 67).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '280d21e8f7b61d55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ff41a13-cf43-4748-8c4c-24f7ac60dbd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 67).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '92eebc3885fc4416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0e30642-957d-4fad-9ed0-74bbe35844b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 67).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '2a01b9367ebe8ce7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3487d518-990b-4e5f-acd3-35018dd9fbb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 67).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'fc1f7a0555033ded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f532766-eb3e-4482-bb52-78987f4bb3a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 67).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd8b2a04f5fb3291d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a052e94c-afd5-4021-b284-b77e03376d68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 67).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '22164e412d9cc040_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e341561-e541-410d-8a25-7fe34eeb11eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 67).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '97aa9458c2245686_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('876d1461-1adb-4be3-9bc1-86cec5849917', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 67).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65f68073835c77fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc0e394f-eba2-4f74-968a-2bbaeb7756b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 67).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '08e8ac67259443d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0bf0852-eb5d-47cb-b48b-fec879aa13d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 67).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '717e3868f0f52f2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4801d41-be49-49f4-8dca-8e412fa6cc98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 67).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3f193d049ed82a43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1a9be0a-8f2a-4e3d-9334-b4866a7de5e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 67).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e30ecfc20b6ceeb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54fcdf9d-0a27-40b1-9456-d73ae7b6bfb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 67).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e33d9acee59d005f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0c34874-c73a-4aca-90ed-4a4ec2ddda99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 67).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '64facc3b50caac0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f2f322-67bc-4fba-8bd8-f5cc68367495', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 67).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set hostname R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b21b7a9ac78278e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('555668fe-8603-4cc1-94a4-f14235493f85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 67).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fb4f2f9a6ff2e8a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a1c3984-74cf-4ee5-b96b-ca0ab10d75dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 67).', '[{"id": "A", "text": "set interfaces ge-3/1/2 unit 0 family inet address 10.82.128.5/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.82.128.5/24 interface ge-3/1/2", "is_correct": false}, {"id": "C", "text": "set interface ge-3/1/2 ip address 10.82.128.5/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/1/2 ip 10.82.128.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '07dd9d4c1e6fe1a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96682832-8a0b-4205-b020-08f18f86cafe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 67).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd122feca18600e60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e2a6c4-56a8-4dc0-b976-5fde454bfe9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 67).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '80311b1407aa9623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5085f54d-965c-461e-a028-34020421630d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 67).', '[{"id": "A", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "B", "text": "show interface et-3/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "D", "text": "watch interface et-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '025235f90d9d00cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('526654a3-7cfb-424c-93b5-6b9ca9a28f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 67).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a30f01da2f94ca4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f6f36b7-4f82-431f-b8a7-ead6bcd8e98a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 67).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '773c5e42394de64b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25a2bb8d-6943-4638-931f-17ed2fa65862', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 67).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4446310265ef06f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89c1b99c-7db3-49f1-894f-cadde915fb5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 67).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c4bb9d4031397cc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0312042f-6aa1-4b62-849c-807f5654f0a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.9.113.0/24 via next-hop 10.247.148.1 on Junos (variant 67).', '[{"id": "A", "text": "set static route 192.9.113.0/24 gateway 10.247.148.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.30.89.0 255.77.97.0 10.247.148.1", "is_correct": false}, {"id": "C", "text": "set route 192.9.113.0/24 next-hop 10.247.148.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.9.113.0/24 next-hop 10.247.148.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd4090befc5f19bee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1181981-fa87-44e4-b8af-36e9911f5ba2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 67).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7dfc0ea94b6dac04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51146002-cab7-45a0-9eea-36ee8921e9d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 67).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e5bc6ada8ea3d73a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04a3db1c-9bb8-4c9b-bff4-962c450fb89a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 67).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'abbfae55d0ae8de8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c757f45a-d064-4572-9bf4-cf2625bf2e2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 67).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c1bf905210dde3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b3c53a-d492-4eeb-9a90-5d0ce47789ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 68).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'befea1d5729958dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d55dd4-f3ee-4be4-a00d-f2c8c91165de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 68).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '776492ffbec2ba43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34961040-7eae-43ef-8479-8206d882de6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 68).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '17e7112353b7038a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd29c037-19e5-4b01-9c4e-9ed6adcecd72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 68).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e3e9fdece97c5694_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('863f4a6f-6431-4368-9246-887d1658a71b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 68).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '695efef478c9eafb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eceb4d44-7f3b-4724-a9b3-345314a9fb7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 68).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '255bb78727456e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89de587c-8b9c-4738-9c25-4b275070c80b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 68).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '43ab86bd9fdeaee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13acfb82-7355-45ce-9249-12547536ac22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 68).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4f13c0e2aeba3d76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cedc2607-289d-46b2-a9ea-38e88e845c61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 68).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '817e5ed0db213649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10d08844-e856-4b26-a4cb-09e91d4a4790', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 68).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c8a94a83754e4612_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('387a9401-4a55-4567-af96-62ab2cb8e42d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 68).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd6c333d5ac4127f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c919531-9b36-49de-a229-dec6ba05c08b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 68).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4f1c82fa27bf2500_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48cb9614-812f-4ac2-8785-39faba275732', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 68).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd5c8367f2abdbd02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b64a7285-d703-49d6-ab8f-9ba0a83ccd0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 68).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '32ad64792553617b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c80e0db6-17ec-4fe6-9627-0f89590b7b51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 68).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '81bf3265e5f1da0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('066644d3-3f1d-4fd6-b0ae-d20e3a9fc49d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 68).', '[{"id": "A", "text": "set system host-name R8", "is_correct": true}, {"id": "B", "text": "set router-name R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4f7bc0e3840e066b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22c649fe-0fa6-4ca5-a2f7-dae651d1ca31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 68).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1109b7b826321698_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf8ddca1-d817-4d7f-bb8c-dd9c87040938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 68).', '[{"id": "A", "text": "set ip address 10.59.196.254/24 interface et-0/1/3", "is_correct": false}, {"id": "B", "text": "set interface et-0/1/3 ip address 10.59.196.254/24", "is_correct": false}, {"id": "C", "text": "configure interface et-0/1/3 ip 10.59.196.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-0/1/3 unit 0 family inet address 10.59.196.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6146cb4f7658e97b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67074c0c-967e-4f19-8ac0-e97d40006111', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 68).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '895985d876a86036_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de4097ac-34ba-44d9-a863-bbda9fe25a12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 68).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d0b46c6279aeb4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8623eb7-b7d8-4a2d-8c5e-b8ef8ca7644d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 68).', '[{"id": "A", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-0/1/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "watch interface ge-0/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6019846db5963f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9ee8b2c-a826-46bd-b3a5-fe7e378133a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 68).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bd315de2bd3daee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b0af59-fa34-4eb2-bf1f-ed705306961f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 68).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '59ece1724764f103_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dff04cb7-5d23-426f-a398-3f823bcd8917', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 68).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8f602b31b3fb666e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff4713d5-dba7-467a-a9ab-cea7292e1be4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 68).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30ab1661e2f83d05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffab8a0a-7c16-434c-9a68-ffb8af7eb39f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.29.63.0/24 via next-hop 10.78.32.254 on Junos (variant 68).', '[{"id": "A", "text": "set ip route 192.94.91.0 255.238.135.0 10.78.32.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.29.63.0/24 next-hop 10.78.32.254", "is_correct": true}, {"id": "C", "text": "set route 192.29.63.0/24 next-hop 10.78.32.254", "is_correct": false}, {"id": "D", "text": "set static route 192.29.63.0/24 gateway 10.78.32.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cb86d7e31c2d1dad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67cdd2b5-4016-4f94-af85-fcca8d19e85a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 68).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5592bbccd6d620c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aadf8fa9-11eb-40c8-92ed-85bccfd97043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 68).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da2ed11484a5671c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7e515a6-20dd-4ac1-beae-607db88d08e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 68).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'febe5969ac128f08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09782b2e-570b-45a6-aaba-50850d6774db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 68).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '738d850e091d49b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e5b9c7-4a57-4d71-bbe7-82583fddfd7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 69).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a78dd507ea3c1302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecc0aac5-cc8d-47bd-948d-723feec552b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 69).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '0bfa6c17a18e19be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef3b21bb-11d6-45e5-bb73-1c98436f2f29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 69).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '5c3ee130c5a5f269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35ca82aa-c670-4c29-9020-43934e435f8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 69).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e553c04700f1d316_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9899e226-7b96-4d8b-9040-3b0be593cc9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 69).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c2fd18066be96bff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb036e60-b918-44ef-a02a-58b9db1d1c99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 69).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '745f790ed3f88518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a6b1363-41ab-49f8-896d-0f5e041d175e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 69).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34b577283ba33dc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b02307a6-f797-434a-acb7-5dd06d53cf28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 69).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0626a2ad89617353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d5c5a5a-fa56-4033-8acb-fa1e92233ae1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 69).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1731950f8f4393e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05d0a9cd-7c61-4640-9979-b854e97c8be3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 69).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0d7725e72eb7aea4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4630aa2-13c8-411a-b4a0-3a6e786aa62e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 69).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4c037a168f9e3293_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc82b5c4-1369-4008-8468-941ccbf554df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 69).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '26286e5dac29e5aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1401e66c-bf91-4fae-b217-8c5b7f1be219', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 69).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b1cc8732dc4543a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4d3c5ca-35ec-4ac6-98e9-c879a0490f83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 69).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '82f509daa29becad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad40f75f-eef1-4a8f-831f-cc27e00ee914', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 69).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2b56ab6c7e1f4269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590dfb56-71db-4b19-a5fc-2f04c6e6b3fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 69).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set system name R6", "is_correct": false}, {"id": "C", "text": "set hostname R6", "is_correct": false}, {"id": "D", "text": "set router-name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1443fb99cd372030_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30a5ed17-0ec2-4f97-ac61-c9cdaddfa21d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 69).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c6e923ef3dceee71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bce826c-9a35-487e-aba3-ef76ae3fb7bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 69).', '[{"id": "A", "text": "set interface et-1/1/0 ip address 10.141.134.254/24", "is_correct": false}, {"id": "B", "text": "configure interface et-1/1/0 ip 10.141.134.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.141.134.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.141.134.254/24 interface et-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '53d3441f404c61a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d203de43-942c-4121-89cf-85060a477386', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 69).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'db7854dd43d11f3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79ab7a98-a17b-4344-835e-6e9dfa2d3866', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 69).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '097812630906fcaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef5f980-69b8-4460-a225-47b147d2e56a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 69).', '[{"id": "A", "text": "monitor interface et-1/1/3", "is_correct": true}, {"id": "B", "text": "watch interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1d347f9408f9cabe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e285c202-93f1-4ab1-a777-a0b4836c5ba9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 69).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6965a1c0e68ffce7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7117435-4c44-4d4b-8af8-5a91bc19d464', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 69).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8d3a2cd3446cd3bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('611b0451-38e4-4838-a935-5febb8358f06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 69).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6aa31914b132dfe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e24bfb81-e1b0-41f6-8843-30a1132faa00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 69).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fb0623d85f623449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5244213a-f1cc-4804-9a6e-d7bcd6b13bef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.205.230.0/24 via next-hop 10.26.13.254 on Junos (variant 69).', '[{"id": "A", "text": "set ip route 192.113.97.0 255.235.188.0 10.26.13.254", "is_correct": false}, {"id": "B", "text": "set static route 192.205.230.0/24 gateway 10.26.13.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.205.230.0/24 next-hop 10.26.13.254", "is_correct": true}, {"id": "D", "text": "set route 192.205.230.0/24 next-hop 10.26.13.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ccde1f3061474ac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c52cd1-28a2-47c8-b88f-d1ee60b7a95f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 69).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7a22719e0aa42e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c33020a-9d2f-4efb-bc78-ea15fee46f4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 69).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '2e9cbab54ad9f05f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a64d5e62-5683-4e33-a63b-e58820184e1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 69).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0199ff293f0d7d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e5e7c9-aef6-43d7-a207-e0bf0b884541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 69).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f0f37bc5bb61b3e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('603b964e-e6c7-49d2-9dac-84f3a043c8bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 70).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c3d228b855a71cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5fb43a9-43c3-46f8-b2f0-3d86bdafa4eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 70).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f94b86833811b1c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49890b10-cd5a-4348-ab63-b893f185a0a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 70).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd3eaf92e1bcd29d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea41c9fc-0231-4167-accb-1d45f824033f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 70).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '832be3170907f85e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('964d9d35-9dca-47ec-93d9-c9d407823990', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 70).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '0eabda2778872a04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2e22c09-80b3-4889-8db3-d2c046e9519e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 70).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3dd68fbeae985b39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45d47c1e-b821-4504-80d6-4098a48aefe5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 70).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c30b26dbf82e1339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d77aa8ef-d981-42f2-86e8-9d4374700f01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 70).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'baa6a38df09d30e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0b9f343-1cf3-4965-b12b-da6f7f3378b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 70).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0c2633109d1b8eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f9b7734-4a6f-466d-95df-b7b4be13d999', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 70).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f7171a52f59918ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07f42fdb-e391-4d3e-8de5-b1fb1083d9fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 70).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5705d2e73bf15171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69db961e-17ba-4f55-8bcd-21641b3866ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 70).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b3142a57be6ca287_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cf26834-7b90-45dd-90ef-93288940d5c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 70).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '86e493b08a9adf69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28a5b003-db9c-40a3-8bb2-8ab8b4c72c20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 70).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ef0efeb0c3b2871f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ca1cac-3ed3-428d-91e6-2c9c2c043cf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 70).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e605ac9f0d94349a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1931a586-c3b8-403b-b04e-3df270877ae2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 70).', '[{"id": "A", "text": "set hostname R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set router-name R9", "is_correct": false}, {"id": "D", "text": "set system host-name R9", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ad21d200bca8dc32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e614862-0a4e-47f7-b926-b7aeb7bac461', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 70).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7114658566d7f8d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9805ca55-f4fa-43ce-892b-26889a98b864', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 70).', '[{"id": "A", "text": "set ip address 10.232.190.1/24 interface xe-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface xe-3/1/2 ip address 10.232.190.1/24", "is_correct": false}, {"id": "C", "text": "configure interface xe-3/1/2 ip 10.232.190.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-3/1/2 unit 0 family inet address 10.232.190.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '858e86ef12decc19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75502154-7566-46eb-bdd7-cee9adda70af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 70).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8070e0497b9689c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f383053f-2945-4f0e-9bf8-a634e1a89ac1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 70).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e1fa2a9b40f1fd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aaee3a0-797a-44e3-bb13-794fcaed3a15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 70).', '[{"id": "A", "text": "watch interface xe-3/0/2", "is_correct": false}, {"id": "B", "text": "tail interface xe-3/0/2", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/2", "is_correct": true}, {"id": "D", "text": "show interface xe-3/0/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '33aff8140028b315_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9290051a-04e5-40c7-867a-bdd81dc50b9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 70).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9e1b96a19c76424e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d46d1a83-fd9f-4613-9533-4680b6465042', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 70).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '443e6321db7c9598_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa9563a6-f99b-44cc-9750-074f16892938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 70).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '2c3c2159a593c044_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('925c6fa9-b8b8-4ccd-8cd1-9f154a537813', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 70).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cb677063ca3c62db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('955ef2bc-a324-47eb-9d61-259d8c1e8142', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.178.10.0/24 via next-hop 10.164.255.254 on Junos (variant 70).', '[{"id": "A", "text": "set routing-options static route 192.178.10.0/24 next-hop 10.164.255.254", "is_correct": true}, {"id": "B", "text": "set route 192.178.10.0/24 next-hop 10.164.255.254", "is_correct": false}, {"id": "C", "text": "set static route 192.178.10.0/24 gateway 10.164.255.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.134.102.0 255.43.192.0 10.164.255.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f9ddc011694d9e54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64633909-424e-48a2-b6c7-89acb42ced2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 70).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd05eef3d350d6b52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33c9b2cb-aa29-43f8-be5b-5af43cc77dd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 70).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da9b58938981b23d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9394c25-1a01-4544-a061-c65a8283c145', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 70).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4946208fa423255f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9346a3d0-cc36-4416-8a96-baf685168e71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 70).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '69ae872c9d1c9f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52a1bb8d-c675-4446-a163-875d2c4a6dd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 71).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ee0aa6a3e9220005_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a242e0d8-ece0-4171-b77d-4d6825d5ae74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 71).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4e67a35ee796db60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79763713-24c3-456b-8c96-5bcf744ce89f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 71).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6b2ac6415336a788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba4cbd1-be53-4f81-9979-67ffb60e70a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 71).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ad8e494f5d3f92bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70dfd6cc-69bd-45df-8b60-e288878a1477', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 71).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '93b29a3df48c86c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70111af5-be21-4be8-81f0-fd2c13975e24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 71).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6723a28106e91089_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aa61ce5-6ee1-49fc-a8f2-cfbbca036182', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 71).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7907dcacbe72029d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0d5eeb1-6b07-41c2-bf3a-165da9727d70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 71).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd41dd3f29db0d920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9474188-7acf-458a-b683-2a6caea5c227', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 71).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '706f6c993adaca0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8220a284-e2c2-43d5-bf58-1f680eaf5be6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 71).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd1c28e1126848c45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebc6de2e-20e9-4bce-b5ac-ba6d75dc7357', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 71).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57ac5f26a8bb50b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d157336-12d8-4a8e-a797-8df479ed32eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 71).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cbed78ff6db6bd67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0337a187-8c28-4b22-b229-fc7069bcf4e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 71).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b8d722142b0479ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55eb0f74-a869-4c33-a8da-55f11bbce0fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 71).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '94cb74fe305f15a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('080b21c8-2528-4dbe-84b4-598983686eae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 71).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8050cac36638b0a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d1ba2e-9187-4ca7-8d6c-be871107d4f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 71).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3a32d03df4a26b39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cdcf31d-e634-48d3-970d-3b7acb3f1831', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 71).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'aaf6a2f28fa7a32f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('621ef3c7-9424-49a9-8018-224579ea9d28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 71).', '[{"id": "A", "text": "set interface ge-2/1/1 ip address 10.211.110.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.211.110.1/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.211.110.1/24 interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/1 ip 10.211.110.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8947a93faad08323_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89a9eb4d-9694-4402-82ab-12ce427446d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 71).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b4f859319b0ebef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32a810cb-e5c5-4290-9b80-378e5de64375', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 71).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7354005931979016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc2c124e-c14e-429e-9c79-195e75bb4025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 71).', '[{"id": "A", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "B", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "C", "text": "show interface et-3/0/0 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cc42c777e4812d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a76aea6f-1aef-424f-ad83-6f4bcdad6909', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 71).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0dfcfd9ad3725a94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31feae6c-79cb-49df-86eb-41665185eec0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 71).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2601ac9858d414e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a6b3b33-2f9c-42bc-9e63-d110fe1fafdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 71).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '77b94cd3ae237910_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('994ed8a2-35bf-426f-86b6-fa436709f263', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 71).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dfc6c388a397cd52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5841f71f-028f-4ae4-9e0f-e611fca79179', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.144.119.0/24 via next-hop 10.178.174.1 on Junos (variant 71).', '[{"id": "A", "text": "set ip route 192.29.155.0 255.128.41.0 10.178.174.1", "is_correct": false}, {"id": "B", "text": "set static route 192.144.119.0/24 gateway 10.178.174.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.144.119.0/24 next-hop 10.178.174.1", "is_correct": true}, {"id": "D", "text": "set route 192.144.119.0/24 next-hop 10.178.174.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fcb4880bce1084cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbf934f6-856a-41de-9897-652e98723ca2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 71).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '55518294f40fa9f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e54d6a3d-6588-4b4a-a192-1b18237e14e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 71).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e872ede4983892b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04422fbc-4562-4ba6-9a7b-260a362b5886', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 71).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd56efa594f77d951_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0806049-bbe1-4b2b-88f7-e2fc22b32b2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 71).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '95b2740f5f67687a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('082bb272-4553-42ee-a46b-ae82f3b113bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 72).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd22ef605b6993db4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb57601-0bea-4f41-ad4c-e75917a80e65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 72).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6c88598746d3af8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b17e2c4a-93ef-437e-b1a3-ff5f478797e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 72).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9363bec32ab5d089_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53027099-90d0-4e64-ad58-7539b91e4862', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 72).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a4ef6be8591da260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99075d09-0ccb-4d0f-8a89-fa1741eb7895', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 72).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e4f3dffb122bb738_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7b39b8d-be7b-411b-8758-cebb76ee49e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 72).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6051d1db28428e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce39437f-6d05-48f1-8140-308c81a37594', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 72).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd2d0b4c60341a72c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27c4968b-f5e5-4fd1-a3b6-4b4d4b2613de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 72).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9336b822a242c88b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a88ff309-abfd-4bac-939b-ddd129e6ab17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 72).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b64f897072ca8403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6b8c251-f4da-4e4e-9998-fc79f807d16f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 72).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'be2b7d5fcab32a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2557738b-f09a-47d7-aa3e-915307349d9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 72).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c0fd480a30bdc4c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfef611c-d919-43f9-83ee-14e81cb3d9fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 72).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8357264e9844df09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfc7b983-53ea-49b1-a6a6-87a40694356e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 72).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '438c701f0ca22dba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d0bf232-7119-4dab-b3f5-bbf678d0f7c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 72).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4d5fb56d07a70394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24eaa8b9-6506-4ed2-b793-3cab08eb98bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 72).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ddf8a16e6125279b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4aed06a-a0be-40e4-95b9-e3a5be5ddab8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 72).', '[{"id": "A", "text": "set system name R12", "is_correct": false}, {"id": "B", "text": "set system host-name R12", "is_correct": true}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a1bc4870e819afb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df583478-bc87-4113-922b-b6a9d5e54c54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 72).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5ac2e0b49802be76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef4bed0b-eb45-46db-8a1a-fdf1d59aa078', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 72).', '[{"id": "A", "text": "set interfaces ge-3/0/3 unit 0 family inet address 10.34.1.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-3/0/3 ip 10.34.1.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-3/0/3 ip address 10.34.1.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.34.1.1/24 interface ge-3/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6b6b212380bd288c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39a0387b-546f-4db4-ac8f-60df1c9c3987', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 72).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5fceb7001775249b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe026ab0-82b5-4af1-90c1-aeddca923549', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 72).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '544f568405bcac75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4f81c0f-2648-42a7-b2a9-b92b4a4015e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 72).', '[{"id": "A", "text": "tail interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/3", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/3", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/3 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5646fbded259e68e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8814e03-f2b4-4c10-80b5-9d0c45ab8e95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 72).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1a0371599eaba6c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31600242-a153-40ac-864a-282840f18f29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 72).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8a17c2e2ff1b3cf3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('322d51b7-1238-4425-b5a5-ea21a0ae077d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 72).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '31c7d7e6691336e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f82e78-a0c5-43a4-a154-de82543ee98f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 72).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '668e9ab85c397f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d842864-50db-4554-9801-783d1cc2621a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.87.86.0/24 via next-hop 10.19.249.254 on Junos (variant 72).', '[{"id": "A", "text": "set route 192.87.86.0/24 next-hop 10.19.249.254", "is_correct": false}, {"id": "B", "text": "set static route 192.87.86.0/24 gateway 10.19.249.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.87.86.0/24 next-hop 10.19.249.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.126.134.0 255.175.32.0 10.19.249.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '46fc3c41a4845680_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a930f5f4-eb31-4ce3-8e1d-8a8e32cb1100', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 72).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '213440e434f27871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d86cda8-ff7e-48ce-a26e-ebcc21cf22e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 72).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b7934f90ace2f756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fca20ed-d296-498e-a763-da0bd7b63668', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 72).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2dffc0a886aec9f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37c3a3ff-c2da-4e45-a6dd-39357198b0b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 72).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '01c644cde2d11bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13b211db-b6bb-4526-97b6-3d49cb9cac67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 73).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '150820182acdaa0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05e8b2a1-b027-45ff-a87b-d6155a3abe2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 73).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9e6d97fc4487043a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1059e20-ef52-4448-bca1-fc8c6cf69b8b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 73).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '22ad8ceae0375ccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aeaf2b6-c8bb-49bd-8817-72eb45c2389c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 73).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e9f05a8c2e9dd27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95847efa-ab9a-46db-a382-e8c476d49f6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 73).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c2e92490078c3d76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d2d646-93ad-4cf0-a305-7d66264603e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 73).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1946db3d76c98682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b7d29cc-da3b-4ddb-960c-3a2859a67621', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 73).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f297fde042894508_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeac3d42-ba21-4a38-a59a-11a0f0edfcda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 73).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '50139121ffb66149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5543411-3a0f-45aa-9f35-fc4fe63b30a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 73).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '21bdbb6dc639c5c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7744136-5f2a-4490-9929-7e0b3dd2f3b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 73).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'dda02d8d4d3107fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19ba6c33-280b-49a5-b966-e2a64d1f61d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 73).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '29cd71fe054e826d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e3799a-928d-4555-a032-dfc8b3504a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 73).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f25a852cceca5fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17611145-a625-48f9-a775-fda061eb6879', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 73).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a038957018acdf47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3fa9c09-d31f-4342-8922-1f8387ebe940', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 73).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '19b1bfb5826c8f49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b761e12e-bfc1-4937-a087-3caf999734bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 73).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7d5f80f6cd33a27a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b07a6138-0e2b-495b-b1e6-d4aee36c36e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 73).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d7de04e9e7b4dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('672dd8c1-c792-4c92-b240-2118aed87538', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 73).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5b8b2bc5cb550101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb35995-c86a-4655-b090-aea67eee6211', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 73).', '[{"id": "A", "text": "set ip address 10.58.171.5/24 interface xe-0/1/2", "is_correct": false}, {"id": "B", "text": "set interfaces xe-0/1/2 unit 0 family inet address 10.58.171.5/24", "is_correct": true}, {"id": "C", "text": "configure interface xe-0/1/2 ip 10.58.171.5/24", "is_correct": false}, {"id": "D", "text": "set interface xe-0/1/2 ip address 10.58.171.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fc012fc245680401_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e44a6a5a-4878-43b9-b4fc-e7ee6bee122a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 73).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd05c5f6bd1d5d6a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc0ef5c2-0833-461d-841a-5858a4077696', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 73).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8bc511aeae962b86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deb0e7b3-ed74-4fc1-afe5-488a7c6a8e12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 73).', '[{"id": "A", "text": "watch interface ge-1/1/3", "is_correct": false}, {"id": "B", "text": "show interface ge-1/1/3 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-1/1/3", "is_correct": true}, {"id": "D", "text": "tail interface ge-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '94eda543f4315bb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ee27f79-5e03-4a45-bc75-07d514f45c33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 73).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2c6cd088fd688391_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8915a5ae-8ef5-4aa3-bf11-19f974ba978d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 73).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fd6c8e0689ed5feb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ee84758-c849-48b9-bb00-2260bbe09809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 73).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ebd6b0611977e39c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f653823e-02a6-4280-b887-8839a0491451', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 73).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c54348e79783670b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c80ce56-a9fb-451e-bc1d-4c6d748ec350', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.182.36.0/24 via next-hop 10.140.140.254 on Junos (variant 73).', '[{"id": "A", "text": "set route 192.182.36.0/24 next-hop 10.140.140.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.241.236.0 255.71.125.0 10.140.140.254", "is_correct": false}, {"id": "C", "text": "set static route 192.182.36.0/24 gateway 10.140.140.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.182.36.0/24 next-hop 10.140.140.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '34b517e72d43e1af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b071a5b-58eb-4aef-92ec-9d6721d69f14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 73).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '762bb5926a7febe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('316ee60d-96dc-4280-a5bf-e6a47e490fd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 73).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'aa54e86697341abe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9a651c4-922a-4ec8-a3fd-495e697ba359', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 73).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7e5c65101daa9ff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d7e26cf-bab4-49fc-a5e1-9eef0a2d2b71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 73).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd326110b62760358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('438f4ea8-f2b0-428b-96d4-0601c10d67ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 74).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a5e36cab8a384c2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3bda11d-f6ee-4a89-859b-8b5f87deaebb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 74).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '46db8fdfa59a38cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0272dce3-2d27-4ba6-af12-22349e0d5147', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 74).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f1bc7b4b2d4c20b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df65dbb-4e09-4246-a1e3-c72c28c98917', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 74).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '54b4368098bf8e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7c584d0-fe57-4ea2-ae5f-f9790faca62b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 74).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3bc8116b8f1872b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dca430c-1293-4a32-8330-a764777c472f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 74).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '169dc468759823fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda02511-333e-44ff-9ca9-f979207f652d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 74).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f50390c0e0b71250_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85d8f4cf-be43-4b62-bba1-917b6a3ab26d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 74).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '02fa7450feedac3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b074346c-a93d-4c46-8705-ffc1b80ffc37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 74).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '73057f306071bb2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9707e4c8-4a65-4d31-a9fc-15a315d6fda3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 74).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c0991c5302714023_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a284dea-a601-4e77-85cb-b1fd34283ee7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 74).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '269f8ebfe18f535c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8486fa8d-8425-4886-ab79-b45d17929d63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 74).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5efec52384ba0675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c794697d-278b-4662-97d1-41f87b358ccd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 74).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fb8f42814522313f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d64ecd2-2648-4a61-859c-2d9e98b40567', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 74).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f7f9842c62129961_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1cfe465-1e1d-419d-a908-c14cbb1cd551', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 74).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'be820de66158a0a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afbf134a-ffcc-4d31-a111-dced4a0cd4ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 74).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '75e2778e451deeee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdc0c6e5-f638-4b39-a9b9-4b72486e4b8b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 74).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ed6790a52ceef180_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae206d69-64d5-4659-9962-cc89103332cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 74).', '[{"id": "A", "text": "configure interface ge-2/0/1 ip 10.245.251.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-2/0/1 ip address 10.245.251.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.245.251.5/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.245.251.5/24 interface ge-2/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '672524c830bb7077_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df334ba6-2209-4187-98be-707d47e8f181', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 74).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '80383348816fc08c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bc78807-4ad0-41cb-8e67-bca195b4836f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 74).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd1474673a2801c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('044193c7-7542-45ee-a35f-c013f7e4ffa8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 74).', '[{"id": "A", "text": "show interface ge-2/0/3 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-2/0/3", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface ge-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6270c5e0e1520142_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59e206e6-17c5-43a9-afe0-a47d0afdc8e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 74).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1a3ab4973e9b10fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eaf3600-5a5b-4ea0-abe1-55a149bdbfc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 74).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '731e7b65483bbf0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de72f721-0f7c-4732-99f9-e92e184a9420', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 74).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e7b3cb6e6cc6e37c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad3aec9-bef9-4c22-a074-1a90410c4469', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 74).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5acc11e168b067e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('493e8e83-81bd-445b-9c6e-1e8087350682', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.190.255.0/24 via next-hop 10.89.104.1 on Junos (variant 74).', '[{"id": "A", "text": "set route 192.190.255.0/24 next-hop 10.89.104.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.190.255.0/24 next-hop 10.89.104.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.234.158.0 255.145.22.0 10.89.104.1", "is_correct": false}, {"id": "D", "text": "set static route 192.190.255.0/24 gateway 10.89.104.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f3d497157dccdbc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a47e54a-9e28-496a-91bf-ff0010ac67e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 74).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ee566d6d3cb474d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bfc8097-93c4-452a-ac5d-8f4c0161f1e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 74).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b26c868117948bbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f6327e5-1a57-4889-b879-8686ee1a5643', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 74).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '991130987e3b28b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d055920-504f-4d3f-b961-a58819e3a317', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 74).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '882a49dab38667af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb943df5-74a0-42b0-8349-51362cfa2bb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 75).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f80f9888ee55f953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dcd3d9a-7df0-471e-989f-def138edf863', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 75).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c67f81285985779c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fc39637-0695-4213-a9be-9edf739b6965', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 75).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '23c404961d889fee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69f350b6-307f-4d4a-a642-9f3369323f6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 75).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4aa8a0de1a099626_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ddfe1b-7353-4ba3-8d5e-e0b67fac076d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 75).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '12d2d7116b0d66b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d326ae59-cac3-415e-8d72-dd13d9f17ac7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 75).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '88b67cc25e586519_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ace7ba1c-5cd1-4f57-a7c0-f9d9869ff917', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 75).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e92f2c741843af00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5fd9fd1-9153-4599-9725-89210c262320', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 75).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '833c268a6bbd66ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ce84298-ad41-400b-8c4e-0391e396dd82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 75).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad998879e3b235ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba6d5952-53e8-415c-b722-f581952e0065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 75).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b59011895b118e7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f848c04b-2b87-4f2e-bca7-8633dd5e8cf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 75).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9195019341769ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1012c19-bcc6-4243-bda4-db6f2a7b1588', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 75).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f21a17d7f12fa6e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f01ffa-9e02-4d72-9d75-82b3295629d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 75).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '99f99a4bd0f97359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2119c2e0-465f-45b5-bae3-784c442f8540', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 75).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '548e4bf05692cfd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cab48ac-fc67-4b2e-8c23-f27d5401234c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 75).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '242ff96b2a5dcb4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12dfab79-2a5f-4f7f-ac65-aaa94fcfcf9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 75).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set hostname R12", "is_correct": false}, {"id": "C", "text": "set system name R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c8dfd9ce58761e98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12c8f41c-b54b-494e-9f20-1faa3611191f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 75).', '[{"id": "A", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '71855c09b282523b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa71796f-889a-46e5-9e20-469b44600b5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 75).', '[{"id": "A", "text": "configure interface xe-1/1/1 ip 10.227.23.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces xe-1/1/1 unit 0 family inet address 10.227.23.1/24", "is_correct": true}, {"id": "C", "text": "set interface xe-1/1/1 ip address 10.227.23.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.227.23.1/24 interface xe-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '654b19a4e60f68c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eae2d77-74a7-4b88-95b5-7f15102d08e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 75).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3b2d5aa62ea74e24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06c91afc-8f23-41f1-b1bd-8ddcbcd62352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 75).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6c0973ad32e21e2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab4e120-883d-4d3b-a87d-cc8e2f321f53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 75).', '[{"id": "A", "text": "monitor interface ge-0/1/2", "is_correct": true}, {"id": "B", "text": "show interface ge-0/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/2", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4a3601f0e9aa95f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e28983b-0a06-4070-9753-d5b3d1f17303', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 75).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '629253ca8de88ad8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c758733f-83c4-4be6-a3e0-52421a1408b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 75).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4ea556acd60912bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7257aab3-5243-422b-af00-d21d2c6855b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 75).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f6f8f9377341be38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c45884fa-27eb-4264-b991-7a8a20e2f10d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 75).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd19b3b0b0e507ee3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3386681d-ab74-4bbb-9365-a802e8b682e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.160.150.0/24 via next-hop 10.2.183.5 on Junos (variant 75).', '[{"id": "A", "text": "set ip route 192.200.46.0 255.135.184.0 10.2.183.5", "is_correct": false}, {"id": "B", "text": "set static route 192.160.150.0/24 gateway 10.2.183.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.160.150.0/24 next-hop 10.2.183.5", "is_correct": true}, {"id": "D", "text": "set route 192.160.150.0/24 next-hop 10.2.183.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30dde127d884b038_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('784f272e-0894-4659-aacd-a093c97ae62f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 75).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c4daff4a781eb85a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('366a6b1f-23f8-47ce-8865-15c87fc3f0ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 75).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bdf579c784d9046f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4b4e42a-9df9-4469-b705-7e94b3d60bfb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 75).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4fbb31caa707afea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91e2e597-d086-4153-9ae3-8895fc3d025a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 75).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '07322e1e59882a82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec65d92-a1ba-42be-b0c2-f7c2a048b393', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 76).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6425e1667e8cdfe4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa016f54-b0c7-419e-94aa-05b0974b28fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 76).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4b19bb271f2db99d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11c13a30-e9a4-414f-9fca-1f83161aa7b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 76).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4e225ea045e4e43b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5c7c45-7885-448c-9d8f-d7dd7d39b4e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 76).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a304b3a3f88b66fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c539403b-8094-4698-b7e2-3d33f4735d36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 76).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '58ad39b6141bf1a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dae88e7e-59af-467c-927f-3bb0b51d7f0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 76).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2f20c241d9c963ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39e4c436-849c-4f1a-9682-2824ee5e4701', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 76).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '72cf45a2a69b0939_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ae1d3ce-43a1-41e1-b85e-705d854c1a68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 76).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0270d9b8af40352_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fecad2a-16c1-4c06-b7e5-be7ad57560d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 76).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b423930a6ebfc9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3e2cbf4-0b2c-49b8-aaf8-5e0ffc498477', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 76).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '845334c4e1148d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12320e2c-4fac-4e78-852a-79f7f5aa95db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 76).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ea1b3847fe2cb05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('290aa9b9-910e-4828-8b44-b5d31f12d08a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 76).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fffbab02275dab56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa04a0ff-1afd-44a0-b0e8-a54c27660ce6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 76).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bc41c9f21f2aa5df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41df5308-5e80-4b8b-847e-e603751e5619', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 76).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '92e61ee3a09613e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64321e28-3fa4-4a1f-9bfc-b4be38333da9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 76).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '758c7dbb18b5fc50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b86ea699-a8e4-438e-8ed4-2d5faba0cd53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 76).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3c8e2c67baec8281_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93ddc862-faa7-45cd-85cc-0d52f7010624', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 76).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dd47a0485d4b234d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('064c7b91-e4c9-43da-a881-55d7cca9c631', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 76).', '[{"id": "A", "text": "set ip address 10.105.60.254/24 interface ge-2/0/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/3 unit 0 family inet address 10.105.60.254/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/0/3 ip 10.105.60.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/0/3 ip address 10.105.60.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bade1ce14f9d40da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d96f0bb6-b5a1-4ced-90a9-783deda12eae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 76).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9cb6f9ff303cfb2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('230035d5-cc61-4e07-bd15-951e50abc957', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 76).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a00f0a122539f8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5726740d-c7a9-40ed-8d08-d5935e5ccd23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 76).', '[{"id": "A", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8fbd2f9008bc5e3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2dd05a2-db62-4805-ad3c-e45483da3d45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 76).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '94c1decd107deb0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('672a2797-ccec-4ed3-ba2c-d81947959a84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 76).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '63aae69dab6c0598_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('978875b4-b466-45ae-8fd4-0e5cb100bc84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 76).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6b0bbd7cc46ed986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('306c09e9-50df-480a-b42e-392b985b899b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 76).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e950d73f168b93a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab4f5ba1-95e5-42eb-bf85-a28d295f920d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.3.75.0/24 via next-hop 10.157.243.1 on Junos (variant 76).', '[{"id": "A", "text": "set static route 192.3.75.0/24 gateway 10.157.243.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.3.75.0/24 next-hop 10.157.243.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.22.23.0 255.34.69.0 10.157.243.1", "is_correct": false}, {"id": "D", "text": "set route 192.3.75.0/24 next-hop 10.157.243.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dad93780905e1f97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8eb810a-19cf-4ce9-b3a8-da89319eaa0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 76).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd7c3c385e6dde9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e907b8e7-6ef4-4fa2-a2f5-c971d50347b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 76).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd213e76520377e27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0abc0214-fd5a-4b27-8b98-81ae0040e91a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 76).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1e025689e8c27b08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a363db01-bb6c-41f6-a1d6-022d3e85661f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 76).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '87c8d5c8d61005e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf829e88-8b67-444c-9c3c-8a1837836194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 77).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8115af948aeaa5f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffbd8921-ea9f-4c99-b8c3-5889a43409e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 77).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd23156cc3193f626_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289cebe6-20d3-457e-a65f-63a04df2d25d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 77).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '093fe6aa6ab550bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('613bdd70-20b0-465f-bec8-0529ba04946e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 77).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0b087c118ba30f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9df937a-daa1-4e23-85fe-876e5de85fad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 77).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd1077350729d623c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b4191a-a6c7-4dae-911d-dfee452313ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 77).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a9f4aa0f60a0d01b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b9babaa-bb11-4d99-bfc3-49d76b197ffb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 77).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '38c1b1d77a67be43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c86f9e74-2299-464c-83d3-807e79b8de38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 77).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '70937ab08ac0eee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a46f5cee-bec3-480a-89ff-6951e036fc43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 77).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0588212919885901_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8922c712-7c75-408c-8c09-3c9f04e6190e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 77).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'cac93b6cbeb21d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afc91553-38eb-471b-906b-d6f37fefbf6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 77).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e30dbfcb6e58a0aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('072a3a4d-5adf-4738-8f75-391147f3be58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 77).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '14b9b797ad70ea24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edcb0e1a-41e5-4dfd-9dd3-0db48aa312ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 77).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c015465ae8260214_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8962b1a1-9bad-47a6-bf6c-c57aa118189f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 77).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c584d2f2fb05ca19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e56b0803-99c0-4f53-8e9a-d17b3c7a1ff1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 77).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '224936839c8aeaed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76902f1a-d92e-4282-bac7-18a8a24d02c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 77).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set router-name R4", "is_correct": false}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ac82ecd724b07b04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3764ea7-b7cd-4117-a145-fed2a63511ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 77).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '29ca768721221358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77070dd3-5c0d-4caf-a17a-c6be813c2830', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 77).', '[{"id": "A", "text": "configure interface ge-3/0/1 ip 10.252.26.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.252.26.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.252.26.254/24 interface ge-3/0/1", "is_correct": false}, {"id": "D", "text": "set interface ge-3/0/1 ip address 10.252.26.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1822163ec62d6c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b196ab07-30e7-4c02-b403-b8af421839aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 77).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da458c5bbd12456d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56fc9283-76c6-4229-a846-cdd8c6ea0a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 77).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '13d210a45e5e209c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68fdd303-2b97-47f5-baa7-72c4919acb79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 77).', '[{"id": "A", "text": "monitor interface ge-2/0/2", "is_correct": true}, {"id": "B", "text": "show interface ge-2/0/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/2", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9b14404f1718e0d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('633c588e-2915-49cf-8041-593e37087e72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 77).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '48937108847a435b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d53400e9-9564-4bf7-af75-da414391f96a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 77).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3283ef0e6f0aad88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a063753-4c45-4a4f-91a8-a2f46e39045d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 77).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3ffe28d17cf8cd9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2371cff4-5ad0-4a26-9f08-db0724bb699e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 77).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c3b0ff47a0303ed4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5f7d692-95f8-4982-bc1f-7375c65cd280', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.18.184.0/24 via next-hop 10.158.185.254 on Junos (variant 77).', '[{"id": "A", "text": "set static route 192.18.184.0/24 gateway 10.158.185.254", "is_correct": false}, {"id": "B", "text": "set route 192.18.184.0/24 next-hop 10.158.185.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.78.49.0 255.106.141.0 10.158.185.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.18.184.0/24 next-hop 10.158.185.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f766efc0d4a094b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e94e5029-38ae-422c-be9b-6c260dfc9670', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 77).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7c584a69786bfb93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('649adee3-578b-48f7-8e1b-2472db901fd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 77).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '44f9c3ffa1dc3a39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f64ba6c-cabc-4324-bcbb-bdbc0713b2d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 77).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b5e92d27719e7974_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b0b03f5-89f2-4821-8031-d11afcf294b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 77).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '327badbaa263f400_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d400269-7aeb-4b06-9171-a7964faa528c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 78).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6363b8005003f89a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49f69497-16cd-4df8-a472-3419d1df4edc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 78).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6453c5b1dd745c8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ef6ba8d-4f10-40b1-95e9-b557ac9c9b17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 78).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '1734fea19eb74c12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb9f5e04-530f-4082-b166-a064acda0a0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 78).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1f06f6b208cbf805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a143d09-16de-4424-a3fd-93c83168cdf4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 78).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '452a0bbc9a81ae30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84b77ff1-a7f6-4131-8ee6-966100207de5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 78).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '8deab30b26563936_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('283b5989-368d-43c8-814f-085d3e34ae9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 78).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '633b83d882d0fb12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b832082d-ca48-4218-9bf5-56deb615691c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 78).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'aeaa693c40e7c602_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2ddb5f5-ae0e-426d-85eb-f333d06a7b5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 78).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4531ef7080dc8bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e96bccbf-a042-45c4-b81b-979f26a25993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 78).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '483b3d0ce37301db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec650a8e-0f6c-4193-93a9-1628971c580c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 78).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '24a580c51329eb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aa88821-f7e7-4604-b02f-4f968071972b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 78).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2dc85dd3f71bc662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a17da648-d2e9-46a3-b0ac-63b7b7692b7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 78).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1f59ff60d8e9fb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c6a7528-6713-49a5-bd8b-cabaf0289551', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 78).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '79440767f7aa556c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6fd34a1-b6e5-42fc-9e79-5066f0f4d2f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 78).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '19041172a344557d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e87403c7-f351-42ae-9c22-8cf450e4d2ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 78).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set router-name R10", "is_correct": false}, {"id": "D", "text": "set hostname R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4776ee57a7e3be24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a97d6fd3-e755-4534-894f-aa477ad25931', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 78).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ab1323bc6802a10d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7670c75b-c146-43e2-9bce-0570c0040785', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 78).', '[{"id": "A", "text": "set interface ge-1/1/3 ip address 10.118.209.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/3 unit 0 family inet address 10.118.209.5/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-1/1/3 ip 10.118.209.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.118.209.5/24 interface ge-1/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '94a08278a9f374ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('764d23d9-80b2-4a25-a74b-c790246f896e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 78).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9e80279d411528a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e62bd93c-6455-4401-a7d5-7cadb2ad25f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 78).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'af9dc3330f85c8b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a856e25-1e4a-4a20-a831-028160163b44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 78).', '[{"id": "A", "text": "monitor interface ge-0/1/3", "is_correct": true}, {"id": "B", "text": "show interface ge-0/1/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/3", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '03b9817c38194120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2010b647-8013-4148-a6ea-fb13798caf78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 78).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5c036f58c1955aa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01da91e7-c018-4fd2-bf96-9a3c64618fcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 78).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '64d1a9050960fe4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aacaaeed-8de8-4e37-99ba-c49bbb0d91e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 78).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3e43e2235427c34a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1db2193b-0001-4083-a679-52184975999c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 78).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '856673e999554395_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b72eb1b-511f-4936-9e40-b3cdb8c594f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.122.196.0/24 via next-hop 10.178.155.254 on Junos (variant 78).', '[{"id": "A", "text": "set route 192.122.196.0/24 next-hop 10.178.155.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.122.196.0/24 next-hop 10.178.155.254", "is_correct": true}, {"id": "C", "text": "set static route 192.122.196.0/24 gateway 10.178.155.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.118.161.0 255.156.8.0 10.178.155.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1d249bbaa7498aa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98ac45cc-233f-44c0-b0d7-fb3c4285e937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 78).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd16a24275648064d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b8520e9-965c-4b14-bcb7-c8f8a964001e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 78).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e780761004e778a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73ed02c-c8cd-4a1d-bf3b-e677291e3e9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 78).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0587c08b86427356_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa6e927d-8c5e-4ad8-abeb-5f734e84005c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 78).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '47475dd42aa1714b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4392b23-aebd-452e-9b9c-a75577686154', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 79).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a4345040dff84674_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('564edccd-b39b-4f5d-9f52-ce7d4d88a183', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 79).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7026e8778a197f67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c90960b8-eac8-433a-ae05-6c1d6329d21c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 79).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '65c6731cf81f4cb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e704e5b1-4936-4338-94bb-2d73c71ecee8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 79).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '65c4b5fb5588d0ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df680dcc-9668-4ccc-bc39-da95a528eb1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 79).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1f54b8b2198598cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e1e83b2-9847-4eae-9512-7cfff7be0d19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 79).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7efe57a131f144fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('254397e8-dc76-411a-961f-7c664b44bacc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 79).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b529292bf8039992_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fcf8c00-7396-4e62-80c7-335e5cc889e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 79).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a74e08c3a819e702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44970c09-fc9a-4265-b244-510ec8f390b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 79).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2167a9ade0b65a91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5643c363-8fdd-4eb4-8e4f-b5536623ba73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 79).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7a21d56e69e7b671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25fd57d3-a808-4bd5-91fb-0207635231fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 79).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aba56ee10bec000a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b19470b-26dc-4fe0-bcf8-1db0d915d73e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 79).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4085ea64517d02c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04a1f2f3-97de-45b5-bac7-2f201aca8b5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 79).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'de093b91a675a16a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ed59703-ba28-4b06-bc4e-82550326a797', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 79).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '65f5dddbe9d8aed8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('882aec1b-a81a-4235-bd17-23fa45bffa2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 79).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '820f9bc84f75bd1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7a1fd29-a12a-4490-bbea-08fd0c8476bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 79).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set hostname R9", "is_correct": false}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bdd00310a1d0a478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f21a23ed-ce52-4fb6-8274-a71fcf1956d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 79).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6d49db6f8e1af57a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df923400-5189-41a4-8887-63051ad7aae6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 79).', '[{"id": "A", "text": "set interface et-3/0/1 ip address 10.233.251.254/24", "is_correct": false}, {"id": "B", "text": "configure interface et-3/0/1 ip 10.233.251.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-3/0/1 unit 0 family inet address 10.233.251.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.233.251.254/24 interface et-3/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6715756f4930a38c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74a633bb-3ba4-4c25-b4e3-5d3b0338763e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 79).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f487fc35f9c75b3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0be0a466-b1e3-4491-b911-9fcb9d1abf30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 79).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e34ac0e6001d97a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca62a158-82ff-4d5c-af98-7e0cc7c5e7b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 79).', '[{"id": "A", "text": "show interface et-2/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface et-2/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4c6cc058e1388af3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96b0358e-e9cc-4356-beb4-8ea6df2d6221', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 79).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8b761128c0e5659e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1de67064-404a-4543-a5bd-291a8e339bc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 79).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ae348ce973caeb8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('320203ca-881e-41c2-88ea-4c6ccc396d4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 79).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fa0d2dc3434af94d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('649efbfe-f7a3-4daa-b180-189bf021b799', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 79).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93738dcbba3fa5dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f5308d-9350-40e0-b19d-5a8c725b30f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.96.172.0/24 via next-hop 10.162.86.1 on Junos (variant 79).', '[{"id": "A", "text": "set static route 192.96.172.0/24 gateway 10.162.86.1", "is_correct": false}, {"id": "B", "text": "set route 192.96.172.0/24 next-hop 10.162.86.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.45.247.0 255.73.114.0 10.162.86.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.96.172.0/24 next-hop 10.162.86.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8c2b40720eb489c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f931732-3ef9-4095-84d6-e901fa2601a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 79).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '65f0c490d972cee3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8d99e18-96e8-46fa-9900-f03209d6ba5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 79).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4b11d1c218377930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d4d7f1-63da-4e78-9bc1-16c678e6dcfc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 79).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8a7c1afa75f8c5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304ab55d-b383-4326-a259-7479eb5170cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 79).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '142c9aa5da29d36a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ff0b81f-fa58-4bd6-bc14-55840a4b0a9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 80).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5bb1096b7a2ad7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('445dc7a9-7786-4fbb-b732-3140d1c956ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 80).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'e4b5977009ec9a5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f5db90d-156c-43fa-b48c-136faf69c044', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 80).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ead8921fd1ba6580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f8b2be-80dd-4e55-8356-810cc758f2cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 80).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ee6d026ba17baab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('227fb575-d739-4a91-88a2-e849408dbc3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 80).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6515e202def329b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8f94567-cc0f-4c7c-b6dc-6117db99d94c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 80).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '713146317ca94049_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('536beeb4-743c-47bd-8e44-687f66beb6b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 80).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1783e9505210acd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86eb0d5-660d-416c-8b73-06ace0b6b40c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 80).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2cc436128b9dd90e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b63094b-054d-41b9-ac11-9dd6d4288bf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 80).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '401c776e14e3c536_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f4e7ccb-9c33-4b7a-88f2-b49440d98c7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 80).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd2043a7e170f0df1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4d101f1-8f8d-45b3-bd86-189faebc3978', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 80).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '080aec5f8a7b5ab0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91b75319-5836-44f6-b089-41e1bd636497', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 80).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '26edff1b27fc6ea3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84b42d56-403e-497f-a806-6d4c44620eaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 80).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06ebe847c1b84186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2d14ef3-66e2-4a0e-b53a-0e0eb4ba8896', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 80).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3c09087d523cb477_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd353bd1-ff70-47b7-a4e5-86a282b5230f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 80).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9b63ff0e856cd274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bd36c51-89f4-4c12-b8ec-16eec9644b1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 80).', '[{"id": "A", "text": "set router-name R10", "is_correct": false}, {"id": "B", "text": "set hostname R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b3a81369a419843d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d56082c-2934-4cab-9cc7-aef3a34e5a52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 80).', '[{"id": "A", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '83219e055ad6d879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4485967a-947e-4e07-b958-9232ae434e3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 80).', '[{"id": "A", "text": "configure interface ge-2/1/3 ip 10.116.121.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.116.121.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/1/3 ip address 10.116.121.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.116.121.254/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8923f3db747f2fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91f13fc5-a280-44fd-aa29-c71ce11c34bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 80).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e480b2a1a070e4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3f79e59-41ee-41e2-a52a-a3155bf599d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 80).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8b484bff3913cb54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efe83446-d3c0-4f6b-ae56-968b5cfde962', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 80).', '[{"id": "A", "text": "monitor interface ge-3/0/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-3/0/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-3/0/1", "is_correct": false}, {"id": "D", "text": "show interface ge-3/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '488707d8338a10ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553a9a88-2425-41da-8399-0204ad986fc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 80).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '384ad957186a56cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0d6260c-1778-4466-b353-2f5fa76891c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 80).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39ba058b02bbdf6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ebb8b7e-bd8c-4b9f-8840-aa9a08356b87', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 80).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '71809eceee82e35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da34c6b3-40d2-420c-938e-86e019aaebdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 80).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3fbb3d9f9ed49cda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ab4df2e-2d81-4a51-a56d-11db541e71b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.113.251.0/24 via next-hop 10.253.225.254 on Junos (variant 80).', '[{"id": "A", "text": "set ip route 192.34.97.0 255.137.100.0 10.253.225.254", "is_correct": false}, {"id": "B", "text": "set static route 192.113.251.0/24 gateway 10.253.225.254", "is_correct": false}, {"id": "C", "text": "set route 192.113.251.0/24 next-hop 10.253.225.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.113.251.0/24 next-hop 10.253.225.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '148f53800845ac2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f8f4bdb-9786-4b7b-aa70-126574ff565f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 80).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ba58c90e87aa40b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9df0e5d-752b-4173-b5a9-04aed2a49616', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 80).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4ab52e6ed00aca00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('615b0afc-41bb-426f-ab87-560401817a6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 80).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9f7772a1883da243_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9113c10-5998-4a99-ac31-e4a290de2882', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 80).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b62fd19cc3a8feab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b2dc9cf-5040-420a-a1eb-a5814dec04f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 81).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1c9bc694a1172c7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a442fc6-8603-4dc8-b6f4-5fea052c16ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 81).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c666803dafe72d46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acec30e9-8012-4f6c-83e5-4d1179b421f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 81).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f07ccb22b8664553_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0ea7cf0-b83d-4d94-b9dd-5684f4838227', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 81).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd9a2bd313910177c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ad155a3-daf1-4fde-bae5-8f8356335215', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 81).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '512a869c8e1be3c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bae1e231-34d4-4741-b3b9-42a45e47f541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 81).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f35ad07bdca11864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1a260f5-d622-41c8-81cd-94503ae29a0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 81).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '53a873f8d6a36e62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c574f5f-618b-4ba8-bd0b-329d2699fb05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 81).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dea507f6d4038ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('958b5962-096f-4ad7-bf4f-2fe6c208f8c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 81).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c4035c587f7079ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b209e10-818c-47f1-992f-b750c3f43e93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 81).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd557df7a5b34219b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('657d0e9c-bfbf-442a-942d-f536d8bf4a31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 81).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4321a4992312ddc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1213c499-44c6-4f5a-a467-a809902f1ed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 81).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8364d12ed384cade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaff12c9-dae8-40fc-81d7-23363cc6a296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 81).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e41d85820ed6277_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a4fc87e-0956-42d7-abd1-2d68d2c9824f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 81).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '08c65558c1f580b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65b4120b-76fb-4cd9-9a54-ee2bdd86ced4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 81).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '03d8430984a26da7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('497e105e-9b3c-48f3-a456-352bc5601125', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 81).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set system name R8", "is_correct": false}, {"id": "C", "text": "set system host-name R8", "is_correct": true}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9f96fc82b12960b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ba9ce60-bb87-4796-83e6-f0e6cc865b51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 81).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '70810d7adbd922f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e6c2aed-84a7-4025-9560-35fae7e631b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 81).', '[{"id": "A", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.14.122.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.14.122.254/24 interface ge-2/1/0", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/1/0 ip 10.14.122.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/0 ip address 10.14.122.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd8677d3f4b4f96b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41fca9a7-142d-4f3d-b40a-8c46fc2b9e68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 81).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'daaf6b2245806dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1dfa2c5-7713-46da-9d93-98987b8da970', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 81).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'efa3c8dff00567ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a19f92b0-19b6-4d17-8112-879bcab327fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 81).', '[{"id": "A", "text": "tail interface et-0/1/2", "is_correct": false}, {"id": "B", "text": "show interface et-0/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'edf6621687212fc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18c89b27-7822-4bb9-962e-5f363d77ce17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 81).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ffc8fe404e1360eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b314ca-19ff-475d-b85a-5ef1c921cf69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 81).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cbc99c510690b4e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a78f5aa1-8bf0-40b7-b1ed-13feb9a430a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 81).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ac724d4d9802b24c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c47df518-f2ca-47df-89f5-d373e2908910', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 81).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4d50835e876cdd98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f337105d-37a4-4910-84d1-4d7063020275', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.118.254.0/24 via next-hop 10.7.132.1 on Junos (variant 81).', '[{"id": "A", "text": "set static route 192.118.254.0/24 gateway 10.7.132.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.103.220.0 255.138.253.0 10.7.132.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.118.254.0/24 next-hop 10.7.132.1", "is_correct": true}, {"id": "D", "text": "set route 192.118.254.0/24 next-hop 10.7.132.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '64ebd40eff5af360_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fae53a8-54d3-4ca1-a983-f1113325f4fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 81).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5d82783ca5dfe242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6309436b-c623-45c9-9bd1-cc3c130ad410', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 81).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c4622e7c3ccad3eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd60c624-d511-4b7c-bc67-f02a93c2162d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 81).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd1d01f5ba412a6a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a88627f-d820-4364-9715-69eab29372d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 81).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '89fb76ac6204997c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9521399-cebc-4330-a8af-4b66eb4749f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 82).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6d65132c23627c58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99a06d35-cd81-45fa-a4e4-55026faccc23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 82).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3ec79c90f571446c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36937a96-f065-47c9-99ff-f5c3bda708e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 82).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6439206b6ad654e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55cd7547-dad2-4ee7-b542-b0954b3b4de0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 82).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '330da861396e9888_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00464f98-8c4a-4920-9f03-0824167c5c3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 82).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2b609aff68315165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1b1a609-ce5b-4e5b-85fa-ce0489c894e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 82).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0a2ba7e014a64ff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cd90d96-361c-4d2b-b0b0-256d4453ec1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 82).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5fc26c47d47848b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e31685-7306-4686-b3fa-125534e283d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 82).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0bc8a2e2fb736d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33188b8d-0a3b-48ab-a024-c0afa1207756', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 82).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'feab16cfe5d79e6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2d94df5-a689-41cf-acfc-3f17df39439a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 82).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '763370e29ebc26eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdab1f6c-1b6a-4100-9b01-ad587d427125', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 82).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '140aa0d0e629a7a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cbada42-4a83-4645-bcda-6055a8390065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 82).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '34f4448b99710f75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85350f0f-121c-4dc8-a8d2-062fb9621f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 82).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '68540c563269060f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f8143bf-0e00-451a-8c01-4635569f79aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 82).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c1ee76fa4554b934_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d75874a-21b7-4fb6-8ccc-3512b6706490', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 82).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f285fa6be1acd5ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('218f5cae-9cf0-4a6a-a79e-e8c031c3cd95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 82).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '31e9febe7900574c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe95644f-2b97-485a-b648-3ce143fcf22a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 82).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3dea1b518866f463_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f846d2b1-d9c8-4b9d-b9a1-f45a56e0d8e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 82).', '[{"id": "A", "text": "set ip address 10.133.80.1/24 interface et-3/1/3", "is_correct": false}, {"id": "B", "text": "set interface et-3/1/3 ip address 10.133.80.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-3/1/3 unit 0 family inet address 10.133.80.1/24", "is_correct": true}, {"id": "D", "text": "configure interface et-3/1/3 ip 10.133.80.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4d587346434b3301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9e5bf45-acd7-4735-84cf-4d49cf1f70fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 82).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fa4f335b9af4cdc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d274dd8e-2e14-4c92-b25a-3d2f7ceabfd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 82).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '22fa3960a9146bf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed6862fd-f10b-4626-817e-8c13c3fc45b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 82).', '[{"id": "A", "text": "watch interface et-2/0/1", "is_correct": false}, {"id": "B", "text": "show interface et-2/0/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-2/0/1", "is_correct": true}, {"id": "D", "text": "tail interface et-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c247a0d83647af15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2dc25c5-b6da-4957-a30e-11dadc75e66c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 82).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0eb5e9edabcc324e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2ad0f4b-2510-405d-b8f5-0a262fcbabbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 82).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '933fd646c6051acb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95e33063-9b2c-4a07-8dd0-f70578253992', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 82).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b7e4f6de7b051eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0103480c-ba8f-4157-90ea-6e9364f6ece8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 82).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1c82763e2eccecab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d53646c-f2f9-4936-a4c7-1c91dc77ba08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.206.180.0/24 via next-hop 10.251.94.1 on Junos (variant 82).', '[{"id": "A", "text": "set route 192.206.180.0/24 next-hop 10.251.94.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.6.68.0 255.85.191.0 10.251.94.1", "is_correct": false}, {"id": "C", "text": "set static route 192.206.180.0/24 gateway 10.251.94.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.206.180.0/24 next-hop 10.251.94.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '57d13259afb46bcf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f3266b1-5006-454a-8bc2-fcbfb1084dfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 82).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '581f989015523fe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcc1df6e-884f-4631-8cb4-93ae5e9df22b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 82).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8b4446c302bf58fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47457f28-2317-4373-811b-5de9f1e70ef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 82).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5635bcf64f28400c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd9d88aa-509f-485d-8684-93cfa6de709d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 82).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5fb1ac594424fa8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64f07627-5b5b-4bdd-9771-5ae605c752d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 83).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0e29218c827192a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae966986-55c6-497d-913d-1da7e68c1de8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 83).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a7495090928bb12e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d026ad7-a70f-49e0-8791-b8899ba8856f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 83).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b9bfb245fc9ba486_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcfcf8fd-2b10-4871-9b58-b7d1c6c1e30a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 83).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f660a33bc057bd7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac658daf-f36c-4900-a09f-145f1e9b146f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 83).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '901c5c12a464a13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b133511-7e69-440c-b25a-24dcb962cb6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 83).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7fc6d8292b19b5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b77c50-efae-475c-ab49-24a1bc175c1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 83).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5169b910c6fbaef9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2e14f14-0f8d-40c4-ac2e-4776c5fa7e0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 83).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65f47a4769984ef0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87015372-8c9d-40e9-a9d7-c1b11182a49c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 83).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'abd702f61c0b28bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12d5973d-5296-4203-a056-0afc7134d84c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 83).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '57ef25c57988cc5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1daa1ef1-39c3-4df5-8135-20076c9d09b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 83).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3ac1759926bb5cc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0612b4b8-cc38-49e5-8035-5a5f1d81de4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 83).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1ff004b458cdc0d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b5d395-76d7-4a79-96fd-e7c86772b77b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 83).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '023aed17b200d346_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d62fe6-7a4a-4de5-91f3-c91b0efa11a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 83).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '56cacac9a03a155f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3868a17c-9fa8-44ee-9a7e-fe86d7779454', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 83).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a2ae00d6f01fe54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2959118a-9971-4c4a-92d5-8b703269a915', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 83).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20315533b86ee396_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d2de8af-f08e-44c5-a9dd-09992ab2ff73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 83).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '95b6f8ab58750c43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14da1276-aad1-4771-b317-0f8b39d048ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 83).', '[{"id": "A", "text": "set interfaces et-3/0/2 unit 0 family inet address 10.252.223.1/24", "is_correct": true}, {"id": "B", "text": "configure interface et-3/0/2 ip 10.252.223.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.252.223.1/24 interface et-3/0/2", "is_correct": false}, {"id": "D", "text": "set interface et-3/0/2 ip address 10.252.223.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ec9fed1b15611c5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be7ad379-030e-41ff-b8b5-4f9fc663478f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 83).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '101cd532abaf0dbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b27e78a1-395e-464c-87e5-3d2f4f20b07f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 83).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '60086c2aa13e3f39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('706a7bc6-1f99-45cb-a1de-6b23e8f18d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 83).', '[{"id": "A", "text": "watch interface ge-0/1/0", "is_correct": false}, {"id": "B", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6f542c145a00824f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18058216-6251-4b59-9d42-73d5680c3ff4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 83).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '14f6484e9f1f9057_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49eea540-bc93-4033-b2c5-d2c581625689', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 83).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a3883cd83a6b9c57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea48423-0145-450f-bb52-9f1779f233b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 83).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '5716d8c02fd244d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('087aaa0e-29f6-437d-9048-6eb94f603bb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 83).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f1be8273605ee74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd06944c-9f9b-4f0a-b17d-a2abadfeabad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.249.234.0/24 via next-hop 10.174.44.1 on Junos (variant 83).', '[{"id": "A", "text": "set ip route 192.143.223.0 255.168.114.0 10.174.44.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.249.234.0/24 next-hop 10.174.44.1", "is_correct": true}, {"id": "C", "text": "set static route 192.249.234.0/24 gateway 10.174.44.1", "is_correct": false}, {"id": "D", "text": "set route 192.249.234.0/24 next-hop 10.174.44.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ca210f55b829fe73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba47b14f-fc8a-402b-aaef-d24a5e0af50f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 83).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e8b7e1570a087c86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f905364c-0d30-4782-9ee6-e08db3603827', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 83).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c60125578c5cfedd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e3988d-4337-4e9e-9a25-b5b7499ae265', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 83).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd271b76668a32554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9a50d61-d5d0-4e6f-85db-7a7baebcd06c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 83).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '573b48179c6c9718_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b56f4866-cd81-4c0e-a533-727be9247d0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 84).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '44c46d525928c5f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcbcbf49-872e-4599-ad79-c80c7f7b7d45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 84).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '2a1621a354c5f1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc1ef4ac-ebcd-4325-a206-bc6bfef0011c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 84).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9a58349188c3739a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3080753a-ffb2-4941-aa09-4eb3461de0d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 84).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a86f7addee445611_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e5aed50-acc2-426f-a6c3-15e00c962c18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 84).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b4c47c47c8179b14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92010b8e-870c-41b9-991d-bb08381883ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 84).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2b6a92350eae3499_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ace7f5a4-f94f-492e-a1b0-847c23a20e06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 84).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0b38bff4fdc7c95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07ea33a5-b11f-4c89-a17a-6c658734a45c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 84).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6d61114771d36d9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1852ddaf-284a-44a9-816f-62920f62846f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 84).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b4de4259f321d38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7516729f-62fc-4122-b39b-669909872372', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 84).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3207cf7c137c373d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4306b9d-474c-417b-b57a-5c28a46742fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 84).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e4188d9e0463bf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a53b394-02bc-41a0-8305-631d86fe0ca8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 84).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '222a0dcfd3e028cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('172b8f20-c3ee-4248-920e-ed9a5df5d225', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 84).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7800134ae6e65a34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ffc28e3-4db9-4096-91eb-f7fef87eeeed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 84).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '551ae4a46be010e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('295d60c5-bb24-4f89-87c3-ecf997f79e6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 84).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9843f0f3e34c5aac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19e397bd-5f78-4d82-ac93-58dafcdfc2b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 84).', '[{"id": "A", "text": "set hostname R2", "is_correct": false}, {"id": "B", "text": "set system host-name R2", "is_correct": true}, {"id": "C", "text": "set system name R2", "is_correct": false}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e5f32bba7b58bdfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed3f932c-c7cf-4437-a11b-973ebbf0e1a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 84).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a1299a5c7929ef02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b09a91d-5237-4136-88c9-acdbd521a781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 84).', '[{"id": "A", "text": "set interface ge-2/1/2 ip address 10.179.178.1/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/2 ip 10.179.178.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.179.178.1/24 interface ge-2/1/2", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.179.178.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1f4608a2ce4ccd55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c177c0a3-52e8-4ed9-9b9f-2320873355c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 84).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4278c7e22396ddbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c85a0e3a-5d68-4f3c-b112-84d1e4e4902b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 84).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '66d4341d0ae4bfd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fabfda4-780c-418d-985b-5b87cbdfd754', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 84).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "tail interface ge-2/0/0", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "D", "text": "show interface ge-2/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '600f425874bfaff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f5fb621-db7b-4743-a13a-24801e1cee35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 84).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b8d7e92e1e1e1fe6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4af7ed0-a851-4d9c-995b-b3f6c271702d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 84).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2bbce8ccfb1d32b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a760ccf-0a89-42f9-ae1e-ecd8219a332b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 84).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bd83e019a1c70abc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4826b41-baad-473e-8667-155a6befceb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 84).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6185a5a2e25d1044_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64abeb1d-4543-4cbd-9c6f-8a267188f411', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.85.254.0/24 via next-hop 10.10.217.254 on Junos (variant 84).', '[{"id": "A", "text": "set routing-options static route 192.85.254.0/24 next-hop 10.10.217.254", "is_correct": true}, {"id": "B", "text": "set static route 192.85.254.0/24 gateway 10.10.217.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.144.10.0 255.188.6.0 10.10.217.254", "is_correct": false}, {"id": "D", "text": "set route 192.85.254.0/24 next-hop 10.10.217.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '154e11fb64a7ac6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d31c47ce-05f7-4372-af04-765ea516d16e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 84).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7cf1c2daeb50cb5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc4d51ee-8eb0-49b3-b6db-17a0c39328c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 84).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'ec8cc46840e27ac3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0b24bbe-1a7f-42cf-b04a-01e25ea3b541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 84).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '655d8433fbc5ff73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f74c47f-b025-4805-a78a-a53fbb940809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 84).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6a60236b45014769_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dff5e58-284a-4583-a484-2b652804eb23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 85).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6c3379fa1b0a77f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110a9b33-8172-420f-b089-4b9d7a68a905', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 85).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7f18cf2060156081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ee6dece-b653-444a-b0e6-e2a482fc99fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 85).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '63de150a99ab82ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7913510-c1d5-4ab7-bb41-6956d1593d15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 85).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'deca460bd6f6ba4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdc98ad6-4b56-439d-a67c-1cf3c77cfcb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 85).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '285b33efd9d16672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8fa63b9-0e98-4ff5-bfa7-9e583a69079a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 85).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '8f19c34ebbf0ef6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e7bb864-0cca-4d62-8487-ea38fd75ec4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 85).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'acca4d02b355f61c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d180f6c9-4a0e-42e7-b5d5-9619c0ae80ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 85).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '287ce986b118f321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eacf1b4b-c50d-4a7e-9be6-1af4c7398287', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 85).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8bc8091a5cfd792c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51968e99-afcc-4703-aff4-11d7ed9bf29d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 85).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3c858fe973d1db32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25561ff3-e8f7-4220-9a6f-e399e8816e2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 85).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1cc9aeedcf7295b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdd654c6-4bdb-4301-a4f6-ca4bc52792ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 85).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e22bc84555981854_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b10e2a04-83a3-4d10-b2c4-aec9c904071e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 85).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d2708d8c7036a45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9e9d4e-34ae-4216-8402-fd46de8f3109', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 85).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fa7c78a8a0fa894c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b61555e9-52e8-4061-84e1-c491a5a90bd9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 85).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ed4d9433d70b7c25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dea8d10e-97d9-4d01-8bac-a3906e3ed9ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 85).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set router-name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ecb72ca6f8b78856_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb2fc556-4d50-4c95-beb7-75771be81f28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 85).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd28750931645930a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b109531-4d6a-47b5-ae50-baee5bcf09a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 85).', '[{"id": "A", "text": "set interfaces ge-0/0/1 unit 0 family inet address 10.160.210.5/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-0/0/1 ip 10.160.210.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-0/0/1 ip address 10.160.210.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.160.210.5/24 interface ge-0/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '682acc1d90721c45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a0eeb74-2eb9-470c-adad-5f5b06796d27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 85).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b7535d5a3029227b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('613f6f6c-01fd-4d07-92cc-bf3b9f4e42fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 85).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c64a00f6aa7e938a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9262d35-4d76-443b-a558-54975d6cb0a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 85).', '[{"id": "A", "text": "show interface et-3/1/3 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-3/1/3", "is_correct": false}, {"id": "C", "text": "watch interface et-3/1/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-3/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e0ce905d5283b0df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7d6474f-5e4e-4d05-a7f1-c996a6e1f12b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 85).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '38ec7617775ca0c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c843178-2b8c-4a0a-aba9-f43bf8a0706e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 85).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '34148637bfef9c27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fc32f37-8fec-444c-9b32-b2a7f4b7ffc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 85).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'de3c4be46649402d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d3b412-bf50-4739-9a61-b152164c58e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 85).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '11923cdc26bf0e83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b42d1c73-c9e0-474b-8a20-8f98dd16c3c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.189.231.0/24 via next-hop 10.32.122.5 on Junos (variant 85).', '[{"id": "A", "text": "set ip route 192.119.169.0 255.57.220.0 10.32.122.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.189.231.0/24 next-hop 10.32.122.5", "is_correct": true}, {"id": "C", "text": "set static route 192.189.231.0/24 gateway 10.32.122.5", "is_correct": false}, {"id": "D", "text": "set route 192.189.231.0/24 next-hop 10.32.122.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '96feb5dc9a81c7c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ad126ff-cd1f-45d9-aa26-780b0390e55c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 85).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '748b9d16cf80816e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('255fdc5b-b433-4767-90dd-c57deaf98613', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 85).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '65ec19e9e7377dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d324405-d439-4594-b178-bd784435b856', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 85).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2462cc73c42f18bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('227fdf97-97bf-48ff-907c-56dd35396b85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 85).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1fd17b18a23a4b84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6402684b-8ffb-4201-9594-cd8cf71b7ae8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 86).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5dcbccaf8ea89ac8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df2287e5-9bc1-46be-8e0e-48404ca31987', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 86).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ad9771f7cda6edc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04d73d0a-52ec-4934-b8a4-4949b9c547ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 86).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4369e0360c3507a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37c7849e-92d4-484a-8d3b-39ed83fc813a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 86).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4229793054e1e042_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a38e9418-d257-4118-b3f8-9ab9bec7a41f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 86).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '619aa7d38718531e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95f2d9f4-7f49-4c61-9199-0d978bdee6f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 86).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5dc78d1c4bb751f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fb9a6aa-f473-47e7-a789-0c8e685afea0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 86).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a8530ada7c401ae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97cdcc74-d647-4f14-a160-1abf52ee0168', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 86).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e315e5dbeee8e565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31e99f9d-1aa9-4a17-82a4-495c98a18138', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 86).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cd628db240cf6ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d09051d-e206-4e38-9233-f614ff503431', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 86).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1cc136e2eb00eb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cf40c89-e9c3-4fe8-a247-b46d73db2f05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 86).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '48518798feb65a22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd2e21d1-f45f-44c3-9205-b9a59a5e3ca5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 86).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '02050df11bca97ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea54c04-a77f-4c85-8a7d-dfe96c0e0710', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 86).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f17ff77b0c665bc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c1bfe81-0b24-4f8c-8f2c-b410af069a1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 86).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd419922307a3342e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc520ec3-e440-4121-86d7-53d2741562b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 86).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c348ff95f8f106b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('363fc3a8-ee9f-43ca-a2c4-9c9957eb4d03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 86).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set hostname R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'be7e04ed007f9883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('783dab1f-c045-4f4a-9598-aff524705495', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 86).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '84005c0a96a0266a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ea70c6a-92ae-4a63-9119-eda008f72ebc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 86).', '[{"id": "A", "text": "configure interface xe-2/1/1 ip 10.135.142.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces xe-2/1/1 unit 0 family inet address 10.135.142.5/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.135.142.5/24 interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "set interface xe-2/1/1 ip address 10.135.142.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c699871133508bd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19cdd4ed-5621-4e56-aa76-0f7ce32de20b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 86).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f331fef9b1a49ade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f19bf2cd-5cf4-4bfc-98b8-300b3f0e7ae9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 86).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fa090c2bd7647b7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da174de-aa01-44f0-bba9-04c1cd2e0d4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 86).', '[{"id": "A", "text": "show interface et-1/1/0 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-1/1/0", "is_correct": false}, {"id": "C", "text": "tail interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-1/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '265f998429d7b6ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2ceeba0-ae5d-408e-bb52-74c2082561db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 86).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b0b5997bdb2b125d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('042495ba-348e-4087-a109-217ac1ea0761', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 86).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd8eafcd5693ee65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0cc0da9-86c4-4544-838c-75cbb50d9a7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 86).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f607b48f733871a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09522361-790f-4c49-af4d-254bca412466', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 86).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '03772f0964e627a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('949bffba-e76e-45b7-9cf5-d070d562c00f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.148.51.0/24 via next-hop 10.59.236.1 on Junos (variant 86).', '[{"id": "A", "text": "set ip route 192.250.202.0 255.236.110.0 10.59.236.1", "is_correct": false}, {"id": "B", "text": "set static route 192.148.51.0/24 gateway 10.59.236.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.148.51.0/24 next-hop 10.59.236.1", "is_correct": true}, {"id": "D", "text": "set route 192.148.51.0/24 next-hop 10.59.236.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '19aff3fb2d1e9420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('885b16ed-6299-4811-9eeb-c55a63763677', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 86).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2ed471d676a86317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7887ce8e-9a1c-41b8-84ef-ef7ba82c9fcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 86).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '298bc3d48fe57ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8d234ba-b410-43f0-8be5-b3a277579b2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 86).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '165c33e2c5246b53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cffc832-b056-49a2-b2b0-354186fa5a73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 86).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '709e6e6fe17b2608_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f1609c-b11e-45bf-805f-44d9487c4022', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 87).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd90965a39047657c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f44b41e-3845-4dcf-a728-70af543732e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 87).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9d87797daf33b6a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f29ec464-7253-4b93-a9ee-082ff993025b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 87).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c6a0c02b25c0583c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbf8b562-89a6-43dd-b7ab-dc6e83f0588a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 87).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f8b3fb648ac8accd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cefd70b-e4fe-42ee-9c57-0d6f2b7cc093', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 87).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '27ab5e4e83906628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aaa5c2a-137d-4cdd-aa00-979b15c4d727', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 87).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2370e575df08281c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d8b4c69-77de-4f9e-8649-1d38ac918e8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 87).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '95b4625dc3905436_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d29b8fab-4db2-483d-a65e-8722d9b86b79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 87).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd36d6e01a0116e70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d054177-a07b-4695-a20e-cf50fd68abba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 87).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '780fa357ef0bb373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('527af9a7-f29c-40e9-8d66-a1a015b9bf7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 87).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6692706593aa39cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a012231-5032-4284-8a90-a22b6cbbb01b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 87).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2f237355ac1b7920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('949c5fb3-91f4-4486-be84-0be4a9a74e94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 87).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '62b0b94c55a1c964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('297e0bc6-2fab-4272-a24e-bcc9f0aa7547', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 87).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd238cb80b140c55a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0367ff1-e570-4a6b-b1e2-8dca735bbdfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 87).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '571f4adb76098f64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68227998-a32c-486d-b8f9-077a6ecd3d73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 87).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ca33e8c33b10f19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcf004a2-f60f-462c-988c-4d5ceb0e7577', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 87).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set system host-name R1", "is_correct": true}, {"id": "D", "text": "set hostname R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '921c41221fe9f2a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f689f49-3b17-4a55-b6b1-57d7c0473624', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 87).', '[{"id": "A", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b5d57df4c5f0ed1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dde7e85f-9662-4ff2-bf81-b6bd3f5a0640', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 87).', '[{"id": "A", "text": "set interface ge-2/1/2 ip address 10.161.166.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.161.166.5/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/2 ip 10.161.166.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.161.166.5/24 interface ge-2/1/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8a985dbe26112416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9682adc3-84cf-44fb-ba10-9d8075328fbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 87).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7a7dd2891a2c3827_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('077580be-72fe-4d3d-a26a-1bb8d0029027', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 87).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '21b6d4cebfe7b09d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be8da8e-fdc3-4832-8a99-9d63a6c50896', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 87).', '[{"id": "A", "text": "tail interface xe-2/0/2", "is_correct": false}, {"id": "B", "text": "watch interface xe-2/0/2", "is_correct": false}, {"id": "C", "text": "show interface xe-2/0/2 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '627e953d2869bf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57816811-082c-4850-8e89-4f390cf59567', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 87).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bfc2518f80a09872_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5017d40-534b-49b9-85c4-421ebe67e10a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 87).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f29c6f60380ff886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd19d014-fcd2-44d2-b12f-4643fbd4a554', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 87).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '603819fffe211371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37c2c660-2c6b-40aa-b63c-f40264045cda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 87).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd32f4fc033c3299f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16a84701-6227-44f0-b857-c7fe47db2479', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.88.64.0/24 via next-hop 10.2.80.254 on Junos (variant 87).', '[{"id": "A", "text": "set static route 192.88.64.0/24 gateway 10.2.80.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.219.250.0 255.28.135.0 10.2.80.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.88.64.0/24 next-hop 10.2.80.254", "is_correct": true}, {"id": "D", "text": "set route 192.88.64.0/24 next-hop 10.2.80.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3f9fac6e9f41dd34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ef482ce-304a-4b63-8039-41c2c17f2daa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 87).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '54fb95129b8aa0df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('002d303c-fed3-45bf-927d-1474055ae445', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 87).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9995c513a84fc6b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a034b71-5e18-4f3c-b8af-9ba831d4c294', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 87).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'df040d433366362c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8e72a08-20aa-4445-9374-db7a5abd5261', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 87).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3f7bd5ff6adefbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d428a94-202c-42f4-8593-a8babb417e66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 88).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '436854961d59189d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85d039d8-fc03-4835-9f3c-c095b1485104', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 88).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '766a5a62ac6a90c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f5bd919-42ff-4d78-91f8-21358c9e9661', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 88).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '169bc57a51191ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d805413-893f-4b9e-a8e4-ac9b1fc0baac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 88).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6d4cca7c8003d3a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f2deda5-6c91-4ef5-8271-6e1212c6056f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 88).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '284e39b542b983bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c130ff3-3544-4e97-9c4c-b8b6e8f18986', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 88).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ec5124cdff72f611_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d89dc2e-06bb-477d-a41c-90be416d996a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 88).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '42ed1a14a9bfb120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a9fd35-1fbf-4c6a-a746-2e9363567371', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 88).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c35d67e38bd7488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea4f487e-cfd0-40d3-a345-d33013efc2ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 88).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28533bf3be51a51b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b77d5194-05f4-4638-ae13-ba752a9c9bef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 88).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '77013fe141b0673d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db3e5d74-74f4-4698-ae98-58c637c8a625', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 88).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1fa3b09070213e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7630294-cc78-44d3-b80f-cbdbc89027f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 88).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '63cb17ba275c0f43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('545b29b5-56a0-4773-a722-93a5ca0659bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 88).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '62d67a6868c25a23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76517517-87ba-45cc-8b10-60e4983ba161', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 88).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc00ff50d3ca2088_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38e49d2e-8f0f-45c4-9346-a63845069584', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 88).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '27818b93660fba62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('798a1708-db6e-4790-91bf-cdce2b8b7e03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 88).', '[{"id": "A", "text": "set system name R9", "is_correct": false}, {"id": "B", "text": "set router-name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7530f8de77de8671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f4f726c-5352-4af2-b848-abd2802b4bed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 88).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e27354888e2e08d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e451f195-9f74-4848-8a1b-f4f8b8a395ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 88).', '[{"id": "A", "text": "configure interface xe-2/1/2 ip 10.39.179.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.39.179.5/24 interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "set interface xe-2/1/2 ip address 10.39.179.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-2/1/2 unit 0 family inet address 10.39.179.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fe4e932d99295371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9f0bf74-624f-4134-9203-61510a615b1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 88).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '872fa1b5921fcad7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('760f0617-7e2b-4d9b-973e-b7428cd5567e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 88).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b233f0a42d7b1638_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fb88d36-97c8-4c61-bd9b-b32ff086ebf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 88).', '[{"id": "A", "text": "tail interface et-3/0/1", "is_correct": false}, {"id": "B", "text": "monitor interface et-3/0/1", "is_correct": true}, {"id": "C", "text": "show interface et-3/0/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '056cb130f40635bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110d4b03-473b-4f65-a083-1798fb0be6d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 88).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e4857f1719d12a04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb4d8d58-3828-4b6b-9548-05b262e2b2b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 88).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '276f3f33de4849d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c45e83e-0eb2-439e-be80-d51fee931416', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 88).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c782279473b90e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da64152d-dc70-4390-9eb8-fc86547e6f96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 88).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a7613118e8705ae5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b094a14-a004-4e5e-a982-4c049615c9a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.128.172.0/24 via next-hop 10.217.97.5 on Junos (variant 88).', '[{"id": "A", "text": "set ip route 192.180.60.0 255.65.57.0 10.217.97.5", "is_correct": false}, {"id": "B", "text": "set route 192.128.172.0/24 next-hop 10.217.97.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.128.172.0/24 next-hop 10.217.97.5", "is_correct": true}, {"id": "D", "text": "set static route 192.128.172.0/24 gateway 10.217.97.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e7f37df711db3efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abcd016b-402d-4a4d-98be-5b878f93e127', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 88).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '858369ad63b15d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79618137-9c51-415a-975b-9d0b59eea841', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 88).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8671566bc4e54164_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0ccb83f-45d6-4384-8227-200912b96fcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 88).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '850291bcf98a4ba5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c44ba9c6-fe9d-46af-aa2d-20d1f3267b3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 88).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9d8482cd5521b747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53dade86-dd26-45f7-a2eb-864fd1e0653d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 89).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3a86a11f35ef1890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32d6eba5-d3e9-45b7-8455-b9f1a3563604', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 89).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5437bbb40a1d524d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6287955-62f5-43b8-8097-360913711cf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 89).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '24a082b1fad8ba44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('253445b2-2be3-40ca-a36b-87140c3712bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 89).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '48ce280ba78c101f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4e10fc0-2120-40b7-85d2-290844c8ff2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 89).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1922e16aca121d37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('450f3cf1-5621-451f-88db-392fd6bcef7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 89).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '088d669c935d839d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12291dd6-29dc-4184-8394-e5d96a53e88f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 89).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '59e343b82c84c384_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d61094d-fe30-42b7-b8b8-fcad62ee338f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 89).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f1f6e38e53fb33e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c61c7d9-f447-4025-9919-14182693b11d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 89).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2a817548f4a81fc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1deb49f-c16e-491e-a6b6-b0e6f43ab5fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 89).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b11d8aba40217087_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('942eb743-b559-432c-a172-72eef3c50c7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 89).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fda6668678cd0cc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef0561e2-e8eb-4277-a499-7b1f1830838c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 89).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '05299805ddf83ccf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28aab6c2-8a6e-4be7-9b91-032d7043ae3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 89).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3aca426c13195737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aae5f3c-f512-4344-9baf-6588ef268962', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 89).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ec5fe3268dbd809a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e7d8b43-ede0-48da-bea2-ea0ab7101c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 89).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fd7c244beca0be4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8606a70-a4d0-46bf-91ff-040d7296ce08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 89).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set router-name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e74dce2dadb5c16f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ae0cbc1-256a-4946-abbc-095e5a8d0e12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 89).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a74d8165d282682b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca08f69-8df0-446c-b38a-0b9abea5859b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 89).', '[{"id": "A", "text": "configure interface et-1/0/3 ip 10.98.28.254/24", "is_correct": false}, {"id": "B", "text": "set interface et-1/0/3 ip address 10.98.28.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-1/0/3 unit 0 family inet address 10.98.28.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.98.28.254/24 interface et-1/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'da5c95a5959a58f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40eb7cf5-d937-4064-9624-e34172f639f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 89).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '57a192be97ec931a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4033b979-8d53-464a-be02-a3489b79caea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 89).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '29af81f4527b9aa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b1f578e-8813-4d7b-b51c-38771ea9516c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 89).', '[{"id": "A", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '469ba7c5519b3e68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71beee7c-980f-40bc-9fa6-2f666bb7f809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 89).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0c116f942dfeaf5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31d42603-dab7-4ad1-a55c-4f5a5011ba55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 89).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '37f76b69116db531_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('322322c4-50f5-4eab-bb6d-bc63d46c52bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 89).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '99f3a583e0ce4343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9e998e0-e333-4053-8adb-341210105e12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 89).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2ca462ebd8c285c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1edbfbf-494a-4e73-b3e6-6438a1399025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.169.154.0/24 via next-hop 10.73.130.1 on Junos (variant 89).', '[{"id": "A", "text": "set ip route 192.91.111.0 255.187.50.0 10.73.130.1", "is_correct": false}, {"id": "B", "text": "set static route 192.169.154.0/24 gateway 10.73.130.1", "is_correct": false}, {"id": "C", "text": "set route 192.169.154.0/24 next-hop 10.73.130.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.169.154.0/24 next-hop 10.73.130.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0a972c2fa6a931f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8acf6797-2d10-41a9-9339-2f8878170ca5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 89).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7aac91cf813a9a20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6177fe26-6c2d-493d-8870-2a918100c744', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 89).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '325d0b0bccc51bd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba5de7e-6633-4e54-a40e-b4b160640653', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 89).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '560c425a1c8c968c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('018a7c9d-f763-4db7-8e2c-b2d2247bf2a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 89).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3b7bb3f19abdbd48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dafcc75-e538-4513-b828-a892f70c8dc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 90).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ffec31b7e1ee47e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64e09992-14c4-4cc4-8d81-6223bf10154c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 90).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '35ff79d9a7886e35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b96d0c-209f-4f17-ab0f-d52c1dcd07a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 90).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6002a49c137d9b6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ca690ca-c254-43b4-a7b5-47ace572553c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 90).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7ad633f7e4f8b74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8df81b5-62a5-421b-b6fd-81f6061b22ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 90).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2e9ad4fb11bb5408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca7b916-b378-4831-971b-4af5eb1a20d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 90).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e8895010ced1a9e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bcabbc5-f043-4be1-866b-4bc90e83029b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 90).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '99febe6fe21dce73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52c21c65-31c8-45ec-baca-a5bb8c4a3cf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 90).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '45bff9a65558312d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e1abe10-9dd7-4d83-a58f-72dd89109fb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 90).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8bb32fb74c058871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f5ad7c-5962-449e-bab1-9056ea19d4d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 90).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '80d4b8de61079bb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1542fe1b-0c97-4472-a1ba-6e29b904e160', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 90).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3f2433221c893987_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b36f95c-d5e9-48c1-bd26-d2754c0f0cd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 90).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '921941d6af0b5d0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c21c0582-ec7e-41cf-b401-c83e23235f00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 90).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f8dfd2023bc6c41e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c92ebad-174f-4cb9-b8ce-1d1896f7cfc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 90).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca4d8404c3c68b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8daf09e0-9062-482a-b42b-7a484bef0822', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 90).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32ecba85c608e25e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f814a3f9-6980-4186-a1be-8b7b95063fd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 90).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set hostname R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2d339e6625664ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ee1037f-1494-471b-b00c-fdf41f3ceb7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 90).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'baf77e8857ccd4f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b24b8088-224e-4b25-89ff-a81bc828fc67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 90).', '[{"id": "A", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.29.45.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.29.45.254/24", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/1/3 ip 10.29.45.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.29.45.254/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fbee00a48e949f0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee2eef8-aa16-4a17-8361-20a20f043730', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 90).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '528be86bf6d8fe90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68ae9074-09ba-4b39-852d-643852ba02e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 90).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '449c1555f4e12072_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bad881b1-1d68-47c9-8551-9bef85fae98e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 90).', '[{"id": "A", "text": "watch interface et-0/1/1", "is_correct": false}, {"id": "B", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-0/1/1", "is_correct": true}, {"id": "D", "text": "show interface et-0/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9efb985df459c359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c43b994-0b69-4bd5-8bbf-37da2570163c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 90).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd1fbf331089decba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e3237d9-182f-48e8-bd58-86dd6aebd04b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 90).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'aab61a811d7bb130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29d20d52-649d-45da-8de2-8f661e3fb5e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 90).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '97b903b082cfe582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4d684c0-b98c-45f5-86ce-95d9d197963e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 90).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '65a022141f4dd822_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('798abfae-7524-406b-95cd-779e76b342a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.228.53.0/24 via next-hop 10.254.170.254 on Junos (variant 90).', '[{"id": "A", "text": "set static route 192.228.53.0/24 gateway 10.254.170.254", "is_correct": false}, {"id": "B", "text": "set route 192.228.53.0/24 next-hop 10.254.170.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.101.118.0 255.54.250.0 10.254.170.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.228.53.0/24 next-hop 10.254.170.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2fcad01a9c7ed162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a3c84a-c5fb-4f66-ab03-3c4b371d05bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 90).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c23eee74afc34adc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f8643eb-0ec6-4b0e-820c-397f1fb63659', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 90).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '13436e660db9588c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('178d6f57-e27d-495d-8a05-457f78f63c95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 90).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a45347c429769894_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6e30ebe-73c0-4315-9652-be1b362af676', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 90).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0bcb15375543298a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bea8e413-1fd6-40bf-9ee1-d2cd036ebae5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 91).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c6398e658e46f314_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1fa8744-ea3b-48fd-956c-afcec7ac1c8b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 91).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '446c09777594745e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8910b841-16f2-47bc-8d05-cb5749cd3e35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 91).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9f12e48891c7a2aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02768033-6442-4849-af43-9ed067ef733b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 91).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7e70cd4ee7d09600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43601756-4597-4983-afc0-a1ad8668651b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 91).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd785212761918db2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cb04b98-3a0d-42c5-a35d-07a5425f2ba7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 91).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ada92c4f36226e3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad3a9f35-90d0-488a-818b-70c930b33dd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 91).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9257166b2aaf3f6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89db5ff2-f944-472d-9440-25608a8838a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 91).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ffb84efeabdc30ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd86f23d-39a4-4448-9a72-b4cb94901d9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 91).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c9f0fb6fa0690ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('761cdec5-d5dd-4c0f-a18b-e3179979631c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 91).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fe7f389726ed7daa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('606e2b37-a261-4778-b06d-d5c07345f352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 91).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4044384516b0748e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95b7d3c8-83aa-4d11-bda6-acd4237a5333', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 91).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '32e409c22ea50422_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aea3f80-9ad7-40d8-844a-05721f245fb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 91).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8be285a65802829c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b0e3347-0f44-4b1f-a922-624fa105c7b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 91).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '328269b3dea489bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8ee349c-a593-47bd-9989-27ba3ce843e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 91).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5a887bec8ed8c44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1845e9f-dada-49d7-9dea-166d1ad2d796', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 91).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set router-name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5775b79b4e5ae3d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c71609ed-43b1-404b-aab8-491fbd16bf48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 91).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd09b84b7203c45d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2a906b7-0712-44cc-a77b-49fa592667b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 91).', '[{"id": "A", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.20.82.254/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/0 ip address 10.20.82.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.20.82.254/24 interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/0 ip 10.20.82.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0af0e6454e8b44e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e63da75-91ee-40c2-a267-742eef9036cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 91).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '94e42128bd56e32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90603ce8-f832-448c-9541-a114b7b2f60a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 91).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '046a2721a572591d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81762dd6-eba2-4f0c-8669-113c99fa29fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 91).', '[{"id": "A", "text": "show interface ge-0/0/2 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/0/2", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/0/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ff81ab8a369fc8a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84ba7554-3042-41e0-8baa-f7f307cb654c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 91).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd786794ac9bb6ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32de969e-8a77-42c4-bf50-cf2eda2d5f1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 91).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '026ec57ec1817793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7b030d6-0804-4623-a4af-b8b5ebff46bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 91).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd3bfeda1ed421d28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf4914a3-1279-4435-bd83-e5f326731402', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 91).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97993cb89c1d2650_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c66b90-cf94-4a8f-93e7-1831d628b311', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.62.78.0/24 via next-hop 10.62.231.5 on Junos (variant 91).', '[{"id": "A", "text": "set static route 192.62.78.0/24 gateway 10.62.231.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.62.78.0/24 next-hop 10.62.231.5", "is_correct": true}, {"id": "C", "text": "set route 192.62.78.0/24 next-hop 10.62.231.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.209.11.0 255.21.214.0 10.62.231.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f6bbc3d9308444cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fa1898e-06ce-4570-bb65-a50b8e9380ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 91).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c34f34968cd0e720_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('751b160d-c975-4d61-a1d3-4a2fcb7dc459', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 91).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5ad53dd187da8105_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9df452d5-4b5c-48ef-8ea6-7e4fbc295971', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 91).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '78f2b8814b4ac8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb55ec2-411c-4c23-a360-f882ef3adfce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 91).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a1d8eae5a7dafee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff91c77a-1c4d-461d-a743-8d03f7d1c70d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 92).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fb0b3935e20bc406_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb1cd369-c74a-49b1-bb67-b9360a3feff5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 92).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f50a36d47e71b15c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a814ccfa-2d62-4bfd-90d5-89f546ce8531', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 92).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7c1e517dabdd2c88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('023ce7c5-0042-44c5-8011-4304b54321ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 92).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e9113f73204bacd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5937653d-8694-464d-8e2e-1aaaf255091b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 92).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '90d18f9b160d1cd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f4d592-7b30-4ce3-968a-bed75f662c70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 92).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5536e9bfc031d3f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a707dce7-f91d-4a00-bcbf-ea688fdebcc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 92).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fa5ee281c2fb96c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d737e5f-d659-4dca-92ba-8d71e41c109f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 92).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eca67182a9cc433f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e2fb3fb-f856-42b4-8594-574ff62d0ac3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 92).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '631d7055c91c0376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bfda1d2-6163-455a-bb6a-7df1c16a3c25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 92).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'aebbc443fe93b48b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef600cb4-919d-47dc-a0ef-365cdbd39c2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 92).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9e2be0e403e3ba36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64cb5f31-9762-462f-ba6c-a2dc3d2fb28b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 92).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '014a59b8e2be972b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37f6e7e0-d80b-480e-8030-71081968c8b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 92).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'afdda08e7494b6bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d19b225a-d32a-4b28-9448-05e5852ae2e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 92).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'baf41d50465667a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c9c014-231a-480f-919a-e757fd3ad954', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 92).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ad489c0449e821df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7445f01-1f08-4996-861d-3e86a4e08274', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 92).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3e6bcf908b6095b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('587de34c-2e03-49f8-958e-e403e5124477', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 92).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b335b427acac15d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('846d35cd-ff3c-4e4b-8cd7-b12c11a3c327', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 92).', '[{"id": "A", "text": "configure interface et-1/1/3 ip 10.139.127.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.139.127.254/24 interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "set interface et-1/1/3 ip address 10.139.127.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-1/1/3 unit 0 family inet address 10.139.127.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd95bca777694f285_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('108c240a-f29d-4840-9d80-d1661fd8ee00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 92).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f23f734f59c5e15a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cf18050-26e8-481c-b517-c13ce8604cf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 92).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '28eb258f0110a290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab46b67b-3726-4ede-ae7d-0d32dff08f7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 92).', '[{"id": "A", "text": "show interface xe-2/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '81eae6a9661c7f88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70081900-b793-4341-bb09-1b3f91f1ff68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 92).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7c54749f6e1f6660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f72c64cb-0cdb-42fb-9fbe-f0d5ed1e5e42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 92).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '779777f0ae9fcd32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc50607-c451-478a-8fde-31d85871ee5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 92).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd16f8ccf2fb64cd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bc1e6ae-7368-4f09-ab46-c720f5419179', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 92).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c9af86704c6fe37e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7448869-9d5e-4040-aae9-156ab433186a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.208.148.0/24 via next-hop 10.138.5.5 on Junos (variant 92).', '[{"id": "A", "text": "set routing-options static route 192.208.148.0/24 next-hop 10.138.5.5", "is_correct": true}, {"id": "B", "text": "set route 192.208.148.0/24 next-hop 10.138.5.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.86.170.0 255.210.91.0 10.138.5.5", "is_correct": false}, {"id": "D", "text": "set static route 192.208.148.0/24 gateway 10.138.5.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93b9d2c458ec268a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fa727f8-a9c5-42aa-b227-00b66696697e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 92).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e4e90fa01f2eb207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb69a49d-4118-40e0-8f07-de6d00d23733', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 92).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f0445be8afbeea6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a183fd7e-53e6-4b29-ac80-6fe005ad2f87', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 92).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ba688e9b3681406b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97deb7c3-a888-4b00-9a53-eb9521177012', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 92).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7878bb6872ade870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e80b3c-8e76-4d1a-b702-0c85c912fff0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 93).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e3ed9c2ea8dfe20d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6452f87-920d-4262-a366-84c45288b9c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 93).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '988294264e5e5f4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb58468-7bb6-4670-b11c-18b95647aeb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 93).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '912bc9d0ed71fa56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6242ce8f-5376-4a7e-977e-18e4d25753ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 93).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd1cc9a245ca5b9cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8de78ea-a10d-4e9d-a290-b3ecb39eb9dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 93).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6bdfe2b95e4c7357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('255e18e4-0edd-4c53-827e-80b6831db587', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 93).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '08c0ebc4e2d18f03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47a252fd-d0fa-4a6c-b9fd-ad44bd76bb90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 93).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2ce671da7bd4dfec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddaa8f25-fc6d-46e6-838c-8fe0063e2c4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 93).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cc08e8ac978de336_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87cb04aa-ebf9-41c6-9d5e-17f9a42849e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 93).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '51b53735cb24b190_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('631a7e60-d86d-4c0b-9882-b481a0de9d9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 93).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b95b2fa83a238e92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74619069-ebae-4d36-98ba-1cab29636ae8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 93).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '144fb56f2ed6ce4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d957f97-7231-4dc4-af34-b1d26ac78b6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 93).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1dd9f02188cc3628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('183d8230-9814-45e8-845b-2cc479ea563d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 93).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'be6b2207a7d7d4b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a05c2c0-e337-4c9a-8e95-efa96b363e01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 93).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4abcf9eb7768b3fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93f19064-aa3b-4952-b50f-dba7fda0be4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 93).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '71e31c7411a1d5f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('820805a2-1f56-4744-a7ed-cbf430671040', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 93).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system host-name R1", "is_correct": true}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fca469645f1bf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ce278c4-a911-4346-ae33-8ebebc9ee01e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 93).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9bc78cfab5fd6d63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('532faf12-350e-4c8c-91e4-46bfe986decd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 93).', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.65.104.5/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/1 ip address 10.65.104.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.65.104.5/24 interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/1 ip 10.65.104.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f58c07a44a1db30d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f19f377c-886b-4e90-b877-0fb79927a7f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 93).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c01bd5c5a1be25c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dbc55f0-a4e6-4f02-b745-9f4b9bdd1675', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 93).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8d310f6b2649392a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93d5ad44-45be-4d1e-bed9-5d0f8daa0418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 93).', '[{"id": "A", "text": "show interface xe-2/1/2 monitor", "is_correct": false}, {"id": "B", "text": "watch interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/2", "is_correct": true}, {"id": "D", "text": "tail interface xe-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a6c06e3493bdf1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6283c853-49de-421d-99f7-c5061efc1b08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 93).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ef4c93fdf62dad97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb02064b-ecbc-4436-8588-af0deb4ae638', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 93).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '344934c46a5553b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('684d72df-cb94-41a1-b10c-727616eaf377', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 93).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b8a9a3a55cb28f00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b50d49bf-5740-489b-b9a9-2aa49b5759a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 93).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c983b53f2224060f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012e65e1-7d77-4112-9a5d-78308aa5e35c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.106.186.0/24 via next-hop 10.4.109.5 on Junos (variant 93).', '[{"id": "A", "text": "set static route 192.106.186.0/24 gateway 10.4.109.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.106.186.0/24 next-hop 10.4.109.5", "is_correct": true}, {"id": "C", "text": "set route 192.106.186.0/24 next-hop 10.4.109.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.141.222.0 255.44.55.0 10.4.109.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bf7eb53447603dcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbcf22c0-932b-4e8d-a750-dc799d02e79d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 93).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2104b67aaedb6d69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4e19808-7a55-4025-895b-1ecb7ee14995', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 93).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '2515df49a4773048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03263ed7-81de-4108-9546-57e30a70eb0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 93).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b66b296a0a0b9927_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ddb2bde-b127-4bdc-b6f7-d888cedb56c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 93).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fbdc7687bdfd0727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bad65c1-7683-48d4-9573-3f0895a8fce0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 94).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '38c1946e3527d945_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6efaba4-d9d4-4b3a-a4bf-c1604b09c50a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 94).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4e3f49222a60fb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee28761-dc57-4ed6-a1bc-2a74c24693f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 94).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '81d81199cb6912e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56d0287d-a028-4365-bad9-1cf03917463c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 94).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '535b6cca66c6d21f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b060812-83bf-4ee1-8548-65c7c52ba11f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 94).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e7466d9b805ae823_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('909447ed-dafe-4473-a65a-0269ddf29470', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 94).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ea586280ffddc7d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2ec849-80c8-4419-868c-9a020e9e2594', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 94).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fb0d931685d62575_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b70dcc00-3e48-4ff9-a942-42dcdb24f4a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 94).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1b5ef22929ca9b02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db938d90-c958-445d-8f16-261b6da4095a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 94).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '688f0d996d7a89b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4211a3b9-de18-4d94-8357-0f5c8a3d42d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 94).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '52019c3632c9fbfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d72712ba-3a61-4ae2-90c7-0277204c0c04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 94).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57597038a3d9c12d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f375b6fe-7349-465d-a3f7-bdd04f33600d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 94).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f106a675d186fc71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58893c64-c6d6-4ee6-aded-80e1aa93baad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 94).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fa49cc2f21fd3a4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0590798-0f27-479e-9b37-f2fcb4953df4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 94).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a8f88b5097b49fb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ceea2d2-5f55-4706-a940-ed3306c51ef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 94).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '065bba74085fc2d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('812fe9ce-f2cb-4fe2-87d8-be30878419eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 94).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set system name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ccceda22905cca1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f0c10d6-15e7-4a3e-ad42-a259303dca90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 94).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4204d7bbc33b00fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('076ae606-7d05-4fcb-b082-8a32b2f8b66b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 94).', '[{"id": "A", "text": "configure interface xe-0/1/1 ip 10.158.109.254/24", "is_correct": false}, {"id": "B", "text": "set interface xe-0/1/1 ip address 10.158.109.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.158.109.254/24 interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "set interfaces xe-0/1/1 unit 0 family inet address 10.158.109.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b3b5e63abbfced4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89c61206-c136-4dda-8452-fdd807dd1f4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 94).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4a3bb54c429a3475_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('466581eb-8577-4c69-a8eb-43f4feaddcc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 94).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1c9f0474052e67c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a1104f-15cf-45ad-9c8a-5ae2c80000e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 94).', '[{"id": "A", "text": "tail interface ge-3/1/1", "is_correct": false}, {"id": "B", "text": "watch interface ge-3/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface ge-3/1/1", "is_correct": true}, {"id": "D", "text": "show interface ge-3/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a1af367982931904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6a4a86c-5dd2-488f-b808-8fe1aff5c654', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 94).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ef1158da3a24cb43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d941b2-0457-457a-9976-b0cda96410bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 94).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bfe33da680e593ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('052c6123-12fe-40c7-ae1e-327813f6d581', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 94).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7db7b6f3925469e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a59941b-c0eb-4cfe-91ac-4f44c9e4a11a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 94).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3477b3c7f090123c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5fd6472-e01f-4aee-8174-601d3189e2da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.167.180.0/24 via next-hop 10.112.182.5 on Junos (variant 94).', '[{"id": "A", "text": "set static route 192.167.180.0/24 gateway 10.112.182.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.121.102.0 255.119.22.0 10.112.182.5", "is_correct": false}, {"id": "C", "text": "set route 192.167.180.0/24 next-hop 10.112.182.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.167.180.0/24 next-hop 10.112.182.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3ee1426b26eba416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59faac00-a3c3-401b-b04b-2e4dc23f145f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 94).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7b88d089ac056ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cffcdcb-a509-4f04-aa1a-cdf87fd5852d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 94).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'ba079da0a22feaaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddb96bb8-a971-4574-bff5-dbde22ade4e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 94).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cbabca152c0547df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bcd56e6-5500-4a75-8400-5a88a81cb4e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 94).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '88e231dab750dac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c28213-36d3-40c2-8b28-f9f83c1bcd50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 95).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7d9808e65344760a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e7ffdd4-92dc-4eb1-bd01-dc48eacbd540', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 95).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '19ea30f3bdcf7bd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('090c1c9f-c890-4ff5-a33f-c388c7f3cc0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 95).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '58a5bf7b1ec672c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c004a514-82f6-44c8-a656-0f96c1379468', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 95).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '2baf693e30cc1f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ac057f-b818-4ebf-a280-6b36e51e80ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 95).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b0c0f2d56abffc19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a831eb95-e54a-47e9-a2de-a3888472739c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 95).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '29a9cac31e054317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8de350e7-2a55-4346-9290-f1789af35d3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 95).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b48fc9546ce65ddc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b505b27-e4f4-4f6a-b89b-f72972b61c80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 95).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5871470ccf12b220_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26306e28-6dc8-4f82-ba57-21260f945471', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 95).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7dde0d8d0d1c4015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c3d1f7-64c9-4a51-aa5d-3142757ba638', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 95).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '838ef6653c4d517c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b944be7-faac-473b-9d21-b67b5c18e24b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 95).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70eafe6c1e369949_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30765a18-a7de-4624-9865-a81cf2156db5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 95).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1eea606bfbbfeefe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b6b58a1-a7f9-4bf0-a7df-c63411f06878', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 95).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0a5087d511777b4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27cde828-3ed5-4bfd-95b7-d0e7ec96586e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 95).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc3ad55ff703b278_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4182faa0-baa0-4a05-b0cc-fc4c52129cc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 95).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8b1757c73db50972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('826127fe-59ed-43c3-b3cd-568c43cd201d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 95).', '[{"id": "A", "text": "set hostname R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8eb5041656de4ae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b4407fa-bb99-4679-aa8f-d339785332f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 95).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5f00936c1ba8631a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12310c88-0b13-462d-bcde-f861cb203459', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 95).', '[{"id": "A", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.26.43.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.26.43.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.26.43.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/3 ip 10.26.43.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6a7ec63ae9acc1de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4bb81da-0b98-45f7-b6d5-66365ed4e2ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 95).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '80da7e00a794cc9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04089dd-4756-45d5-a363-dec7b5fe259f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 95).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f1ab79552f271a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d9fd95-1170-494a-993c-b59e2118f128', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 95).', '[{"id": "A", "text": "monitor interface ge-1/1/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-1/1/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-1/1/1", "is_correct": false}, {"id": "D", "text": "show interface ge-1/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b0dfeb3d1e44111d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1403e056-6a23-48c2-ac4e-4fe74dc11804', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 95).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '24fef2329fcabd77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beff69bd-5836-4d28-9cc8-8242614c66e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 95).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d705c3a8dc682ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdbefb0a-fb5e-4caa-a9b0-86cf9deb41b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 95).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f1a578a49dae8756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14afc6d8-2f78-4c79-8f6f-a828cdf101fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 95).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e804f5708d7faf8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9da21fe-6965-4add-acbf-702128ff63a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.47.0/24 via next-hop 10.240.208.1 on Junos (variant 95).', '[{"id": "A", "text": "set routing-options static route 192.21.47.0/24 next-hop 10.240.208.1", "is_correct": true}, {"id": "B", "text": "set static route 192.21.47.0/24 gateway 10.240.208.1", "is_correct": false}, {"id": "C", "text": "set route 192.21.47.0/24 next-hop 10.240.208.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.204.245.0 255.230.124.0 10.240.208.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30484127f797156a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd978682-3030-4182-84d8-e4c38806c26d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 95).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0d92ada507b880fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fda9f5d6-ae76-422e-be11-f78e4fe7c3f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 95).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0eaaf3caaca46ada_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e1e43fa-cb10-42f5-b3f2-c30469511dbc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 95).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c008ef006277d5c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18a9d0e9-0eaa-4629-b5f0-064d7e39acb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 95).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '76cbe6ab98e071aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d3cc519-36ce-465e-b5ce-5ddce05824db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 96).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a9d2e3945d7bd569_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d598db9e-20b2-4f7d-ae10-59f8f39f48f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 96).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '445225da4f40b017_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded452e5-5fe3-4aab-952e-48acb4ea7c33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 96).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '0b8b4f1fdbcc0333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02852dad-8eb8-4efe-ad3c-1cd4b4506366', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 96).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5a487b2d6ee93e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a050b137-765e-4bdd-8935-813401b86278', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 96).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b896189aed66108c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b562c5f-acb9-488c-98bc-51a1e9ddb811', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 96).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1031d7e9de70b466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c03ee83-5473-4fb4-ba0f-9cc1a214cf8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 96).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'db25a5782f983ce6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aac2b0f6-f238-42ae-bf6d-24f25881870c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 96).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '55044dcade02d12a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f08612-bf4a-4e4b-aa98-2fcc07741fc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 96).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '831037eac0b43600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbcdf210-3da0-4e38-bf33-6f7e36858112', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 96).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'df8ad4167f031e03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42966ef1-face-4e2c-87d6-e171458a3902', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 96).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f9e2ce688856fbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5425c40-a1fe-4bd2-bed4-5c6a6a03c9e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 96).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5c7c574b4e7280e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('863299f9-a991-47f4-bb91-8d67d540d1e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 96).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b1e6e6c8e03cf4b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99cd3752-5f4b-4cea-a88c-92445ee3d14c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 96).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '98de1a0bbfc20132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2be01ba5-2e29-4e4d-b4bc-c88b5501a968', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 96).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e9d24fcb1a987f3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bca44e5-5661-4692-8345-2937f134091f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 96).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fcc4a67ef93229c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c5bed04-6ebe-43b6-a8f7-7317b2ab4f0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 96).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8b061694e042756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b68c8374-7eba-43da-85b7-1de25a18315a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 96).', '[{"id": "A", "text": "set ip address 10.248.35.1/24 interface ge-0/0/1", "is_correct": false}, {"id": "B", "text": "configure interface ge-0/0/1 ip 10.248.35.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-0/0/1 ip address 10.248.35.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/0/1 unit 0 family inet address 10.248.35.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'aa961d863c2705c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('305d085c-7d22-4df0-a504-e0fddc0159f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 96).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '66eb5dca147b43f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e150047-8e50-4766-a506-cd61e4310c56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 96).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '776aaad880e6656e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76e78aaf-6934-4c8b-90fb-ee73828d15a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 96).', '[{"id": "A", "text": "monitor interface ge-2/0/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-2/0/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/1", "is_correct": false}, {"id": "D", "text": "show interface ge-2/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '099c92df2af158e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba5cfd52-3e14-4075-861d-084addfd8b74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 96).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '90566d4d6cecd83f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e64e543b-fdf3-4dac-9102-869cd3f5f73a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 96).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a560fd2a7a16211c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f708ec4-4c32-4002-8df9-9852ecb0c910', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 96).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd2b5120f3c271370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e536ef1b-f090-4ab0-93b6-2a71ed940c45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 96).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8eaedb18b83be66c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d9c6f5b-0ad7-4057-b4c2-c80daacc1bcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.13.213.0/24 via next-hop 10.195.143.254 on Junos (variant 96).', '[{"id": "A", "text": "set ip route 192.232.83.0 255.62.39.0 10.195.143.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.13.213.0/24 next-hop 10.195.143.254", "is_correct": true}, {"id": "C", "text": "set static route 192.13.213.0/24 gateway 10.195.143.254", "is_correct": false}, {"id": "D", "text": "set route 192.13.213.0/24 next-hop 10.195.143.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6195c699bc03e7fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04f14ec-f854-463d-8d44-bcde0fa0c0db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 96).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c6945916124bad02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbac5f61-eaad-4091-9028-dea533ec96dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 96).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '53d8f53f84d391c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d414934a-3013-4594-8531-98e00bd51a3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 96).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '79e24120be1072e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50256610-354d-4c39-a6ff-7a574c8724ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 96).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a0c38f21c42bc46f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54c3b69d-9d70-4dfe-9a1e-35c7069a4a0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 97).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b2b63b5e4f3b7333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd08d1ce-7cd7-4058-bd8a-792e5fef9550', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 97).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ea8c7a1cfd4d61ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae4b7536-0f19-48fe-8306-3d6650dfc67f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 97).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '791375aed0a7c473_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eb93dfb-72f7-4084-bca6-a3742d6164f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 97).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '246d932f26e3a4da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1177a1d2-7824-4a2b-99a1-f8316255dd47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 97).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'a13f2054db81e225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c59a2cb8-c9fc-4d88-bbe3-96112b510e54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 97).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a059ce7d7a88d7d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('545277c4-09ef-4bf2-b4c1-2d689ba00805', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 97).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6698f37fcd1632f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e75f4f2d-1334-4c12-97d7-00d322971a7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 97).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9f45a2efd9c1a981_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d68a0199-2d1c-455e-80e5-e6c0de7bc795', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 97).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b2a71e21738dc18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9165f73-7d83-4f5a-9bb8-f062414fc14a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 97).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '1903dc93269de604_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('502a560d-4d68-41f7-8af1-450028e9ed41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 97).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1811c68657edf88d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bf172d2-15bc-4a6f-b28e-65ef47a0b4d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 97).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f4fa4cb81eb8d257_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53bbf725-2b9c-4c9b-a146-47e05793bdaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 97).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '71d136f4d4948940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c6828e-ddd4-47dc-b2e5-43185cc15886', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 97).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '98f5d1c157053d94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638af1df-f9ce-4630-af7a-9282a14ede09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 97).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4fdd694858a6da03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60516aa9-d0c7-4276-a8b9-53b17b3a1e8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 97).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set router-name R12", "is_correct": false}, {"id": "C", "text": "set system name R12", "is_correct": false}, {"id": "D", "text": "set hostname R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f10f1477c9397f39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('904235f9-a1c1-4bb6-809d-70d52b74771e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 97).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df396b0acdd865ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63f1ce89-30af-4d13-8692-82181c609d14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 97).', '[{"id": "A", "text": "configure interface ge-2/0/3 ip 10.235.148.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/3 unit 0 family inet address 10.235.148.1/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/3 ip address 10.235.148.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.235.148.1/24 interface ge-2/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '43d1e30aaae8a362_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a38daa5c-711e-4e0e-8a24-ae40f4d2f534', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 97).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '31385485fe3f75fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('315400ce-e664-4b4e-9711-2d7d6731e5fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 97).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b36626b583b9806f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d40b1897-f158-4626-b45b-0f54958c66cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 97).', '[{"id": "A", "text": "tail interface et-0/1/3", "is_correct": false}, {"id": "B", "text": "show interface et-0/1/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '476594410d5219f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45b092b1-4a33-42e2-90f0-4e3870d493a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 97).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9480d53bed37b0d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6401e0f7-6ad6-4f7d-8d6c-3db9c1118f90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 97).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '55de62597756a2b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('704810bd-65be-463e-af8f-896620b0bf13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 97).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c5169088f625ef15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e1d5da6-c554-49c9-ae3e-f992d831cead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 97).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a25f96009a72da6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81a92356-af99-4165-b423-217926ba74ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.225.228.0/24 via next-hop 10.50.211.254 on Junos (variant 97).', '[{"id": "A", "text": "set routing-options static route 192.225.228.0/24 next-hop 10.50.211.254", "is_correct": true}, {"id": "B", "text": "set static route 192.225.228.0/24 gateway 10.50.211.254", "is_correct": false}, {"id": "C", "text": "set route 192.225.228.0/24 next-hop 10.50.211.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.64.62.0 255.179.189.0 10.50.211.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '94532ac50cb0f795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('164542f1-c381-405c-9a4b-ec18179dc7f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 97).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '242fe90e5aa19897_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85be0df2-66cf-4b48-a541-0ed345df3e1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 97).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bca1c0fba32efcf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bc55b55-85e2-4e35-b30e-28cc24dd1904', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 97).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'bde510ca0c59d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e16448f-7e7a-4143-8b33-ee822a868f7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 97).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e7c176eb9b1aed7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebd4b41e-34ac-4905-94bc-722aee01ad69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 98).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '12ed703a3be8cf2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3553539d-83c0-472b-970b-f7fea1761b6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 98).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5de1d85db8f68f74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42aadb2f-6898-47bb-8a27-a2197e868550', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 98).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b5848807c0328728_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76896198-f9b6-4d8f-a333-fb4cab84021d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 98).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '20c9c41adcd8aed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6889f72a-ac79-402d-adf2-8d29b2da8d9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 98).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '86e4bc43a2d6a383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('038da678-3c8a-4a9f-a5aa-68da58449f7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 98).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '06197d78970dfb52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf19973d-f5a5-4710-a1db-c55e33f53ba9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 98).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '92383fc74473f3ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca16864f-b4bd-468a-b397-631f63f0b1e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 98).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e6502836e442695d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f80f37a5-2c13-458d-a175-6dae2fac7bb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 98).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7c2bfc0af964aff8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f58ca67-d0b8-4bd8-8c32-348fc6ae098c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 98).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '710b5cfc9bcf989b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca3f42e-6c7e-4881-8420-6ac9e467f92f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 98).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2e9e5f97b7bca88a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14706a5e-aa91-4854-a7ba-58f4042a762c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 98).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f697fc52e851905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c25586-9004-4d4f-8d72-390141883282', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 98).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '02c2542e0bb9c652_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f137b5d5-766a-41c3-b6a1-01c53e5e4763', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 98).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '41ff0e0b989fbb1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16dbecac-8a2d-4df9-a140-bfe22090a98d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 98).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c5ad28d20db30731_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f61a1ba4-9803-4f08-8da5-0ca569391935', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 98).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set hostname R9", "is_correct": false}, {"id": "C", "text": "set router-name R9", "is_correct": false}, {"id": "D", "text": "set system name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e019b5c9e8d4da91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f14088c-254e-4bad-93fc-2578c05bf241', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 98).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a56b21af135141e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b97b96ce-e46d-42ec-838b-7134f58f8b27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 98).', '[{"id": "A", "text": "set ip address 10.198.176.1/24 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.198.176.1/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/1/0 ip address 10.198.176.1/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/0 ip 10.198.176.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ebf8d1e96146e4ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fea48f30-ff7f-4af9-ab63-80467b294a45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 98).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c6b56152cd0b53ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b99ebf0b-85d1-4604-a4f4-453ff34b1022', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 98).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5ae58895a5e223e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b5422d1-a80b-4be6-934e-dc1b556a6017', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 98).', '[{"id": "A", "text": "monitor interface xe-2/0/1", "is_correct": true}, {"id": "B", "text": "watch interface xe-2/0/1", "is_correct": false}, {"id": "C", "text": "show interface xe-2/0/1 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2ed39215aa879f50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24a47379-0493-4e35-a8d0-11a769b03daf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 98).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9a27b77c10c151af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c269ce04-7235-4219-8e8d-c028c52b5631', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 98).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '13b1138b7aef2f1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5450bb2-9962-4070-b09f-cf0a10659c97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 98).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '008df4fc6d055f75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97e91657-b0d9-4abd-a2b3-2ac7c03fd31a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 98).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b89e4cfabed024a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85dbfc5a-99a8-4f9a-9ecb-8bfdea6f5c00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.24.0/24 via next-hop 10.191.214.5 on Junos (variant 98).', '[{"id": "A", "text": "set static route 192.21.24.0/24 gateway 10.191.214.5", "is_correct": false}, {"id": "B", "text": "set route 192.21.24.0/24 next-hop 10.191.214.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.15.62.0 255.209.245.0 10.191.214.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.21.24.0/24 next-hop 10.191.214.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '85fdbac4b6bd5822_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('174f6361-1e80-4ff2-80d6-2c3d73a942f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 98).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4e274a734042def1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('891b8c85-d097-4f6b-b490-88591ed78d7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 98).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '05e052468da22b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef85815e-1f4e-462b-a322-bb6b3261468e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 98).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9371ff05958638b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac29ee61-3ee9-49f4-8778-bf3d9b043963', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 98).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '598767734e45c2f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5477da03-30c6-4790-b590-386896c434bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 99).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e11cbaf34e3ad6ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ce33eeb-e414-4c7e-9c8f-3e292327e848', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 99).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c3de8df67513da44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a621c5-3ec9-4809-8618-723961df0b6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 99).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'da0ba406e42d1dde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100087c1-4e6f-4acb-bce1-e708d434fab2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 99).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c3f8a30cfdd5b6ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95720c07-7598-4781-a713-4d81d923dc56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 99).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd7fa3d26e6a28404_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0b58a72-d780-4314-85d9-a3c983727ceb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 99).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'eed825b4aed45ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27549473-27a7-435f-8a48-c9c45dc05ce3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 99).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '20be12eddf296369_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd37f9d5-4217-4c1d-9bf8-2fa0f4f5670c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 99).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c99e2e3579935b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b78190-494b-4deb-a5d6-70f88835d07d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 99).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '11219b4c6c7a3d30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e41c2b1-d168-49e2-8e55-f9c7716383ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 99).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '64af65cedd1b0dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935fddb1-109f-4235-bbb2-c1fa2b5d6533', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 99).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3f96003b4327f985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98a81325-ebcf-4275-b7f6-eecb143479e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 99).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f24a6a53bf31bf15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9784bc8c-7664-4668-b16a-56ec2e492f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 99).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd3f53181959f8696_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae449ba6-f661-411a-8ab6-9406631ce726', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 99).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2a5b00e1bf60ca00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fbc3679-2a1b-483d-8e8e-8881270ae48d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 99).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5495395a06190b47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('846e4456-2ff4-464e-b91f-53477c830449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 99).', '[{"id": "A", "text": "set router-name R10", "is_correct": false}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set hostname R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8fe4a44c1723a3b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('477e2ed5-abdd-4561-bf22-31de27544f9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 99).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '11c3dc706943c651_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11da2ef8-0f4a-4888-aaf5-ae48f2f9d7a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 99).', '[{"id": "A", "text": "set interfaces xe-3/0/1 unit 0 family inet address 10.107.186.5/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-3/0/1 ip 10.107.186.5/24", "is_correct": false}, {"id": "C", "text": "set interface xe-3/0/1 ip address 10.107.186.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.107.186.5/24 interface xe-3/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a9eed9353e253b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce5789c8-d0d7-47e8-93e7-8e865d29541a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 99).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9a6b67fc18f6d88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ceddfa9-2f3e-474f-bcaa-c9bbd6044533', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 99).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7040964ff609ce48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc615b5-7b0b-436e-8ddc-38a10060658c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 99).', '[{"id": "A", "text": "show interface et-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-0/1/1", "is_correct": true}, {"id": "D", "text": "watch interface et-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '543c5f878df227a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('682337d0-d8b8-41db-8fdb-8d1d5e48f611', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 99).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'db574b91238f3366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f4a555c-14fd-420e-bf6e-cef4020c553e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 99).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '811120046a6d6e2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e83ff5a9-118b-490c-a136-3a5702337c81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 99).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd8700935ee0ff114_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3226d36d-9ab2-41fd-8896-627392b65bcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 99).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e496bd23e766cb6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c81500-ca3b-47c9-acf5-c5c0f2a7a3a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.164.208.0/24 via next-hop 10.7.146.1 on Junos (variant 99).', '[{"id": "A", "text": "set ip route 192.176.20.0 255.141.72.0 10.7.146.1", "is_correct": false}, {"id": "B", "text": "set route 192.164.208.0/24 next-hop 10.7.146.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.164.208.0/24 next-hop 10.7.146.1", "is_correct": true}, {"id": "D", "text": "set static route 192.164.208.0/24 gateway 10.7.146.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7564a09c5a88fafe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1338fa96-446d-49d7-aa4c-88f68ce95fcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 99).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'af253df6333a82f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc00a77f-1571-4756-9bac-98051a145c8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 99).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '54483d130e98cb4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3eaad40-e939-4f09-bca4-251becda2be7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 99).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'aab6d158e40b9d68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('706858ce-c730-40ae-9d50-5ae81a9f52a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 99).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '475b1eea9a850ea1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('973ce4ec-03b6-4ff9-a91c-de30c16c9115', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 100).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f34bdff4f55aa221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c25e605-3918-47d4-8c0e-9249fbba7a40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 100).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'dec4b954e587a318_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c605ab1-3195-4cb2-a113-1cd1b1bf36f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 100).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4c6aed73c2f50580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed15c0c-652b-4c43-846d-02ccce7014ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 100).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '68f621f95310c32c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b88c130-c154-4470-b8b9-27fb86a5f31c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 100).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3d0c43351ee7ca71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c849ebfa-90db-4f5c-b4ca-90bd9b12d80c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 100).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b97431d4e856e573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1379a713-1e2f-43d0-a953-e819c987199b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 100).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0df2c1565c506bba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f777041b-85be-49a5-bc16-7183975c6aca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 100).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3a851a0e61eaddc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a364c58f-d7b8-4280-88c3-62e7b6545585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 100).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '95685371c94b501d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c0dd27-3212-401d-9258-dfca0a2885e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 100).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1b1df88ab6ea0cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4342664a-22b7-4137-b754-1588980f8001', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 100).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b062610fe003d556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e196f260-b194-47c0-93fb-7c7816d86a57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 100).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '013c800757c15f19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ea08631-68a1-46cd-9709-3a1d76ecabe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 100).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '77f5897ecc070ff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('451f1d51-1493-4961-a01f-edfa6d1e1984', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 100).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5790c8f4bd1574e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('823b939b-9bd2-4dcb-8745-176427d217dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 100).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bcaae8358704856a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d48705a0-2e41-4034-a250-eec16b73bb1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 100).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b600cc9a0912edfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99b36bed-2981-487e-9ab3-a0ca807f3a02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 100).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6f7a3c6838468a3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c1b0838-233c-410a-a448-d0f6ad8fb044', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 100).', '[{"id": "A", "text": "set interfaces et-0/1/1 unit 0 family inet address 10.121.28.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.121.28.254/24 interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "configure interface et-0/1/1 ip 10.121.28.254/24", "is_correct": false}, {"id": "D", "text": "set interface et-0/1/1 ip address 10.121.28.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a063fc1a2d791469_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb6e8140-4bf4-4aef-9c77-a556ae4f6743', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 100).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7601c5559516fc4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8cda875-c581-40d7-8c37-15f307a1f142', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 100).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3cdc070c327dd2a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('120ca0e5-9399-4f4e-afb0-d482dff1b59b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 100).', '[{"id": "A", "text": "monitor interface xe-2/0/3", "is_correct": true}, {"id": "B", "text": "show interface xe-2/0/3 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/0/3", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '58a5de81f9871e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('771f9841-cd15-481f-a43d-0ed30863f53e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 100).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5caaa895c92ac545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da7aa738-22f3-4b0b-8d64-396662d3df35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 100).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '964943a7d4b920b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8691deea-59c5-4cd4-86e7-1247cdf38afb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 100).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6461ab3fb448d94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fa61866-b9f4-489e-ba40-870b5394801c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 100).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f71b4e1f5c732dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4a43bef-1792-4b17-9bca-67f587d58ca9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.166.18.0/24 via next-hop 10.23.103.5 on Junos (variant 100).', '[{"id": "A", "text": "set routing-options static route 192.166.18.0/24 next-hop 10.23.103.5", "is_correct": true}, {"id": "B", "text": "set route 192.166.18.0/24 next-hop 10.23.103.5", "is_correct": false}, {"id": "C", "text": "set static route 192.166.18.0/24 gateway 10.23.103.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.3.12.0 255.131.202.0 10.23.103.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f7060691bf48ef66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afafbd44-11c9-4850-bf56-2be91fb81ef7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 100).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1acd3832c28d9acd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95dbaed8-f084-4ad5-a61e-38fd94d1866e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 100).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4c87f96f6a6d77cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9910485f-452e-48c0-8a58-fe8a82fc7dce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 100).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '865797e1b1fbe4f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2210a5ad-ea53-45e6-a67f-ff46f6f92feb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 100).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4640d1defbcc3700_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95efe967-c3a8-44bb-b13e-1acd500b845f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos?', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1024 through 64520", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '90fc81ed06f61ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b062a93e-bd51-46bd-902e-adb452dbfc08', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos?', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '6c93b7ee3fc9e54f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a5f2d3e-754d-4029-86d5-05260f43f799', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0)?', '[{"id": "A", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "B", "text": "It is used for OAM operations", "is_correct": false}, {"id": "C", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "D", "text": "The penultimate hop pops the label", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'b61849ce62111999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6668e57-2af2-4690-b7e8-9b8977e3d01b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP?', '[{"id": "A", "text": "ResvTear", "is_correct": false}, {"id": "B", "text": "PathTear", "is_correct": true}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '61118f65cb07c9a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b56b6c7-cf94-476e-8399-df264bffebc8', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP?', '[{"id": "A", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "B", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "C", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '83f23f138bf7441d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c977286d-570c-4947-ada5-94e8a31ebb66', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 2).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1024 through 64513", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'f9e965bc63f7b74c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28b46900-3224-4b8d-8879-c5b762756292', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 2).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show ldp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show rsvp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'f274ab30697164c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1f0a9e6-cab4-410a-9a8b-85a2dba380c9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 2).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "C", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "D", "text": "It indicates an IPv6 payload", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '380b8b25584903e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eae860a5-13f6-41f4-930e-02ae7d304db9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 2).', '[{"id": "A", "text": "ResvErr", "is_correct": false}, {"id": "B", "text": "PathErr", "is_correct": false}, {"id": "C", "text": "PathTear", "is_correct": true}, {"id": "D", "text": "ResvTear", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '24461f87ac7cf73a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa580a88-65a6-42ac-aa86-b19a8b18d78b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 2).', '[{"id": "A", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "B", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '14f28d0c07214ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('460cfc78-f051-4d6f-bb07-93fd4db0188c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 3).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1024 through 64800", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'a7bb8dadec005aba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b736b86c-719a-46fe-9205-0bf66a6c719d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 3).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show rsvp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'a0356258d879c6e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a753104-5ae6-46b7-bac4-e8295601b5f9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 3).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '7ee32388713e8133_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44bd786f-42ac-40e6-a002-a6fea49a0e6b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 3).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "ResvErr", "is_correct": false}, {"id": "D", "text": "PathErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '03d3f395023a7150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dcf94ed-56f5-49a7-a24e-c4964b8b49f6', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 3).', '[{"id": "A", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "D", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'c84bff1a7ab5527c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac56c7e-cabe-41ed-8f83-d22ecff10294', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 4).', '[{"id": "A", "text": "1024 through 64800", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "0 through 15", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '9d3a9bc74774d0e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914e3371-8e5c-4525-a9be-7eeda2fa6b84', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 4).', '[{"id": "A", "text": "show mpls path", "is_correct": false}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show mpls lsp", "is_correct": true}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '7e457705e5cbae63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
