INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a9fb371-0116-4f8b-8ec0-ddc943001fc5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 41).', '[{"id": "A", "text": "PathErr", "is_correct": false}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "ResvErr", "is_correct": false}, {"id": "D", "text": "PathTear", "is_correct": true}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'da2beccef7b340cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbed6468-02ba-46a4-b2d8-ad06adbcb48d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 41).', '[{"id": "A", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "B", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '7a4a6ecf17164a27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2b872d2-0cc5-45d6-a4bc-52bde1b12fdb', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 42).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "1024 through 64515", "is_correct": false}, {"id": "C", "text": "0 through 15", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '4918ad984a5a0b67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca83b52-9abd-4911-8b92-ca6969394f9c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 42).', '[{"id": "A", "text": "show rsvp lsp", "is_correct": false}, {"id": "B", "text": "show ldp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show mpls lsp", "is_correct": true}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '7fce7c8eb56dd4a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
