INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d99974e6-aeaf-4740-873e-7327a983e681', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 45).', '[{"id": "A", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "B", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "C", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "D", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'ba2fd5c39d650976_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f97ad5bf-49c6-463a-85c4-388a88bee955', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 46).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "16 through 1023", "is_correct": true}, {"id": "C", "text": "1 through 1000", "is_correct": false}, {"id": "D", "text": "1024 through 64514", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'c575e0f53e9b0d15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9e97fa0-c47b-47d0-bf65-43cd7b1809a4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 46).', '[{"id": "A", "text": "show rsvp lsp", "is_correct": false}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show mpls lsp", "is_correct": true}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '8ff4217406cdbefc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('375ac4fc-14d9-4f39-9cfd-78a30ba76e0b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 46).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "C", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "D", "text": "It indicates an IPv6 payload", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '492c03badd5ca74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
