INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5291e2a-e775-4875-9454-5a7cd276e534', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 71).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1024 through 65002", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'f9be6f1e84e8efc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70398ca3-acf9-441b-b9da-16802d7c8e0b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 71).', '[{"id": "A", "text": "show mpls path", "is_correct": false}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show mpls lsp", "is_correct": true}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'a32f82057c3c7f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e37579c2-51f8-40ae-8eb2-93f71bb0dbc5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 71).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "C", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "D", "text": "The penultimate hop pops the label", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '58b0f09bab488e42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
