INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2c9dfc7-618e-4d43-bfc1-112acb27e8f0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 75).', '[{"id": "A", "text": "show ldp lsp", "is_correct": false}, {"id": "B", "text": "show mpls lsp", "is_correct": true}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show mpls path", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '351005c334d1ec1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d6b9d9f-8dca-4f7c-8a24-6c4893729470', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 75).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "The penultimate hop pops the label", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '45d5e4b7604754aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2e13a38-0463-42fc-a657-e2a3c534e485', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 75).', '[{"id": "A", "text": "ResvErr", "is_correct": false}, {"id": "B", "text": "PathErr", "is_correct": false}, {"id": "C", "text": "ResvTear", "is_correct": false}, {"id": "D", "text": "PathTear", "is_correct": true}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '8a64c37cc7afca48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf84a592-5f8c-4321-887c-1a2db888f74c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 75).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "D", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'a4a667c9b698b8d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
