INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0cd9c95-a109-4c40-bb4d-b8226ce0a5a7', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 17).', '[{"id": "A", "text": "Simple packet filter", "is_correct": false}, {"id": "B", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "C", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '28e4481096c4cc76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5abbf829-ed1b-4436-bcc3-565210a419dd', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 17).', '[{"id": "A", "text": "Log and permit", "is_correct": false}, {"id": "B", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "C", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "D", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '44a3cb5e92a188da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
