INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0cf6da2-a2d0-4390-b7e8-e216ee355d96', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 30).', '[{"id": "A", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "B", "text": "Log and permit", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, 'a3d7daeba291040f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e6c464-72d2-4d71-a634-e87454ee6242', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 30).', '[{"id": "A", "text": "ESP mode", "is_correct": false}, {"id": "B", "text": "AH mode", "is_correct": false}, {"id": "C", "text": "Transport mode", "is_correct": false}, {"id": "D", "text": "Tunnel mode", "is_correct": true}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '7fb4f5ac2d9f7a8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b57f8e4-acc5-4c70-9d34-3558a739af08', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 30).', '[{"id": "A", "text": "A physical security domain on the device", "is_correct": false}, {"id": "B", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "C", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "D", "text": "A routing instance for security traffic", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'b5c40939723e22f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
