INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46bf2fdc-0da0-492e-81b9-1f893b999f85', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 34).', '[{"id": "A", "text": "A physical security domain on the device", "is_correct": false}, {"id": "B", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "C", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "D", "text": "A routing instance for security traffic", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '0d915c1d9bca42ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92f385d7-0463-43c7-8734-362f16db169e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 34).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.17.151.138/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.123.146.236", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.123.146.236", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.123.146.236", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '47b1a0e1bfaeb224_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9433f58e-df4e-4efb-855e-d0413cdda5ae', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 35).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '975be0ad3033f720_gen_v4', true) ON CONFLICT (id) DO NOTHING;
