INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f70b79f7-f037-4ab2-b150-0d4815e3733d', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 39).', '[{"id": "A", "text": "MAC-based filtering", "is_correct": false}, {"id": "B", "text": "Simple packet filter", "is_correct": false}, {"id": "C", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "D", "text": "Application Firewall (AppFW)", "is_correct": true}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '0a3491e40889ce66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('417c6886-4ef0-47f9-99e5-67239f893cbf', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 39).', '[{"id": "A", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "B", "text": "Log and permit", "is_correct": false}, {"id": "C", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "D", "text": "Reject with ICMP unreachable", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '76269f18020973fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b489929-9ad0-4579-b851-cd41b5a8867a', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 39).', '[{"id": "A", "text": "AH mode", "is_correct": false}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "ESP mode", "is_correct": false}, {"id": "D", "text": "Tunnel mode", "is_correct": true}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '30b4ebfe179d38de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
