INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2245fe82-72c2-4b19-9050-fb1d8bc62ee5', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 47).', '[{"id": "A", "text": "set nat source pool POOL1 range 192.168.213.80", "is_correct": false}, {"id": "B", "text": "set security nat source pool POOL1 address 192.121.192.191/32", "is_correct": true}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.213.80", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.213.80", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, 'bcfc5c2f268976a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9456cbc9-670f-47e9-af0e-742ce743fb4b', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 48).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Simple packet filter", "is_correct": false}, {"id": "C", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, 'f1e4a5d6a59a1fe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f20aa720-1e1e-48c3-9835-e26917c91354', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 48).', '[{"id": "A", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "B", "text": "Log and permit", "is_correct": false}, {"id": "C", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "D", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '2d9ea7b7181edf86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
