INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dba34fa-c669-4495-bde9-9b7dd01b5b26', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 52).', '[{"id": "A", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "B", "text": "Log and permit", "is_correct": false}, {"id": "C", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "D", "text": "Reject with ICMP unreachable", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, 'b125c1b548e6758e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99f7263b-e76c-41c0-b101-7ba248532c73', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 52).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "ESP mode", "is_correct": false}, {"id": "C", "text": "Transport mode", "is_correct": false}, {"id": "D", "text": "AH mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, 'c5b0eea5c14356f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b6af7a4-7963-4e21-bdb4-cd0645adfb7e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 52).', '[{"id": "A", "text": "A physical security domain on the device", "is_correct": false}, {"id": "B", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "C", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "D", "text": "A routing instance for security traffic", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '5eba017496234f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
