INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df63e1f-e576-425b-aa90-abe4c5aba6e3', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 56).', '[{"id": "A", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "B", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "C", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "D", "text": "A physical security domain on the device", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'eed2386c5eac3b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0985fdc-4cba-4fc2-87a9-b6cedfd80d70', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 56).', '[{"id": "A", "text": "set nat source pool POOL1 range 192.134.208.29", "is_correct": false}, {"id": "B", "text": "set services nat pool POOL1 address 192.134.208.29", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.134.208.29", "is_correct": false}, {"id": "D", "text": "set security nat source pool POOL1 address 192.207.201.207/32", "is_correct": true}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '4238054dce588cb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c655341d-00bb-4db6-9d04-7b66cf331a04', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 57).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "MAC-based filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "Application Firewall (AppFW)", "is_correct": true}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '074c0ce50283681a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
