INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5c7fb7-a6d4-402c-9d55-9568914e338d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers (variant 8).', '[{"id": "A", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "B", "text": "A bus topology with a single backbone", "is_correct": false}, {"id": "C", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "D", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count.', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, 'dcffeaac78bebf16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daadb336-5029-47e7-a9da-b71ac13fa89f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 9).', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "IP-IP", "is_correct": false}, {"id": "C", "text": "MPLS", "is_correct": false}, {"id": "D", "text": "GRE", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, 'bb83c4ee67882d26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
