INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0776d29e-e591-4b8f-8a7e-8d953d7e69e1', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 19).', '[{"id": "A", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "B", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "C", "text": "Virtual Topology Entry Point", "is_correct": false}, {"id": "D", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '12bbb0b4579118f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c3724f-efd9-4d80-937c-a3a40e0ca865', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5 Virtual Chassis Fabric (VCF) (variant 19).', '[{"id": "A", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "B", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '73680fdc1b5eb92f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
