INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c04a82-c3cf-4bbe-90e3-badb01d20ea1', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 77).', '[{"id": "A", "text": "GRE", "is_correct": false}, {"id": "B", "text": "IP-IP", "is_correct": false}, {"id": "C", "text": "MPLS", "is_correct": false}, {"id": "D", "text": "VXLAN", "is_correct": true}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, 'f8ef57a99340aef1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f022609a-cb8f-447f-9fdc-bee8e125d562', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 77).', '[{"id": "A", "text": "Virtual Topology Entry Point", "is_correct": false}, {"id": "B", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "C", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "D", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '902151c73521fcb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
