INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a4bf839-0c6d-448a-9f3d-7fe7e9bc821e', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI (variant 40).', '[{"id": "A", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "B", "text": "set config-file /var/tmp/config.conf", "is_correct": false}, {"id": "C", "text": "apply-config /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "load merge /var/tmp/config.conf", "is_correct": true}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch''.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, 'cf01cb788f5a754e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
