INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3df0f45a-1890-4808-bca3-287b530a6bbb', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI (variant 100).', '[{"id": "A", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "B", "text": "load merge /var/tmp/config.conf", "is_correct": true}, {"id": "C", "text": "set config-file /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "apply-config /var/tmp/config.conf", "is_correct": false}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch''.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, 'ecdb14e3cd0966fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3247820d-9e3b-44ea-a337-4d217d2112ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery?', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '86db3368c1c4b7d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbe25733-9fcb-4c9d-9603-a0089aaa1005', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix?', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5a4ff94ff200a4f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('130bfdfe-1a2c-44b1-b003-e9509bcbae2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network?', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '97cdc1a17e761eb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('839dfdef-9880-45c4-829b-57c9c56534e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD?', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'add24842394cc9ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c3a8ce-9438-4856-b9d4-612471d9f328', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch?', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2fbd24ff8195e13a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('981cb5db-d853-41ae-9f43-1f31a7de833f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk?', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd9a9ad6c1c285f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3395e1b9-0cfe-4e51-b218-de045d54f515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning?', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4e3cae8d9884e513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6059f148-cbe6-471e-b37b-e003adf94c64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive''?', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb3f7e1f129f78a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4555214-56f6-46ff-aae8-9e2432f1a032', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network?', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '28f5547c0f1ba9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d26f0eb-cd9c-4ca9-8bee-bc936a4f20ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route?', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '812bba07b059babc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f7e1294-556f-46e7-8cbb-a218cea5dd77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses?', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7bfc8f293355b5e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610e66d7-2b6e-4126-a85a-c2b194948802', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol?', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b14282c3bc2bdbe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb44d1e6-f246-4b3c-be9c-43edb27cf928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent?', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fa288d19d944d50f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7671d6c4-2ce5-4eca-a039-c0d1b0fc4e27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address?', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c2e074314cc463cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('102353e7-a06a-4caa-9df2-91e29a3a35b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server?', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b06a8dacb7fdf49c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c199a98b-11f2-4dbf-8643-4c34fe8e5fa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.222.180.0/24 network?', '[{"id": "A", "text": "ip access-list standard 10.246.122.0 0.163.115.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.246.122.0 255.198.121.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.246.122.0 0.163.115.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.246.122.0 0.163.115.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.163.115.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a1a5b220b16155c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f64832c3-c28f-4aaf-ab5c-33bc78ddcfc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device?', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b76e360b030e1c4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f72744fa-127e-43fb-84dd-0d802c5e4cde', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch?', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'efdd764af82990a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8772314c-3fff-4b74-bafe-c16457b7209d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management?', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '17dce49968f3e29b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61dc33d3-db60-4887-8085-ff6690842df3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation?', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f5d5f63b57e60096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ebe5b37-419a-4eff-b823-4f1e67eae4dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 2).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e8c716e4fba68b1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1f603ce-e65e-4eb8-a16c-5fc5c18bd214', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 2).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '629d821fe76fc2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71a9f6a6-d904-4717-b4d5-43fe3c9a6c34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 2).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '363008ee24717219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bccc717-29e2-458d-9970-82e6106d2be4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 2).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9a5dbbce9b27f353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04653f6e-ca18-4027-b18f-008aebf4ea53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 2).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fabf0895ceb253e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b28baa7b-1546-4c28-8986-93d10155b686', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 2).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cf684d214dc1d79e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4ae1cb9-61da-4d83-8fa4-dde8cff6d542', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 2).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e44d3daed7b432ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b5e9eff-71a7-4d55-b42b-cfe22f60bd35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 2).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f56e47cd978a16bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2421460e-9f3b-440b-b53b-c885e8278304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 2).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '78d2dfb208c3d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4cb76fa-399c-4ba1-adcc-6467540d3f84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 2).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6094c10421f309dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0c052b-950a-478e-89e9-339b9600feba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 2).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '06747016ba470884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9962c0b-3453-4d82-b15c-80ea5314022f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 2).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2d8b5072dcdd29d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c33a02de-a5d1-47fc-908e-487524dc88f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 2).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7ff933b8a325ce4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c75eaed7-ef1e-45c3-9ec4-0170d5e07d72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 2).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8eb13bfaa1352da2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('742b8917-675e-4c56-9d53-4aaedcd40bb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 2).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd93eaaee9a51d9fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5000c85b-93d5-4049-a3d9-62b1882a6863', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.121.96.0/24 network (variant 2).', '[{"id": "A", "text": "access-list 1 permit 10.103.107.0 255.56.1.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.103.107.0 0.162.217.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.103.107.0 0.162.217.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.103.107.0 0.162.217.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.162.217.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ebfc7e17a948b883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce24e227-e0fa-479b-8655-5eda0080552f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 2).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0c241ce8b5a12d11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ca7817c-f4e8-449b-8902-981d3f16b1a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 2).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '30e30fe4b81d5317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30746f7b-3ce1-4f06-bcfa-37b01a21c763', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 2).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b2f8f6aa6065fe70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('287e1c36-c107-464b-9fb9-92e910d08060', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 2).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5cec65de11fb48cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6d45ffa-df28-43f7-9e75-8f6f53682315', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 3).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '74a04f3d4557172b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a50f94d5-8b6c-487a-bdcc-0b801004aa3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 3).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '58dec74f877d70b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c636b1e-f156-4bf3-8389-c1825516c820', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 3).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a133a461611e44dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa014914-c24e-495f-b759-e7485cb48453', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 3).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8b06b935981953be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f92eda9-a000-4e4f-bfb1-fb34ebf4f14e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 3).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5f65efffeb35dd97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39bc25bb-2533-484a-8b72-b2cf61bdc891', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 3).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a5fa5c3d8374949_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf84040f-2428-4b61-a8bf-072d3c2682a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 3).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9bb6d6a1ca1457f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('512824d1-0654-4d8a-a33a-54e20a4e9a7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 3).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5224f25cfc26519_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ca1c7ed-b4f5-4578-8b9e-479dce928e09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 3).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fc0edf6a28ae2ffa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e09753c7-b8e7-4809-8bb1-56b2e626dc35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 3).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f92fae9d5af07be3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fe8cf7e-5c27-48bb-af5e-223dd6f4d217', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 3).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '906c4536cd8ced9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e332455-0d67-4846-ba1d-3bd7b8edb290', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 3).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'c84f371cf1f97176_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5332a839-16bf-4e8b-a335-7613b6edd215', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 3).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c631e2fc3982ff4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6a9faa1-a06e-456d-b695-ab88ad453535', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 3).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2cc31ae35338f2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ead5a9d1-6fff-48e9-a0ed-f240d9dcc4ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 3).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9a439d8f82155d94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3208d3af-6e18-45b2-b8e1-da8beb98ac77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.117.103.0/24 network (variant 3).', '[{"id": "A", "text": "access-list 100 permit ip 10.236.16.0 0.95.227.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.236.16.0 255.155.40.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.236.16.0 0.95.227.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.236.16.0 0.95.227.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.95.227.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ecf931d857d43935_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d97e1cff-1a4f-42b8-9117-914cae2d6acb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 3).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '756b55fa429820c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('477b613c-409b-4c4d-b818-e5268c1932ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 3).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '693d95a675296764_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41c1de0-9d7b-49c9-afab-eef880064518', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 3).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '940abbd2a87954ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('770b97a1-b82c-4e9d-88e9-8f4ae0086fc5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 3).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'dc8c56ddedc9c60e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8694bdc-a9cc-4c80-9e9d-4f700971467c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 4).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3ff7eca3d9117186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12f2c7bc-5fe8-4743-acfa-f796648600f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 4).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c1145d8e3e23c95c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('776dd493-11b9-4419-bfda-c3e830906e1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 4).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6529ac46fccabd76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b66d90c-749a-42e0-80de-aed67011db24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 4).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7dbf211f192f5b6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46c10250-3064-40a8-996d-202b912368e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 4).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8df5e88bcac5dc60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78c6d398-0160-4221-ad66-08620ba56675', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 4).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '80f6f6d5c8dcba43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('824114af-9cab-4c7d-9fad-d00760b91353', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 4).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e8214030063dbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1145fe05-c0b0-40d1-9ecd-7075f4253257', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 4).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '83c293fddc7a17ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c02c83b-5c4c-4bdc-8c20-40a487db80a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 4).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a25286d68d6703e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59f84401-fbed-40cc-9ece-f1d3c2a83143', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 4).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '264cab0aa8e567bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cb1d764-a507-4a4b-a9b2-186162773f75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 4).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '64b7f8b950697f6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72453a8d-b82b-44c5-9c5d-d0ab22cfaf46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 4).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1c667426b074eb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('076a60c0-dcb4-4d1f-8d3e-5f037d186637', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 4).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '550085b4bab7e97d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49364d2b-2858-48fa-981d-739b46a65c41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 4).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5fbbfa35a0374748_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850c3a27-f711-41fd-a1cb-06740b7b80f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 4).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c9ce11142d56bb43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3189d169-469b-4900-b43d-6daed00dd2ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.165.46.0/24 network (variant 4).', '[{"id": "A", "text": "ip access-list standard 10.132.0.0 0.226.195.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.132.0.0 0.226.195.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.132.0.0 255.222.79.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.132.0.0 0.226.195.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.226.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '736b708dcab846b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99ccd737-07d4-4c8b-a533-f4a0ea5833ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 4).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '366182aa3da74e3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded568e3-2bb0-43df-abf9-dc1f3315b693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 4).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '44f932bd4a5adfc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3821c133-a361-41b8-9c54-2aac2f6dbf96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 4).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd511eb7a83fc9d87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c96ebb60-e66d-4846-91fa-319842b6033b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 4).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '667393c3aab6dc17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ca09b98-1b85-43da-9d5d-791855fd0c14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 5).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2f7f35f2a3d787ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('251bfb36-7673-4cf4-83cb-c644dbc3b19b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 5).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1f593c2a84e707f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e08de88-5c9e-4640-ab3b-26b5cbc1f9a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 5).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a17215ea0ab47208_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d2f32b-997b-4422-9e7e-0f5445f852e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 5).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'acb2d59bc1c3db7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b342e63-a5e0-423b-808c-b1ac42755f09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 5).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cf6f0f9dfa0c019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('885cd5da-6c1a-47d4-ad84-bbf2bb37aad2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 5).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b87bea4938a87245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c1b5f7-5077-4e25-a26e-aabd8907959a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 5).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90e579a8b7fed8e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e74bbe12-be04-4eeb-ba4d-27abed2ab389', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 5).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0d27c3b69289cbec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('804264a8-58c2-471b-85e6-c8d62c3c45d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 5).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7f8cc35606695eea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c45fbdf-a6b0-4e2b-bd8a-263cc7659b24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 5).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '02d1e931c8bf33c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc973918-9311-4861-b947-dc4a757d4b15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 5).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6b2ba0211a33a453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('356bf688-025a-4fa6-873e-e5a72411de9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 5).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7ca5e2b55094f852_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2492d1c6-32cc-4d8e-a7f3-65f0e793c600', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 5).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'baf3e5241531cf5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87302d36-d759-4cfe-9b69-9183dfb30a4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 5).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e7c37b48b1a97cce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('222c1d34-5a31-4796-ae9c-45b2a93e45d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 5).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4f345c7cca19f8d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8343479-f317-42c7-b2e1-56e8b7d3a12a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.15.161.0/24 network (variant 5).', '[{"id": "A", "text": "access-list 1 permit 10.152.12.0 0.180.52.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.152.12.0 0.180.52.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.152.12.0 0.180.52.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.152.12.0 255.157.190.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.180.52.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '507af3b3580e8806_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8814b5e9-d2b4-4f1d-8315-e050d375e015', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 5).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1478fb0a4e893091_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e19ea41e-8da2-47b3-a119-9e36704b9419', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 5).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c70eb97599831504_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e6846f2-4c3a-4385-8398-a1489beee453', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 5).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd7f448887f9bd55a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a0c300f-0128-4bf9-aee9-9daeafc510b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 5).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5da9c7e8b3bc8fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e415391d-9235-4f16-a681-88ca4ea3ddce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 6).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8545e8f120bc48db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54c843d2-8365-408d-b954-936fd9a285ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 6).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '24b632b1252d937e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa3a17c7-1b12-4147-997c-a02ac32fd4d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 6).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'dee500e832b80188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69065875-de97-4815-9048-bdf8545cd911', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 6).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e88452cd8bfbcdfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e884928-4e99-45bc-8a00-0935151776e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 6).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20d4f4b52649c6eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b1af516-8a90-4254-894e-a9bbd16cfb06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 6).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c696dc027926b1b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc69f61d-c2e1-4fdc-acf6-8850566e55bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 6).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e739b4144b48dcbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4310d86e-ff65-40d6-a2b3-7e702f0ca4d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 6).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '818172d2e63ab751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2844fa28-67b6-4d87-80eb-57b7e7f62df1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 6).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c59a3651ab417d82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fced38c-5705-4105-8674-765755a9e269', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 6).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4d2e6c836e5de849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b5d4ff7-92c5-4faa-81fa-52fdee8da52d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 6).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '772caa5e21d21c00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1122a30c-402a-486b-ac79-a7dbadd4806a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 6).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '470cb1736bda0aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7e9c5f4-3282-409f-9969-eb37e8058f45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 6).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3dcda3acaabe5f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e2f7dc3-3e35-4ebb-abab-60ed743c7edb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 6).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '12482354f61993ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c82360-96a0-4f50-8f20-76bd82fcd9b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 6).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8c609b64a7fe839e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c790c6d2-9a3b-40ac-b034-63063a294d17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.197.112.0/24 network (variant 6).', '[{"id": "A", "text": "access-list 1 permit 10.253.220.0 255.123.93.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.253.220.0 0.170.138.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.253.220.0 0.170.138.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.253.220.0 0.170.138.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.170.138.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a8aa778803f599f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9c47409-610c-4f6d-a7bf-b34944fe3865', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 6).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e7c1fe00a3d09c87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a051485f-a819-4ea3-bc3f-79c37d20de83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 6).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b082300b5a39da3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96b5e991-782c-4651-95ea-4a01a731b3ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 6).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c0be9887cb66d47b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9cfce5f-f54d-4abc-85db-7ec30d135d4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 6).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8aca859b5b688302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9af6eca-7cc7-479a-adec-66e44dcc4ef9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 7).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e6d525428817755e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96015613-6a22-4585-914f-817ef09a8c3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 7).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0270541517c69fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ceddeab-4959-4dc3-ac3a-65a489602327', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 7).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'ea2d2131e7aa8607_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb1d1d9-d7da-45a3-aa2f-a58aa78dc87e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 7).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b599f28a0c9035fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79f5391f-bed0-4016-8241-a199dc269148', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 7).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '68e69c4b3042fb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abec13c9-12c2-428c-a546-973e9a4be917', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 7).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b565221173e7a336_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2721dcc-c8d5-4e70-bd62-4772cca4a6ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 7).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '496752c7ccd7f6fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d917af8d-311b-4d88-873d-2b7a9a42c6ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 7).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '12e4ec0bdbab341a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('511edea8-9fa5-4b23-9e4d-f4f82d7b07dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 7).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0ebade6f7ff4dd85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f1b7a5-1ec8-47b4-8e3f-c37c11ffa776', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 7).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5db00984d3db4afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5aa08d71-83ba-41ee-b7ba-3ec73492a893', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 7).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ed8729fb6f77da01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88e0e6d2-0f6e-4f92-8e41-e68b82063e23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 7).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3180984a436caeff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ab723b5-59dd-4e63-b293-9a640667aef0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 7).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e4c1ef99062c286d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1afcc175-38de-400a-99a7-46c531123e26', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 7).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5184f9ed1ec80189_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcc21aba-b393-4ee8-a584-034d71c6e282', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 7).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '773f82b029eb7546_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc54e35a-247a-458a-a05f-4efc3b3bf755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.218.0/24 network (variant 7).', '[{"id": "A", "text": "ip access-list standard 10.52.230.0 0.196.123.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.52.230.0 255.99.108.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.52.230.0 0.196.123.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.52.230.0 0.196.123.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.196.123.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2762c6cbd90aafff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48a55bfb-4718-4fdc-a678-3a486d14f807', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 7).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '60e6d8a953a79407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a65fb1c6-7776-44cf-9867-7cf29c5dc330', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 7).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a2cd8e81e82dbf73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7d68f7b-2a70-47af-9c2f-beebc1a6cf79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 7).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0948e76348cc1d1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb486c3f-e122-4f9d-9223-4fdebda31879', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 7).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '35b646ca4813c8a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97211ba3-462c-4b41-b7f9-18c0c5ebb1ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 8).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1671551bfa26d186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ac70fe-117d-4185-b2a2-5fce54b686ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 8).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bf305e9340d921c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49b19cec-e377-4f6c-9fac-ef01c6ec61c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 8).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '27941eea9207124a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fe82503-1a15-4230-9eb5-90c56eb2e23a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 8).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c9bb7eb571ca2e08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f76662c3-c68f-4ce0-aef5-2ed38d97c474', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 8).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cc09a854efbf056f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5516bc15-d733-4ba7-a833-31e75a6a6593', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 8).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f73a1777fd0cc32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63f26d27-3739-40a1-a9a9-605b26012fdd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 8).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e8996d36b951184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a13bc93-03d3-41e0-9d77-901bc3aa1bc5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 8).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed014fe5da48e2f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adea478f-495e-4e6c-a1ec-3811a54852f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 8).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8029a83e41670552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4456a40e-3665-4449-ab21-2232c6340f99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 8).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '12525984dc46cf63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05fbdb35-a070-4786-b70c-577ed3dabf1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 8).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '98736c9d4a0a849b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('757946a4-3ef2-4cf9-be6c-0a69b1a9f200', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 8).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2fc673a2be8d6879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d757ff-7536-453b-8282-9f73dc01f86b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 8).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd417e675384bbb05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1569b72e-c88c-4372-a728-f363ed3875e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 8).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c96686eb8c377f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('495aeb8e-de64-420d-b818-cde55f95ae5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 8).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'dc816667632a9d9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20fd48b4-5d2e-4747-b3b5-0a14b3753b12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.14.80.0/24 network (variant 8).', '[{"id": "A", "text": "ip access-list standard 10.194.192.0 0.217.117.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.194.192.0 0.217.117.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.194.192.0 255.94.188.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.194.192.0 0.217.117.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.217.117.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6bae8465fa41608e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('984bba7e-5814-417d-97dc-cad0f4a0a74c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 8).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '303318a99e0683d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82ccae7a-d3d7-459d-be30-f808dbdff1c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 8).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'be4d815a31c67947_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('074859fd-1225-44c7-9685-aff887967235', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 8).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6a9771d977cef91e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb9be59-4321-4247-a819-ee646c27f9cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 8).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5090fa0e69321562_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a11e7e5-39f0-4498-b37a-be2be94f661f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 9).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '29bb1f065e25a2e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e73ae9d-69b9-497f-9aae-1911206e0a00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 9).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f7e477f4db663a95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abef0aef-8837-477a-b008-9f3cef60e4a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 9).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9fb7f85d96a5986e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d41fda92-549e-4643-890c-350d38a036b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 9).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'faf005213cb45595_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e45deda-6d7c-4b33-9692-79afa11f04d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 9).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c9bcb06cc35888bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2657f737-b4be-4974-ba13-296295ece5b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 9).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c25988858dcbe600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff5153d0-43c4-408c-b59c-1bf9a29215b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 9).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd5db760140de9ddc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e15f891f-c666-44a4-9ea7-d52d1332d91b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 9).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e8854f318ec36cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07810dfd-c211-4865-884c-69e3225cb5fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 9).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a6c4cf7084d4d973_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef2f2de-c8e7-4a89-8e89-730ef49fe498', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 9).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0c84df15f1190a12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('489addc3-e801-4a55-9e76-4cd0752df787', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 9).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '65b5d4ef71423ebe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5206bd58-440c-424c-b1d4-d27ba6ee660c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 9).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '765eca8ea4e11f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75e5458b-d8c5-4ffd-9c78-766f50b2cd8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 9).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f3089a85b0a414f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f1ccb10-6b75-46e8-819b-4d79619b9a24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 9).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '42841cba85ac2a89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6972f31-cbe9-4569-a0d9-e9c47b89ec43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 9).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17afe6b26f039ead_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e43379c8-f0f2-426e-94ab-a763fbf14ce8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.203.34.0/24 network (variant 9).', '[{"id": "A", "text": "access-list 100 permit ip 10.79.127.0 0.48.21.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.79.127.0 255.47.171.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.79.127.0 0.48.21.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.79.127.0 0.48.21.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.48.21.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e0676bebb2997f86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b89abe1d-365e-48f4-97dd-0bc02743cb20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 9).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '23dd529af48566dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec98a27-c20d-441d-90ef-5bf748b4c601', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 9).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b71759a218bf983f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54f4a9e6-b10e-4bdd-b0f9-a80a86e93dd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 9).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a62d394ffffbad1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5976b708-b0e5-4bd6-a5aa-7068250a7ecc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 9).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd4ce4baf45513373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a66d845f-9cb6-4f54-bcc1-1dd175c5542b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 10).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '51455d47ededefe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d15bdafb-34bc-414a-923f-a53021d5de9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 10).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a07ed01f5fd26399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14fe2310-334e-4fab-9f45-0b0234599606', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 10).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6e6f2590545914bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b9516e8-5b8f-470c-bf18-38ff7ff92fe9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 10).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '4caa8c28dd70ed16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e3bbc3-918c-4ad5-9be9-ee0b80cdb907', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 10).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9767ec2fc02fc662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70bfc723-68de-4f41-95f6-d0b1872a892d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 10).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06dab3c8abeeadcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45384c3b-fafe-436f-8910-d31cf9f58dcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 10).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '877b2dc4c3a8d421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('209f12e8-528a-4aaa-a25b-a2ea287087fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 10).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c406fb0acd9e001d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6de85069-8efe-41f5-a3fd-d65c7cc77a88', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 10).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '180dbc9d1134a6ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8271e6e-85be-4aa2-9974-eaa5058febb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 10).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0bfd3114bd2c21d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20937d2f-3be9-4f6c-a1f9-eac3405d8d60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 10).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5a324b74d1b478d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0581eff-4e6d-4f3e-8b55-224fc1fe4021', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 10).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '87cb171ab34a9a14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21602337-430d-4545-99ca-e9722b981aa2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 10).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '78a942f91d18d7e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d88ff99-8041-4de4-abd9-b94840191c1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 10).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ee5b6ecda8bcff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f22cbf9a-2f96-4499-856d-43400e0127e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 10).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7dfdaf6492623482_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf7134bb-9f95-4288-a712-445ee7cff17f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.76.220.0/24 network (variant 10).', '[{"id": "A", "text": "access-list 1 permit 10.192.174.0 0.173.133.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.192.174.0 0.173.133.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.192.174.0 0.173.133.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.192.174.0 255.253.38.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.173.133.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a5d7a2bfdb50ef7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f29321-f099-4401-9474-0559c389e707', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 10).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fe823e86ca16b3f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3352b22-2b52-4d0e-8586-cdbea59afa11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 10).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '94259e9341c3b191_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('677e1314-f67a-44fa-8886-8709646e2de1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 10).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a3e25d28aa55dfc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e105272-ce79-460c-8a56-a4299b2dd2fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 10).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6670f55561a18a26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ab2c410-1fd6-4d4f-95ca-d3f3738fa3f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 11).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e78b4cb90b9aac00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c013dad-8cbc-4e5d-b02a-1ccded19e888', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 11).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3669aa8c5b00951f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65cd7d3f-8df9-471f-8e4d-dc41fbfedb3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 11).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c7fc1cd17e6c643c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca1b1d6-039c-47c5-afb6-e638db084879', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 11).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd42db3b31aca3403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2092f0f-e6ec-4476-bad3-b38444178cfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 11).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '46d18e1f77e62f8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57070818-db12-4a4e-99ef-53b85c3f4760', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 11).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8ddae79780402d43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37c2603a-9021-46c8-844f-026172f5bbc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 11).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e8095b2e5fd1eb7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d35d83f-9d84-473e-9698-a90a7669f19e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 11).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a3636d5556194fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8a7892b-b35e-4f1a-92a8-436f1c587338', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 11).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f316c486342c4c00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22a8d259-a231-4e63-bc54-d6ef88a2e9e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 11).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ded82258286e42aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0ab2930-5d9d-44e2-979a-d9f4cc18bbc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 11).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7a0d3bed4071c05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e25d4570-8c38-4694-960a-0583e7452c32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 11).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f74ddc4c407eb7f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcfa1cb1-f1c7-426c-af27-5472214f4c91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 11).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '752ecf993dd600ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dae803fb-c555-4d61-88b5-8b216bd19757', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 11).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '207b9400acf8768a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d49a3f3-d85d-4736-b859-fc00f36c4001', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 11).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e2bcb7ea831042d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c76ac33f-50ba-4d3d-8394-f54ed0a91ef7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.248.0/24 network (variant 11).', '[{"id": "A", "text": "ip access-list standard 10.164.15.0 0.160.130.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.164.15.0 255.102.184.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.164.15.0 0.160.130.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.164.15.0 0.160.130.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.160.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f528ccad77378b93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41e3a739-0ddf-41d3-b6cb-37521c1d3a0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 11).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b3fae847bc995964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09dfb8ec-5197-4dc8-8a8b-d24a54eec6b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 11).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5bd2a4fd5cfc5db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a4b51c-677b-4bbf-85d5-ec5a71db7d15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 11).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4ba7c24871fd0b86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d06742c-da14-4a46-a48e-5061a95bd4bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 11).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '493d29393fb46aa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd0e4260-a4e4-4684-bf1e-794162708d5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 12).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0e82e36632d393f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d8d751-0ca9-48ba-913c-f2fe199a6749', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 12).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ed659b05c4aa545d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1a43451-e368-4154-898c-e89912d9877c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 12).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '64c0f90711a607bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd9599ea-10a5-403e-9929-b320d294bd6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 12).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '617708bacd90cf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7894339b-e2b0-4ec8-8317-5667e14b48e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 12).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac5973e480c68002_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e6ff5c7-0f6c-43bb-8f84-35037321fb54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 12).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '05133a607aefd0ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1677bc6f-2a3f-42ae-9d99-bc1758291468', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 12).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b37e23bb96129676_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('950cb423-3938-4e7b-87ae-75f6e35783af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 12).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3271e68e13092b3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c355389a-0bab-4508-b4fa-c5d2d83a2578', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 12).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1962e7975c11a7f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77c357fb-b9f9-4ff8-bb12-69cbe062e0c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 12).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a3d707346a15cd4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d9d2cc9-b88e-49c6-8fca-8959ae9938cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 12).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f220ab02341dad2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c902658e-9039-456b-a4d3-6318c29112d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 12).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4d402ec770ae96f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24a13144-8a46-44d3-9136-9186c4c874b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 12).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '451000776c90b308_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33158f36-0167-455b-8bb8-9da83d1d1a9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 12).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '45807b3e81e321bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ff6c75e-cd57-4be8-b9d0-5ecb4cd44955', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 12).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '014b239d2852f34f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e444d327-1bd9-480f-ada0-ea7c9bce0ade', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.199.69.0/24 network (variant 12).', '[{"id": "A", "text": "access-list 1 permit 10.42.80.0 255.251.135.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.42.80.0 0.20.162.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.42.80.0 0.20.162.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.42.80.0 0.20.162.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.20.162.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8adc387463e1539c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96901069-2014-4548-a6e1-0a937bf1713f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 12).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5234e7afc692a66b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b411586-2af8-4f03-9423-2a78893dbbc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 12).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '01f3b4cab4f97215_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47eea2ba-27af-4bf6-8aae-c4f799b5e82d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 12).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ccdfa603e82967ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7b56840-3f24-4dd4-a0a2-a7de7243321d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 12).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '392610a86d559a56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6edc17c-7538-42c2-be31-4f50d42ec39d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 13).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b5dcae4040c4610f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4c2c657-54af-4604-8c53-432db52c00df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 13).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1b08866089641357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b724e118-2b45-456a-8b48-11d9483feba4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 13).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '05dc781054d6be58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3955b31-c97d-4197-95f4-b05229240e0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 13).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5a697841bdf8f8df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1b1811e-237c-4727-a9ec-46fc414c7c23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 13).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd4b4cb1ddbe1c18e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e3aa4c-9e54-478d-be07-8f6e97d1886e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 13).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3eee679c70141bd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('670f5c2e-19e2-44a3-b32d-db47892e177e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 13).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '320f79440d866eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0528c059-6b16-4f55-a520-ddd2bc7b3122', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 13).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90cf7d0a2cba13a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b46b10e2-ab18-402d-98ba-ba7094a28d19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 13).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '29c78334d0c10442_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('003f6ac0-229a-4b59-87a9-1226441ba3b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 13).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8b1ebba30d90e24a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47309f51-4efd-4e5d-9bf3-935fc8a08623', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 13).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b52b64aec7a86a57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d1c46d-ed01-4804-b950-89e055f04b4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 13).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '988fdeb56438f9c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('196cc9f7-19cd-4ea9-8fb7-614649d48eb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 13).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '30da983acea727a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59748f90-38e1-4b06-a1b5-9912305935cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 13).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0d46d11933b6baf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2fb0143-7348-43f6-82b0-3bc564a24989', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 13).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4c73b771ee2166be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f807216e-3b6e-4372-b4f5-eea26df54513', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.62.66.0/24 network (variant 13).', '[{"id": "A", "text": "ip access-list standard 10.247.102.0 0.39.114.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.102.0 255.9.150.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.247.102.0 0.39.114.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.247.102.0 0.39.114.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.39.114.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e7a28fe111ea3e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7558549d-78ea-4f0a-8e2a-bfcc89c371dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 13).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '67ed162be18d5268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aecc3974-11d7-498a-a60c-a22d2a555c38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 13).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3d69697af8ff886f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850f0327-32cf-47ad-97f0-b7a1357ae4d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 13).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '27ba794939c25081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('180bd63e-1530-4de2-adf7-8a153a81d6fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 13).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8c1ab50ef73d0b68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49b11feb-c255-4ddb-9676-bc04dd3953c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 14).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee7499b09ec4b742_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7055d9e6-afc8-4ce3-8ca8-dc6db804f25b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 14).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd26f34919e01cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e8ed211-c4fb-4942-9213-26206b9c4433', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 14).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'bc69d37fc43b3485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a064532a-ba1b-472d-9316-038e11c163e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 14).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ed870bb1b563d326_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('696adb27-c8fc-438f-895b-b10bc5c035d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 14).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'af3e1d19e278a395_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('642561b7-bb79-42c5-b636-0eeba27a0114', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 14).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '502490da4f617ef9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaf971f7-7f44-4292-9ee5-25379baec2d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 14).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e2e2400ed8dcb353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('515847e1-9999-44e2-af04-01343ee88a69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 14).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '476f3754a6f291b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68327ce9-9de5-4780-95af-a459296fb1ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 14).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2239f37d27ab5b44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3029cb91-57c2-4564-9bbf-458ea60caa04', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 14).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2a0e80082b0df26f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4a04ce5-9fb8-416c-8665-977f703d7058', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 14).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c0745b1a17dd9e57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f849eee-29ad-493e-b56d-e8ef601a372d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 14).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd5a8365c1f0980a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ce7b7f-f864-4071-ab8a-a1dd8cc6a7d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 14).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e2fac7a9baeb0ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e7e5bc7-3c6d-492e-bf24-2bffa229b63a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 14).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5fb4088b4c390371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('086a930e-d83c-45ae-9fc7-274257d0a77e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 14).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '64da37ec7454cbdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d8c71a6-e5cf-41c0-aa23-2c032a3f282f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.41.145.0/24 network (variant 14).', '[{"id": "A", "text": "access-list 1 permit 10.47.99.0 0.197.39.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.47.99.0 255.183.189.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.47.99.0 0.197.39.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.47.99.0 0.197.39.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.197.39.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c337cd8cba5e1f76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87123220-6544-44cc-b06b-4401b5a93c96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 14).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd8e6892cddc0f7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda6fce3-d60a-4384-a8a3-f214a7fe595b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 14).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd4a6ed28bd821352_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35ef06f7-f5c8-49e6-83e2-2fdc42e033e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 14).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '80fcd19bef3f914f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f97567-1474-473d-8346-915f79c770a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 14).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e2468d4549abaee2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('329760c2-25f2-44cc-857d-a5ad1fb69f16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 15).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b89a0f081f80d7d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a137367-8f19-46be-94d5-35a4b382b908', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 15).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '78246781b592a182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c13431a1-fd36-4cc8-a5a5-554f2204e73e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 15).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '96f6b9541189c9aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afd36e67-64b0-4afc-ac6f-3fdc233e0116', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 15).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ba033282d5bfc062_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79e8f13a-3bb3-477a-ac29-ad61636103f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 15).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '99779efc83f9035a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a71d039-c06d-4c9e-97d6-4de779da214c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 15).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd15a74b6f557e682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8086222e-1d12-4918-89d2-78bdd8428c16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 15).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ebe05d83cdf377bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a666ee3-6463-4b4d-b576-ba8b2c822287', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 15).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8f36229ea0430c11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d27fcc1d-f094-4bd1-8d46-18f7b4a8ded8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 15).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '42f522d302196aa9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('838b7c7e-277e-416d-a847-950a2f988406', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 15).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'eee1064093f962bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a420d9b7-c6a0-4ec2-8659-003cab875728', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 15).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '471fe391ca468f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cebbdc1a-8f0a-4f07-97f1-b2621c0a5508', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 15).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6589db7fd594a9e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38cf2d1b-d015-4e44-b98a-3847f9bc74f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 15).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2295dd0b1dfea77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff6f16c9-4c3c-4e23-998d-5c08fa9aea2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 15).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed2dc85cce4d53e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cd60346-fd57-47ad-bd89-2e00fc932b9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 15).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4919dbff5e4816ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c38a529-c19d-4717-97ed-d1e1317bbd9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.90.224.0/24 network (variant 15).', '[{"id": "A", "text": "ip access-list standard 10.78.53.0 0.17.9.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.78.53.0 255.30.197.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.78.53.0 0.17.9.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.78.53.0 0.17.9.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.17.9.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9def6223bab649cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7cfeabe-6786-410e-899f-5e4bc2c1bf70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 15).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c9fbfd3dc610830d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbd55d16-7a8c-4509-b9ac-475da66d51c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 15).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b8f763ecf67a0d0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bf104a8-6829-4730-8c19-24d206a17ebe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 15).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6b1c8d41e04ccaaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd3e74f9-418f-4d80-8e0c-37fc03a1f750', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 15).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c619db01f5edd5f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58a55a99-4526-4ba6-83f1-38c66220c741', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 16).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ecf4594e14d20c78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ea90570-bbce-461a-9f47-b57e700185f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 16).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c613784a1e5ec555_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e33464c0-c771-490c-b50d-c0a286c311da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 16).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '93e7131117f99c48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('762e9e34-a128-4bbc-a014-fc6af1040a3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 16).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f68e107f5eba9c3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c35d4b6-047c-4657-b733-bde82dd8ab8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 16).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c3fdeea069f14cc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eed7aef-423f-4862-a04f-928dec793e8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 16).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1afb869011a4e804_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b979f20-93e4-407a-96af-68e80d5dbef9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 16).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '99529fdc0f7ac83e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d0d685-b56e-42c5-8230-062fbd53101b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 16).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06c3509423a8ea1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2acc6cb9-50c3-4151-8504-e5f67c99acd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 16).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '18a3a9927fc92eff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('807b11e8-7ee8-49f0-aedb-740e0fe13fdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 16).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b5621708a265bc4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a5b9bdc-4bd7-4012-bf7d-a2bda9068e06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 16).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8069b9c5decb25c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b2b4c5c-31b6-42d0-936f-e2cc96af1eee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 16).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1cc8186bf9808f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7295d40-ca72-4ffa-8b38-f251ed8c9fe6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 16).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8064838109dcc1be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08ef4a09-dfaf-4b14-bf45-1de5cee14f05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 16).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1233c37d856df541_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdcc6bb0-8075-445d-bdfb-3945668a8076', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 16).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '409d95b2879f0f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('963b6e49-66df-42b8-919a-3be7827d5a74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.190.33.0/24 network (variant 16).', '[{"id": "A", "text": "access-list 1 permit 10.153.163.0 255.222.46.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.153.163.0 0.171.149.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.153.163.0 0.171.149.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.153.163.0 0.171.149.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.171.149.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd66ecafb1d6a5cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc508ee5-d8a4-4301-937e-7e03f5158343', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 16).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '883617705e5427ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4821834-9da9-4bd5-abf7-c88ab7fb75b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 16).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '612be945a20ee43b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08865ecb-139b-41a3-af47-afcf5b344de4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 16).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '70896290272a574b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddcab708-ef50-4a71-be31-f53cb32eeff4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 16).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cadac874792277bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c1a4c98-64a3-4c90-a18e-ab8bbb6fa383', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 17).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2137b6e0062d3c15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bbdf012-b1d2-4b30-95fe-bac64b399818', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 17).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c3051e004246c719_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cf56813-485d-4555-922c-52dba077dca2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 17).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'd39574ad425a2b00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d20e15e-5314-4cfd-86d7-fc0b73c4c7f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 17).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2fab2114c9f96430_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffd27fa5-7d34-4308-81ea-c2757c5c2223', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 17).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e14a2f04711fc46d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f8f1e71-eb0e-42b9-a354-947b74bfe941', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 17).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec8c72e54afa8aa5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7145303-a2d0-4cd2-b575-d6d9da242bbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 17).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4bfcb96468f77490_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27904a17-1407-472d-8aec-df2d7cda21d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 17).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '160084a7b865ba93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef954469-8876-4e95-8c1b-480ef9d99d94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 17).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a675f422bf778e64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2506ffe-896b-41c5-b1bd-f4f9df2f536f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 17).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '507930b104927015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f49fddb-c530-44e5-a358-550b85062977', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 17).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6bf54e72bd27930c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c3ef5e7-5e4f-4862-b833-561626793aa9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 17).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a3b03fae13e9328d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6931a7cd-9358-4008-b27c-b95379e15e96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 17).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ebbdca8d68890335_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e2aff99-a5b1-4c1c-bed5-73a6a34365d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 17).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '127dc84652e532b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40f5bd9a-300e-4894-82e7-9b380ef0676a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 17).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '24025dc7fb1ecc70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec79d0c9-4304-41cf-8b2e-3124840ef25b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.155.240.0/24 network (variant 17).', '[{"id": "A", "text": "access-list 100 permit ip 10.120.99.0 0.32.155.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.120.99.0 0.32.155.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.120.99.0 255.196.19.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.120.99.0 0.32.155.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.32.155.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cdb6dc4913de2d5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca678938-f4d8-4add-8b67-ce606b93835f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 17).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '333b37f5084cd84a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d990ada5-8895-448c-ba2f-2a77b62ea1bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 17).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '79a0cb08c5a79dbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c21d3fa-2ad9-4ceb-b0b0-0d93f99cef1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 17).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2b656d60e5a4e6f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96c24561-a82b-424d-9349-9fa4b050ee3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 17).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6c5fd654ae7cfb96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d38ee246-fdb7-4294-b921-495d6237b2f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 18).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '061b04ae20604993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9b9f660-a1c9-46c8-823e-52547ac530c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 18).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e17b9a5e73533437_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82b72722-ac9f-4894-8722-36fda0070a02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 18).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c346eb5f36b633e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abed059b-c168-45e2-a8b7-39b6cd37f9c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 18).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '00aee6473a2e606a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('892fd30b-0137-40de-a828-e2efddf395e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 18).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3e2b4b9c471a4a8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a103570b-ea39-4a3f-8b49-5cd92a9e70ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 18).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2be21b4db60c7adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4f82d15-fab4-40e1-9e3f-4d595b97f26c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 18).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '796bf6666c01d9d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f449bab1-1018-4070-95a4-c2e2489145fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 18).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a90b6a73d12bb41a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ced0711-f21b-4556-9737-eeb065fa9fdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 18).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '980ae8ca75a2df0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da935ee4-fca6-4a7f-a691-bc40efeee135', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 18).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '48c2055219526899_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bf4086b-ff87-4632-8ad6-9bec0e72003b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 18).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '69551a98b9b8d639_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af95cc95-7445-46f1-b311-588c48bf2583', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 18).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '07189ac9e9dcea75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5cb1910-2cb3-41ef-9488-8137624cf238', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 18).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '83e1e77febb061be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bbcb007-c097-4463-95b8-885cab4e31b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 18).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '66742d81e2747032_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a760155-d286-4ebc-a29b-ded7b40a775d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 18).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '52e00b014ab082c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('295a73ba-d30f-4dc5-ae53-9a111e5674a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.23.189.0/24 network (variant 18).', '[{"id": "A", "text": "access-list 1 permit 10.169.219.0 255.49.128.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.169.219.0 0.113.5.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.169.219.0 0.113.5.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.169.219.0 0.113.5.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.113.5.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f54fcead7b87bf1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29230b15-dc63-408f-9037-da27ce271d28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 18).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f8f977026d85cecb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5599c24f-b322-4052-8e53-0395370908e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 18).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4a924a97f9d575b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85f377b8-44e7-4787-b495-caf6c5fc0451', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 18).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '00c5a305e9406fec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9c21b7c-cead-497d-b996-39174c3da3b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 18).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'bcd0aba26ab98ce1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf83c7ce-3295-4fc5-81c3-c8beab64c11e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 19).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0a332591907f8a92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07acc7c9-c543-469e-99b8-6f83d18064a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 19).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3bb6904f31ceeeee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11e015b8-36f8-44e8-892f-95bfc6a80fd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 19).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f80f8ba63237372c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6191645c-cb4a-4280-93a1-fcd9205b6794', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 19).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ea2c089718fd1d78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6134733a-4c5d-4389-af21-fe7cbc2b1b89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 19).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc8948419c994267_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b6ff90-5b23-4025-8a43-a38e59d1d059', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 19).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f6495ba2d5be230b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2bb7d5d-6912-40f9-9c8e-507f1319ed89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 19).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3bc1875b3537f83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('814968ff-35bb-4fc1-9c53-3d6bc61623de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 19).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '25e27f0336c70606_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c833d55a-02de-4b96-86be-b171a505e447', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 19).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '81e0b952a21f97c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15455204-7aa6-4ba2-ad60-960f13268be0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 19).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ef228a3521bda2ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee89c27-9c85-4b53-9391-4eaf6a1b0b54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 19).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9e472a9445f3431c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a32e04e-0f95-448e-8484-e296d2fecf07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 19).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'abb9ba5ffaaa3855_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e349bb60-ec57-4824-aae8-a3722f032c5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 19).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6799753083196de8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0e5a59d-0660-4433-9a6c-9498cee037af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 19).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '58d9c22b514b5c6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89d6107e-daee-4500-a1f5-cbfb6c904087', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 19).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '58be2641fcba28dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46488167-6d58-4091-aa34-62084148d88f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.158.0/24 network (variant 19).', '[{"id": "A", "text": "access-list 100 permit ip 10.16.13.0 0.213.192.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.16.13.0 0.213.192.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.13.0 0.213.192.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.16.13.0 255.84.80.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.213.192.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f06f1e2c60fbe08b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d73e7c-4d42-45d5-878d-50f9362422fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 19).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '33e27fde8c7664a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cb954ea-3b53-4cb2-9c1e-3e224c90f661', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 19).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '95ffdce353e1c40f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d6ff240-a422-4bc6-89d8-258d1421bb62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 19).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e3e5f5ae528b1f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad52068e-5732-49da-885d-2f7bf511d93d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 19).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0e5820c8c217427e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb56301f-29b6-4b21-b06e-850c1b396935', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 20).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3e6b4e5b76b4add6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74d7cfeb-4acb-471a-a23b-870d903c1f55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 20).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aca161993e1f5d3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbbf63bf-09c3-4ad0-bcce-1ed08b75493d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 20).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '3d2c960ff772a4df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590c110c-d519-49bc-90c7-10dfe9d61f53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 20).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '094e0b62efc0b227_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55cff1b8-a37b-40f4-ab72-5c44fa34be1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 20).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '22a6e6b38ab25a7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a094ade7-ce54-4e0d-9f90-1575e935c1a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 20).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f625c7d8f6ec85e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b6e4e8-d387-47b3-896b-de8e26f88aaa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 20).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e6e33f806bff9dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('833a9c42-f068-4585-90b5-d825b210a53c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 20).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8758c89491c185d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81a8f0f1-c6e0-4f21-8f2d-bb263d72cdaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 20).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8f0d0ac3370dea47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e8bd6b-515b-43c3-b45f-49fd19ec39ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 20).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd17c90298a00cb94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b55e79e6-60b8-42e6-b9af-fc756a9d4ec8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 20).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f03129951b5777d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2f1971f-da06-45ba-8d4e-5828cb9369e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 20).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'bc74c5dd19b37efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f16926d2-caca-498d-9b5e-1b4f1501d02d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 20).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '55c7533d13ce1dad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44d68100-2be7-4700-8a8b-ffe9bf365101', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 20).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e8c02c48efd6a02a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fb127f8-c4fb-4bbd-a474-6e2b303267ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 20).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '63fdd1d7271f968a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c5d788c-4322-427b-a6ae-f7149613a5e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.91.152.0/24 network (variant 20).', '[{"id": "A", "text": "access-list 1 permit 10.239.236.0 0.135.90.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.239.236.0 255.255.109.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.239.236.0 0.135.90.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.239.236.0 0.135.90.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.135.90.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a6076606c9aaeb42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c69d8dc-6333-4115-bb64-429210dff0ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 20).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c985adbad7de5cc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7195c7a-e044-47f5-b390-94dd1a97ba68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 20).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cf59e475da95a32b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7505cdef-1b65-4075-bd46-131c335c3162', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 20).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9ceb783330bb0fa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95577838-c27e-4eb5-96ce-689deb2c00d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 20).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '2554e10abdfc1b2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3674d1a8-f3bb-4230-b79c-600cf3906da4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 21).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fd1dd5250c92f6f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b965d09a-1b48-41d8-881c-b9fa8a78550b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 21).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b3a0cbdfbcf1b979_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ebe6680-e1ae-4761-a130-2f15ce59b039', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 21).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '197d0631e8acf6da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cabafc34-78af-4995-a481-7a89e9a1adb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 21).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8e57956046fec46b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9a94b13-2d26-4c08-bcf4-b33c65a43b79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 21).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4216e0b75f539317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e21b29-dd95-456b-892b-447afd12f082', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 21).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e7c356f3f4a5ec44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6085b1ce-4e18-4d79-81a3-445efa4cce08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 21).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8b4b69081e1a74ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a06846a-84e9-4018-9fa4-5c1927f20358', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 21).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '226eb58f5d4a0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afbf67eb-2a42-4a15-bd4c-ef28385e6766', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 21).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ad45fe45a86c5a09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a2506e2-4e39-43f9-b4f7-ca2dd51d6d01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 21).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4fffb5550dbbce3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5d9d51c-e156-4595-9657-c067651b649c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 21).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '88ffec5bc0bd6805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a2cd0cb-4369-4773-a29e-d69dd81d395e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 21).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f8ef768947987431_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaa9625b-8054-4745-9f13-d99c650dbd40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 21).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8c053c285a7e07d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f65e3f8-65bb-49a2-bcb3-5a7d5bc1a01c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 21).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '001d647545c440e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84d212d6-59af-4f26-aefc-15fd204a15cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 21).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '41d9ef7d73341221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe8e10dc-35f4-4542-859e-dc55d6527145', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.89.159.0/24 network (variant 21).', '[{"id": "A", "text": "access-list 100 permit ip 10.200.126.0 0.173.130.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.200.126.0 0.173.130.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.200.126.0 0.173.130.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.200.126.0 255.175.151.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.173.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c0828143ab478cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b67db1e8-55ad-4973-b44c-17184d1bf2c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 21).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '92d7e267ada42144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('403a738f-8b20-415f-90e3-ffd778b74a72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 21).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '19f519f2797e8cbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41bf3ce2-eba9-411e-b03f-ea01fc2dd66c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 21).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c9c2891b0377ded5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f8d2f81-38ec-4133-8981-0320e20e17e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 21).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'a866d463db4afa32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af4226dc-56b0-4671-9bdf-90781783cbaa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 22).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4d20d4ad01e8280d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1481f214-f159-4ba3-a900-b0782021244a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 22).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '663cc3c0a9074e5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff95758c-0f9d-4749-9b48-59a6df20d4e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 22).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '45183132fd49bc31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30714bbd-a6f7-42ab-9018-9cd03dd8c344', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 22).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'dbaa1f9b967cede9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ef8e04c-1ab3-4e55-870e-f1f93e91e831', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 22).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac69137573065cef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c9e9cce-dd80-4a86-9843-e75c8a1c8bb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 22).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8d952d6f70532613_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53be41ae-bf8c-451e-9fea-df28fdf16aef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 22).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '076bb76975909eda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e30a8321-df9d-41fc-9573-fd231490ca2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 22).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e55b9bbd1404e0ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd35c94e-43ee-4bcd-af54-4826f78639ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 22).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8e20e4a47501e4f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d77ea83-59c0-4367-b6ad-01734e8b2482', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 22).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '58cdd82c2ebeb6fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77c6583c-3704-4281-87af-1c5e1228a048', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 22).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8007f2f457fb24e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f80a105a-ca8d-4167-953e-02fbd26cd802', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 22).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '607ee6639f9c7897_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cd7ca7c-d9b8-4d98-ac61-a1021bca73cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 22).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '878dc1465d35998d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9ab5f68-0424-4ed3-b780-89e00f39b7f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 22).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '10101511a46ee922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5337689d-d7ba-4bb0-a401-1a3a573429de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 22).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e5b9ee8cdc1f9470_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('229f6521-3f0e-4228-834c-7a0180d7df75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.247.196.0/24 network (variant 22).', '[{"id": "A", "text": "access-list 100 permit ip 10.49.250.0 0.83.245.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.49.250.0 255.165.25.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.49.250.0 0.83.245.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.49.250.0 0.83.245.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.83.245.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ec8cdcc8ed079ca8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c451dbbb-fce3-4f04-950d-ef765a694bdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 22).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '585831a4c492a389_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d64d5c1-4e6e-4210-8fb1-0ca5d18d2bbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 22).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3ec7d4baa8a78ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec3e36a-2041-4c9a-835f-e6ea5c87aec6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 22).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '93158c01de8f5093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d0af0b0-e28a-4abb-b07d-96f3729a3c25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 22).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6dcd8d40ac94eb28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57b515a2-dfd8-4161-9a60-bc500f7b922e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 23).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cb531ee99cae6807_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c4c9da-dbec-4195-b02a-6fd98f2f4123', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 23).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2d5b9a166fb8e029_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d54bc885-0ecc-4aaa-bdf9-2e22ca587d96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 23).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c48fc2b985fe3462_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d72170d-10b9-4884-80d0-d77114c27544', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 23).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5555b97011e31e1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfe4224a-cb42-4200-9bb1-e9df0f6c1f6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 23).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e386b73d116ec0cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('915dc69d-2d30-4ab0-ae6b-e694ca6c3fae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 23).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '19202c987b394134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6852708-dfe8-411d-a1f3-920111c94fbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 23).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b60647ceec51963_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e93be65f-589b-4523-90c4-be8c48f02287', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 23).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b44ea84b32584055_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1cc127-eaac-4e80-8f15-470e08a55b63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 23).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '39be37fdfa7bc83f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f52f7844-f23b-4ba4-b385-011f35972959', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 23).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5cb74618db7fc77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a065e156-dfaf-4177-a895-c26df6629a27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 23).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '01e0127a3bf0a27b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ce39355-25e3-4911-b0dd-420e0561315b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 23).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6ed701609fa4d215_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e92768f-7c04-43ac-af45-cb7a96405223', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 23).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b593f106706af755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d0cc626-9d03-4154-aeab-c77b778eaf09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 23).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '158997627f439fb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21d2c80f-2fbb-46e1-aa38-b7504e701337', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 23).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ad77198a188a40ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3455df4-c646-489f-97d3-f325751cc327', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.179.56.0/24 network (variant 23).', '[{"id": "A", "text": "access-list 100 permit ip 10.247.117.0 0.129.7.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.117.0 255.23.12.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.247.117.0 0.129.7.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.247.117.0 0.129.7.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.129.7.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '07c19d81b7b39d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76e98956-93bb-4d0f-938c-ebf3fe139f97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 23).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '70cc5f1ad06b9e5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aab851ea-9395-430d-8053-6d2d9a20710a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 23).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '48a7d1b1356411fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd663dd6-86dc-4f7f-bcca-206cec7ba686', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 23).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '825c8c9c51759d03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff7e714-7610-4091-aa5f-fde0f80487e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 23).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd1c8d328d0a766ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('455df082-811b-4b97-adc4-a1ceecb4fd2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 24).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '20f0ec3b5039f1f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2c76a00-1d72-475e-9e3e-aa0db1f65692', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 24).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2cf6583240e7bc39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a79198-c68c-4460-ada7-7ff1a31e9ca8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 24).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7db6eeb6b938e995_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2f00d30-3908-4eb6-a89a-76eadcda8aab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 24).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9db0581457a51753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34cb5383-5430-44d5-a366-dde2b427dbae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 24).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f0383f901bec3dfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b336802-e16e-4d52-b8f9-f8682689451a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 24).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f00321a9b57b6486_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d010c12d-60c8-4ec0-8bf7-501922a74ebc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 24).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b590dcae1f1be290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('197970a8-ff59-4813-b1df-af613fbdbb96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 24).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e7c6593f5624b7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf97b349-afa6-47e1-a400-c14277ff61ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 24).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3eb91a06f6df57d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd26a204-904d-4634-a20e-1312de01fdb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 24).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f101284454c68419_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dac442eb-cece-4a58-9235-c903aa3148d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 24).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'aedfa999f7ceef1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48234f36-d961-43e8-8bb6-ab3e151f0a3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 24).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '70f681aea9e4c66b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ec6ac5f-6f3a-4d3b-aca8-26bfb8c0c5bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 24).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9c609f75e5ce663e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0736518b-590b-429a-a81d-e7114efd6b26', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 24).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '837928406e8387ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f71cf45d-9f55-40c2-ab2e-79fc441f966b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 24).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fa98b876072afa01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b5a63d0-c60e-4b03-9ce4-b4a10f1df69a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.113.248.0/24 network (variant 24).', '[{"id": "A", "text": "ip access-list standard 10.102.210.0 0.112.249.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.102.210.0 0.112.249.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.102.210.0 255.60.7.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.102.210.0 0.112.249.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.112.249.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '709393d0746061a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed799b35-6fa3-4b88-8e89-9bca703850df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 24).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c11618c21f69dfaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6009ea59-2d6f-41e7-9a6b-6de8a87ca6c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 24).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'de3e22db900c419b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb678c80-0314-49ee-8cfb-4daabf913971', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 24).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ff4da11230e21f6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('849f27c8-5628-49be-9cd6-107bb455a256', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 24).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '404328d92bd8b219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('336d7c7f-c9c2-4114-a020-a56c6e9f43f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 25).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab749c014352ce0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0081763-b5b9-4e66-9d96-62585c70d6c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 25).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f49e3ac8f6f6c1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69f9e26a-f1a7-47ac-918b-24feff690909', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 25).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e2d8780112884ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c2e9077-4d0b-4ca6-a7e8-f5b8ec2a0d9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 25).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'bd55b00610a7ffda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d1954f1-0794-41ea-a2d0-92db6e627d33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 25).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '484970d689617930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b7e65b4-1c0f-4b51-b1f4-4826d49d99a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 25).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ae0743b9d4fc777b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed20c2e0-62d8-49f5-bdf8-dd3a3bc8cbcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 25).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e9661bc96a3a7727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9f40981-2bec-47ad-ac11-2bf1504e74ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 25).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b24735302f272f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef268cd1-6367-42f9-8780-b5b4c7f09467', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 25).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'adcebff618e1ac14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c51627-04ff-47e7-af17-8c21b2f63cc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 25).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '9059788c02f149ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e00033-59b1-46fd-9bb3-9a3b224ad2ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 25).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f99f07870319656d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6686f64a-a724-41da-85f1-633e07e63772', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 25).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f1151ef376b26f22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daec8a87-d843-4eef-b47e-4e41b057d985', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 25).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '866fde103cd0258b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e62c21-7d21-48f6-997f-6da5529277d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 25).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cfe8196558c9ed88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3624070-72d9-428d-a7a1-c3e94fe00d69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 25).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1f65037de60f0dea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b4cd3ee-1e1d-4d75-b6ff-0b5cee1be835', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.193.0/24 network (variant 25).', '[{"id": "A", "text": "access-list 1 permit 10.76.23.0 0.71.53.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.76.23.0 0.71.53.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.76.23.0 255.14.156.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.76.23.0 0.71.53.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.53.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7ccd524caf78c14e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7925365f-bf14-45ae-96bf-3bddd0a78af2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 25).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '45a5d4cbb9c4dbc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('947ebed2-a13c-4588-b362-137109f61c77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 25).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9b074a7828cc3cda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3912ae2-6f6c-4c0f-808d-87421ba2c77b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 25).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '16cdea6b74600c26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ce58064-38b9-4392-9ff8-81156f66214a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 25).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '349935960be2e029_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7de7140-e6ed-4bf8-9d71-195337307ada', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 26).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c731eb83055e0e4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ab0f228-08b1-43ad-84c2-796ea46b3d6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 26).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3b54c474f7e6c076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdb65e34-012b-4a9b-bd85-c63155c96bbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 26).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3bb4356dd5b9ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a09305aa-756a-4722-bd3a-2cd50e5b58c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 26).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '30d45377a921ae6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fea92393-4a9d-4846-aca1-b5eb341e0c99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 26).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6ffbc93ad2285702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('160316e2-950f-41bd-8516-d642cb65dfa6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 26).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '480d21b96ae4222b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e19e81c0-cfdf-4f95-973e-cf3dbc622478', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 26).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3c727bcbef65c1c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eac8b1e1-8690-4324-9b2e-8466fe62ef29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 26).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '32a84f34dea409d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713d3f0b-874c-446e-9212-9f7f95849059', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 26).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0dac1b490da2502c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4969d79b-0ff7-40b1-a0ab-4b8fa9c00673', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 26).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '081fd4bf07a83660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bca948d-8fb2-4b9e-b870-344a3c1d0306', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 26).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '62106b007321edd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62bee2c1-7a94-4d65-9265-745c78d27b4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 26).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b96aa983e536e2c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a46f93-7912-436a-82e4-f818145b214f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 26).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c9c270b06a52d13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cdb63f7-1db4-4489-b87a-70fdb5765c60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 26).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c8bb3630f21e6396_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf2e41aa-a72f-48ae-b5b0-f23479ab8f6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 26).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2e60f0fa12a48f7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a5de7b-d9f0-4569-94e3-c3ca5ffbcb69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.40.0/24 network (variant 26).', '[{"id": "A", "text": "access-list 1 permit 10.64.49.0 0.239.101.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.64.49.0 0.239.101.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.64.49.0 0.239.101.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.64.49.0 255.86.108.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.239.101.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd719660e9cefce57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d371b1ce-993b-4262-91c6-e0a3c23c1dc8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 26).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2bbd3c237a5be465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0802d0f1-0db9-42c5-b52a-46f11f74c568', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 26).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '81f7f9886ef59793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdfa074a-db3d-4a1a-bbb9-c207f037612e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 26).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e4fdd0feb51e4c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aba2f262-f8ea-4b70-8873-35b886724a7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 26).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '64d7b75a5d35412f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b181a945-2e14-49e0-8aaf-28b636cc20e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 27).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8b712efc8abf8d52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100802ca-a3bd-4492-a7ac-1ddaa97597b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 27).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8ff46eaecef4e366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eee93f7-2912-4ee4-ba36-f7d2d1cf4e75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 27).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '90daabaa07720028_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fb5f6c7-b842-4926-85af-9fd7cbcd5983', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 27).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0702d04b64eae3f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85ff6855-da54-486c-bf22-ebdadb3df5d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 27).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4158d2f457c14231_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efdf0eeb-3eca-456d-a866-a6eae81b3cfa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 27).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed4f71f4a643f8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66f23aab-1506-4138-ae8e-f9780c0653c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 27).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4689202e6d136d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84f2219a-7146-47ae-a670-2be024111170', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 27).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '685609eca6fd0779_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cef54a2-4604-463b-97f5-b564736f7a19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 27).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e63cf8bcb2e7dc27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8579b584-3c3e-4377-818c-4adc2152c5d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 27).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8f77b27369a69393_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fec639c-cc70-4046-bc67-29a1900018a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 27).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '02e6aa5f983e2661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbf7beb5-b2a5-4b9b-953a-0e19085f9c7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 27).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a111f741ff33e441_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8bdc439-bf06-4064-8444-7603ac73f5bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 27).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '042047104f5bfc0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03fc947e-486b-440f-8bb8-f6e3b882f9f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 27).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '29511922b2dab800_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d30daf57-87e1-45d8-8786-90f8494b1466', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 27).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2f7af6e292c82be3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfeb21d3-4d39-47c5-8cf9-dfc2afefc4be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.238.212.0/24 network (variant 27).', '[{"id": "A", "text": "ip access-list standard 10.56.12.0 0.94.189.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.56.12.0 0.94.189.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.56.12.0 0.94.189.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.56.12.0 255.27.141.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.94.189.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'eb09e3562630a08d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266672fb-dc43-40a5-a817-6ca1f725715a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 27).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2c4244a336691454_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c6026d-f114-415a-a350-cf5d39590df7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 27).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '580c3177c9eea558_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20ba6ad4-9cf7-4555-ae12-bfa94f9266dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 27).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6bbdcb4289fbe671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('274c5624-6d80-48f4-a8c1-8157bd7aed87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 27).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b9e9d2f0e624cf5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcdae5ef-4555-406e-9cd8-d74b864bd9b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 28).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b65803138c737ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('524f96f5-58d2-4616-b12b-6f209e226581', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 28).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '16a31036ae9a45d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d50add4-4c82-4b1d-9ce0-780f71b356ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 28).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '80fe558e7f99f6a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fabd1ee5-14c9-4fa4-b4d3-30220e764a89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 28).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '4809b084ac2ffc92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45826162-08c7-4d91-bf18-5ce1bf07f829', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 28).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2c2f51b440a3b263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2da3088b-23bf-4b4a-80ef-ee67af3942b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 28).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8aeb908173b4d96e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02bbf6bc-f7b6-49f9-b9bc-4fbbfe7e316c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 28).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd5b567b72c48c4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('245edff4-738f-4b3c-8ee0-6699ae042bfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 28).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '831b281fd70a5741_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aae1003-ca11-44c5-8675-409c106d4405', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 28).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b59471ffb5cfb273_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fc87a0f-3934-4fca-84bb-2a00603461bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 28).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '67bc10045a8077a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd453c04-9b23-4829-a5c3-cad274c1d7ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 28).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '096f50f867f7d201_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25125e2d-7c54-49f9-b187-92bfc74f87a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 28).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3573eb182cb1d17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a119b042-dd78-47ee-a2fe-05d45a922fa3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 28).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '78b51e7bfadd7357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('586d7165-02b1-4e6d-a8d3-9de8d33075bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 28).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '91accf3ef5e9152e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b6cf4c2-5ba8-43cd-ac91-bc667fc9a128', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 28).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fe08b6ff29e786f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7deb83e-b005-44f3-acca-6344dc049e9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.229.156.0/24 network (variant 28).', '[{"id": "A", "text": "ip access-list standard 10.204.101.0 0.109.58.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.204.101.0 0.109.58.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.204.101.0 255.8.87.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.204.101.0 0.109.58.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.109.58.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f07c8f98bd5bacd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c80c5bba-3a93-4eb7-b218-c3900a39eb54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 28).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '385674ad56c04759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38e4edbc-8dbf-4ae2-82dd-e55edab00e07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 28).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e3ab0e6263c70bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5585c4a-d6db-4eeb-ba04-02dfb711d35d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 28).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8c217a2827563fb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cac0fa53-6871-44a2-bf15-082bbabb7b69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 28).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cd16a8d6d046b33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3356823f-5d8e-4824-b9e4-2c211d29f423', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 29).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e544c01f4661f877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5bc2020-0c15-4dab-b77a-b1c3c2742713', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 29).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1c1060dc059cc0ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ca90f5c-227d-42d7-b91d-b2ac85bea165', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 29).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '3b0dbf60ebdd9d95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25db6e01-3daf-4eaf-aa28-c256549a341a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 29).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '12cafad7a08ff423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7854b12-6d78-49b1-b3f6-fcc0d7824fb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 29).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '12e5881a4d4bce70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a17f8ba-8e60-4b92-9d69-14be4ff849bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 29).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6d34095cebb8a34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea3194aa-f674-4ec2-9498-272b5efac27a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 29).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0261d4adc58aa4c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8a26599-7270-45a4-aeed-7c1a0cfce762', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 29).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '09480a51cbcd1785_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3c5934e-5387-42e1-a208-413336a7a96e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 29).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7294ae0ab09e9cd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4108364-61f3-4c81-9a32-c9835cf92943', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 29).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '717d9ab366bff1dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f086098a-9a43-4629-8004-e748010799fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 29).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6f4f1216ef0a090a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1752b8f-0926-4ebf-80e0-56b25c144053', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 29).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '00fc6495f06fbacf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d884ac1b-d474-46cd-b30b-0612d7384678', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 29).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1b143ad6be578838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd59577-4cab-44cf-a3af-e0a167a75d23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 29).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8e6f8ae1f8613ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5cf9398-09c1-4781-bce2-e8663d7475e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 29).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '47db18534ddb0ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9309d41d-0780-40a1-9f67-baef8fccc603', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.25.153.0/24 network (variant 29).', '[{"id": "A", "text": "access-list 1 permit 10.16.120.0 0.62.217.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.16.120.0 0.62.217.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.120.0 255.66.246.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.16.120.0 0.62.217.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.62.217.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a45ed3f5d1375c6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8591c96-79d9-4a19-b5a8-8b945e1eda76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 29).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '401b75f946c89c93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80772db5-6599-4b87-b361-60e5b9eaaaf2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 29).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2913f9b01cf18377_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caf43a04-af41-4055-baf7-c850ce68d115', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 29).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '95ae95bb74af9a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d755fce-d237-4290-b651-f41c822a83c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 29).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e3ce047bd01bc707_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289efd34-8492-49d9-991e-77b52a45c6de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 30).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a001afb761087c14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1851866e-39fb-4b26-817d-a5a857b31527', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 30).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab5eb6b6f6214043_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff1fce1-0a7d-4396-b6e3-699c5e2758a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 30).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '91a43dfe06afbc53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d1fa4f3-d67a-499a-a854-30eb0e9c3d17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 30).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8fd58616d969dbba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5f7ff45-e932-4b82-ab38-44aab000fafb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 30).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e90417851a9a7324_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('020628d4-5417-474e-ad67-ed217d00fc4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 30).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '56bf6414faa1154a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6be71093-bf3a-4f0d-a50a-d70823c93f1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 30).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8139b4e1f92a5d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46c4380a-3753-44f4-9acb-54851f548027', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 30).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bedb04f8c581752d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f64626e5-6b91-4194-91cd-363c63d27bf4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 30).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b456aa24493ae59b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46eb90d4-a47e-4481-889d-4c907b472a7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 30).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b1d40d6635a2fb7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c93dd6-787e-46f3-8248-14cb8fa8d299', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 30).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '97a3a2b6a02d701f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a6222d8-f17c-4768-9a4f-d7985da4265f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 30).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'cc68f0c70778af4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e74ff72-6c6e-4d82-bb00-8abe5a8e1b2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 30).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f2883aea13483d6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fdbe7a6-3ddb-4c89-a1ad-970b73c01ee5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 30).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3f419e68352edb9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a680ef-2aaf-418d-b649-52281e9d8a0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 30).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8421452a9dad21b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcbc2e19-f09c-441f-b791-00429ddab6ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.58.114.0/24 network (variant 30).', '[{"id": "A", "text": "access-list 1 permit 10.236.181.0 255.50.130.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.236.181.0 0.71.184.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.236.181.0 0.71.184.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.236.181.0 0.71.184.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.184.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b5efe9175ae6a381_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f77d23b2-a255-4106-bb09-ad0de1c0084b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 30).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f127ce64aa0260af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53f2ae22-7ef4-41f3-b366-46740876b47f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 30).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'faa66abe6bde8563_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8f29093-0460-4bad-8aa6-2c84ee09b94c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 30).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '61d927de33515165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e5e64aa-2eaf-4b88-a179-bd270ec5257c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 30).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0be001040ea85288_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24085e83-7266-4393-ad65-eba0c9a5bde0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 31).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f748a2e50075be90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('862b3322-532e-4825-b803-85488a66ea05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 31).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '39f0277f8a2f94d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e22bdb5-5282-46c5-824d-c8d0345eafa5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 31).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9776e7c3eb17ccdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c3d00e6-7183-4b70-a005-076e18a27e2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 31).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0e9dbe9fa8ae544f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a91e071-d90a-4a0b-bee6-7846e041ec81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 31).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '56b67aab3cc55430_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('002b9e6e-3954-4fa0-93ce-a1c4457f0a6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 31).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aade5f24cb64c7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7947990a-a90c-4e48-9e23-4e2d9ed61b2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 31).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fa1fc6b2d0363f8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e0827ba-ec8f-46cd-a2d0-a6f70735fbd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 31).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5d496dbf4feb1ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1684ada-cef1-48fd-8e86-6e937a7d7f55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 31).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '46cb571201787c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23e167b9-aa4d-4a87-8c23-2e7c17378e7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 31).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd0043b7c4b1bf765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756298a5-e33a-4d47-9603-b7ebcccc57d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 31).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4d4a9d0ca4c0807c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('348343c0-ec2d-4ffa-b2ff-42c92bc76f62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 31).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'cb2af4f3158b42b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88c3eb26-bb0f-4989-9972-55f9c0158717', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 31).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1fe848fc75be916c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ce47f1-9e91-42e1-86e9-8c8c4f26fa9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 31).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8b6459822e05139a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97fe1b9a-879f-4378-945e-96933434b980', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 31).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5fa0d7f2bfe12aec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d766c7c-d3db-4570-8ede-dd5422715303', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.74.5.0/24 network (variant 31).', '[{"id": "A", "text": "access-list 1 permit 10.227.113.0 255.57.215.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.227.113.0 0.255.244.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.227.113.0 0.255.244.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.227.113.0 0.255.244.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.255.244.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd12aa83f573df18c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05bc9974-4a1e-4948-baa6-39710134d097', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 31).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '66a54eba627d59fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aec7617d-df0e-4c43-a8f8-b9e6f86dcac1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 31).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cf3aa1101cd427ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28dbda59-8ad4-4fa9-840f-e9c1bd371b9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 31).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '18b17a37b0a88a48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec015d41-173b-4798-a70e-4b4f3f04af2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 31).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0a33bb8bd27d5b0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('679d5227-1eee-471b-8789-3c7c869531d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 32).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9dfe35ede4745b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7af650f0-6d0c-42d3-96d0-3b399528585c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 32).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e742a2ef3cf00343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cd974c2-5eed-4a79-a309-0b129a4c2d5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 32).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8ca5c01934761c80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d069741-3007-4a32-a61a-2d5fc22a4a4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 32).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '703c116d302cdb77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1677ae9c-9dd7-4327-9abd-2a0562707f7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 32).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b9cb51883dc383c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4956435-5585-4d03-8b82-c43b2737465d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 32).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3c13a0cb6caf0554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e09df31-7580-44f8-87bb-fe50f553c6c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 32).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b90900263d4a76c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97ba828c-5ad5-4067-bc7c-539d0c5887e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 32).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26668e4a11a0d72c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('550388f9-df72-4b90-aa2b-06e5b6cf93f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 32).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'bfe03639bdaf33d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4989fbc6-976d-4aec-aece-c4dc8611aca9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 32).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c0a0b0f06a8f75ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a0073fe-e14d-4056-ad37-cb21ec85282c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 32).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd8c12b88df383198_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6653384e-1c9a-4eff-ad80-11c42030c0f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 32).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '054a1e4e3a090665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6edcfb46-4a3e-4d52-95a9-340e5d48915c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 32).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '38f760f81a22fca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('517de0db-6be8-4093-8dd3-282548b2b3f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 32).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '887f6d855fa41205_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('188137ff-6ad8-4438-8fb0-fcdc1ee2d2d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 32).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8b20a3cca95fdefa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d35ccab-52a1-4058-bd3b-97a779cbe7aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.212.250.0/24 network (variant 32).', '[{"id": "A", "text": "ip access-list standard 10.16.93.0 0.215.150.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.16.93.0 0.215.150.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.93.0 255.156.137.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.16.93.0 0.215.150.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.215.150.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4d1ef91c71d41a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52f63019-4cee-4ca9-bd51-9686aad78195', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 32).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'db5f3f5cf0f34d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523f3456-a293-4b26-965b-02cf9fae4ad1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 32).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd41c0254d9d5a77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bbbca10-3511-405d-9d2a-92d2fbcd3fa3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 32).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '09c258af8428dea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cad3f476-3408-4721-9434-9fbed32c001c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 32).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4e0965bd0c19464f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a59cb24b-b8da-4338-921e-d67f54333308', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 33).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5713d53a6635cac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc55b58-2a20-4868-9136-ea211f471a14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 33).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e681178d51a576cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8cf5d01-1811-4b13-9806-f591a4cbf9db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 33).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3cb73d8e94154cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fccf886e-a8fc-4366-8bcd-62dc6ef1fa2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 33).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5cb9cf8c4f7eba26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c33dbe0d-30fc-4bc1-bdc8-651c2b7ff804', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 33).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4237fe6ff5a6c0e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9cadb75-4dbf-4576-9f90-32eee667d75d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 33).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5005564f076c7557_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('562fdcc6-eb1f-4306-824f-1962c28cc88b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 33).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6b3f3b1bfc8bb169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08b380ce-dd8c-45fa-82bb-c41d4983fcb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 33).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5af78e8f063bacfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7d570de-23e0-4ebc-bd6c-23284610fe28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 33).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9af3e6d0220b5e4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af0840f3-c4f4-428a-b09f-844e93faf9c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 33).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd911c67facf189b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87b81e07-c4b5-4a22-aeb1-34dd5c202771', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 33).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3e9fd11cb17f78f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('286e297c-c129-40f5-8e29-20bc0e7360ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 33).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2b3f72e57b51ece8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68393204-e51f-4d4b-aaa9-6f147dd0da6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 33).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4281970bd40dc8cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e315cfb6-c56e-4baf-811c-16fc38c00a95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 33).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5b1c4e17161c7c0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd5a26d6-6a74-49b4-8e46-1456cf66f19a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 33).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b676868a0fe6e62f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41213f55-fe75-46ee-8f4f-03707eca6edf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.39.62.0/24 network (variant 33).', '[{"id": "A", "text": "access-list 1 permit 10.73.221.0 255.134.255.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.73.221.0 0.215.153.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.73.221.0 0.215.153.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.73.221.0 0.215.153.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.215.153.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7f9269694681b1ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ffbb0b2-f564-4a9e-b6d4-ef93b5f49706', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 33).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8e144dc2c10fa812_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dce8722e-fba6-4bd9-9c3c-981405fcede9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 33).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd50fa3e16ff7f4d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fff18a6a-f4b7-495a-9942-bef2a652da4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 33).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '56cdf8ffb5cc27ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cbeeec5-49a9-4748-93c5-315fc4f242fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 33).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'a3e0e51ff5726d15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('017dd072-6b7e-4a2e-bceb-8f46a3bff029', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 34).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'df7c61c4bbde6f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be45e13f-1266-4024-b1b1-4babd23cb5a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 34).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c8b3147098e43d06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a2ef60f-d635-4446-902f-7fae82a2fe18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 34).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '86138faae5d797b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625dcc54-0924-456e-9098-2e1906e9d090', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 34).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8d5619f57980d775_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d4dc521-3389-4ed2-a738-7ba8e6a3d1bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 34).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20ea9ed80912c7bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8713a68e-0b52-4652-95cd-d518d49f5acc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 34).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8de37798f7df2065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d499b47b-8272-4b60-a265-3eee3335ec37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 34).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3465b425489eb00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e9d0c9e-6c0d-4585-a9dd-ef0be15edbc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 34).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0896b9e91cbeaded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60da548e-219e-4512-acfc-207ed88ba624', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 34).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a55dadc50deb20de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b9b9a65-14b4-4a6a-94f2-380ba2a2c710', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 34).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c23706257dac0d13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b042caed-419a-4cab-8bc8-cbfa78b880f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 34).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c362e610cb1081d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84bc6db0-5732-431e-a607-b56b2f6c820f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 34).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '966d653382e928bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52ff778-3e05-4f1e-86c0-21758601eeab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 34).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9911ab95162eabd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('934529fc-1e65-4eb5-8ece-68119dc314a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 34).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '05f6602ef1ab7659_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37e619c2-25e3-4c75-9fdd-0c3d9aca0324', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 34).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '714e6dc2eb87eb12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fa8e24b-b1c6-428b-8996-edb874e24fa9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.187.140.0/24 network (variant 34).', '[{"id": "A", "text": "access-list 1 permit 10.61.16.0 0.129.27.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.61.16.0 0.129.27.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.61.16.0 0.129.27.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.61.16.0 255.27.127.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.129.27.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '49973b4a49ba8bdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f11e5a-081b-405a-9db2-be1dc0c6e607', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 34).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fabe7579e406762e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0504a91f-6a62-4394-a948-dc83650024e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 34).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ca0740fa8024414a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edd87def-e2a9-448b-a8f3-65b7db4ad519', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 34).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9f675d7d26d495b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93b0ab6e-95c1-4627-9f60-055fd3d50716', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 34).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '7db3414ca0a00e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86c6777f-468d-4ad3-90b7-71f9f92f05ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 35).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7b8566418dabc2bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e47dd93-704c-4119-907a-ded334ac3201', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 35).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '97c376beeab7c003_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('060caa6a-3ce9-4015-8546-2c8d9a21d982', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 35).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8066bc178ad61a2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a49c4d99-0c64-44d0-8154-1a0edfbaebfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 35).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9976fabe1b86c2e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb26d575-ec50-4fff-a50b-755cc6961870', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 35).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '01cc17c6b44e8d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('363475ff-be36-4fd0-9743-c5999b109b15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 35).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '29ad41bd49a8f3a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84895bce-0686-41a9-9f6e-ac1573da18e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 35).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f36d937d7a351968_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98b4ffe8-17f6-40fa-bd66-97dd3908e43f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 35).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0d1be2f177ecfbd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a84d570-9349-482c-8b94-b4a38eaf6629', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 35).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e40eb50f9696638d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb60d1cc-8c19-41e9-b276-e88a1ae56d5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 35).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8aace2142d41e1ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d01fa28a-9209-4c77-ad0a-0ea354876a87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 35).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1ff47bc63119bf97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab57392a-3c0d-440b-8b66-7ca296ed5521', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 35).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd54fa9bcdc9aae42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a9e822-3f91-4302-bfc0-0cc61df7e508', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 35).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '48937edfe65f77b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c3db2f-e724-4955-bddf-226daff7c0d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 35).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2bd67ee38cd8457e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62a92082-2572-456a-aae9-52637cccb562', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 35).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '54aafb8cfe858f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac6dfbea-1b80-4f71-8d1c-72e7361782d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.98.5.0/24 network (variant 35).', '[{"id": "A", "text": "access-list 100 permit ip 10.14.23.0 0.213.235.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.14.23.0 0.213.235.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.14.23.0 255.158.62.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.14.23.0 0.213.235.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.213.235.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '36adbebb147a0da7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d47d7437-4341-48f6-9f30-3a36b713afda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 35).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '258b5471fb4ac647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d87497c6-052f-480b-94c0-bf3c5a559d79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 35).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '95fb17bc673007b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83db99da-ea41-4b77-b06a-49c9847e767e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 35).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2712cd0eee9171fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13e384c5-ce30-4ef8-a688-83976fc482a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 35).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3f40eb2cf943c229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf7f228a-0250-4f4d-8caa-c3e1b62dd492', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 36).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '31e9973cfc10a70b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4993db4-a3e9-489e-9ab4-90bd224f1336', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 36).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2b95754e8aa158d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ddf7f5d-ace0-4a19-94ef-53f48cdcdea6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 36).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f94f70c9a8457717_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc351690-4800-43c9-9523-2fc70f17cf71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 36).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ae70e33bcaae0813_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25ed4945-7712-44d5-becc-284fd62fc8f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 36).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3721bf5fd8737a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dcc0c46-88e1-4a99-bbf9-1fcd3496c17c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 36).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9b5f28d70793bfb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f7f28f3-2cc9-4179-9ab7-f903ee63ea3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 36).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b0648e4a9de4faa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141451e2-08da-4bc6-85fa-e7f8f913bf44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 36).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '105dec48407f309a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f066d792-e6e6-4d75-b683-bed9e84b8769', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 36).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fedf10797f244886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4137821-f00b-46e8-ba17-f44a8e49e8cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 36).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b41e882a24b24a1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('064cd1fc-d4e7-4a2c-b5e4-85b9d1e86758', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 36).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e726e71fe2165cc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ebfdf47-0632-451a-907d-240bdd5e7ebb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 36).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '87b8f54de8dacfc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638936bd-9717-47a2-a479-b6fdc85a0db6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 36).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bfd4b05afab2e8aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10ca90c2-f8de-46dc-a75e-9e3a1cf119f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 36).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7bda527d5184c2d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1466df2f-d7b0-4972-b941-33bbb5766ec7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 36).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e7623e2923a5444e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b375a05b-3fc1-4ad5-8669-6c80d33f2244', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.43.19.0/24 network (variant 36).', '[{"id": "A", "text": "access-list 1 permit 10.124.12.0 0.120.191.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.124.12.0 0.120.191.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.124.12.0 0.120.191.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.124.12.0 255.101.172.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.120.191.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5073543175ccc344_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0d3fa9e-3a41-47aa-ba96-bd1e853d4661', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 36).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2c348bdbb8839a00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69ccd909-ed6b-45cf-860f-a8498c0b898a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 36).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2c8bfa89598999aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14e22540-7afa-49d5-aae7-b4b80f7f800d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 36).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3e2b15e29bf7f22f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('061b39ff-5926-43d9-8c73-ee0dc21b351e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 36).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4451b776bed87b2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8704a054-5b07-4f62-bbf0-d72e0b962001', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 37).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '075cc15057a54254_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12c9456b-6610-4462-ac2e-575674a40713', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 37).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd38f612a40248876_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa296044-c644-4ca9-84fc-57e63278632d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 37).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a31353bb89f3ccfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be1da9a5-6e02-4739-b26c-506601751294', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 37).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7ee1f9975f71ecac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abc2e916-eac9-4dd4-9b81-998449895a5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 37).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3dbd44c18b905383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b58962c0-be3b-4149-96c6-2ea66be22fdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 37).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '602633aa8ba2fff6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d4a8f2-aad9-47e0-ab72-372132e054a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 37).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '63afb8002d1cfd7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b8dd2a6-b127-4e61-9d61-9df36bdf2f35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 37).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '02ba13c163ecf1b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25cfe254-0dee-4b40-83af-572a4a903b91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 37).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '569a63120c73e8e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efa9aaa3-a2f4-4bb3-b8ba-00bf2c9a229e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 37).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd054947a61578150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f58a8e6-6b43-4030-ba0e-4c56fd4395fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 37).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '466f693f916ca485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a47d11d4-3361-4da2-9d35-ffd0de070d0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 37).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fbc468e7e6e0f555_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('834c214f-a9ae-44c1-a716-4ad38066275b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 37).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5a7c91d79c2bc9fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cf294df-6830-4d77-80bd-d965129a92cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 37).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a5e54e968aa4083b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18e800ca-1495-4c19-992b-cde8c5f773a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 37).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17cd57181dee4df5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5a42fd7-a8fc-4090-88c1-d5e487ce7829', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.251.185.0/24 network (variant 37).', '[{"id": "A", "text": "access-list 1 permit 10.149.76.0 0.109.182.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.149.76.0 0.109.182.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.149.76.0 0.109.182.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.149.76.0 255.210.97.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.109.182.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4dbd1ff4b6e84f71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('294b4ed1-8932-4032-b2e2-c32b2759cbfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 37).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b6fd70026b93cafb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ea3b478-89a2-4ba1-a9a0-7136c0623faa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 37).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c9f993c3f31f79b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb2e8657-8738-41c0-8475-fb825d44acd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 37).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'db0184614422297f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1ebf9e5-8886-4db0-8f12-02669bd5cf4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 37).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3c6b2e8353da269b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6d1a9c1-8f65-43d4-b9c2-eb28842b58bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 38).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '14744b3b2aff2b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8b80e7f-2798-4aa3-8350-fb31abfb0f27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 38).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b8f0880b63ce6fc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6fd4789-235d-4aef-aabc-1db8783ac649', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 38).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '634c70a4961d5244_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d6b947-6d61-40c3-adfc-e630fb9705f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 38).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b88d45cb57b8d682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e0b8852-2e27-4cdd-ae07-d1f2e0b3c629', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 38).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4adc55eeb06b826c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75386e11-1468-43bc-9371-47421e0369d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 38).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1101f9b7f7721957_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c6b10dc-b920-4fa7-9702-f333e1c851bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 38).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2563e5eafae4134a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('811293bc-b11a-4f15-8b07-6dedc60a81c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 38).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1eee3d5fe782cc79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8648f9d-a6e1-45ac-8041-48156214a625', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 38).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8c24061c0b6c8a0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8026978a-a6f1-4349-9160-0f22e70e4406', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 38).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3a11409c8e80d94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19ff4f6e-a5db-4802-ab72-0f05a94048e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 38).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '11286c7c05a8f738_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f70e2f1-a638-45ce-819d-b2beb99a3e85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 38).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '732cf34c984305fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebcddfe6-803d-41a3-b89e-09d737997326', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 38).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1c7f8538a3a5cd8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68524042-c072-426c-b021-0853616ba02c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 38).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7bf4065595ba39b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d659da42-c3c7-442c-ad21-8a41b08fc156', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 38).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fe0834a5081c81c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f51ede0-2efa-41df-8132-e45b2c48b4a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.115.213.0/24 network (variant 38).', '[{"id": "A", "text": "ip access-list standard 10.56.74.0 0.78.175.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.56.74.0 255.224.104.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.56.74.0 0.78.175.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.56.74.0 0.78.175.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.78.175.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0544c92c44e9557e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2dcdd76-6ae1-4f3b-9bb7-b8e625b41cbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 38).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '346a6637a2cb73d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c1dfd27-3328-4002-baf7-8820277deef7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 38).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5c5d50c0ee770cb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27365ff8-7a61-471f-9ec1-1f1926e07b2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 38).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0379f893a649ce7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4cd190f-b78f-4799-87b9-18ca826470ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 38).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b2ed086707805011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('799115e1-2bba-4cf1-954e-1da1be033eb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 39).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0d2b38e04557fc6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b57ae35c-a3cb-49fc-b4a1-1d39717510de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 39).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c62f906affcbb7da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a4ff4f9-6712-4e3c-a976-21e407b0483b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 39).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c985f4e929d54805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adb316dc-c910-4ddd-aec4-ae4c33f35955', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 39).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f75e435ab7d6e924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0346f80-d11b-469b-a1a8-dd0172b1a03f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 39).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '570f9a17686c39ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e55e0516-3fee-467e-88ae-92e06981559d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 39).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '820c6f0ad79d8d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b129293-d42e-4a88-a269-14b216e796ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 39).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e79bf2d0b2cc1d1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a03be43f-48ae-4d16-8d2d-161e2f108a18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 39).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4359a2cc2d6f4788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab18f462-7ed7-4c88-8940-f90d3db4ee25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 39).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a9058df732bcb1a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba47638b-05ce-41eb-be14-5dd4481a3f05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 39).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '99f44d77fd45f974_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e269e9dd-dc68-4522-bde3-bde9de3eba07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 39).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4afbc9b6c0a070f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ea4e153-905c-4e7a-ba9e-4f57d541396f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 39).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ca22c1852a0b42b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efafbfd6-39b6-44d1-ad41-55ecaf441955', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 39).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '17893a8c6da63c03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80a7b050-7298-40fd-b211-d42c89c45452', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 39).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0a4734a8d6be78ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acf9ec11-d2b0-47a1-8779-8719ecb57d58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 39).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1d24afedaa58b7c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca059073-07d6-47c9-8cba-f723b9549b1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.196.56.0/24 network (variant 39).', '[{"id": "A", "text": "ip access-list standard 10.115.52.0 0.120.147.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.115.52.0 0.120.147.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.115.52.0 255.60.101.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.115.52.0 0.120.147.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.120.147.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '481660f99001633f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23a1ce82-366b-490a-90aa-7a60056105d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 39).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6576b81fd6951893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bcc3d65-a5c5-4700-9b6f-c4874c203801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 39).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '359f8f8284747e3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46a6085e-77ac-49ea-ab76-ffd19c81d5f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 39).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd04de779e9d7620a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('555423e0-a38f-44ec-ac25-053e1d9412ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 39).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8e91dc930fa723b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb02db66-f823-4e24-a75d-8bec99f22e69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 40).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '429a43e4d9a813d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('482edb32-4e43-4a34-9cf4-72c004d698fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 40).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1dee1e158c309beb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2169a7a4-dd1c-4330-976e-90f3af20abdd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 40).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '12b9f4533fb33a1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3452bc42-0d84-4087-82ba-cde596a44766', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 40).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '85abe80c2966a4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54314380-a5fc-44ea-baa1-576d68b5af03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 40).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd53ebc8be7da549_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af890508-224e-4f99-bb66-69484a7df3be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 40).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3ecb8739f0aa175_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2b8d63a-4100-4870-b787-4826917b7415', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 40).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9dc45d94f2505a0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f369265-65cb-43cb-befc-515fbb61610c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 40).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd540dd6fccb6424e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('342cda27-ee11-4516-b693-273f657f8bcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 40).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0a4e1b01f96a95eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be952c90-c142-4bb0-be06-d76f1365144d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 40).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f2a5851d8a140515_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bcf7bba-2097-4c40-ba45-4cca8bf97cad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 40).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a0b195bd229708d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47df3b70-2d8c-4d1c-be79-671973829715', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 40).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '91a827958cd963d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2c803cb-9c21-42c6-a90d-25c217c34391', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 40).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fed798095b010488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('880668b1-f9aa-4ace-8581-97d2bfad9f45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 40).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8f935d59d301c303_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63e4784b-cee2-4322-9193-c1792b7f07e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 40).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e9c4d50a5f371179_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e22a0489-0d5e-463d-9331-90d447466c63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.35.8.0/24 network (variant 40).', '[{"id": "A", "text": "access-list 1 permit 10.50.54.0 0.91.235.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.50.54.0 0.91.235.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.50.54.0 255.69.86.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.50.54.0 0.91.235.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.91.235.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6f56cbbb590791cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10745204-576a-45b2-a38c-b28a007df557', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 40).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fed89d7eb6196052_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af48b656-37fa-465a-a45a-18a0d10d07d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 40).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd04eb942c9b7502f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b41ef51d-723c-496a-8104-525f45c6d963', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 40).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'af0999b22c4ebfb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44c2932-6b34-4368-99f7-ca83c1cf53b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 40).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b7ee1e0ac86f3caf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba5d2638-bb8a-4483-b6f3-60e90f53c8da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 41).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3693549d32d26c35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f1ef2f4-479a-4155-abc9-2ef65dec82e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 41).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fe5af52ce63d0694_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c81b74bd-b29f-4d4f-88fc-1a03320247f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 41).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3359f3d0f4a3c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdba8ec1-9419-4ae6-a8e9-8c014efd0853', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 41).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ac92221e115be76f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6055adc2-ac90-42eb-906e-44a2acef34a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 41).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26593b48884da934_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37fbc3c0-3dab-40ac-a51c-a43915e9a382', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 41).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b0e312db17b0eb29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c289222-119f-477a-8b9d-cf9377d10598', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 41).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cd5f90324380248_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cba36fc-5dc8-4f61-88e5-f5cffb3bc152', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 41).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6afb1adaaf26be09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c88fa2dc-3d33-4408-969c-495ee687910b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 41).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a95ab4467ab4b0e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb84c3ac-cae2-449e-b258-ae0cdb4c7df0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 41).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'da4ac2f108109aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c84c7d4a-1d78-49e8-8b0e-53f13545f60c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 41).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'eb7b2b3e2dac0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e6b0c4c-93ea-43ea-8e5e-70a206074d5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 41).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '13233edf417f8016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b827bb2-8357-43bc-a90f-1c65565f65e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 41).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c8cec8fce1a14b4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c08e9c73-8968-495d-a4d8-da6db77fc037', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 41).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '19831f77234daa0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93be988e-fe23-48f6-b41b-ba6f4075f7f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 41).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0399657690f7913a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f6a65f7-2865-47a6-9329-708f76aefc6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.152.59.0/24 network (variant 41).', '[{"id": "A", "text": "access-list 100 permit ip 10.103.225.0 0.69.229.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.103.225.0 255.201.220.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.103.225.0 0.69.229.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.103.225.0 0.69.229.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.69.229.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7a081bafc9351ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d00c465-2230-4818-ac39-ab18a7ac67e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 41).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '088794ff24452e21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12fd32e6-6ef2-4eb7-af5c-42eafcd34765', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 41).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd86ecaca050c9a9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f456ebbd-42c9-4b39-bea8-6c46cc1bd041', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 41).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ab362dabd6176fe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3981bfc-aa35-458f-a296-505aebc7083b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 41).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '279929484514afa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6644f443-b09c-436b-a187-021ce22908d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 42).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '44e5f0027744fd49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75f4b467-c657-4c80-a092-902a3b4d36ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 42).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ec7516a0786a618d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e52541a9-5ee8-479f-b2a1-e1609e2b2271', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 42).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5e82ea614c7ce02b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d01c43dd-4714-40c4-8eb4-91944091b9b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 42).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c8115e47b0b21dbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('027626d0-fe4f-4a11-bc7e-5394ccb203ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 42).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '963ab150847ef559_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c23ba4d-ae93-42b3-b01a-e8575e3cb67a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 42).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c278a48b6bbcee78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('681f2dd0-9f36-46a0-8c6f-c8055ca82bfb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 42).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a8b4b3bb1bdbedb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f369a856-0c0b-456f-8409-5cc4abed0cac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 42).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c70f78a8fdf9ac96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec828a0d-dda7-495e-9f1b-b0c1bc9f5001', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 42).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4b7c36a291f96358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887adfe3-d64f-4dba-9969-d73374fe570e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 42).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'afca0980ae56af7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c22cee4-072d-4a58-a6f4-b764a5f1d669', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 42).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ec8362de4c80a5c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01a752e4-5b7b-4d6a-bb55-8a6fce73cf90', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 42).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '65c1ad053d73720a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bffc0d0-b166-43f7-9ea2-52a6fea07ad5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 42).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a9e088436947f3e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f89136-eb80-467a-8e30-f42cc566906a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 42).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1e50e8c736ff53dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c72598e-a11e-4903-8738-f10962d4c718', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 42).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '09aeeb81e4b058b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f02aafeb-0b61-4ffa-b817-19e784d0c45e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.249.55.0/24 network (variant 42).', '[{"id": "A", "text": "access-list 1 permit 10.10.102.0 0.237.143.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.10.102.0 0.237.143.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.10.102.0 255.176.8.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.10.102.0 0.237.143.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.237.143.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '778719a84aaa458a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a13f2d8-6ee5-4fef-a782-57635b122492', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 42).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0d65a6be6d179c34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3331d07-4635-4de7-b084-734b065e2a26', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 42).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af6b3ef29b8b758a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5842263-6e18-4a7b-8f46-57aaf001a87d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 42).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '268c2e106973a2bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa3141d1-e6d6-4a4e-8b5f-de58fa08e80b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 42).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '534c49baaa712c61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9515867-cb15-4e50-ba24-b83da8fa22cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 43).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4d96c5396aab289a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50cea227-f18e-4a08-bebc-929093441376', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 43).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b5d27295eaba3aa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7718f23-b948-47c0-806a-3b1ad7266394', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 43).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'd312944c9416c768_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e397a50f-3555-49ea-851c-2036474aa71d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 43).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '514e4bcd14a5c14b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('746fa5b9-853a-45e5-8a2b-bc2ee742257f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 43).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd1d9604e8205cf04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67814ccd-7b69-44c3-989a-ec85aef4578b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 43).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '88ffd5c47a2163d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a461e023-524f-465c-a3d8-e644e9cf2f1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 43).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '45472e69d2fa2ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be0d6942-bb72-467c-807a-b703f51428eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 43).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '478916763a836e9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d54fa4d-7b03-4108-bfba-29218ba99b4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 43).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '42e3f6ec59a8ecd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f7a82c-ed06-4285-9f09-b93bf3e53d01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 43).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '95596f8ba45299eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94885d73-cc1d-44d1-b6ea-ce0c0ed29238', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 43).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '53a9e9a411f143a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d23ab3-fc6e-4e6f-9591-25212a263d16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 43).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3f96616111a32004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e4686f-e675-4c55-85b6-8d05532997d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 43).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2d11b547cbd81665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34b17ade-8f65-49e7-b95b-ce5d1e9180c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 43).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0ab1f89652fbcdc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4309b218-1809-4256-bd73-bfad42ed8a23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 43).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '11615a686026b2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e371c4ff-41be-4ead-bbd8-62046a418201', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.190.232.0/24 network (variant 43).', '[{"id": "A", "text": "ip access-list standard 10.95.239.0 0.35.202.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.95.239.0 0.35.202.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.95.239.0 255.31.215.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.95.239.0 0.35.202.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.35.202.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1274d056b22a1d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f29f0686-302d-411c-aee3-74ff307ba1ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 43).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '7167d54075143224_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b4e12fe-6d67-466f-84c7-295e980ae809', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 43).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd604c690729ae81a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb458d4-f751-4e15-92ab-f9ffcc52c4e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 43).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '10ab082c1943edd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a828bf0-95bf-41fc-b891-515f44635ebc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 43).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '32a309833cfaa953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20fa9d34-6910-4bf4-860b-924160dca3da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 44).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6d3ebbb5542dc8ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5e8531b-c2c0-4914-94ff-5ff922ee87c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 44).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a7bb15a82622b952_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7097a435-a685-4679-98ee-93e4ea8803a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 44).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7923ece7a9b4823a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d93f2a04-c18e-4a96-8e55-c1cdb1e302f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 44).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd660af70a478e506_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c187f2a2-0291-41c7-80c8-a662d29848c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 44).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '43999e7bbd62cac5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bba9c3b-8dfb-4d55-8477-de337c2e283e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 44).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e4eb72cf0415d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b87cb3ae-be3b-478f-b717-8ccddb02db48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 44).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8adf40c0b932bbd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42dba777-b894-4005-b534-cf11917eb62b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 44).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c54d09b5b76f040f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('475d71ba-9607-4b7a-be4a-60e58bcd4dd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 44).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '243da69bf82895e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e46c6bb5-b025-4ff4-956e-70e9129e2a80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 44).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8e02198e8c6be68a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07e778b9-0efe-436b-ad06-08a5e9e75693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 44).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '233a7d30603b6e6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00ce786a-f780-4a4c-89c4-ac1269957ca6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 44).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4ced926c5ad997d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac3baf41-6a77-49f5-9e1d-a4d945ea8f08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 44).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e530b01f828d466b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a047bd18-5843-4c0a-932f-9b71548f166c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 44).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'beb90a0c9c550065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('222a10b6-9dd6-463d-a7fb-53857907afd6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 44).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17c1ade2614130c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b924ab5d-0e1d-41a5-a43f-9d38791bcc56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.182.0/24 network (variant 44).', '[{"id": "A", "text": "ip access-list standard 10.180.132.0 0.52.147.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.180.132.0 0.52.147.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.180.132.0 255.175.207.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.180.132.0 0.52.147.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.52.147.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '822e55462fb0c197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e94f455-b82f-43d1-8077-8d7e2f60f860', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 44).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '820c6edc07121969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a75d9c83-fdd1-44b8-913d-f632d7f7e111', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 44).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4f7ccaa13eb63986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d2d0329-dccc-4798-93bc-a86f4eb6db73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 44).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ef9b5d84a12dd687_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15c5205a-45ff-4118-a8e8-02a0428738c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 44).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'fddf201e6f8504f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db94ca7b-a6b8-45fa-a885-3f115bd7e531', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 45).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '12ab6a1a1bf315c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dce0457c-1bf3-4aa0-92a3-377d14c52e3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 45).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aad9590eae974ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feebca77-f02d-4ba7-a3bc-4f39cbc577f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 45).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c5072a6f15d4ebe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b4f153d-ab3e-4e9c-ae9e-8f6b03b82f3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 45).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '17a3c10fc6fbca1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45c50e10-550b-470b-ac70-a3a632caa563', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 45).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '03fa15ecbc81a99f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9478129f-2a0a-43db-ab74-7042e72b664c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 45).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f9b0fa04da117c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('007d683c-f188-476d-a0eb-56665308f237', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 45).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9ac9da7a48c8ac9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04432e90-a944-40e8-9a12-1e08c417ac07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 45).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e348dc28bda31415_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f439d28a-95ac-4c50-87de-b369fbba09cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 45).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ae201d84428d7759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e719e44-8adc-405f-97ef-b70cc43a2067', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 45).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '058aab19735d107b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffb48797-2062-4098-84a7-c54dfedf6744', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 45).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'dca494ad2912f320_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b590e16f-48a8-40ab-9f0f-1456b1f73b00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 45).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'adf1a5854b8f658e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eb2b3ba-52c8-4010-b5a2-9afa4b4b9c1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 45).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6d221f2f4ab57378_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31ceb67d-ded3-45c0-8c78-e1ccff332ecd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 45).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f53d4d37d178fcd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66e6d1ae-3be1-44b3-81c5-4ffb00511774', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 45).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '289e094ca754673d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c31cee1-62b1-48e9-a642-c08c6fdf6885', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.30.201.0/24 network (variant 45).', '[{"id": "A", "text": "access-list 1 permit 10.189.191.0 255.60.99.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.189.191.0 0.71.67.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.189.191.0 0.71.67.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.189.191.0 0.71.67.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.67.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9a9930aca33a6093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f5b834b-e307-465a-b4fc-158d89db0a45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 45).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ca3c42acc98f40d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2df72ce-917c-4910-b29a-ce8f20a1455d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 45).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c37528d17e1f121a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01e38361-2c06-44bc-b05c-8c04559d40ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 45).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b6b0e608a14c90f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1a4a987-9555-4261-8c31-4287c634b7bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 45).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0c93057d1c4486c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f41ae6d-dcba-43da-9a4e-3fcd5681a023', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 46).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ec5f2ee23e09b263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a35455d-d335-441e-8d8a-51d0a4e6109f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 46).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bad56e5b46fb2061_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09d37f04-3301-4c79-adce-52bf1b8e11bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 46).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6443929cdeae2d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e6f14b0-dbb3-4350-b183-6c5c2a3e9f52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 46).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '83a11fa550ee23a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('280abd96-349e-4258-9df0-ef7a61101ace', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 46).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e289ac7ec090db6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1829ba00-976f-4f2e-a7b8-f7fc08685b06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 46).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd61f611f717d6e0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dace112-a001-40c6-9e76-d59ada34d5a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 46).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '15292b6bc0975cea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52d2d7d9-4d23-4f46-901d-808bfbfcfef5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 46).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e7ecb472f480eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e25e8535-f6af-440d-8409-fc2bbde45c1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 46).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c08b8d8a6de8dc5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa9c3135-60e3-4269-82ff-72584c82f9c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 46).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '24488d357a816d8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('823fb82b-a94d-4bb7-a11a-564d2c4d4bc6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 46).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0a9ec7d183731faf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7118170-8cbe-457f-ad3e-4ebb62d67c7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 46).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '90f1c8877e8602e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdffca58-6799-4094-8109-b92bfcd4cb89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 46).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'df43203f5ccfb1a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df89cbd-02d5-4463-9fc4-264adbd9392e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 46).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e77667181ba4a0eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e8024fe-1c26-495d-ae4b-1ec8de44d0e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 46).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8bcee54a556408f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e14c44c3-570e-406d-b9b8-b4d566fa277e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.87.227.0/24 network (variant 46).', '[{"id": "A", "text": "access-list 1 permit 10.239.44.0 255.149.64.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.239.44.0 0.149.221.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.239.44.0 0.149.221.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.239.44.0 0.149.221.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.149.221.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5560a178672f5cc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c817a94-0f14-4563-b6b5-faee1494c757', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 46).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bffa320ddbafc993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7846e654-9afc-4d16-a14a-7b7ef3d675c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 46).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a39877703729047c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74d22a04-3f56-47c5-921a-7201ba1b6a17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 46).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0e4efbfdcc9c4223_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe82f2b5-6e39-43e5-a42c-604cfd49c1d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 46).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd18a037931dfc87d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70db3df1-672a-44a7-9d06-b663e1cacb79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 47).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2b92e2bb0f8362bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a84ea15e-a56b-4cb9-aead-f91f66fc08dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 47).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '96d1c948654f7bfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69c2f85c-328f-4a8f-be1d-289c6d588825', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 47).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a321bf4f744f7839_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f245c7a-c12e-4fe1-9544-70ea56715153', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 47).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9435c66b69ef4905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8c80361-33e2-414d-b55e-c77032c940b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 47).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '312afae31da11aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab6c1b37-2e87-4837-97a1-b106d8b9df4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 47).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4824f3461aeb2e34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9629fded-7557-4f23-b987-b0a065c074a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 47).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0ac1aa9e463a65a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('612b219d-7dc2-44b3-833a-95f6b482e078', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 47).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '91958d17d51717d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2acf1dc9-5664-497a-9dea-316c0ff8a3a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 47).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e09a1e423fad7def_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e31b13b7-ab2d-43b7-9a42-a4a5bcd59034', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 47).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '35a46b4a161006b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7109e91-d314-4703-aada-e97a062132c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 47).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0350fb77a2cc3cd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f379a596-3b3d-46fe-97d3-78542f65e345', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 47).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '22bded1c6770ac75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17cac827-26f7-4b14-b516-9448775e5d3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 47).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e00679de38a3b0c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc5cd41f-8afc-4622-84dd-a40f3b3ad1bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 47).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd40a9d4642b40001_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbaab2aa-f852-4d9e-9286-2ef989c8f59e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 47).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4cc6e68fc4be04ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8417c8af-1d92-48bb-a87e-c13019761358', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.159.83.0/24 network (variant 47).', '[{"id": "A", "text": "ip access-list standard 10.33.54.0 0.132.90.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.33.54.0 255.106.20.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.33.54.0 0.132.90.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.33.54.0 0.132.90.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.132.90.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4fe020d27c6aef87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7acd3a47-c32b-47e9-9fae-afb8c17ac522', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 47).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0de2dadabed5329a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e90f2db8-355c-4ade-b280-dff450bc1072', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 47).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ee3f8e853477af16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d76d48ca-82f6-4787-a408-e1e92f935813', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 47).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '082d2a2acf65761f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff1d1bae-2f61-48c8-9f7e-c1f1674d8ad8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 47).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '74b267a13befcba0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d821f9c3-4ba9-44a5-8f43-16f545d2ca2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 48).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5e73855e107a0de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09b4c321-d1d9-4ac9-94e5-dbfc1641366b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 48).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1634d263653dc29e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('952bd91a-0fa7-4099-ad18-029cbc2ad4d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 48).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '13c085f8d28ca4f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0b032be-b0fe-4306-b704-1ad5a7dccd16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 48).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'bf75d97028fe5c81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73a8460d-3915-45db-9210-8aede7595806', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 48).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0f860c4bf6ca503a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0ba85c6-40c3-407e-bdf4-e4bdc3763897', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 48).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b3f50ef095d7c83b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1360e859-b4e8-4e17-8034-bd4af45dec46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 48).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '60649c977ce5f999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b91667b-93c4-4df0-9610-d2dd2bc6515d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 48).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a53531e437574f7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f3b5a88-4fae-460b-aa22-71d2d50e36b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 48).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '5104affa96b635df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f167868e-0e52-4fde-adea-c25103f41ca6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 48).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '64f75d8d60af535b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63460b9-f062-4cba-b5b0-00f679d38b46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 48).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '06e493f4bfac6480_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfdbf305-d56b-4296-bf23-3d2d898dd5e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 48).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '27750bc995884f21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e7430b5-89ee-4a06-8001-f0c2ef184b72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 48).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f0d99ed9e2654ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eb7c9ad-f8d8-4f9c-8041-62a128018df7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 48).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4fc95ef7aad4e3e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8686318f-3862-426d-a1bd-6bf22b8f1f25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 48).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9dc9f847def2ffc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf98a32c-8585-4aaa-9292-2679568a37ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.153.65.0/24 network (variant 48).', '[{"id": "A", "text": "access-list 1 permit 10.85.112.0 255.118.0.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.85.112.0 0.170.151.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.85.112.0 0.170.151.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.85.112.0 0.170.151.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.170.151.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b22e645025e6c5d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c505c2f3-3b34-4ade-9e5b-2c12d670153a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 48).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e958815ef244f788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a39ff115-67c5-4b30-9b10-b32c66ac9973', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 48).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9986dfce34494535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11dac341-d244-49ce-8e5c-d5388a9e2560', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 48).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'fc845f30234fad6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb324e48-90f4-4e52-b7cd-5a7426f989bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 48).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0c0670dfc54b881a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b66079-4c2e-4f52-8f90-22cba8132360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 49).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '59fe5e495af5921d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86cfe856-d75c-41d0-a9cc-1832abad54e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 49).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '369e402b1f9e5a2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b5192d4-6723-442c-bcb6-fd47bd1d9b7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 49).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'cf491f3217fd8848_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0a49c3e-d30f-4de3-b993-db2b9d05e9bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 49).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '854e137e13fd2c64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f50d80-5728-4ac1-8b0a-b641bcb22765', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 49).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c15458d0e04981db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97eec12f-deb2-47e6-9265-865b537ee5f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 49).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fd3e51fe718d0884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6074d3d-fb82-4bad-b12a-fee69ed0c18f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 49).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2202a46d69356ade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b29df5f-3179-4761-8c19-540c9f0917f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 49).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8c1286a073621d6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('203cb2cc-448e-490d-bf0c-40d70d896230', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 49).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '075ca01d27fd762c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f06d6931-80c3-4d49-975d-12961da07e82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 49).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '306a6fc6f2bef32b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aec4bf4a-faaf-4f9b-8ea2-dc90e4c11499', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 49).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '557ea783a37bb4b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68538c4d-02b6-4612-bb45-8a95342f7473', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 49).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '0276e5862629c58a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e21b27-ed3b-45fe-8c22-135b707bcfdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 49).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '88c5a6d83327776d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ecbdc6-23ee-46cc-9329-a1582bb6a916', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 49).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd801ef344dbdcb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('794acb52-0901-4646-8f7c-b25acb783cf2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 49).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7ff6808f6e1d2980_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b6186d2-d84e-4942-887a-b9730dcd6641', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.7.71.0/24 network (variant 49).', '[{"id": "A", "text": "access-list 100 permit ip 10.159.4.0 0.252.194.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.159.4.0 255.100.128.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.159.4.0 0.252.194.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.159.4.0 0.252.194.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.252.194.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '337341592fa7930f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5427ff30-615d-4adc-b295-127efbdc4d47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 49).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '02c5aacdd5935ff2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a95c71d-1965-45c1-a79e-7fc2ebd92094', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 49).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '524cacc7d39ba7c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8835ad16-e46a-494d-b53a-2c48ce8f3e9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 49).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7888b8cd89d8d3f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c45b200-be3c-443a-a403-d15907072134', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 49).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '2f08a9fc238cf376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb663918-2a88-4637-a0bc-ad01f134b420', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 50).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '84db290895d251b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c7432d5-043e-4e33-bb55-b41ba5c1ab02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 50).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '106dca0c5c51f46f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eb8960f-c5a7-4aa4-90cf-f6813e891bab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 50).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5227f0a31ff9a1f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b6fb192-d3c2-4425-ba17-ed70db7985ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 50).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7916ee5eb7084162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be0b98ea-25b8-4468-b898-8a11d1f8e379', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 50).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '18b928ea3278cae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff155bc6-3f2f-45c9-ab70-72f55f782d6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 50).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cffeb23b27bafc50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f21047f-8ded-44be-959f-539d31e39adf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 50).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7bf99bb585799bae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f60a2bac-225c-466e-81e9-4f1f3b2a5523', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 50).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '10f8ba57312fb6ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b62ec9c0-2606-4ac6-a8e2-080a807f7b1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 50).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '41ba9b1057439359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be42f568-3580-43d5-8659-cbf9badb905f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 50).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a66cd7cbcec62ce0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e2b3f99-4b63-4d7a-998a-7afeda034312', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 50).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a09b4cc2f035a6f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f58d3160-30ce-4eb6-b953-2b1958f42837', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 50).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'dc2f56d4b522f8c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de185d5d-c98f-4533-9788-10abc6809264', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 50).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f9f21183cbe00de6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0b58d4d-4d55-4ed1-bcb7-acf006dcd837', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 50).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7f4f56fb07d8052d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f505a3e8-bc1d-4777-8d19-c3dfa7d56df1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 50).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9ba54461bd0ac85b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a600ab0-6b28-4a26-b306-9ae94dc04630', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.52.178.0/24 network (variant 50).', '[{"id": "A", "text": "ip access-list standard 10.184.114.0 0.117.119.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.184.114.0 255.77.71.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.184.114.0 0.117.119.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.184.114.0 0.117.119.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.117.119.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a46bf036bea38098_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a40da56-e170-4f6c-b375-0700a839da90', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 50).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a60b79849a7d6561_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4e9a583-b293-4d6f-8c75-30d6826d7ca5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 50).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '298ac4e0b86de618_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47accfd9-ebdb-45a3-bcef-a0b7474d6ef4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 50).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '62caafedef84c7e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ef23b50-e2bb-4b22-85ce-68546616e270', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 50).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '33a184cadf5cf81b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2ba793f-c791-4d67-a1c3-75e8ac8960da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 51).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '46dc603bee299d26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1829a59d-6301-4b47-b5d7-d12472d721d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 51).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b31cfb98556edb1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20aa1557-b564-4ab5-9833-196be2c24cc2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 51).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9ea98221c573e09d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b6ee98c-e8b9-43b8-8f76-84e227eda0d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 51).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '543390d7af78e24d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05e3a127-3294-439a-8b6f-b595f28f0dc8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 51).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e913cb265c3f0ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9a19bca-c4a8-43a3-aa65-320691097f77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 51).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fae869fcf0b9c402_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2477e3d-18ef-42a8-9362-52f43b8af2f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 51).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4d9a295ed8bc15b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52663ac1-b714-40f6-bb02-93925fc561a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 51).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9061189d51c5c2ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e11df03-c407-4cfe-88bf-6fc23e916cc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 51).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '415ef3977d1477c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('173fd013-c056-46bc-b431-75fc7ff3541d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 51).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd3653a56a3f217a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b461f561-9382-4efd-8092-0fdef767e89b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 51).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5bde52d06f455338_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee51c052-f134-4fdd-b99f-b3a0e02c4273', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 51).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '99018e3dd8f75268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('774d53aa-43d9-42d4-8c57-b7073394eb92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 51).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3d473476a5b713cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c16d37e6-01a9-4f08-a6e5-46de1ebecc52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 51).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1048947bc917c8b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a95671-80f6-496d-92d0-81669745ba97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 51).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2ecaeae965a4aa6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b7a293f-28e5-40a8-8ca2-28f6ed3415fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.96.16.0/24 network (variant 51).', '[{"id": "A", "text": "access-list 1 permit 10.80.213.0 0.11.87.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.80.213.0 0.11.87.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.80.213.0 0.11.87.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.80.213.0 255.96.83.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.11.87.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4a053d0ce13d36e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('718d8536-349d-457b-b472-59b5125880b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 51).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9bda26df62f04ba5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf627e5-c11f-4e15-b24f-35abf9d7cf49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 51).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2c573bd81a17a169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d127b79-489a-4a57-b3d1-2f70b462ee4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 51).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '010922fc5c2ba56c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60c609e9-1469-4e9d-8946-001ce5119546', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 51).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '74a15a4498ee3690_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ded34d-d2ba-405f-b1b6-19cdc0379b5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 52).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1fd64c17e0606b38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7e7c04a-5344-4036-b9d2-399f6e551b1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 52).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9e7b155b222edbe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbd82e50-607e-4069-a69e-9473497caf4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 52).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '76e3ab5ba85c11a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('739d7448-507c-4b98-a9d0-385cd34561bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 52).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3dfb425ec6660d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aede8952-5e20-466f-8b01-7b0cb60dc60e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 52).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e2ef044c700ae60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1c3dab7-e72b-4103-bd11-44f7b1e14721', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 52).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16a82ddc6daf952d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('099c4fbe-c6cd-40d0-b3e4-89028f929076', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 52).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '191d4fb3e263a5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87dfff76-ea11-4cff-8966-6b95a7262ecb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 52).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e1595c0be0ec355_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04f114c2-0fa2-4d6f-be6e-65869313267a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 52).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a454dc5355d73d4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eecfc4e-26a7-4493-8c88-0980cd6b185b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 52).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '040d2e3b91741c71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e966020c-4380-41cb-b6d2-b6d776840da2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 52).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '73b8072e3dc77fb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e81f7cc-2eb0-4573-9eb5-51e20deb2103', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 52).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3f128de800d513bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3bec178-99ef-4e0a-9859-2c4a79370688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 52).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ce79cbe8e7b4a735_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e36373b7-2c8b-4a98-906c-ec49a26a28b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 52).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4d8e05adaf8d9756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7884d730-9fc4-4d2f-9134-66715b6ae19d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 52).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '49810ffe7fcff54f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9349880-513d-43d5-8378-acf8a9dfe9d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.192.102.0/24 network (variant 52).', '[{"id": "A", "text": "ip access-list standard 10.78.177.0 0.6.123.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.78.177.0 255.209.80.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.78.177.0 0.6.123.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.78.177.0 0.6.123.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.6.123.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '653ecf059944c872_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eb4a4ca-306c-4c99-ac44-5b93a07d0066', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 52).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a7856a3ccf43c60e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc109d5-09d6-4473-9b29-1c5479b37d0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 52).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a5e78baf4c411ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68075eeb-f0a1-4bf7-8ef5-26e0c98107e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 52).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7fbbbc6ca9f72af8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a4d29bc-2538-4223-a698-6609fabc5360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 52).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'fcad4830b9bb136a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f64f8ffd-aa0b-4c70-832f-501d75102b09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 53).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '499df84c2b9c6fa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50149744-0fa8-4ed6-ad97-60e4feb05bd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 53).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2da0d92d2ffdedb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81df0d3c-af92-4fd9-a898-602003db8930', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 53).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '810f261dfc1a21cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3cdd464-e5c0-46b3-a522-6939a9fe787b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 53).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '58bb645a3f2dc2ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94314feb-c3f9-455d-9449-6ac5aa50d6f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 53).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bc06dc76c44736ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec5d6a1f-e01f-4091-abc5-a72d5afcfddc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 53).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a25dfff19f420ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2ae5b35-a0ff-47a6-b1a9-11a50bcf86b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 53).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee6e08ee11bae229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef64e0e9-e442-4d54-88e2-9667dd105606', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 53).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '555d8a8e50af940f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b298c2-e367-4fec-a89b-3e8c528ebae6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 53).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '48b2ce405f428182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('781fa055-495f-4aa8-83c3-e00dbfc0f03b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 53).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '98cd38e769478ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ae9dcf-2055-4a46-a89c-93e11e75a94e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 53).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2e50da31a0805e19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19a46f5f-a303-4547-8ba8-c17aef566ed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 53).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '216aff8ed507b8f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48543908-58f5-4a45-ad79-bad3e424aaa5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 53).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87f766953a40f7be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2829b045-0b45-4fc5-97eb-ab03951c2d12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 53).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a6f4b25064e172c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af9dd9ce-f8ce-470d-ae9d-6ef65e0f9fa4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 53).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '306db457a34b3adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f05994-d717-42a1-b86b-d04f3c513e27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.151.184.0/24 network (variant 53).', '[{"id": "A", "text": "access-list 100 permit ip 10.150.181.0 0.66.138.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.150.181.0 255.200.64.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.150.181.0 0.66.138.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.150.181.0 0.66.138.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.66.138.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd543805c79665cc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff83f4c7-22d9-4808-a45b-84499e038cd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 53).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1445ab6dc79589f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d9787ba-9830-4351-b217-662481be3f20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 53).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '62c09f6918ca12db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a60cc686-9a7d-4553-a12a-0724a41b9691', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 53).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '63b2d30dfba907ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f75e6e-b879-4db9-ad38-77bdcdb0e442', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 53).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f437277ec9b3a5b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c09423-73f3-4fcc-bebb-f47123406886', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 54).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f45a08a136590573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc249571-6ab0-400b-ae6d-0f82c835dd08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 54).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '616c2282c2d1c991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49e2d6a6-529a-48f5-a80d-b7c7f3071af8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 54).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '10f0d61bfc2c7680_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f50e24e-7531-4566-87de-1901e633c910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 54).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '98c899e7c742d115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f23842-50a0-4262-b693-daa96e08bbde', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 54).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee897481eba9b052_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ef0df7e-b992-4728-b4c4-e2e7f5265910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 54).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '500cc8266127c80d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b11517f6-89bf-428d-91f9-c398b762741c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 54).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2d207e786f9e5a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6e9ce6-ea03-413b-951d-915cf276c533', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 54).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c38b4afce6551344_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adac0fbc-85cb-40ea-b970-480dddf8cfb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 54).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6323d72ccd9792d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f66e7ffa-1a9c-4e81-b39c-740ba4cf370a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 54).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4dffe34b0bb890b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f77709fb-1949-42b2-9721-82d568e73070', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 54).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ca0cc508460d6542_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e52ba71a-6b0a-4599-be3d-a6170ebd9740', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 54).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '70bf3983587c6a2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75d812d6-8f16-465f-bc32-7d9a872d2ca3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 54).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'aeaa6325aeee99c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d731a98f-4670-4896-881d-f16e0002e884', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 54).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1b00ad62530df556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f578ee05-8fd9-4987-9006-e9d173b4a33d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 54).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'a8e7ae6e79b6e1e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c24a58-8b4d-4497-85f1-dc7b213d624e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.65.45.0/24 network (variant 54).', '[{"id": "A", "text": "access-list 100 permit ip 10.40.233.0 0.156.96.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.40.233.0 0.156.96.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.40.233.0 255.215.62.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.40.233.0 0.156.96.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.156.96.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f0c693814fd47c07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e85b75b-1dc6-4e50-9411-0320a504e078', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 54).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '074a4f5ee5a3136f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a3b482e-cd49-4546-998f-8125c2e51104', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 54).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cb2a12fe44a175e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31003ae8-f2e7-43f7-a42f-5f0dff8cafbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 54).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4480f670bcff184a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a11184-4183-4c73-99f5-28fed7624e25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 54).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e35774c8b835ac35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcc305b7-9392-481c-b3fd-4f06f8643445', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 55).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c72a5ebff41e217a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee710d52-f386-4d62-b339-090a4bd82c85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 55).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '80c966509ab40f0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e763343-56fc-4951-9c20-0ce8afee707b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 55).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'aecae4a47c9c4474_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19fd7900-4d7e-477f-ab74-2d0e6dca8a3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 55).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f68281d1d84cfef8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('037b9e28-bb49-46a4-b6f8-ec9ab9efee5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 55).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac653174a0e24aea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a05d68-19ca-4ca7-9a49-5bf95c71305f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 55).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a399238c2ca54f98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa26287a-ae70-4360-b1d1-d4b8d996b910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 55).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed0a29455a8ed125_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('495ee802-b5a0-4c12-b1ce-e56dfce35e24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 55).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '98cb6dac7e1c2544_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb4657e-b4fd-4cc4-978b-99164335319a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 55).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cbb6ecad08bc73cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638bf1c2-3c40-429a-83ef-c70a8ee76f84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 55).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fa2978685ccbd184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae49c6b9-895b-4c44-9e42-80db72951996', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 55).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e37d7668f3e61bbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('120f0802-68cd-4956-90ca-612358292548', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 55).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1ddc61d097bf9d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c761bd20-a90b-42f4-a95b-ea9520d86d87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 55).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bd7ffdc09142053b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6eaf2b9-4e5b-4dec-a2d1-166bff8d0d3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 55).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '361f21f8862d5dd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f95de23-912e-424f-baef-de99b0d1d541', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 55).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '524289ebc592001d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('186c89ee-1e9b-4dc2-b376-c92c8b7677bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.171.197.0/24 network (variant 55).', '[{"id": "A", "text": "access-list 1 permit 10.247.26.0 255.89.128.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.26.0 0.44.126.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.247.26.0 0.44.126.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.247.26.0 0.44.126.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.44.126.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '71cd1b8948bd6183_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be5a0315-107c-4c0d-b0d6-6885d27eddfb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 55).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6c8bcef6d6efc56e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5d08d7e-4bfa-4833-985a-1ba2f2595b58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 55).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd69309248a646745_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d33f6864-b5b1-41d1-adfd-c3a0509b40ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 55).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c15e7909bd4cd2f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81ac8666-19b4-47ca-8ce3-98408302e50d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 55).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c60c959e407be351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c0a9ae-abae-4ad3-8c6d-ffce71c8a3b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 56).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '156f5a47fe977c2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('293ca1b2-6dc6-4863-99e0-e4fd1e2cf115', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 56).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a030b44546c87813_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf7f325e-bc78-4382-a268-ef0ed0d16120', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 56).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '56da3980d4f206fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec246535-9dee-4887-8cd5-601e1e0f1074', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 56).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'caa73503e0894eb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1badb92f-66fb-45f2-a4fd-d39322f42544', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 56).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '35fb79301d2127c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb976f4-6221-4fec-aec4-0d791abaaf8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 56).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '591d66d643aceba4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('036b1101-747f-4e1b-ad8c-2f575b444849', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 56).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '79be6154c373708e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49c0d973-1188-4075-9960-87999f23b6e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 56).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e9849bfd429e43c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fb69980-afbf-44f0-af45-91d8eb83d9ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 56).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '322f27d594d0d838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61bac254-68b2-4a3b-926f-b47382dd7f4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 56).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1ac3d66d9001db42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42d40d47-ee9f-4be6-b784-136fd75803ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 56).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '16af9749b3730161_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78243712-d831-49c0-b1a9-1f1be3ecf4ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 56).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '9ea76937ca2d1bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55dc1e5d-1493-4571-836e-c95cb738afbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 56).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7cfafa015ab1ebc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28ea10c-bec6-4f68-a1f5-cde332e953f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 56).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1a27fde8ec3e58e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24cab9f1-c6f4-483d-88ed-d7771d96b1b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 56).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6b1f9167cfe1ac19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('167e646e-6c34-4aa9-b36e-3905380fe759', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.20.87.0/24 network (variant 56).', '[{"id": "A", "text": "access-list 100 permit ip 10.219.116.0 0.29.18.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.219.116.0 0.29.18.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.219.116.0 255.210.226.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.219.116.0 0.29.18.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.29.18.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8ea44fea59e81083_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a4a5b8-f7ea-4303-b7dd-50cd63697063', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 56).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'de119990c0d55163_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f802362a-f6f7-4c3e-8aa8-f5e3980ce164', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 56).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '373b386a12ca26ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9c5da9e-e827-467a-aa0e-a4d86472d6ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 56).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7411228f51b9edab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f13e654-bddb-46d6-adcc-65d1c13589c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 56).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4fbe24e088314417_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e23d3d8-3bd8-493f-8fb7-5e40fe680ceb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 57).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8898e5a4a3605fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82960ce5-b4b1-4797-92c2-446c2636ac9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 57).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '214041ccab0730de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9677d7d-2fe6-4626-8af7-84bd29879b8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 57).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e3eeb213025e8a08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b441e03a-189e-42b5-bc67-9b846354f524', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 57).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '22f2de7104cb1662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4838e5a-d254-4526-abea-1e76e2d7adb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 57).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4565a85f7a17e2b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b6fbd5-35ec-4fbb-96fe-d8fc2f6923ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 57).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b5fcfdee5ddf572b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b4bfa61-8d65-44fe-aa56-de484584ead1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 57).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a003de42bcf1bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b76f27e8-4463-4bc1-b7cd-89e0da7d66e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 57).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '770a0887d42ada8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2dfce10-440d-4a27-b006-50935cf9e387', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 57).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2bc85999c8fe8ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c7abbda-a780-4081-825b-c278e43b6815', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 57).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'cf95f3db541573ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eb663f8-bb1c-476b-bae7-a9efbc7a3450', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 57).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7d3600e4cabaa302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d1b91cd-5af0-42ac-805b-ec198cbfd106', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 57).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7200b730e4c7e314_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4e6fdf4-325f-4ac5-8df3-b864d2aaa686', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 57).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6b5384f726a0e987_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5620018-e3aa-48b0-9119-5c975034e244', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 57).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '965de80db83a8aa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f734d398-7f80-454c-8114-50055f6a2f52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 57).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c7423c1c0fc47d38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cd41992-2023-4beb-a859-1e6530f4f511', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.188.56.0/24 network (variant 57).', '[{"id": "A", "text": "access-list 1 permit 10.203.215.0 0.40.119.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.203.215.0 0.40.119.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.203.215.0 0.40.119.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.203.215.0 255.111.128.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.40.119.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'adf1acab50b55a13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5af35e91-6868-4a9d-aace-95b84e8271ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 57).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fe5dde43e206900b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('431b662f-a4bc-45d2-8d35-6f3b4705ec53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 57).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b903a5252f575f06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3ae90b-637c-41a8-88a3-278b1a56a88f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 57).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8b28070be36263ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae5f8f38-fd03-419d-b8ce-bb897eb05565', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 57).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '54b82a3973066210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f454976-9ed7-4bc3-95d7-e6256f3c0747', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 58).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ac29465068f8df97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a226e53f-7d2e-44a4-81f3-1b969954625c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 58).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '652f1770b7a57c6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ffd890b-cff3-4894-9b45-b82d746f2f60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 58).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e8a88386949d5c0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('043f5e92-2e8a-430e-af50-09a943dc0786', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 58).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '50a1276edf37ff8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54999149-ffbf-4b6c-863c-17a478e087a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 58).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '701c8c1f87981002_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33fca64e-0552-4c67-972f-5f26f45be509', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 58).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23da1ac0852907b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb6b3974-9f09-4b45-bd2d-36328262d12d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 58).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4805c71eb6fd7cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a064a7c0-f05b-446a-b864-2ae083d4cdfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 58).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '39ec8cd3c091d27e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9791331-aa45-4f80-8758-d1fd32d27ee3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 58).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'aaea0b321d5f2ea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a1f3ec8-8c0d-4429-b567-e7a2c9c6b383', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 58).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2634e4ad99f666a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35cea748-8e44-4ff4-81e2-8d30169d2025', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 58).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c5a4c2c7f783749f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f7eb00-36f3-42be-978c-44195b169e32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 58).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e932f2fd4d895edd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('264b5ee8-28b2-49cb-ac1d-8bf1eb871e34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 58).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f0d3edb7e973ac84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c05e407-1a35-411e-aee6-e774143aaacc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 58).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '97c1719d58e91ba6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fe04998-31f7-4eca-b28a-59cc9feb04e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 58).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd6c91af9e868e23a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('881c4b7e-4ee6-4fc1-960f-118718b702d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.74.0/24 network (variant 58).', '[{"id": "A", "text": "ip access-list standard 10.237.153.0 0.216.14.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.237.153.0 0.216.14.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.237.153.0 255.50.186.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.237.153.0 0.216.14.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.216.14.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '481f9835ae32a88f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a51c81c6-0125-4dc0-9415-e4a7c7cc7bbf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 58).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cf10e0a3ad39d35e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48a0f6db-32aa-4595-862b-e317357381ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 58).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '231606782c0424cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('214d5ed7-6ef6-4200-881c-2cd0379be0a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 58).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2a53a3dfad7b3918_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('095db395-41ce-4ec4-82fd-160524fa0b3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 58).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd81e3c3e8fc1fcd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('731ce15d-885e-427c-8445-4ee166bdb632', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 59).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2ba91a48ce79e4db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f093a6b0-53d8-43d3-83e5-3bfcf19fc108', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 59).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1633b15fd281a761_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c385f67-c7fa-4b0a-aa3f-5012e6601ba9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 59).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a21012d0c1110b04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b235a8-1d59-41a8-b031-4d99010e834f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 59).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c10d0c0600045256_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ba8c0e-07b8-447a-b823-71b370f85b98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 59).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '64b391b57084eae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33665918-c493-430c-809f-ee24ca3af18a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 59).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4f317ad48c726a4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4881328f-a509-42cb-9043-567536f7d28b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 59).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b351952dd9b7a48c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4a3fbbd-5039-4090-8624-05c94317dd7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 59).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cdfcc4b4fb2e0210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c051af1-b001-4eef-9bbd-523256dadefe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 59).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'eb2be1cc028a378f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc227d36-404b-44af-9f70-2517b9a20226', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 59).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fb2ca7dd3fc5347d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('690c1c9b-3069-44b8-8893-3f882f369da5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 59).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd0f7d4ba79f55792_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e82a7c-d861-4c10-91a4-616f51aa5553', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 59).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '8581adee7578c953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('126d8ab4-8650-497a-a042-022e6cfbd4c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 59).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '911ddf572275f6e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2679561-ee5f-4d96-a953-09a34271acac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 59).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1a61227cd48e71c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1598710-1ff2-4920-8851-830ad3b41434', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 59).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '48ba9e32ca3b541a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d3265e-ffb1-4f4b-b55b-e4d10dc12d00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.195.2.0/24 network (variant 59).', '[{"id": "A", "text": "access-list 100 permit ip 10.24.65.0 0.237.126.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.24.65.0 0.237.126.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.24.65.0 255.108.250.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.24.65.0 0.237.126.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.237.126.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f780eb43df8ee33b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3058c321-0a50-42e1-8130-fedf47412d4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 59).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4a491deb6e0249d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0026d8d2-d5ef-4d1e-8650-cd2553d45e8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 59).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04df2ee6c57ca4a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10a07637-b5fe-46f0-b53d-dc681e8b1c81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 59).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'fc9bfe3b7838658f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('382c3c79-8abd-414e-82ad-f7d1a2adf070', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 59).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '39aa9036e0b4f9b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40fe8610-c425-4753-8ade-7f171e983860', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 60).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '996df5c467dddd39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0fe080e-c65a-4db8-be49-32dd4dd03c9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 60).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd9c7109e0efc155_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8a181e0-6bfc-4d3d-81b1-4835c827e94c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 60).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '4c04b41a005f6dce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fceaac75-9680-4bfb-8042-4362204b678b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 60).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b8680de9405a7bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f670707-a017-4f21-8e10-6ec167c3fd3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 60).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '59544762c0958816_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79d1d1ec-fc3f-4966-bbf0-9bba3d3864c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 60).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c19774cf04b484a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81722435-9671-4c8c-b7df-7327986e6c79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 60).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '13db2dbbbbcccf4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c27d2060-9e6d-4c4d-a2e8-655c582f630a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 60).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '09277fdba3538a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81dbadfe-1bdd-4868-bf78-1a9dd003be8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 60).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1fecf70501fd4893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ffb8be-27a4-40f7-bef6-e7dced852451', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 60).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e3775af6fb39f18e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27bb224b-4c55-4ecb-95c0-41ee4ec851e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 60).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a1ec7cb40dcc5aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e9b2739-a5b6-4e70-9278-ec01b3459be0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 60).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ef33029fcb86e65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16401fc9-a1a4-4a2e-a914-333a07357ae1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 60).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2aa08bac5ad045cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f58b5c-6d7d-4076-9515-df7b54608f43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 60).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b5b438e7208cd096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe965132-44c8-401e-afb6-25d18634b8a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 60).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6e76bcad5b71ccf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3654c071-2cd8-49b9-8a0e-318ec3b160fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.240.171.0/24 network (variant 60).', '[{"id": "A", "text": "access-list 100 permit ip 10.45.150.0 0.68.195.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.45.150.0 255.231.185.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.45.150.0 0.68.195.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.45.150.0 0.68.195.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.68.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8ee90d0b89debd7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be42fbb-fb19-4548-8e80-b459451a839d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 60).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6bdcafcbca962e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('151c80e7-005d-4b7b-a693-e837bbcab472', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 60).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '51b910fda50cba94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('195db8d5-922d-436f-8a1d-3687d1cd07ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 60).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c218a4f492b80f33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a206944e-ebf0-4fb4-aae4-c2c7d27aa459', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 60).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '776d5495a9cdabe1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492500c2-02b5-4777-b2fb-9a00c9966325', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 61).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1e1943d5bfb5cb23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('175d132a-6d66-4cf7-8335-036e266fc86a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 61).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '75d4ba043d528dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c8097a-672e-4915-8364-7e948f1116ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 61).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '426a2c13f2b13772_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae5a1778-7435-4ac6-b9eb-a20667cd6405', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 61).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e0fe794d48394b7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('867f1cba-c326-41cf-89d9-fa9107db34f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 61).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '89a00ec4801ae52e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1dfe6ca-af8a-4365-9d1e-b167bb15715e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 61).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a2373f3cbceb252d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d00cad-5149-46b9-8bf7-10829fdc8283', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 61).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9f78ccdddea63e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f166107c-a5dc-4cf8-b006-e5c83f71a661', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 61).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aa0e8feffd41ac9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('577bc07f-6290-49fd-9ba5-e59fe9562639', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 61).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '06fc8262cb99c01b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4369397-3b90-4927-ba5f-1e69e8823141', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 61).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6aed4f7035f43824_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f5e3de-0c9f-4ce9-9fc2-0ed2bf0f7ce5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 61).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0b5c489cbca1f95b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71028b6d-920b-462e-9679-52299def0d13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 61).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '37a44ab628a2317c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3347ccd8-09bb-4566-ab43-1709f7ed3505', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 61).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fdded4a9294b8cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef185aaf-a19d-42c0-a53c-53503bbad166', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 61).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd00defd320fee641_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('912b1b9e-16ac-4ae8-9e1c-385506a6fe52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 61).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '92e86d86b2d115a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f78dc4cb-91f8-4bfb-9114-1faafcc0a5f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.146.163.0/24 network (variant 61).', '[{"id": "A", "text": "access-list 100 permit ip 10.223.202.0 0.45.33.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.223.202.0 0.45.33.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.223.202.0 0.45.33.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.223.202.0 255.93.200.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.45.33.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '324a8ec12979faa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39eff152-fbd6-40b9-b6d1-dfc2f5f6ef4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 61).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '21f7399f57057fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e14d3a23-d70b-4020-a1fc-f2b094caab6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 61).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aca62f0ce65b93cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb2918ea-3ee7-4039-bf81-e27dd9c950b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 61).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6d8fb7ae121fa96d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82a58837-880f-45fb-909a-62c11a33706a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 61).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '470e65e279b71a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3786ed69-79e5-4c02-942c-dc24a3fdaa23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 62).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '94dab8f0e5ac697d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('898d6ac8-c093-4ba6-9c74-0bb0cc6f11b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 62).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7179407aa9890229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c56a6fb-ca32-439e-ba3f-36f51dbf5cb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 62).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '0953f74c4ab822e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e09daf-f1bf-4837-8061-727d29071d8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 62).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff2184ec07b6e86d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2a11385-b9df-4ee1-a41a-cd51bbc747ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 62).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9da457da551ea5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b9c3ecd-8159-4aea-a72d-efa6de114e33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 62).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd849fdcebf81dfb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae332f90-0d12-4f7b-9c23-7acd1e7bcc57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 62).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '97b7128af1ffcfb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96402afe-3cdf-4466-8bc2-46b704ea3032', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 62).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '641d04fa8762799b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5193a28-4153-4f28-b8af-e91b38732bd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 62).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '57e23041f771a5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b23f2226-33c7-43be-91ec-5c7e94fd63e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 62).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c5924d510b0b9e49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aaf7021-5727-4ae8-9fd4-fdfb3c48b865', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 62).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '40c55d1db0e4ebba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6e07821-68f0-4756-8c10-7ba0204d746c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 62).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '20f256b25e195cbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe71215-cba9-4142-a80a-e239ec02fe00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 62).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7e97039548c259b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d1dd6a9-cba9-4ff4-b344-b59721aea356', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 62).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fae1666f5783ad23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e3ace27-1491-492b-ac6d-1f8aaac9dc12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 62).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c000b9efcb0e0212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4730ddb-9df6-4090-9c8a-c21795767cae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.22.0/24 network (variant 62).', '[{"id": "A", "text": "access-list 1 permit 10.201.122.0 255.83.142.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.201.122.0 0.150.124.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.201.122.0 0.150.124.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.201.122.0 0.150.124.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.150.124.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5b5c42572eacae81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d97050da-3862-476a-864e-9140667f2222', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 62).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '10ed172cd61cbb27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de48e7f-a5da-43d0-9408-9ac2ee17691a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 62).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c38d6d7fbf8c87de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28e9e45a-235a-4b22-b8b0-94f9e5f8c9c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 62).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '74f7c802be355266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f7acb8-333a-4525-afe0-8316d50ff4bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 62).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '9a68404e5fb33884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6db0bb70-5946-4792-bf0f-60b88c1b3490', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 63).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0f25f34eb39b1d7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80818d43-230a-440d-bb01-0bb754a088e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 63).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2df40d745b3cda57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddfb91c5-0f76-4f58-ba0c-78b4041e2c8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 63).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8a287f3393c9e8e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a7a5a74-2b20-41c8-9628-294148f84b5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 63).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e31bec8b92bef081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13cc25cd-f5db-4d4f-97a1-870c522a6a8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 63).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b3618c8e5fe124c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('226fefe7-c4b5-4261-9278-2d66035e2877', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 63).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '53885c30d797a3be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a6da2a6-158f-4b7c-91bc-71c5d17b920a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 63).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '00273636ecf943e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6764862-aa8b-4afb-88d7-273d5104b471', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 63).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4a24990b3b678d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98045cea-dcab-4701-880d-33d38265a094', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 63).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '41aeebf9216bbabd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0b13498-b2f2-458f-96f9-a3bfec1a5ef8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 63).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '98aefbf3591903f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e99bdca7-88fe-4891-ac9e-b101232a3325', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 63).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0e07647728853661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aff6d90-9ee7-4349-b8da-5dd47c5518b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 63).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e7b91c7a9d74099d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('138ba522-5483-41a2-a63b-45fa9bdffe5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 63).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9647f08b6c040147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('275a735f-1b49-435e-834e-c8249147007b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 63).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1c01b280f42c3647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db1f8f56-056b-4379-b740-c399e5328eb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 63).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '18749e374515f42c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfd2c3ad-709b-4779-a3ed-3eff544a0603', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.207.227.0/24 network (variant 63).', '[{"id": "A", "text": "access-list 1 permit 10.224.63.0 0.19.50.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.224.63.0 255.6.29.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.224.63.0 0.19.50.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.224.63.0 0.19.50.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.50.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1fcc872cdd3c819f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14fe001f-e7cf-4024-b076-7a119c3956cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 63).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3e771b5178ee991b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9748d053-a1c8-4c73-b26e-c7f18f60a951', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 63).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1688bb94e38baf06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d56f05b-2c4b-4334-bb8b-3cbd74c16ab0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 63).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ef7c6d35d089d03d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f5e132-19ce-4a0a-9a32-3c86bd16439c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 63).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd86ebd2ad2e90f28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2043622e-1c9c-4538-bde8-d6ec6a0f305b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 64).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1a03e511fcd789d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5e1d96-3996-4dd1-bb6a-5a508e0a290f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 64).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0159220edf2e9a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71977109-a50f-461e-8abc-1c6d4e0e9e93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 64).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6642be9e7559579f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75472305-05e7-45ed-a0bb-fc2de91d2a6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 64).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '6b173e5a676784d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('840861af-ed5a-439b-a239-2d7ef34a7918', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 64).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'acecf2d94f0d57f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24d0ba80-8549-4045-befe-2d86a4ca83ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 64).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '72b000aff57133c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10310ab6-c7e0-4788-b743-a5a15f620fc2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 64).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fbf780508e56cea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6784611-0dfc-4726-9d67-1ae61877b0c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 64).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4ab0f6b3f9ce67fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6669d89-d17d-4de9-80ec-e8f1bff90d4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 64).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2313183ad291633c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b455816-12d9-4f4a-a973-89079ea9abd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 64).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0f4fc848a192e892_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada6d395-6906-472b-a0b5-e924cb067265', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 64).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3f396708869826b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ba74562-1c04-4b86-9321-a519d29f9563', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 64).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '51bfc90407dc2962_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3037badd-3305-4cd9-b038-50f6de512525', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 64).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bd127da623a192d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c02390f-3a36-44a5-8f84-e9faa17be74c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 64).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '354d4914483e66d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5782a195-7860-43ab-9ade-69d83f4a75e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 64).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'af86010c407bdf9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1439a174-ad08-4f93-8966-1b85f69c1250', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.191.10.0/24 network (variant 64).', '[{"id": "A", "text": "access-list 1 permit 10.166.27.0 255.129.122.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.166.27.0 0.197.73.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.166.27.0 0.197.73.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.166.27.0 0.197.73.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.197.73.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04d9cfc6b799ae33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fecebeef-c0c5-4e93-92ac-75f0186f6e89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 64).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3736463d65d3345e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea97baf-ec84-4799-8fd9-05024fc28615', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 64).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a0c32b0b24201b9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67a3f2e8-8fbc-4af4-9611-f35100e33dd3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 64).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '439afbbaa05a6972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('567a2397-4e3c-4a0f-8ce2-30287a680288', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 64).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '7ae810c149ba2810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('456f3626-e5af-4ccb-80e3-1fcbd670cd75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 65).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8cce203798e7f148_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34db2778-290b-4fa1-bbf6-ef350b2cbb2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 65).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '96635ef24c95550a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee4d6cfa-180e-4079-8910-9c2474e22c70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 65).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f0ebaec9dd97e77d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d08836e4-36d4-4245-a50e-05ba63ff2cf6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 65).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0d91873cc27abb2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('393ad7bb-2445-4484-bfc5-3a4f3aa839da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 65).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8de8ec739bad4864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d324a18-cec9-4581-ac98-901deb8ab7ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 65).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '10700e607964502d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce0178f8-63c6-4932-9d5a-f2d9fe37fb43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 65).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '845c275931015f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b82ac29-b0dd-4248-b397-e61fe4978ba8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 65).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cc4b36a84e734a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5831768-84e2-4f30-928a-d752f280774c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 65).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1d8b0ea6061f0ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7b75df5-60e4-45f3-8a24-ba33e77ed482', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 65).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '45fbf4706fb60153_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d09177c0-aa23-4d3e-8bdd-953946fe333a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 65).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '95eb08f2cd81171f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('219f95d3-31a5-4ccf-a088-9483b622f32a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 65).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6e224ca3d4605f00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e66ae31a-a6a1-4fc4-85ca-27147d84be1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 65).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bae3875bbb7f0274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7862af08-a548-4fc9-8471-868e674073de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 65).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6098ef74aae60253_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf9f484d-5ce0-4d07-9836-9700516a37a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 65).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '02ddee2ab81335de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7426eb56-b296-4367-af09-fe2b18e1b46e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.126.54.0/24 network (variant 65).', '[{"id": "A", "text": "ip access-list standard 10.93.179.0 0.221.237.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.93.179.0 0.221.237.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.93.179.0 0.221.237.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.93.179.0 255.152.20.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.221.237.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '22d804baeb0cc266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a9faae3-2a64-47b7-b677-f0e1cbd23dad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 65).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '900eae05a3d6160a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1372f8ba-ae47-435d-9600-1d4d2dd5ebf0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 65).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8d9cfb4a2f9eb51b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('facfbf10-f5d7-4868-99ea-511865e0d217', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 65).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e1952e352422ea63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27920146-97e4-4606-9fbe-44d3535f82d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 65).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '52d75254f4098b33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de13418-7a7c-47f3-90c9-6a03064d05fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 66).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89bd432f27f25bbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df63e0c-2754-473e-b1d3-237d9735676f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 66).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3ee3be209797d275_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20b88c02-c61b-4880-9111-35e77b173732', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 66).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f336e38cc63767eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0da14571-048b-4634-a413-b4d6c5927cc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 66).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a89c2de55291cf62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89aa5011-eb92-4003-ae56-905ca126ba2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 66).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'efcdd288b28bb066_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a6c65d6-1ccf-482e-b2ba-ca341209b75b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 66).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bdf5d15811389513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9947bdd7-80c2-48c7-99a5-d83e013d651b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 66).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2e96a046a668df19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d1c9577-2d16-4a2c-a9cf-09aec50724da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 66).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eddaf628ce46b01f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5154bdab-5752-42d4-bc8f-5f80cb40f1bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 66).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0758e3b61c3a1a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26338de0-85fa-4217-80dc-37adcfd5188b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 66).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '118e49da06b14359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5e3bdde-4844-4eca-98af-064c2f30e695', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 66).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4a255dece6734e4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8920be94-b442-437a-bb09-f537accb7e8f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 66).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7e7155e5c24032d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1588be9a-9d2d-4db2-91e0-715283e861c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 66).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2321a632ae511328_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756ecb02-d637-41ef-a557-6341a7f3b05f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 66).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '563af3d6fd349209_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3ccb38c-550e-412f-93ea-bc034e225b77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 66).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c3f4a63c2c6ef6b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc62ce4f-ca80-4e11-a655-fec5ce95e305', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.28.177.0/24 network (variant 66).', '[{"id": "A", "text": "ip access-list standard 10.161.127.0 0.4.216.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.161.127.0 255.131.207.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.161.127.0 0.4.216.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.161.127.0 0.4.216.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.4.216.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '92b6be01e8ad24fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e920f4-f3e6-4d68-b3d5-8d2be0a2fffc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 66).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'badff36df84838f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51eaba83-39fa-41a5-88ee-4ee7c88437fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 66).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2be0c06b07346d9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b98211-572c-4830-aaa5-babee09520af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 66).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e33b225c4e6fd08a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('851bbe13-5bde-42a7-a79b-80a233d977ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 66).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b54a3fae6bd1adfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02dbe33c-4b05-44b1-8077-56cfaae624a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 67).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3f23ac66d1958431_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e958a6d-d419-4b5e-a353-e4dcb7adf8b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 67).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'be2bdcf6e544161b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0b8cce0-d9f4-46ec-a793-720d6b6ac326', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 67).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a54e32616867f290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96343858-37a0-4d68-a9a4-64c106aeae18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 67).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3eeb72bbe6e83efa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('412212fe-7553-4a48-90f8-5346f43ee70e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 67).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c093e5befcdd9cd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf52b189-bddc-4578-aded-5650c5bf41f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 67).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2580e4f8b0f5cc54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72ef800e-b020-4f88-910f-b781ff60e0d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 67).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f15398dfca72a283_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45dfc8c9-425e-40e8-ad59-d97b33151a2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 67).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b44c6c4d3181ccf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c6c2f27-e9d5-4bc0-a00b-040387258114', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 67).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '27392524d11e6c96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4268df33-5d5d-4617-a73e-e913917d578d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 67).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'af8e20475021f301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d48f7e82-1b45-481e-9e8a-99ceb88a827c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 67).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '209d7548197985d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71ea0f2e-552d-4071-b0fe-fdbb899e4a4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 67).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2fa82d0151dcd46d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('580f2d01-ae06-41d8-8be1-f06bbe53e9fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 67).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '23ee53fd7208fa57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35b2b057-635d-4753-bc79-b0e076458e7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 67).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '00842d5deea7610d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cdc3628-2a9a-44fd-85df-0d41b1dbe86e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 67).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '57f1e9f72aec9362_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d01ccef3-a88f-4844-a015-b4779a47db34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.134.146.0/24 network (variant 67).', '[{"id": "A", "text": "ip access-list standard 10.153.106.0 0.70.162.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.153.106.0 0.70.162.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.153.106.0 255.43.185.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.153.106.0 0.70.162.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.70.162.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b432788a956301ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2654c56f-4ba9-48b9-a7c9-0c2d4842f40f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 67).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5d381ef157b8f260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00c45b0d-2340-45a9-b959-13fc4e5b4515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 67).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3f243d53db7b3162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5c0ed56-4f61-4917-951a-2eb61c4cca4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 67).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ed431de687c350a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15cec828-b079-488d-a317-b55a3d46c85f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 67).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '628f88711cbff7a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0b3083c-ff22-40cd-ad05-88f768f891db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 68).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '52c0f5392d1f7176_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63f07208-8333-413e-91da-fcc7b9ec206e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 68).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5ea2047d4f051206_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1227dd9f-a3e6-4c78-95b9-f54ab59e8064', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 68).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '1d30caadd55eeca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff68bceb-bf05-4b73-96a3-230cbad6239e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 68).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd9c74b3b21532a46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75c3c976-cb90-4e08-aeb9-c26795327bf4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 68).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dd7bc6712daee8c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1026238-b19d-464b-88f2-096f7935bc7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 68).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3e343f50847c8f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b843573f-18bf-4b96-8302-a6e5677c3ba8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 68).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '37c5e9e82e90cb7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee0f0f50-6fbd-47b1-90d3-f836e924f3c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 68).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '22054b73c074fdaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b3da92-c687-451d-9f94-7c354d719c72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 68).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e5bca11a8a6f3a9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('175f3d2b-0a51-46c6-8fb0-144ae744bb9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 68).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '16cb24e186765065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9121e0ea-2c3c-421c-9f0b-05025c096523', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 68).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'fc57a44706406eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c4ae9df-c4d2-4ad5-9b7d-f12eb6dda109', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 68).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4be3b007a33bf35b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4edaaf35-9328-45fa-9c4f-a0ad923fa3a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 68).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '47063a5724d26bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23e86e5a-2401-4e1d-8e80-f4381d97e6a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 68).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2abe012a16626579_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('429dbb55-fd70-4944-97e4-2895faca5de3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 68).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ebaf920d07f12a7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0521166-c75e-4986-a792-63445e259ad6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.224.63.0/24 network (variant 68).', '[{"id": "A", "text": "access-list 1 permit 10.139.114.0 0.133.17.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.139.114.0 0.133.17.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.139.114.0 255.37.48.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.139.114.0 0.133.17.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.133.17.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e54a4836f3b51f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ead35bb-8488-4c95-a942-3d5072fd703e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 68).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5cc46b9657674bd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2670841-61b7-44d9-be6d-6de4b6477ced', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 68).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '077baeb4c44dd58b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ba607a-97ab-4d33-b83a-e87be0458792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 68).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2d9a3a9f332ee8f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75718b8e-6fda-46ae-9cbd-02b27d3cd577', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 68).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5894eeaf320609dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a44eb8f6-09a2-4a1d-b26b-7b404d20bdeb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 69).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a34719e9b7a0e895_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00401223-80aa-4bca-baac-d7851b2c70e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 69).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0667080bc3bbdd81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e54860b-9c50-43f6-998d-679f50edf272', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 69).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6ec84f3c7f875b7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('552d1c3f-5d77-4c2e-bfdf-8accb62b5c64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 69).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '814736ed65a0ca42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4841c55b-e3f4-4f61-8cb3-c04a4b0fdaa3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 69).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ad88f5c0cbdaff59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('025fbc28-929e-4819-be65-1c93c96df7a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 69).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '431f23752fbb49a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07411ac3-dffb-4fd2-af81-2f995288c80e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 69).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b7eeb4b5b49653d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47339b9d-d8b2-4f30-94b2-feb2fb3f50fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 69).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f54661bd208f8d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f15a1566-a623-4495-ac7e-a51151a17143', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 69).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ff68058c4beacd2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ef8695d-01e4-4fd1-9bdf-eec2b9302779', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 69).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd7adf9ada97799ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b4b0bf7-8d12-42ee-b177-6d0cdac7ecd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 69).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '406fe134187010dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba17728-e481-428b-a984-25f056b0ba23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 69).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e271993e841e4877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fca97fa3-7b5f-4786-b71c-799ad30487ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 69).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e6fbf0406688fd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee88755f-ad1e-4a2f-8040-5b7685a2b088', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 69).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1aeac6140a66e8af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0315c6d3-84b1-48cf-bbfb-41053d31e535', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 69).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5f47ee0ebc0067bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8532bfbd-ff6f-4140-bd08-726f60f644f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.171.178.0/24 network (variant 69).', '[{"id": "A", "text": "access-list 1 permit 10.224.191.0 0.19.195.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.224.191.0 255.90.62.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.224.191.0 0.19.195.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.224.191.0 0.19.195.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ec3e8e1d76c8c47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e36b9da5-c5f6-43dd-a821-f6fafdd2d7e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 69).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9c90fb8024cad192_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4a94d55-9629-473d-8e18-adfebd003d49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 69).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd3391b67c6164f34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fca6bf50-6753-4540-a699-c46f841af535', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 69).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '27065f4f037f84d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc03ce35-cd81-4f30-bb71-2d9ed2df7976', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 69).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4815821f84052b67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca36a7c-f10f-4cbd-8388-36aef929dd08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 70).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0195605d44db9e1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eafc5c7-2c0f-4d9b-867e-3280c8aa61d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 70).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee21d823f5adf714_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d3d8a4b-6532-4060-8451-e7405fcc8627', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 70).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '923945fbb0815313_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44196700-9edb-4098-9895-780cd69405ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 70).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'acc6a2b0ddb59b8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f778179c-9d00-4e05-9e77-563a07381209', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 70).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c044b9493ebac612_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9e00acc-0a15-435c-b7a3-16309d550aea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 70).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fcc03376bc235a46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f777df27-2c64-4258-ad22-1738886a714e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 70).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ab584ba156315885_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2e25a0a-afde-40a7-bf6f-f7a4af8a9ef7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 70).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '950e0fee6e0d0704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41b1dc5-1c1e-49d0-aaca-c8e84229b7b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 70).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '23ab10d72335fbf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('368c1219-2aba-4ff4-946e-a9ed65ac12ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 70).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '37353f03df321e04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7a7f2e9-e5ca-4a3d-bfe0-50551e810111', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 70).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd67416f577d135c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5737065d-6d47-4160-ab5c-7daf963c1e7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 70).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4ab3ab714c344162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d008096-9652-4150-9255-bc7eb1145709', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 70).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'eb2dd09ba31a5937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e87e76b3-e110-4d5f-8229-9e64c3f895ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 70).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3f55effed43c2a40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('163833f1-3370-441e-aba0-de28c1b53231', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 70).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '707d16f0dac4927d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67df95a3-cb78-4ee7-b426-909795fcc6ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.76.10.0/24 network (variant 70).', '[{"id": "A", "text": "access-list 100 permit ip 10.32.141.0 0.142.88.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.32.141.0 255.163.190.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.32.141.0 0.142.88.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.32.141.0 0.142.88.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.142.88.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7c3c865984b84663_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad9d19d2-5cec-4ae2-882d-f14d2fb843d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 70).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '160eca33afd3b947_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('056c72e2-8f3e-4e16-a50d-850da6b4221f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 70).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8a56abc3e0f8d1a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89ef6ac6-b3e0-4a49-8749-4bc90f208332', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 70).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '00a13e2e01d839d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5325e575-9f09-40b8-b7b2-53a2a39eaedb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 70).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4c8842afca19c706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb42fd34-3b6f-4e1b-b484-58375b7f71bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 71).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a83c15b1ecc663c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df482353-0e9b-4664-b909-96c5198b99e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 71).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8731acf0e9dd7d01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b16d76e-47f3-4641-8aee-15575c50bf8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 71).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'ae736c42e089edf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6f221f4-dab7-423e-ba90-0a8a1a87e098', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 71).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5cda6956891dc863_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d4726d-a945-46ff-9e7a-a41ab6d1e693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 71).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26dacb9b49d8863c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceeaa9a2-ef69-4f5c-ad2e-24d1a6caf2cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 71).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '173e6c8dd911f93a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83c7a1c8-dac9-43d6-8321-bd95a5530ec2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 71).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a62703b8f712747b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb3a68a6-8cbb-49b2-83dc-279cec0f5a65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 71).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fab17ac9f1b6797a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78b3184f-f51c-48e7-9211-415435d13b17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 71).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9f1ac7df8e420893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61ee4798-3e41-44e8-8f2d-e30cbac0971a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 71).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '072b89f6222f7380_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c43792c-2356-4bb3-ad79-d153096b9bf1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 71).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '00fd9b132e858b89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbe5a665-7b40-4fd1-b00f-1d8bc7d57a59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 71).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7bc367133015b758_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d7077bc-f025-49e2-873f-2526fd8fd2c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 71).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2c9c50af9379833b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a9a46d5-d055-408f-ad5c-108be635a8a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 71).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fd9cbe44ec6461f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f881794-fb66-4a39-b2c4-44504bd2a593', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 71).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '130f9135ae6fa51f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34950229-9e69-4817-96e9-5d9ee40314ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.116.106.0/24 network (variant 71).', '[{"id": "A", "text": "access-list 1 permit 10.135.47.0 0.189.34.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.135.47.0 255.104.53.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.135.47.0 0.189.34.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.135.47.0 0.189.34.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.189.34.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '994c18a74495b425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7dd6427-85a2-4481-b9a6-cc6e49be114b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 71).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '15a8583a985033ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba7c43ad-9025-410c-8267-ef8ae4d51bf7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 71).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af52dbd1c9966135_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cfefba0-029b-4749-8ec4-d8cb84111cf9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 71).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '81ad640da8afbccd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf7b975-7678-4ad1-8a18-f3604d28079a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 71).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6088f5a82c3b9368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350ae671-c2d6-4b15-8588-7b50242b353e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 72).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bf66accaca5cad8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a404beb-2b93-4953-a4af-3b9755f63698', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 72).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '75adc2f1babc322f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d203379e-7a9c-499d-bc21-f59295eef0fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 72).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'caf99730cf60c37a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a381343b-f0b2-4b4e-a1e3-0071a600c733', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 72).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff93b2ae33858eee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56c24f02-f2f8-47cf-be18-397b200ea3d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 72).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '87f45d94f5e25812_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be1a4968-e65f-4861-8055-7d1004493c7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 72).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eeff3a2fd365c3ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5412aabb-eba9-4349-ae3d-e6ad9f94d83a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 72).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fed018aceb8ede66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600b6de2-bdd5-4bfb-b54c-e03ae11d7dd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 72).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7933ca9fa39c5ea4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d5928c5-cbd2-4e8d-bb83-fd18309a52dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 72).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e7b4fb4d3d653834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbc3e63f-2e34-4d6f-b2bb-b57a415d5870', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 72).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8217b8988e19cc91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1dd261a-3bd7-47af-8f1f-0204681a736c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 72).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c723ec763bb6d6bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcce784d-5e4b-4845-bf12-bed731cb5b4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 72).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd4e912528b019c55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ebf34f9-a749-49df-ab41-05a3f4f2ec7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 72).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f10cb7604411e79a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc9d9e5c-cd60-4ef0-abc6-c63642cc1118', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 72).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '48ed755bf30a5e52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cf1063d-c17b-4cf2-bae4-140bbca04967', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 72).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2aa9cefac59f4d2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e4c87dc-b03e-4c59-bdce-c7f412410863', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.219.207.0/24 network (variant 72).', '[{"id": "A", "text": "access-list 1 permit 10.1.226.0 255.163.190.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.1.226.0 0.147.149.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.1.226.0 0.147.149.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.1.226.0 0.147.149.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.147.149.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a600c875dadb4a1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edabf7e9-9ab1-4d7a-a9a3-7db49cf4fc02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 72).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f9fbfcf914957049_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88ada83a-b909-48df-b719-d4d421fc339b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 72).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '73deabc27a246ced_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8309938f-7bbb-4ebd-a843-82b322bca81c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 72).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f17f429f0b9e0ab9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52fa62e7-555f-4e34-8119-ea36bc40828f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 72).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '329f29b317a9c45e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d40de21-e857-4b02-9663-b6542520c257', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 73).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e0daebc5df1a2f79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75556ba0-6da4-40d0-a909-1469bcf56c05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 73).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '10bca9e151d643fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d53f77-b55d-4f68-9fca-c538e7907f24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 73).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '75f84da005a485d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2515e9bf-2946-4ba2-997d-3f7703fb4d66', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 73).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'eb528dbe33669aa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d221f8c7-32cc-43f3-a3e3-618835e6a9f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 73).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'da29e0fbfc1c6a33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd42f55d-2384-4249-95cb-8e9599458d50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 73).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f688f3fa42bb0a52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0699fdae-70bd-4852-a954-98548d5f0ab4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 73).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b340d0c34b6bddd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b755393b-af71-41d5-85fe-1d755bcf84ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 73).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6d3bfe5d63a51f37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e37fd307-ff85-4eb4-8da8-6326ad942aff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 73).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e1eac3f7c1d67ec2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cb09789-0d70-4a98-a7d7-280c53f1517d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 73).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '50d68e27d1b9fc7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb87d6e-397e-4dee-8d06-41627dc16c9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 73).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'facac0d62a93ca4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f2c052c-0760-487b-aa1b-114e74482fdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 73).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f342ec5b05117b28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b973f69-ff2b-419f-a0e0-70dbe538462b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 73).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5320a1f5530651ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('112f2135-f871-48e4-ab95-c25ce010005b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 73).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c61d74698528c100_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a28a1427-94d2-45ca-ac89-199b9dd6ebea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 73).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9b81ea95a20c655b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('592c206f-770f-4490-bb12-de07f4648928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.177.0/24 network (variant 73).', '[{"id": "A", "text": "access-list 1 permit 10.30.25.0 0.71.185.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.30.25.0 255.63.63.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.30.25.0 0.71.185.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.30.25.0 0.71.185.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.185.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '14eafa750db190c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('457807aa-6e0d-48e4-81b5-5edf8274c585', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 73).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a4c5a2e8060bce7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2eb5f72-fd7b-4808-b369-b622cf8b103a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 73).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3ab10e88acb5002a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('627a62ab-4ada-48d7-8e6a-f73f2746c6f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 73).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8f8e586d1a4eb8c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15db103f-8b56-4e4c-8022-c4d7406bdc98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 73).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4d5c85da9f874685_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fc90c1e-215a-4230-88d0-7f666aa8770d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 74).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '882caffe478e7f13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88be35c7-a313-429d-9d5b-880e2084b9fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 74).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '03f4ef4ebd755848_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('218aa839-8abc-4c53-9431-ce35c74fcd56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 74).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '753587f79a7a8e8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1491bcad-efbb-4ef9-9511-95f2d1acc46b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 74).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '49ff5d83609449e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0e689cf-9b87-4e29-ac93-8e7075c9fe7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 74).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '182d74d8e20d18be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('449ea477-8b81-4052-8889-4b554156fb5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 74).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5d9e948f149bc690_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33c70180-4d26-4163-8b71-c65e47630c3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 74).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f764f337918f5cb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7e42778-441a-4601-817c-080849eefe33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 74).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4144c747c5a6b021_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b868111-f987-447c-9698-34645d8e95bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 74).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4c2557442891d84b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f53e8305-578c-405d-8fb2-42c6c66ef9d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 74).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '87702709a571cd2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e961055e-b249-46a3-813d-fe0e4aeca14b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 74).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6af29c8c63cc14c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e31d6367-40c3-4b02-8d59-86e8534ea1f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 74).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'dc50a0f1cd13faaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c55b59e-09be-48c3-8713-d40cc62ac360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 74).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd76256cc00d95bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca57dfc-b8aa-4f82-b1d0-b3915177891f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 74).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '696b3ccabbc0da77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71301c39-e8d2-47ba-b56b-36d3644771f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 74).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '739408c21fa15fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca710e92-7013-4d6d-a4c9-59e88026c05c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.131.45.0/24 network (variant 74).', '[{"id": "A", "text": "ip access-list standard 10.101.186.0 0.104.179.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.101.186.0 0.104.179.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.101.186.0 255.178.85.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.101.186.0 0.104.179.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.104.179.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '403b9fde3b28b976_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e67a717e-cf8a-4e1a-b771-06be7a97fa58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 74).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ba0cad5235cec4c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41997ab3-9ce0-468c-bda0-0a02cd4c338d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 74).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd8845f582d92e4fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('364a3298-4978-4b75-a3ee-b32c016f9dd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 74).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '34c32b4ce3e56b1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a19d8cfb-54a4-48b8-8085-638c24bfb8fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 74).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '482725cc37b0a991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22f4f206-1106-40c6-bc40-f3a86f8b5d8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 75).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f895e1e2faf4f63f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77d3434d-b453-4b99-b596-b2fec62dcaff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 75).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '33466e52e5d44098_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('259d8e32-517d-4eb9-9ca1-7a8fe35976cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 75).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '901db31c160b2535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6d39c2-ec06-460d-9178-8b8213e0628e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 75).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7e391da418d1aaeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c69871a5-bbeb-4930-ad76-146d0c92b003', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 75).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3fd28da686905845_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eca07766-0951-43e4-9cfb-dbc986ed30a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 75).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '311164d9728eacff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c5fa30-4d69-486e-8197-e265083d5cb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 75).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23d3428f531b8843_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f49c777a-bd34-4c30-93db-d787b7ecebbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 75).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fdcdb1504c5c04b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fdeb898-11a4-400d-bde3-e43a2135bb70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 75).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '938e38ba0f0e8130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a8a4a8f-c89d-4666-8e8c-00d70db2038b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 75).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c51ea47e2c695033_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fee3455-f6e2-48d4-993c-8530231e1894', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 75).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a1ee6d7d1ebd31d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da01f0c5-58d6-4d49-b7bf-e1c058e2ff53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 75).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '377735540d37d19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c08c85-9743-4a4e-8f36-b9f2551f2cb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 75).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f9a0833e630b80d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3015af5-2903-42c6-9a4d-b3510009e782', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 75).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87777330a7124d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d25d9b0f-e8c4-418b-a36e-d34d508145d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 75).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '30c4dfab47866580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca507a60-39d2-45cb-af13-e6e471a7dff1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.123.116.0/24 network (variant 75).', '[{"id": "A", "text": "access-list 1 permit 10.48.20.0 0.161.168.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.48.20.0 0.161.168.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.48.20.0 255.148.74.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.48.20.0 0.161.168.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.161.168.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dc6780a6ba26d53f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fb929a2-fead-421a-a1dc-cf56b577e216', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 75).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2e152793122a96b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21af58ca-e2b0-47a6-94fa-61f394aa05d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 75).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e41fa8fe2622fc85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d7ce7b1-7cf9-4495-b42e-f06bb3847c7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 75).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '82bc59993335b866_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1df2567-3e81-4495-8174-df30199846c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 75).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b8cd396ef839dec8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0992699-4d88-4231-95b7-3a9c43a8cafa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 76).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd1b5da3a17892391_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec35880b-475a-447d-8e59-b5370a4e8194', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 76).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f24512ef42ea1a5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5f0a2a3-7fac-49b7-9eaf-4b8dcb9ca976', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 76).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '163e0968b0917207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22dba850-9d54-4f50-b91d-aee9ef061842', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 76).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '52487fa0a56669d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('822f57ea-9f1e-4f4b-beb8-17183fbee1be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 76).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c5e0e0cbbbeebdba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c82ec98-9eea-4fa3-bd33-94dc6fc6d39d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 76).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0388219843b0a5b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02e9a2d2-79b4-427e-8c8c-636fe0af70f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 76).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '73318cee85e83d3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81259429-8aa9-4fcc-8f70-79d85270ad81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 76).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '66b3166239177b4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27288212-4946-43d4-a89f-6961581081f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 76).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3d7867aad99dc53b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66aabf8f-b3fc-4319-8399-5304a46cdd72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 76).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '927debf7a211b0bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81023e65-4b6e-406b-a2a7-e180e56213a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 76).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd5262feba9cc016f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d76c06-f9c6-4ce8-bb80-ea4c83ade806', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 76).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '94e135df671d1d75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05eb4610-b516-4a92-aab8-fdefc544c89e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 76).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '82e6aa34857ed86c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed6bf0c-ee71-45f7-909b-d2f91546e6bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 76).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '947224b059edd47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0dcdf71-8513-4fea-ba7d-15f9362f2715', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 76).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '095610c4de7c4e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56f690be-074f-4d30-9306-0654bbed66a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.55.45.0/24 network (variant 76).', '[{"id": "A", "text": "ip access-list standard 10.34.226.0 0.35.196.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.34.226.0 255.231.31.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.34.226.0 0.35.196.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.34.226.0 0.35.196.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.35.196.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f2a67fd4c79c16e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ba2360d-8588-4227-917e-8d05a019af34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 76).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f292325f90f58f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac02f4f5-9f44-4b6a-b658-204d21f9c6be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 76).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8c95075f6f2309d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1497b2b2-1674-4286-99aa-a13c6e8b1f7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 76).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd271fc5dcc5f5fdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('411c18f6-1830-437e-b58a-f84313f935bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 76).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0d010e4f594c4523_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3caa3368-2839-4616-9b82-cbbeb2374b86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 77).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2617952311392883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efdfd8e0-1bbf-4d0b-b5e1-a392714f9c9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 77).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'dd5506f53f4ad2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbdbe6fb-3a19-4b03-9107-ce6635026650', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 77).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '93b3edf0da07611c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5818ed45-458f-4fca-b508-b83dcce22131', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 77).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '96ef6f9a9b1121ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1367c500-1d0d-4859-8f37-7af56be802a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 77).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0aefcc776b252076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74aa9e81-01b1-4f5f-a599-9b498e168a94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 77).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16d6930f8db33ac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4eb889a-1d0f-4bb3-a61e-530388f5e826', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 77).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '373bf4aedd8a0d81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3005ba1-1652-4029-b1b5-ce2fac7edb13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 77).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eea925fa61386e57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87bab873-9ef3-4cd9-adcc-a2e15d760e16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 77).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '00bfb9ccc04e3825_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7bd29b8-5fed-4077-9c52-17b28280561b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 77).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ce9525c58c77d658_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dc87e8c-27fc-40a4-ae29-b393b077f5aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 77).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5fae237f0145030c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd7afb8-94ed-4d28-a88e-e553aeba876f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 77).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '298a8bb4a83b42e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ea9c151-f088-456f-887a-3aa401dfeacc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 77).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '90e10e354a220bc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e43eebb-8209-4a9e-85fb-5c14718485a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 77).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4c090d12bd3a561a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2bc0667-c3e6-4bf1-98a0-f2a98211a3a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 77).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c28780407cc2b0e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efc0da6b-0552-4491-9627-54813e205091', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.102.28.0/24 network (variant 77).', '[{"id": "A", "text": "access-list 1 permit 10.61.12.0 0.107.77.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.61.12.0 0.107.77.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.61.12.0 255.117.159.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.61.12.0 0.107.77.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.107.77.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f7e9135bb9ad76bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('192f2c12-10e5-4f71-862e-cbc057435b0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 77).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b48df22a5ecfad56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ca3273-c562-4b83-8c62-f97771452da2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 77).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a138015f822c72f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f88f1f4-8a05-482c-a341-91af9bc23b86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 77).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e7bffffd10c09d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350889b9-36e9-4b56-8615-8dcf6d7251fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 77).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6866a77ce2eca5fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03ad8178-7f5e-4e52-991d-c7748bd5c9fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 78).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '035353ee30f3da19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c397e5-fa31-4091-b764-3072e21938b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 78).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee6af40e5b533184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6b4e31a-9f3c-4151-9778-6cc0165b2d7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 78).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'b61d3935806cdfe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('559cd271-6f7b-4961-8d6a-396bb265a8a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 78).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f256c7d180d33e5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c0f6ee2-c534-48d0-b78b-fbc2c29ad09f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 78).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7f9243d80ac9347e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8975b398-d1c4-41f6-a042-564850d3323b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 78).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c01e7b005182afe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a6ea8d-9d5a-412e-b1b9-239926b673d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 78).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26d86e7eacd5d6fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51b34344-c9be-43a9-87db-0ea66ddf97e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 78).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3df2efd28a4b283_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42fa7136-ce47-4dec-85f9-d68ee6b2eb48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 78).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '56e2ff3520a2e568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d31439b-e290-45e8-add5-d24d1a7508fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 78).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'eb347ac5adf0525e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d3e575d-12d1-4e22-863c-d2016507f4a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 78).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f2c7598790c3f877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f705319-13a1-46c3-b77a-b869f027e0ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 78).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a4928d3677e2d905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e42cfa8-37b0-4048-9a04-cba8be6e11bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 78).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '77401d859d36541f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f7017a0-9b34-4efb-8791-7540ebff3c00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 78).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f77775a2f863746f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('104f3832-a438-4be5-8074-b60fd4dcea88', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 78).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'cff8dad20428c623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f95e42-d78b-43d9-b5e5-c0d8d3e4cdff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.57.25.0/24 network (variant 78).', '[{"id": "A", "text": "access-list 1 permit 10.42.70.0 0.239.113.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.42.70.0 255.177.86.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.42.70.0 0.239.113.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.42.70.0 0.239.113.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.239.113.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aaf02c2d771b090e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68dfb4d2-295a-41f9-b20e-44b02b721fd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 78).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a594562f68e3d809_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fad53480-913e-4207-bfc7-513ab1c99235', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 78).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '461eb68d49a3442d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad365fbe-e786-4e43-b394-f54e1234ed4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 78).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'eb9cbf24b4d0fd7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09188230-c45c-4aa9-9429-4faf9e360f7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 78).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd418b38b354aa43a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa4e5052-c5a9-47eb-a1a2-27554b37d597', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 79).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'dd43ec31e6de7513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('823dea73-8f8a-49ae-8eaa-d407c4a7586a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 79).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7b2435068d75c647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('860715ab-0fae-4573-9672-fd34599f78d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 79).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8246cad4f0d24c6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6161c4e5-1447-4a4e-903a-502b178a6ebe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 79).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3fde76566655273a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dc21f9c-7e2a-4c05-a5db-9da67c49c392', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 79).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e10c996cf866dee4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a95181-863f-44e4-835f-c3457637db9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 79).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '088b1ebebdf073c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb6e075d-35b1-4645-8ed1-402ccc68c413', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 79).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ce20bb77218bae74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93991613-f919-4582-8cae-475386541a29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 79).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a132b014da802154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5322e603-3ed9-426c-8699-8547f84d8737', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 79).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '006aeaa9d274fea9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bba0150-ca9f-45d5-adca-4edeeb73b3fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 79).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f0b1a294693a9937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50d182e2-203c-48f6-821a-3095233f4e56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 79).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '588dc9d8ef5a05fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b8ec956-2235-47fd-b8cf-056d5714a63b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 79).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '352784059351b059_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b80c24bb-6ad5-4caf-8fcc-a5eda1b36398', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 79).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '75bdc6138ccd097f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35e0bc39-0704-4fa5-854f-bc65974a1039', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 79).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5f5ee52b00ec86a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb67e22-d33a-4824-85d9-42c5672ad41e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 79).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ee3d8e6b06aab77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71129778-981e-4470-8ee4-7c878a5b2cee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.209.67.0/24 network (variant 79).', '[{"id": "A", "text": "access-list 1 permit 10.191.45.0 0.19.160.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.191.45.0 0.19.160.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.191.45.0 255.164.81.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.191.45.0 0.19.160.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.160.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fac6f5359fe0d409_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8d39bc3-1692-4074-b133-15855e423d42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 79).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4dbc0e4123544113_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f6dd82e-f898-4954-9d98-5804c619148b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 79).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ba13eab1af574022_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b9f804-2e27-4198-a454-ccbec99421c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 79).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'caf193a79b6c02db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab97ff0e-e2c6-455a-92ff-bb3714fd9a31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 79).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cb5016a354adc137_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24ce8550-84f8-445e-834c-55cd12292f6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 80).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4221d4a023c0f65c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c8339f0-4ce7-4b74-be81-ee08685edcc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 80).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd4e51a70f2acfa7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6196539c-993b-4d46-a857-df9da3ac01fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 80).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c4f859861fe86bbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4053fdd7-10a2-467e-bd23-e3ae32a8ab67', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 80).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c828db7abb20733b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0122916a-d3c1-492b-8bbf-3ff2ac54a799', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 80).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6eaf52d730bc69aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49781b39-39f5-439a-bb49-3a55d030bcb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 80).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '78f921821bf152e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('332d041f-c5bb-4fc6-9b7d-8b74fddf5f08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 80).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '265bc0fac7ac8665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf47d55-a44b-4f5e-a1f6-4c2d427108c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 80).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90edd73338ed824a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e07031-baa0-4dac-9304-6f9d17cd5946', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 80).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '10395d3ced48ef23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9fa41ee-b12a-4855-aa06-598f79e9f92b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 80).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2a658d48ec7b893b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8bbb86b-40d5-4bf1-98bd-fc90ad371e74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 80).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1a3f36c5a3b9709c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb6a5bca-2efb-462d-8888-9ac241c3d86e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 80).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '5eaf5ac0eb50e787_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8252aa30-3f5f-4ebb-80d9-de07dc59c278', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 80).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '15e64d9eecba4d33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bba77a55-b528-4364-823f-015af5ad4c0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 80).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '96df2330f31110d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1458728b-9db5-4c3e-bf6d-13defb56929d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 80).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'cd1c1b03a5dee8fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf50196-6134-41a3-b74c-589b2d0a7e77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.247.0/24 network (variant 80).', '[{"id": "A", "text": "ip access-list standard 10.168.64.0 0.193.245.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.168.64.0 0.193.245.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.168.64.0 0.193.245.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.168.64.0 255.177.255.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.193.245.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a2327fe18f2934f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('190a054c-9e99-4d04-9beb-9f174ca579f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 80).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f74e3e7b2d5aaf90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74147038-cba4-4ef6-ba19-cf50fe3a50ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 80).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5534ffe01bcd2dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf221d77-76ff-4878-ae95-aa735328c3f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 80).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b7cd7a644c62121c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aad372e-56dd-4ecb-a07e-9d2872698472', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 80).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '41b1594402e8c512_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7017972-e9cb-4a13-ae33-1154c2ee5e53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 81).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2ef1e860c27b9273_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a015e1b-b6b4-4b32-9faf-6a59b987fc6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 81).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ff557ee5c6c80392_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be842f39-514a-4b71-8536-6e2fe80ad0df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 81).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7ad10c25c62f3b6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e3709d4-baac-45e2-a668-583e2b15cd79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 81).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff17a1375e1a4fb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3961c582-163e-49e4-91b6-5bc364e9345a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 81).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b90eb09c74f2ced3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('969826d4-36d7-4655-8f40-149f8d97d69d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 81).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '46ef8227f624e394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72f2824f-a07a-4ee2-9efc-1f777725654c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 81).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b02f6c6dda65c218_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89a499f1-7ae0-48b9-8a2e-e17fdc162f20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 81).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc6c5c12fdd2e1d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8607723a-d4f0-48d9-9d4e-b01cfc9213f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 81).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '83c202d04152c360_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cbe6f1c-3bc3-4d7c-8e64-67905f795ea4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 81).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1cb48d4d07a0091d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a48453-3647-41a9-ad02-d361ac8c4896', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 81).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9f433cca00972660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('544d655c-e5b1-45f1-a969-91580188a09d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 81).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a2d8ef5293943999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4a9473-7d33-4e12-9aab-020e7938d773', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 81).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '88b7154416a2ebc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ff640ac-e338-4cbd-99a6-fdca943e03ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 81).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '63b637f8a15e668c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc87edad-4282-42cf-b3df-dda540a92afb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 81).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f22d2ee23d013828_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b21d8273-5de8-4931-9c1f-2da6f1aca8c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.240.250.0/24 network (variant 81).', '[{"id": "A", "text": "ip access-list standard 10.108.59.0 0.51.232.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.108.59.0 255.34.122.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.108.59.0 0.51.232.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.108.59.0 0.51.232.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.51.232.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2ddf95ee127eaf1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98c424d4-463c-47fd-9462-1821ff1f0c92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 81).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8bf78d106f0a16d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32824e4f-a74b-4455-b639-29da81905d77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 81).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '443ee0495f0ad8b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba090fd1-3573-4ba9-aa5f-652f780e3ede', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 81).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '88d7a9a9cb542f98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9118974-cb31-408b-ab26-31ad428d0a8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 81).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd2b8fe25d8dd44d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7c4ea1d-bd31-4cdc-93e4-33c816539d14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 82).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd24e44c3f294590_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed563424-a23a-411b-9d6f-1b6778433984', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 82).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '84845e69dfeb8b48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd35b99-a21c-4ba5-8678-bb7bd0494aed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 82).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e652a86cf4bf57c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dad5be8d-265b-4b43-ae6b-b820b5aeaf00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 82).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd4bd121d7a041267_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97eb6e64-ff54-4981-832a-fb29965469a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 82).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '34852b96cdd6cda3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac3b1ed-f45a-4571-9ded-2c345b5f8aaa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 82).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '993b85b94d886793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d60cb14-2312-47a3-a641-711638eef41f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 82).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '285739c53e482b2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c453e6e-69a9-44b1-9e0d-0caccfc0ce87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 82).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee263c610a5a6e28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec831cdd-42a2-445f-9801-afbd46df6df3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 82).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1dddfb5bbda8fbf4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c900378e-5cd0-4b14-9b0e-45b8b950162f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 82).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3fd44d0209731004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd590fcd-99ea-4fbc-be40-24076608c642', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 82).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '37e9447cd605f1cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e85d7d-1483-48c4-bd92-9c61fb8cb575', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 82).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b89ea232c98be0fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7192ff63-c349-4fd2-ac2e-af10bfc6e898', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 82).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1e058c277533d651_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c26c13a-260e-4355-8624-15127eb47677', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 82).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd01ba4fe3e3b5865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b09e7105-f084-4939-b34a-379ec35bd46a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 82).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b20fc9e489024244_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38612eca-a44e-4558-a93a-6c62535e3827', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.70.179.0/24 network (variant 82).', '[{"id": "A", "text": "ip access-list standard 10.124.173.0 0.178.20.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.124.173.0 0.178.20.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.124.173.0 0.178.20.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.124.173.0 255.186.43.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.178.20.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c1fc111b7efb6b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de3b492f-767a-4236-857a-e608fb0ec4ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 82).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '85060a26e736868d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fa012a8-e6e7-4859-9aff-f7c91f0c8382', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 82).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b2836fdcb870f301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1093bba1-0763-4a87-969e-e8377f2a5cf2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 82).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c4ec848c16e147fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2933498-7e46-4b5d-8ab3-206138e0b1ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 82).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5513e5db11be50d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73f24655-4d2a-4266-9481-75cf592a981b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 83).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '82461ce141ea87f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b0dd92d-8a80-43d1-a2c3-c49d02a8a8cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 83).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0b4f5a66406e2dee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daf569f1-6d19-4ce8-8ef5-c51eb0cc0493', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 83).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5e14e4f9f39de0dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16093c0d-2f2e-4505-92b3-6f90b9a00541', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 83).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9894b5d68a087604_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e88ba40d-6de2-4fdf-bc56-b6163f96afc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 83).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4fe1e75fa994edd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aebd7b0-49f1-498d-9719-bba34e847874', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 83).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef4df483552e7a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9e6d0e7-1c6b-4ee8-88f1-736988d810d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 83).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc44203147ac5d1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0610c2a0-acc6-4d85-86f8-26291993b401', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 83).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8639a2bfe73ff0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76657d6e-94cb-4872-9e67-93d9fd5511df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 83).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a0bdf73e1cec4a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d0afafc-8235-45d1-82d7-d1e69ac8b2c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 83).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4fa04f1144963849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e1c3e9b-52ee-4c59-b762-58e10c828fbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 83).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a8270becf3b16083_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fadba34-74d9-4ba8-a1eb-5a28e2b17cd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 83).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6cd996cc747f0e89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0a8b6d2-e2fc-49e1-a1c9-a569ac3cd3c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 83).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c510fc793f2a6a7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06deab27-60ba-464e-ae0d-b7a50a160414', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 83).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd6fc31d1a3563585_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a1a5e1b-39fa-4d9c-b02f-11aa324a1b64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 83).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '08e4abb452d21d29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a1d0096-b6d0-406d-b07e-e6b6a7f8bd94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.155.27.0/24 network (variant 83).', '[{"id": "A", "text": "access-list 100 permit ip 10.26.230.0 0.100.116.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.26.230.0 0.100.116.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.26.230.0 255.184.16.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.26.230.0 0.100.116.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.100.116.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f4a0bd16a1a06ff8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a0c63bb-589b-4e72-84bc-6f726a27898d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 83).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '01d7cec62bf43caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de01e3df-1cae-4d8a-8cfc-46db98ce5688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 83).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c012e3f21a15ad35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7019e2e-1811-4cea-a956-b2282d55b9c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 83).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f42c15a5a74ef35c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1428f07-1485-49f0-8c5b-4d820775c3de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 83).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '337ccc39dd0df13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86789e38-1e37-4409-8b58-724c3a28fbb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 84).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '48b6895bd20df3b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f463386-722f-4200-84a3-a6a95d97af04', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 84).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '763ed946acb7255c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f02312cb-22be-480e-8c5e-7689cee90e4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 84).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '85b8182f532d434a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea74d8cd-5684-4967-9656-601e2d0854f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 84).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd23a316ddfb83841_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b85a0ef-b621-42c4-944e-ad5d463e7fa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 84).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8f18e5b1e27e7c5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3fc7bbb-38ae-4ab7-a97e-36a1451a28d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 84).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a467bb98f7bb96ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f78855-4776-48f6-b703-e4e231955e9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 84).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '15491c9ecb948d05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('516e5dc8-e1a1-498b-b4a3-64195194c36d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 84).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd633795a70e2b3e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2dbbba7-6b80-4790-a316-39a060278156', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 84).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6f45efffbec2aba7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13b72711-60c4-428c-8c2f-e3b037b1d9a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 84).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7a161f3bfd3e2d57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa6403e8-b63f-431f-b0d8-d4584d5bed2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 84).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '911d0a40376c8c77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c942df-07bf-4618-b841-060ca57fea15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 84).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'c0bde905fb0c634e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9949fa74-0e5f-443c-88dd-c8ebc3a52a5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 84).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '46064d90395eb171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b28ae96-fbba-4522-8f49-dede971643d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 84).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '13869c7c770c68c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('522238f9-4dea-40cd-9126-081a28360d9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 84).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '610d3fc92463c1a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('994f61ce-98f9-4999-9a65-2e19bedbe36c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.43.21.0/24 network (variant 84).', '[{"id": "A", "text": "access-list 100 permit ip 10.24.113.0 0.191.159.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.24.113.0 0.191.159.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.24.113.0 255.7.131.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.24.113.0 0.191.159.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.191.159.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c52a52b2ed6b19a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fec8daa6-a966-4320-ade0-28d3ca723792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 84).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd8edadcfe4cc5933_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea5e559-8864-4607-87da-360b35094393', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 84).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5a0b406ba94ab2d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb8e7e75-d940-41a5-901d-8ecd25e228c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 84).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c981239b177d65dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ac2fd83-8e25-4251-b7db-6fcd57e5824d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 84).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '15eb30464030b0c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('244f7314-23d5-446d-9da5-1cb70fdd27b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 85).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3215bdfe548c2f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8086c643-3031-4441-ac81-04d4f9cf14b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 85).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9d23351755c13207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f412f7ba-74e8-4cde-91b8-3e84c7b9f5f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 85).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '2da20be19a8997b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a26866a-2815-4946-aeef-6ed1d13316c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 85).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd91e252f0b8c85a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63592de1-3708-435e-ba38-17a0f859ce6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 85).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '48fe748554e553c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b116efa-fa77-43c8-b328-523b3493d598', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 85).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e25631a14d5777d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b380857-b5db-48d6-89fc-2f33da0a9e01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 85).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fb5051c88d1aef6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f62bb7a-b89b-4d77-956b-a729abb029e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 85).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3e272f7c6ccf7c9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a71a507-ad1b-485b-8937-7580287bda24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 85).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7b741b02428b356c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b409301-6251-47ce-a89d-e584994c93ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 85).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b9142dc56e929a00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72cfdef4-65fc-4f05-a84c-318a2c16fcb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 85).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '036e88e46c5e5518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09d64720-56a7-41d2-8ec2-79c1f89e81c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 85).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'aa3056c11a78d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5bffe01-10bd-4efd-868b-7ea93fd449fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 85).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4db3c98996dfd4d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f4f91f-06c9-42fe-8be7-9a897f066f65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 85).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed0950ed40843fd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0738a778-f620-4c04-857c-50c74e55f34b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 85).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '897b817c3b8c5f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22f950d0-a307-486f-bd06-acb08edc00e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.35.123.0/24 network (variant 85).', '[{"id": "A", "text": "access-list 1 permit 10.129.155.0 255.237.101.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.129.155.0 0.62.34.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.129.155.0 0.62.34.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.129.155.0 0.62.34.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.62.34.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd71501418e7f7006_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ccefdc-c1e5-4433-ad82-af47652aec51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 85).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0b2b41c761353019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a598e94f-8b22-4a20-afeb-135257eac752', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 85).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0f496b7660f67fa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c02d2337-9072-4370-a70f-e40032da0e71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 85).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a45430e8bc0ba74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbffa356-f6e8-4396-b67f-caafdd585861', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 85).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c02c0bccf3bf0fb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('822de788-8960-4d84-b7f5-334a396a7b8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 86).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5bcf9cf83ac8919f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e792a88a-08d4-49fd-b3c8-f382d52ddddc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 86).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2424974df557f400_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd5a523-379b-4a2f-ab85-293c3b011614', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 86).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '2e9a801c918ce9ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed842c3-d1c3-4c84-998d-c1124adbff19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 86).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '63a17c793cadc4e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('128d8879-803c-43c8-8fb6-79f87147ab94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 86).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0bc116bc0f90f19b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6189501-1c22-4083-a2d5-82c099f8b013', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 86).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7b5c40a18ab46dec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2eb2b88-1aef-424e-8466-af40134b9129', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 86).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '54f080a74afafdf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43143f5b-b671-452d-9a51-f517a8edca4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 86).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '366f3cded76df7f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fc719c9-247b-4c44-8abb-cb5ff6d5387a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 86).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c945115ae4d7007a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eb84996-3161-4a90-9d23-0a8e6681d0af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 86).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '25fe8efcee98645b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ee0965-d878-4634-a200-8aa31249020f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 86).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '065c0dea57b1a32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc18ac5b-f25c-4409-84cb-de77afee0539', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 86).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b39466811d7c92f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f69a50-ae14-4bd7-bb6c-902251545501', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 86).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8f4b0670a21747a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05a20d6b-d92f-4a44-92c2-4edd3eb60664', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 86).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ff92ec9341c5f3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('068db95b-ff5e-448c-b052-3fbbe39e432c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 86).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '64d140955c5124bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de31e467-3e48-4644-8170-db8205675387', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.93.217.0/24 network (variant 86).', '[{"id": "A", "text": "ip access-list standard 10.39.97.0 0.205.250.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.39.97.0 0.205.250.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.39.97.0 255.90.50.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.39.97.0 0.205.250.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.205.250.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a4a3c1d2fcbb24e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04ae2d54-c67e-4dc1-99f0-a128bcedef32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 86).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cda22f29bf7637b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1faade20-1bdd-4c10-99a6-bde2c6b10d51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 86).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '49f5c6fa7908a529_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3ad6d03-c45c-487a-9966-eec41d9f7791', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 86).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a9047bd821e8b904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289ee2f3-7a1d-4f1b-956f-c4935d436ad9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 86).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f668e918260ca5b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60352205-a264-402d-a08a-89129dc1ec40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 87).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89662abe80525931_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f23c98b2-daa5-48b9-be6d-e33be76e9cfa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 87).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b8c2c2114c90680d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b76b1ece-a511-4456-8b7e-7b22d4a21990', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 87).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7f4df362e861d2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('637dcd7b-4fe2-4425-aa8f-d50cb73f073d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 87).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e9ccd7f6c0168666_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecc06dbe-423f-45b7-9b6a-557095d3a845', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 87).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fdefdd52eb733a5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1943e720-e747-4c24-a62f-7024c28d9db3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 87).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '540defce61a89afb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e9d050b-c099-4c4b-8a14-9561f00a2c80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 87).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '903fbd5c585d7d02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9569813a-364a-4e17-bd87-884f0c915073', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 87).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '082319752dea65e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae149d8a-56f8-40ad-ab6b-56ce5f989a10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 87).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b25c8aafb7f9f5bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb1edda0-00fa-4591-8da1-cb822f8c3bd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 87).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c20320abfbf9a83b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6504881b-2ed0-4a07-b93a-585f9dd08f02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 87).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2849ca9d5602d403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e68649f0-622e-4b8a-acef-0296bd502217', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 87).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ad13c978b078a11b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4774485-bbee-4d39-9a19-92b3320bee33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 87).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cce896ec99125081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35006f7e-b002-4300-b997-418db5eadbf8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 87).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '655b22f5999e2d0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc4ef3e2-67a5-4193-9946-4e97f11073ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 87).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '472a7f877704d7dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87db27c3-1a77-46ed-bb38-7fcd23879dda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.18.156.0/24 network (variant 87).', '[{"id": "A", "text": "ip access-list standard 10.228.244.0 0.174.29.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.228.244.0 255.86.197.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.228.244.0 0.174.29.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.228.244.0 0.174.29.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.174.29.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cde2c51cd1fbba46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8e7c0e9-60a7-4da0-a41c-82ad3b6a0aa7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 87).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9d9235c5bc501f66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ca2f229-b4a5-45fb-b082-6634f51aa773', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 87).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7821405af015f0e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5ddb756-c3c4-4eb9-abab-3f74b2dd7fa4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 87).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6767d852efe13637_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29bfb2de-b36b-428b-95eb-e080f69fe540', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 87).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4290c0f18961beb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13eb2749-7c04-4a18-b3aa-0b71a5a6707d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 88).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd798f7c2c2fc16fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69abb05d-c065-470c-b365-0772ebec5c0d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 88).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '742877ce0fa9001f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe677e62-35a6-4daa-b878-3851eecf957b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 88).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f699dcc5b3d0becc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bf8cce9-1905-46df-8f4b-595af4ef49aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 88).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '909f125963a55952_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed7db18b-bbdc-455b-9a8a-e3e27f5bbebf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 88).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ca7f9df6df03354d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289b5686-251b-4862-9d61-dd3cd4140c0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 88).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '08c05a3462a21c3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90fe050d-a610-424f-bf58-72c351a032ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 88).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd14749d340d8ebb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff5e0509-a748-4bd0-8863-c1a71bb2e2c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 88).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '528f43fc8532b159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f71d3619-11c8-4bcc-8038-cff551e20a47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 88).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'dc0643d8ae238df3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f69cd8-69a4-4615-9fe0-4c4cf5a328ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 88).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '97110e7b85817ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6da8387d-3b80-4a63-94b9-779655213989', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 88).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5849ad848d6faa27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26f905ce-969b-42ec-8339-53d2a81193f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 88).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '30a07bb3af0f6eb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6813c1f4-e62a-482f-87b9-5386aca72188', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 88).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ff449b71974cd3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4999c783-4fd4-4c2f-a39f-0f5c1213564f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 88).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8cf41057655be76f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecf0e60a-0e9e-41d0-92d3-72ca8ef4cda9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 88).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3b36a8fc8d0f5b42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('188b2bef-2291-4207-a490-09a79cf48fe8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.180.185.0/24 network (variant 88).', '[{"id": "A", "text": "access-list 1 permit 10.101.98.0 255.86.65.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.101.98.0 0.4.32.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.101.98.0 0.4.32.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.101.98.0 0.4.32.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.4.32.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ef4ad0fa7b6542d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c32c2c7f-cb1e-4ccc-9ee9-30c3001580df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 88).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c01d87d5c874c47c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c1caabc-0586-42a4-b935-91030621fa40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 88).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'deffe42635767511_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4566296-7259-451e-8961-c04fee399960', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 88).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ed5f6492f985816e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d9c9c5a-7a2a-40bd-9052-20effc20d72c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 88).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '764bfca70bb01711_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf62f4da-9d49-4765-b68c-9c2acbf950bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 89).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6140faef0a1b9b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1fcc5fa-ea66-4902-8a86-818da5d13992', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 89).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c39bd883661a8476_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc435f6d-ba88-457c-ae4f-cb9dedebdcad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 89).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'b9232494125e9565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99bdd1b3-55dd-42c4-a3d4-ea71e5285c6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 89).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd527322a2056c0d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5afb896-e818-4369-90df-e2a98e4db00f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 89).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4d66578a7064b996_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9589e4a9-545c-4305-a45c-f4bfbb631799', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 89).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1deee54ddc24520e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bdab710-be10-495e-8aa3-48a76afe421e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 89).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6fa6089f25d9e59b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b54f8357-5f5d-4a39-bb7d-75e7865f0724', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 89).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5665c8963a9ebde5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fffb3c5-c04e-4e56-bbd4-45335678c28f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 89).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '35e7823c7473bec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e6d215-5dff-4ae4-a05a-2b14ad390d25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 89).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e3f16ac5f992deea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db9d2f19-7d72-4ad9-bd23-912b70e6ce9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 89).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '86a7d04784b07e38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41c45b6-c26a-4bdf-9b0d-a2241db26e2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 89).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '805971845e8bc004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc24d97e-1dcf-49b5-8e9d-34b4c2c7535c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 89).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '250ccf3160a05865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95110b78-2416-41b0-a8ea-18121059a471', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 89).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e57af55cafc5f3c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41c67543-2b9b-46e4-b34f-ce982860346f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 89).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1b829dce814dd964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1dcc7e-cb5e-4d19-a698-67b543c16ff2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.254.0/24 network (variant 89).', '[{"id": "A", "text": "access-list 1 permit 10.236.129.0 0.93.24.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.236.129.0 0.93.24.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.236.129.0 255.230.61.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.236.129.0 0.93.24.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.93.24.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8b1243cce96a6f6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f3b39d6-2eaf-4945-ac5d-c271352e0a4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 89).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6afdf4fae26f7bc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93a661bb-c700-480e-ab89-b19a076960d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 89).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2541210e85bdb15d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b3bb831-4620-44a8-81d5-53269843ffe9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 89).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '1a1d09037d6a80e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67f1d624-96c6-49e9-8fd3-552012fd19df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 89).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '78ade020ea9df277_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9951471d-c723-4d01-97ff-5a6ebfc3c376', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 90).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8d0245658041e0a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58480d50-fbf5-44d1-999c-cb83585be719', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 90).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f1b7d67c4fb624b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4f70455-86d9-4e69-aaed-ff985403c82d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 90).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '242ab22881431aeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ddcf11e-660e-42e5-a684-430ecedf3bb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 90).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f056085e7d1f35ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2ad6650-bc85-4b2e-bd36-7bc9c75762e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 90).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5c5f2a689b474616_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b0a1abf-2058-450a-84cb-f501bf654669', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 90).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b396a015420ee1aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5eb721b-1bd1-4147-b5a4-0d5ca61fd58f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 90).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a4689334b26ef0d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('144fb351-9153-4c32-9f31-6482d7952ba3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 90).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9d5f3f83b086b9a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e99af447-6bcd-4843-b63b-a9da4aaa1b2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 90).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '20ff92afed37f78f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3354afc3-948c-4d3b-b89f-3ab225735413', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 90).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '96bb3204abb7eb2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d45a10e-7cb3-44f0-83b2-f94c58d46c8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 90).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c4805e873f9bad49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f2d9759-9e10-40dd-8600-fd8675fce486', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 90).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3bf55cb13b95334e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49519ac1-2cdd-422d-8c6e-3f83a3a79c5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 90).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '463a6cea9d6b6e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9229a01f-2e22-42e7-b981-e7073566358d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 90).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '68846a6267e65340_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f540160-5b1c-428e-ac12-27775b89e421', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 90).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '12537d9440e7a896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a0c2f7-bd8a-4792-9e01-fcaed19cb81f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.12.122.0/24 network (variant 90).', '[{"id": "A", "text": "ip access-list standard 10.181.172.0 0.178.49.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.181.172.0 255.159.151.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.181.172.0 0.178.49.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.181.172.0 0.178.49.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.178.49.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b495e2cb9345b087_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df40586-4393-4aba-a716-3ac25aaedb08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 90).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e0badfe51211a47c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f81ad023-087d-4ff2-b99d-fb2ad825bfd6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 90).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd6e3bf93361ac04c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db9737e5-0a2d-4f8b-a58a-5efb702153c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 90).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '08f50bd84912efac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c00d35-178d-4ac9-b2e4-cb571ac002b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 90).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0e0a508e269df797_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cb7b1d6-9155-4868-aec8-f32d78bc527f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 91).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '433e64665495669c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa9b797a-ee4e-4f70-a707-297280798dfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 91).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bd81ef217cf8276b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6af25f0f-7edb-40c8-bbf1-318cfb4d8fef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 91).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '83e3c8762ec2336d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0df02b9-8cf9-4182-be31-da7387758623', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 91).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '590125b9721f442b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be7c721a-0039-4885-8553-c724434e463a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 91).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0456484825205b6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('317bf0de-16e1-4124-ba65-bd0e0a593cc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 91).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '17dc2f79a3ce2834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('744d9f78-ae85-4809-bb72-63a362062c2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 91).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5ed133d319267a8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4276a62-711a-4662-8602-3fd856ac72b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 91).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e0bf1b65754880c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3be29fd-783d-4838-8515-f76acaae99c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 91).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '86bed93d1ff6d1da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a74b8b96-4c37-4a59-9314-9231c22f076e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 91).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ea0748cdbab9919e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed7ff515-b9ec-4ba7-9770-f14275269f27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 91).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd07729621d8519ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17642f0a-1bfa-4fd2-9a58-e56cda271b69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 91).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fd10b8a7b737edce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('623b95dd-a1d4-4882-9030-c4feb9a0224e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 91).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd0a909df21bbc99e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('787cb860-fbeb-4720-8e0e-483f17b4f53f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 91).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '58f9b3a8c1e3c8bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d26877-f5f5-4d25-91d4-d4783beaab9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 91).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5485b8ebe813ff47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c655192-9a46-4eba-830b-dae3a6413c3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.232.10.0/24 network (variant 91).', '[{"id": "A", "text": "access-list 1 permit 10.120.205.0 0.25.49.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.120.205.0 0.25.49.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.120.205.0 0.25.49.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.120.205.0 255.20.72.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.25.49.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fee2704106233012_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f43bd34e-e478-4577-a8c8-dc40d25c3928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 91).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0220267bcacc317f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f45da32-3ef1-4da2-af74-5c1a622c60d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 91).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7bac8ce449596af0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98a19ab-077f-4b82-ab15-d03e5fc8e696', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 91).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9837971539bd6fb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac4f1629-ae0a-4ec4-9adf-eda2dbc6695a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 91).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '9ad5c61e49be6d36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('776fdddc-f211-4d0c-a263-f2cf0227d1e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 92).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ea9b0bd06ef8af22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a98b928-eff2-4f23-8e7a-c2f85b0cb634', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 92).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '214e8acf8eb0043b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0db2527c-eebd-4d03-897a-9128de5996e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 92).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5c81a832ca1a2e75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9747c13-e5b5-4b8b-af5f-bedf7c564e28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 92).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'faa30fc6db38cb4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dabbdca-3ea8-4fa9-9830-6d1e69333f93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 92).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c9d5c7df7af8fcd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceb99a57-af81-42f9-bdf5-f02bb3590515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 92).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8666535b50836e42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cde2e82-31f8-4e34-a694-966ade292d81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 92).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a171e01117027aa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce4535a0-b577-4409-b97c-1168f0b2b733', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 92).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eb1f66dd3a41b0cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4442a92a-f26b-4c82-bb1b-b0aa41ff1f9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 92).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cbdfa5314437d6c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ca8df67-bad8-46e8-bb9b-42e702131939', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 92).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5c18256355263bb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92f76867-4bce-4514-b5a4-7d2ab50f1228', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 92).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6bca8885ef2d6d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('572ec6c7-510d-4ca0-96d7-46044bd7c3a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 92).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '1cfc1d9c084df7b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6121b77f-13e4-437f-9e85-dfbd75d076a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 92).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1855c01e073c2b61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('685dabd9-5e18-4071-9528-b6152fc8fba5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 92).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '299cab8d7c49407f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fa049a3-062f-4bf0-9cd2-78a99446cf4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 92).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0db93352ef1da03a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8f948d4-33bf-49a2-9570-9488a89d5953', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.17.253.0/24 network (variant 92).', '[{"id": "A", "text": "access-list 100 permit ip 10.173.161.0 0.113.106.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.173.161.0 255.226.49.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.173.161.0 0.113.106.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.173.161.0 0.113.106.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.113.106.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dcbbfaa2afa04a07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931b34d4-de81-48c8-9c96-28fe9d2ce4a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 92).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b5992dee013ec1c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aa2e7a0-c691-4770-9b20-7b9d4d369dbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 92).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '188a0b79aa55f465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73850e4b-6ed5-4fa5-951d-b0b30a2c5526', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 92).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'edc06b0a5c244ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd6b7125-ed79-471e-907a-8cb421003f12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 92).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0774f8a2148655ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada4b1d1-fea6-48e8-8bb2-e02ab18f456b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 93).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5b94fff88794cb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd687df9-591d-4b0c-b1ba-c066e5ac2668', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 93).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aec0c615a5acad12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e7945e-eaa6-4dad-9748-cc6e90ab77b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 93).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'aac455958572b708_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10399f5d-7122-4b4c-b0b4-0ffc0ea218f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 93).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f7d2659999368c31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c7351a6-29d0-4882-904c-30c1d9c640de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 93).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b7212a13d2d25a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc382e89-5149-41c0-975f-74a168188276', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 93).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7d67f148992014a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b778c7b1-fd06-4a0b-b1ee-2231b5d56dcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 93).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '31962802b99a5f4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bc3e31b-15ed-4ca7-a86c-6ddbb7523cee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 93).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '11fdc1e9059cea06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ba6d75e-c5cd-427b-8305-1ab896c31f0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 93).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1d57694106894491_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7643fbdc-e3a9-478f-8be3-1ea25706c0be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 93).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '220009e61f847c6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b1b2604-2f35-4f4b-95d4-a960752bdf3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 93).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'bebf84713a7119e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daa5452e-26da-420b-8586-028803c4e5d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 93).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '8ede2708c870085d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10e69a74-d92d-4d9d-acf5-208caec9d6a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 93).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7af39823e67b317d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e022f1d2-e82f-413c-8196-9184b1400bcd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 93).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6a43132a617ec94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e76c0260-f525-4b76-abb9-a4d68e03d548', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 93).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1f3cb8615f35b5ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d21c94cc-8b19-4267-9708-05790dd229c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.27.190.0/24 network (variant 93).', '[{"id": "A", "text": "access-list 100 permit ip 10.122.65.0 0.41.70.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.122.65.0 0.41.70.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.122.65.0 255.252.250.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.122.65.0 0.41.70.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.41.70.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af15fac6035b58ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('407ce91c-7f95-46a1-a364-434e3ef1f064', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 93).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c626c2ae89b89373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('712b3304-c554-4118-8dc4-d92506a9bc01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 93).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '14a2678299771474_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccc37111-c3fc-4ae8-9ef8-b6e10ce529af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 93).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '57389e7e31962659_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304fc261-7f05-4abd-81cf-58d89285f7ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 93).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '25eb2acab9f7bd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b426392f-d1f9-473e-a24a-c58aa0559819', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 94).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4435fb995e83c560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdc467d4-727f-42fa-af7f-184bf7508ffd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 94).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3b6588669e352384_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a33b5c89-04d4-4b60-b6cf-e386ccbadf7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 94).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'deacd2b9ff572e68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b217de3-8706-48ee-9757-068b2db23f80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 94).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2192f38407130f4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4dca4a7-8b3f-4518-8833-7f2da370cf23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 94).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3abef9d94e158ff1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc17e0fa-c8bb-4ca9-a8a6-0c339013c7af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 94).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef1f7ffe4b34af61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72a32175-4213-495d-888e-427792ae3d3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 94).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '186bd63546671d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eca59aa8-7bdd-402f-8de2-b62b2e94c5c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 94).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '652e01f7ff20a104_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52ab235e-81fc-45f5-8763-576a37eb2b01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 94).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'abdb67fb84c978f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0de40872-ad94-4126-bef6-a3067d116d33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 94).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b05d18d3e0ce6f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4aee280-fa72-4049-8efc-e00557ff4468', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 94).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '57c7c12b97b0500c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1359241f-d454-4b81-917b-d14f2054fca3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 94).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ba643f20b592ba59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd84b110-5e51-413a-a32b-42d0dade2e8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 94).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9873c55ab3c3615b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39c356bb-2de3-40b7-b3f5-0af46532467d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 94).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bc90cef233464e90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb5fe471-9cec-4562-8dde-058dd7e6e5fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 94).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f57e9c1575303d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86340cab-7193-4850-b185-169c951f8ac5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.195.125.0/24 network (variant 94).', '[{"id": "A", "text": "ip access-list standard 10.161.54.0 0.84.254.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.161.54.0 0.84.254.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.161.54.0 0.84.254.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.161.54.0 255.83.16.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.84.254.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9fe8ff54317586d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c67b921-1ff3-4e3b-b3b5-a5bdfe039dfb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 94).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9fe199246e692c36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5afd127-3d27-4a02-a605-8e434f8acb9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 94).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'afec3e60b01c0f08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d2d109d-eab4-414c-a376-73df585df53f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 94).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c27e3181eeaae33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e8d65ce-cfa1-48c1-bde7-5894912e5a08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 94).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '55357b97f4440663_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd2675eb-a4b8-43b0-8b39-97f5a24f1008', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 95).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '483ae470e59cb26b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab00e000-306b-4b19-8a40-ca94c0fe4337', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 95).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '483038db30caf4f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c319db9-857f-4f77-bd60-ce257012e3ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 95).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7459ed31fb98a763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfceb65a-3bd2-4316-a83a-f0ef02b50705', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 95).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c28eab1dc4b38c81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a68321-2ef9-4c43-aa18-feffbe63e3b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 95).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4c48b7e4f96494a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97b3c07f-2afd-499e-a754-73a3f85d3e5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 95).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8dc54cf17c61749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('809895aa-bece-482a-b2d3-f3523ab36ba4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 95).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b8eac30f6332b41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe319129-de09-412a-b7f9-0e9b984766d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 95).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6fff6e83053c2788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a715a0d-c4bf-4cbd-9808-50c056593c71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 95).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b2303fcaad7f1d7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5edd6eb3-ab6a-4195-b086-47d02122566e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 95).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '73ba167d474a23b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8f12547-40d5-481d-a542-1a26402369cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 95).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '245c11aeb23af3cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b11c713-6914-4dff-92e2-587123c92bee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 95).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '0be5fa1c20944f93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ee6bfd2-a2a7-4141-b146-b62922f13815', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 95).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6a8638e7b92692d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f06e6c-d974-41e6-9591-07e1d62f7e73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 95).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3ab391709258a902_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cfb3647-761e-482c-97c6-b7c2fd7be349', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 95).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0ba6cd971ee2cdc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e71689a-054e-43ed-b4bf-59156d8db629', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.56.158.0/24 network (variant 95).', '[{"id": "A", "text": "access-list 100 permit ip 10.84.76.0 0.104.100.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.84.76.0 255.158.74.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.84.76.0 0.104.100.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.84.76.0 0.104.100.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.104.100.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cd09d52934ab2706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('068ee7bb-a4ce-446f-a0b2-427d9560f812', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 95).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '93d389a84a5bf925_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('912698d2-0fe7-4b5a-a9ff-dd86cb3e89fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 95).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '52c49b576ea8621c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f580e3-6cfb-4d9f-a6be-6056c597e733', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 95).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f978a1c9239ba366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4639b1b6-91e8-4341-a997-a05478aac401', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 95).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5debd291582892ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c679a07e-0971-466a-b31f-101553c69619', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 96).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd76f458e6320425c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf89b89a-2a9e-4736-ade5-a4a13766f099', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 96).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9744e7f887db0f15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff5e10ab-e6c0-4008-91d7-5dfd14b695a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 96).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '297d495227b3c7bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b020ae4-887d-4469-8e0a-712d49aac2cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 96).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ed12b4a22ed76433_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbe6f235-a5ba-465f-b76e-bb36c00e2ca8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 96).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2090b8e768029f12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4845d384-77ea-4d70-a662-0fad656e52f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 96).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9d58c8c1475916ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a527c13d-fbcf-421a-8336-33881164228e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 96).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9db406fdcbd8d824_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b861db28-d5be-4675-8593-7a24caf0c07e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 96).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd2340667542eaf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d8d5f3-32ff-49b1-a0a2-24e1161540fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 96).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'dc2e35b06973fc54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26ba4aad-b1d3-4777-b954-4d5193518d79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 96).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '775a33958a1cfb5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b4a0343-8ac7-42ae-a726-d41823ddf75f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 96).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '817397734c8535d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6578aa12-d18a-446d-a970-f3bd95f807fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 96).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '38c77b9322b1bc02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2284483-9a7c-4ff9-9f77-02f1a2185b72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 96).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9cb33ce3b91f3453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c9ccaa7-73a2-43a2-81e7-37127742e6ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 96).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '86044c4d6249a524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb0b3c0e-5fe5-4143-9474-373e5cecdbb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 96).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e755d9fcbe7d5daf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6936fc67-d17a-48a6-b210-faeeefbd8585', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.186.9.0/24 network (variant 96).', '[{"id": "A", "text": "ip access-list standard 10.166.153.0 0.162.39.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.166.153.0 0.162.39.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.166.153.0 255.210.209.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.166.153.0 0.162.39.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.162.39.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd66df21f973b1c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ecb845d-8b50-42ea-9219-6ffc186a2f5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 96).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '423bb09c4aa33850_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cec0f7c-b712-4b48-a233-e63ff3ef7fe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 96).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9abdf3487c2ac210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f0255b-0039-4b9e-afcd-6624dec01985', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 96).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '36538d2ef957816b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9700466d-696b-450f-ac16-205a331bf6de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 96).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6c89b9fd0e07123f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd8da51-78ba-4c55-ae34-00cd6982cc1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 97).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9fc02cad0b9d1c39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da5c1bd-3592-4bdf-863a-5d58be949690', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 97).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0b8e82fed1e8fec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e201529-b98b-4461-bba2-0b0582fdb9a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 97).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '377c6d00e83dccb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcbf70b9-0c85-49c0-90af-7cdc23f1334c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 97).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '11ed14fc4cf94599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88352de5-183e-46bc-9a91-723800e0f5b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 97).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e96c69cba70363aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('503e8cd1-1650-47e0-b449-d2097f6f010f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 97).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f0307a54f864abc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887a0af7-5862-4601-88ea-8aac12fd98f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 97).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ccdccdb837683e91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52ad8a4c-4b0a-4eaf-af39-0db99dfe5726', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 97).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd5b2f1a53540edd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8aee2d25-6339-4356-8939-934ee8406fff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 97).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1de16724ececdaa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7583e93c-97b0-4a13-9588-d41b98f0ad8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 97).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '81712200e4475fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae1e35af-7e6e-4215-9cce-69ccbb29813c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 97).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b3b76055ecc4ad09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1204ccb0-aac1-461b-a011-ff1f1facab5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 97).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ccf5cf50330acae7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('475b8235-7225-49dd-93ad-8af59a54e8b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 97).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '99aeac64b7aaca84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d621b9f-da96-4a42-b461-96849bf22b28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 97).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9431c139606c1883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd7837ae-927e-4ed4-8ec2-299cc56ee734', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 97).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b0563b219f966a80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('335b6867-ecba-4491-a248-34bf387d027a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.1.0/24 network (variant 97).', '[{"id": "A", "text": "access-list 1 permit 10.93.213.0 0.240.229.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.93.213.0 0.240.229.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.93.213.0 255.189.125.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.93.213.0 0.240.229.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.240.229.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8aa3544ef138df78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('953c3623-d9a7-4b3c-ac9a-381ce32d208f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 97).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ddf82052f594b1a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3738057-97dd-4182-a116-4d364f0d48aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 97).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c9ff37a3aa43e3e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('423673af-47f0-4d9b-877b-3923f75e2b05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 97).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ab6a5a61394833d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b91e1ef-d3c2-4825-a573-829a4a0131c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 97).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cf96e20a29116be6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5704292e-6eaa-4195-8277-c9626eeca8d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 98).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e1d4f2f81b355672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00310a08-c160-4b2b-b4d9-056fba908489', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 98).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4b673913281a53a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2511a442-bb17-4924-a68c-810d3016e874', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 98).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a0db91336b621a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ea2107-2b93-421a-9afd-fb406ba60432', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 98).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b44c03fca3a1f7ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a97d0af3-a83b-4c52-878c-23645aeac076', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 98).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef637480933979d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e54be308-c618-4461-aa9d-e03da2751593', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 98).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3a7f2781e0e1047_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceb22e12-3bc2-4c8d-8ee4-6591152146ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 98).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2646e0235060389d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25e78cdc-d387-432b-9e52-3f8c4cdeaf9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 98).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a11087468bb0804f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('530d036e-39a2-420e-b47f-20a3eeec50f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 98).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1edd27cfe339b004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a544fbf2-c4cf-4e0f-a1f1-5b2418191e60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 98).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0cb7f482ff0cdd8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3da70420-cffa-4b1a-bb15-765435879368', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 98).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f5c32eab8173ec1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78931f6e-989e-430b-a86b-682fe66117e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 98).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '1965d486f98c85d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53cf04ce-c835-4907-838e-447138dcfea6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 98).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2d1c6fe30d6d4406_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2452c0cd-09dc-4e6f-9e8c-96d2b6afce13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 98).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd10cf6aa3b1620ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4c6721c-844f-4a57-9c8b-9c7c7c48377b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 98).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c54891a515f6d5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b8dfa50-e200-4434-aff4-92a0208fa06e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.216.222.0/24 network (variant 98).', '[{"id": "A", "text": "access-list 1 permit 10.142.110.0 0.152.188.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.142.110.0 0.152.188.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.142.110.0 0.152.188.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.142.110.0 255.29.226.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.152.188.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5c4705b1c3d3ec35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7abc55a-26cf-49ee-9c93-a581fb7456c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 98).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '230bccdd604f251c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b44111a9-80d8-42b8-b19a-9a64af5b6de0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 98).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '53b0d63a14f7cbe6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a58b7688-f877-4c23-a41e-9e8855d3e605', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 98).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b0b0ef641e496d68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9dade09-5217-46a5-b782-84f8d3ce66aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 98).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'ed72dee2f9c0cc74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('841f3e67-c6aa-4983-a86e-e69166a7ec97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 99).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd3d83b8e74c88fbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0332fc08-5f5c-4a65-bac6-7e97c7e98904', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 99).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3a5d453745b4c39e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4c32041-3bf6-4993-989d-0b9d21a6e59e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 99).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'baa1a34e145fb4e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1373f5a5-f26b-4c26-a195-ce55454f8abd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 99).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b5c1a8cb139dcb36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c9440a0-1653-499a-af67-fbb76db2d409', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 99).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6ff0858100da0842_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9d1a3ef-5ee2-4e10-bcef-97bfe4af930b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 99).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b1349d3e40a33f51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61b11fc0-dd5b-45e2-9e95-3e20af109bd7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 99).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'afb00e8841fb9123_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('943ef498-e834-4f07-9443-dd0e7821439a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 99).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9c1e855bfc95dcf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c5755e9-05a1-45dd-b039-11b6c3a55d1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 99).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd1cfcf97d6e3208e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb01c20c-2405-47be-bb75-580961d42340', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 99).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7669ac67ea3eecb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d3eedb4-22eb-4f7b-bc3a-9c095a05067c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 99).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8850fd7762840acd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('661eeaf2-38f4-489f-9bac-ffc4daa9ce6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 99).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '5c6c145b8d8864d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ac4cafa-f849-47be-b56d-b369df4ab32f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 99).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '232b4527bd7a6b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8558f082-f6d4-4789-9232-8a783ac4ccb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 99).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '68a718c7a5f45953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e635369d-b91c-442f-bff9-59a74bd59105', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 99).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '19906d5d232edd36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d9b52ea-e45d-4032-a6d1-8d9bc80a58b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.178.43.0/24 network (variant 99).', '[{"id": "A", "text": "ip access-list standard 10.200.74.0 0.219.223.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.200.74.0 255.112.159.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.200.74.0 0.219.223.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.200.74.0 0.219.223.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.219.223.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '73c5a54e95edc8f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f419d91-36de-4e4b-8018-36a523e81391', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 99).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '661038f5ac5a57d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52fffcbe-c95c-410a-9b99-db63d4e457ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 99).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '35594da4a231a58f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d9749e2-bce1-4148-a722-04d9b87e6a84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 99).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0ec921de077dc483_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f7dbab5-53e0-4a72-8dc4-e0fa817e35d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 99).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '902dfa2484fa10db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56783385-89c2-4f72-9263-836648d30e80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 100).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6a7c26392eda77f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49c4590a-abc9-49b6-9f70-ac35f3d11876', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 100).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4914b42c4708f08a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83e49b3f-e6a2-40d2-a063-4f4897517e5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 100).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5188abe05375cd31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0d5e86e-94ec-44e6-81ae-9f744fe8bc55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 100).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '46368c8a1d2360db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('068a41e6-7ca2-4df5-b5ca-ad4e8d1a87c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 100).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '881d445941495501_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('384652ce-4bf8-4893-bdff-c92c24c63c0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 100).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5e23c15714c6d57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd11b2fd-50e8-48d4-a207-8c320ba818f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 100).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f822cdc9baa25a01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9415127b-3243-4d2f-a6e4-ff40b04d62df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 100).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b664569f35d17a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4669cc67-2fcd-4d4a-b03c-e3d5f6e6e698', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 100).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '606b4a4362476e91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bed759e3-6147-4102-bfb6-d61022925158', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 100).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e2770895c5498cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95e37c82-379c-426c-a837-d3d927efee5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 100).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f54fe02bfe9fe16a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba73cd49-7049-4bd2-a48c-251b70d1c1c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 100).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b2bcee4fc5fb7f14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32bde9af-697b-43d5-96fc-8e5c4ee6eb51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 100).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd6739a94875c80db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1f2dedf-c57b-4bb2-9e49-e75c84966108', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 100).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e7e1f82db9c0b498_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b4c83b2-ef2b-4e76-aeb3-8317568b1fa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 100).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '27ae1cbb2d1db2b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5690b910-e56b-4298-af8a-b3c7e922e690', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.173.185.0/24 network (variant 100).', '[{"id": "A", "text": "access-list 1 permit 10.48.30.0 255.86.218.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.48.30.0 0.121.130.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.48.30.0 0.121.130.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.48.30.0 0.121.130.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.121.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '02d48c377da13d69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddc748b1-cad0-4c8f-babc-e743caac4dff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 100).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f599a0a44831bfe2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a10a5a6-f8a0-4f6f-9423-99f2d3250647', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 100).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '58d02a324d9e14cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f08e2ad9-ec43-44e4-b122-be39160b8fc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 100).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2d03a625d24fcf57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96b1ba79-52b3-40f1-b668-432d8f1ce101', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 100).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3cc8a29f3de606b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8bdd4cb-901e-4435-9175-bc296e94c04f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 101).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8e5b7c80ce730329_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81e4ea57-dfad-4809-8bc0-5a548c44b0e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 101).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '57a781ee24a2a7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f93f153c-dc53-4e47-96ce-5bf51fc05f6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 101).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7a1a1a94df072a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bd7468c-c13a-4e3c-894b-41e6cb424b6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 101).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c10004f751849a70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7191348-8261-42d1-8f4e-19b516f6f089', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 101).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '65828a468804e28b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('541e3269-d9fc-4e31-9daf-29031000a6b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 101).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '68ee28d75f32adad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af6bc4e5-317b-4d54-a761-114aa8a56fd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 101).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e52a5eee7e6bbe3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('835ea249-01df-4a5f-8156-9b1548227cab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 101).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd92602ad6f296a26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76ff964a-f340-4972-8659-b0751e7f3777', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 101).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '16a12ee8e49e6c60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fea6838-f20d-4944-913d-5f3a70d0ea38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 101).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '326d270cb99354a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53c7cb6c-229f-449c-abd7-a9eaff1373bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 101).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f358ceba8015df41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dca7ca1-212e-46da-b43b-655a55935ad1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 101).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '56d8ed43b2db9e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff296ffc-cdea-4997-a0e1-66067dd04603', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 101).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'db012b831d07e726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27595f43-73df-471e-924f-0cc8935ae55e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 101).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fae2b5b15037970d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('326e565c-08c9-4c77-b07e-1481cb61b244', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 101).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ba720d21ac646dd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef3d6d9f-35a2-46a2-9827-8787f999f37b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.109.103.0/24 network (variant 101).', '[{"id": "A", "text": "access-list 1 permit 10.121.72.0 255.9.95.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.121.72.0 0.26.47.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.121.72.0 0.26.47.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.121.72.0 0.26.47.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.26.47.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'bdd827847cc08f28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88156bb9-9a3c-4339-8963-06783e87ab01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 101).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '89f3b5e82ee6c24e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8e3bb41-24ee-4f52-95c8-5592c57bd102', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 101).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '24461e9434354d0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f8f5c34-ff15-40ee-a145-153e15760c8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 101).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3f69cd32d706f370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db585bf-c211-4f8a-8c4e-5194ff83885c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 101).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '48903c6edb479bd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec662bbc-7304-4ecb-9efa-8a9a8b95a959', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 102).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '09a90747ba9016b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d5b7920-a8f9-4461-a6dd-962a6d9882c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 102).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fe8d85477735b7ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d59e97c1-3949-440e-9f90-56a6317ec88e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 102).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f67010a89cc8835c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbe6d1fe-1655-4969-bfe7-25953ac24cbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 102).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ac90249f75ba1a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb539b22-3d65-4f3f-a357-c9878f476f1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 102).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '03a92b1122d51c78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed8071fb-da41-40a2-87fd-9e9b3aa0642a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 102).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6a3009934d90945c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c72096da-8940-4d4d-84f8-69e69b5f2cd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 102).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9528bce3124f3d63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b07b1b3-4e0c-44a8-aaaf-6e7d95126f22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 102).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac3bdfc91bd866e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2bc5177-a7ae-4bde-8d47-3dd28a49ad8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 102).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cc7d6836862886bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fbd82cb-a633-4d73-9d0d-3b1eb8e49d78', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 102).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '29c9d510bba07609_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb15e1f-6e69-40f4-b483-d7bedd03a71d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 102).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4b67572f92394814_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4211ab69-dbcf-41bf-a91d-9599564fba40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 102).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '9f97fcdf70ee8e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78b4474b-f40a-466a-89d6-f22647be17a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 102).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c19d2cb2a16930c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7207e33f-a4ff-49e1-b64b-78c2d1b9bb12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 102).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f57c4ea43017b095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6691e1d-12df-4afc-bfdc-58af318ec32c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 102).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4b884064a18f6308_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13703d8a-b03e-4662-a0ba-5115e2057d61', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.65.254.0/24 network (variant 102).', '[{"id": "A", "text": "access-list 100 permit ip 10.109.139.0 0.80.40.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.109.139.0 0.80.40.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.109.139.0 255.32.1.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.109.139.0 0.80.40.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.80.40.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '24ef2a40ece97361_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('361840f4-0447-4b62-adcb-b085d932ad34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 102).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cae2e98992ba8e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3733cf3-9b6c-407c-ab5c-9f3432e23675', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 102).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '507dbfcb7886afdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e44e1867-6bf8-44d2-abbb-8afbf62b608b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 102).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9bcd4b2392857056_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('071252ce-d9f6-486c-9f5c-96cc1dd53d7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 102).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8cee94ad7fdd7b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a28cda63-5c4d-4d50-bad0-3c0a56e00878', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 103).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '47400e00e76bcf3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ae4b0c-7a0e-4578-8efd-3a50aac85dc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 103).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5b114587eb8962ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e863f63e-80e5-4f47-8251-cf1f0d8e0f49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 103).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '244aca9f69042849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b5fa1f-4de0-4e3a-ab4c-9584243634a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 103).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '15768fc4ef9e51c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34def7ca-78a3-4596-9ad7-1232108159fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 103).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f63a585793156e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5792b731-6e45-45f1-9046-3a5815f3d14f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 103).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2533e1c1735b6093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54683ae3-894c-4ef0-82b1-44c89fcc9e69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 103).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '24ce93b1d807e921_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d669d1d0-3ee9-432d-8c96-f1390245c841', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 103).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4cf64258ef303237_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff09ac4-f64e-4fe3-aa26-c35b30516642', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 103).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '50a718abf9d3fd42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f6e18d0-2746-43ed-a27e-6486602210c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 103).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4e0d5f3ccef78142_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1a8674a-e3e6-4639-b1a5-1a1a323d25cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 103).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9a6cb6968c336d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df1bd92-3056-47dc-93a0-b2ee2791fcc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 103).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '287fd8c45f930f9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8a1da05-cbc3-405d-b5b6-238a280b4266', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 103).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ec2da56c4b0e775c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2af27da3-b724-4161-806c-41e9759c45f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 103).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0a3da7d52a7fe212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c377985-6227-40db-9ab9-281e082ff55e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 103).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'de529f025ec03e32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2a31874-a70e-4927-b924-33025236f78c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.177.83.0/24 network (variant 103).', '[{"id": "A", "text": "access-list 1 permit 10.167.17.0 0.47.35.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.167.17.0 0.47.35.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.167.17.0 0.47.35.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.167.17.0 255.207.21.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.47.35.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '38decc0940d7796d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b60a9c6-eeee-440f-b90e-3516f53aac74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 103).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'af28ebad5972cd0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('659e256a-cca1-44a3-975c-2c45e1526669', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 103).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '29d4a0b0573b989e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f758445-c982-4dfc-b42c-189cfe8a963d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 103).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '81bbfa6a25ab7b59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d157d319-ab43-4b7e-85b2-9014cea61ed4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 103).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '339e0fba6e56ff46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be934b5f-8609-4091-94d1-d5031c22fb12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 104).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9c25fe3ef3acab7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11cf6920-4ff4-463e-bb30-e0d9f88e0a05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 104).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0632184c2c71f1ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df538041-96ed-48f6-8d47-2628f79ea143', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 104).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a60c759b50093a9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65dc794d-885a-4dcb-884f-1a5421f6eeb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 104).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a93168de293b4769_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f5250c2-97f6-4d6a-b1ba-16376b309716', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 104).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1a0bb70c6afd0d2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93378cde-37a8-449c-a8de-b4189e102f16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 104).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dfa818df1fe398c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67855cf7-cb9b-45f1-bade-8f8879057bb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 104).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '861b166f2ad71fc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756cf3f5-d8a7-49e3-920e-1a5327c759df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 104).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a6d27c43ab56c6cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d42c65af-e73b-4232-8987-d2e0692014e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 104).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ea49c91fd765d728_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2506dfc9-97e4-424d-987a-15bb0be40859', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 104).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8ef1020670a6a115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb0f0310-213b-4bbe-a50c-084a13a11d03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 104).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '40d63c71ecce6337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3105dd6d-0ae3-494b-ac70-b3f3a6d19954', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 104).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f534c2d4f81d5ee6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5b7b840-b3d8-42ee-a65c-a34493560922', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 104).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '84f828ecc7e0be43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78913efb-1fbb-4699-b66f-392200173739', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 104).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6209a730c16bce88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23abbb3e-ac3c-4921-8969-0de4738cf90d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 104).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'efce7a29dba3717c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4be4bdcf-c9a4-4d0b-a07a-36628fd636ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.63.188.0/24 network (variant 104).', '[{"id": "A", "text": "access-list 100 permit ip 10.115.179.0 0.193.80.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.115.179.0 0.193.80.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.115.179.0 255.106.242.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.115.179.0 0.193.80.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.193.80.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2d2b34471a95c17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2d54288-59d4-43ba-a235-691a2a576aa6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 104).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '062f017de4f157f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b3b9bda-81b2-4ae9-b8a2-192c3a5f3e36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 104).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04c529a8ca236789_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a44e08e7-37cf-4c5f-b862-b3bf96feb8f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 104).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '864b30efde36316e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95a50a5e-a208-437d-88af-8a3aec20b848', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 104).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '92bc54ca07b5ec98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05745f72-774d-4ce8-b7bd-6c7e00af94b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 105).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b0a83c0abfe14c55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8791f57-8c19-4ca7-b95e-57bb9d346c83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 105).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3a05e240b2c90fd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f68336d4-f9a3-4103-850f-cad2020d9b4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 105).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6bba742e3fa80ad4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0187c34-4cc9-4401-a69c-12749f7d3d19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 105).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a96aa9c7a9122a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d54bb946-fbaf-43cd-b18b-7801a3025f79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 105).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9179a797353ad4c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60fd6d6e-d99f-488c-b5cc-5451ab2c371e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 105).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1075af6b2f67296d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b8bf90-94ca-44a9-9402-344527e2ac16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 105).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '582c17ebae73e44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5260b366-5ce0-4448-b399-5ca7ea761144', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 105).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '701d988ccace5120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e03bf6b-e289-4e15-9001-905af36976d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 105).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'faee38377a613717_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e2e245a-1add-4da3-8041-64f0cf12f832', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 105).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b8e4a8c45f613484_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c5ab5aa-c639-4a27-9e11-175912682764', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 105).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'de9aa415eb5a2d22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b0bb790-9ceb-4ffb-b89b-beed7b9de796', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 105).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '48f6377c12b0345d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d8f197d-1d62-4748-b6f1-5e820e5304cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 105).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd8edb1fb83c0fea8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47f634b2-9c3b-4a07-a3e1-ab5e0c47941f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 105).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '36f81b88cc04c99e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1c61db-0c39-4dde-9bc7-0d52d5690275', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 105).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c4ae13968eafaede_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbb5bc36-50c6-4c26-8315-d1885aa791a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.198.122.0/24 network (variant 105).', '[{"id": "A", "text": "access-list 1 permit 10.136.132.0 0.153.35.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.136.132.0 0.153.35.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.136.132.0 0.153.35.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.136.132.0 255.169.43.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.153.35.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '991b6ecf5784b2a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ab283e-fca2-4805-b2d0-d603c9b2dc48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 105).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f090815b9d5cbe21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b278492-38fa-4089-a841-a58982e5cf15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 105).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f945911b11079795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('881dc536-089c-46af-8a2c-d415a19c39a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 105).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9c5bdac12799fad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('272fe9b2-bc00-4596-89c7-3506a26a0aee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 105).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '85fb75ed504bdc34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('430a1040-5079-4a3c-b544-39a359337680', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 106).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0c2fa66f2cb6f763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e488afd-ed2c-4e06-ad96-f92e1d8ab195', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 106).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bba20717550219bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f06fa4fb-4820-49d6-bc63-1b6fa7eea1a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 106).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a7c015eb945846f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1b089ba-9048-40b2-88b1-09fab457bfba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 106).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2918934f612d45f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70a09437-de71-412b-8aa3-9ee17c2159c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 106).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '91f1549bf3f9c752_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bed39ebc-75ad-463d-8e58-c5510e610c9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 106).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4af425d2d602382_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7ca3cc2-2e15-4c40-806d-33ba58675267', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 106).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a3da7c0dc8de3139_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bfc1a70-425e-4d3a-82ac-cd4ffd5a70f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 106).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4745d163e3f326e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0f8890a-81b3-4a20-bed2-1ee2c47101f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 106).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '36e6f6db24eede00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2caffc9b-eeab-4fb2-8bdc-bd2237ccc405', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 106).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e893fe0e9a1476a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54660ac0-e8d0-40a9-97c4-8cf4093c6176', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 106).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '93e9839da889023a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a25f894b-cbcc-42a8-be9d-01a884a2c697', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 106).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fcb2fb04975ec800_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('721042fc-8a00-4cc2-ae7f-78fa7ab0fcd3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 106).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3635dddc717da55d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb3aed4c-d7df-4ee5-b100-c611d34e483d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 106).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f7b7974e3dfac727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('601a9211-f562-4407-84a2-a2f9285bdbe5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 106).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e5d02dc386f0244e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51bc8351-2a58-45d6-9ae4-7c8c16b123ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.97.6.0/24 network (variant 106).', '[{"id": "A", "text": "access-list 100 permit ip 10.239.62.0 0.250.23.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.239.62.0 255.214.50.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.239.62.0 0.250.23.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.239.62.0 0.250.23.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.250.23.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5719180e142ee88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2bf34f-64b1-457e-9c67-256f8bcda688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 106).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e4cb46bb2371c715_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82e187ab-27cb-429f-ac5b-842ba34eb885', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 106).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '503187deecdb94a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4d53fac-fc3f-4cfc-964f-43352bc2130d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 106).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7554841112020c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4814466b-5099-4623-9b61-75055b1883de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 106).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '43ab9cc5919a9c6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('400f6078-893b-47f8-805b-12bd3bbcaec3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 107).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '786c97926f703705_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52f1a981-6faf-41fe-b9e8-c1d657da8758', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 107).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '98e7a4d126b7d213_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed45db2-ac79-4ba7-a8fa-7b8db39b2c5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 107).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '318e86268ea825f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('287d0916-7664-4380-bf59-33c5488e4efd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 107).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b7e1e614e4572fa9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8c94109-9a8a-48d6-9d84-d647e79d89cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 107).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '149141a985b97746_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff3bc1a6-c86d-45ca-aad3-25283596ffe0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 107).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7a68201c45b775c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dafe90b-559c-46c0-8539-26299576c60d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 107).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a64c36654b76d9d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6db68555-f086-48bc-9edd-83db525a214e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 107).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ce2d10a497ba04dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c81a8e2c-231a-4391-a0de-8dcd7867d8f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 107).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '16f49c5b6bde8485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da85bf2a-2db3-4add-9af5-0db299a4671d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 107).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c09f92d261622133_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d15fe3-c956-4c7d-b8d7-57245882d7d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 107).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '03b6e8a528747c9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7acca7f-03b7-4116-8e22-0357717e79f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 107).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f4e3cb48a1042eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff41ab1b-964b-4dd6-bb93-2cde046840fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 107).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4bb08a236aa269fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dd7901b-8f60-4e80-95f2-b07d0714acbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 107).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1bfa0731a8e224bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46233651-096d-4b9b-b083-4faa310f0a70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 107).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7f10ad8fbf3e69d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c748b2a-2f3a-43d0-abef-ddf52f77343b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.78.127.0/24 network (variant 107).', '[{"id": "A", "text": "access-list 1 permit 10.236.95.0 255.202.69.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.236.95.0 0.1.70.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.236.95.0 0.1.70.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.236.95.0 0.1.70.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.1.70.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c54d2f9e271eaefe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14ac1cae-3069-46c1-bb32-8f52e6c3f95e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 107).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '948ed2e3147a9b78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48d2defa-5260-4c47-82e2-42d721073d2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 107).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a48d5180ca4f380f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec673488-2a05-4213-bdc7-7ef6339e119a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 107).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ae65970b4a44277c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b21eeb27-1a98-4abe-8b10-ace71f160f3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 107).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '92398c0ed8fc6e01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63095f19-5ace-4b60-93df-3b9137458cf7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 108).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '029527a9557605b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89563a2b-e2dd-452c-b2c4-dd943de5fc31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 108).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '90f4c6c48a8fed0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab56fa55-81d8-48d2-9814-3ebedd9a2914', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 108).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '80eab4ee9fa8370a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d4417b-80be-4e1f-8108-e38bc00580e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 108).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '504f1258c2bc276f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24291fd1-1136-4003-8226-0d8305c79435', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 108).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ad1a0ad582e246c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a11f874-41e5-4454-872b-5a8962c7c4ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 108).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e6b35cc6bfad1085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5926ad82-a9d7-43ff-b2c1-18f460c0649b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 108).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0b6722b5090ed8b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89945795-f83d-4e9f-adfd-4e9259bfeaf0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 108).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '151e3cc0f60c9765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c9a07b1-fae7-4aac-a903-ef866cd65d40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 108).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '93b6f6a6e82e9ded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d190869e-ce90-4b07-b3ec-415af106e140', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 108).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2603e0dfb7a69b38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de17a303-6b5b-4ec2-a5ec-376c977064ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 108).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b213672624cc2f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef1c3b5-974d-40a2-bd9c-49c3c6a961bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 108).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '77f1a743b8123827_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cd97748-cdb1-40c0-a803-2352b856016e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 108).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4fe1708f41955679_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1907206-7826-4840-86ae-6b7fc78b2a92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 108).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '69c846e4b1121eee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43e1277e-92c1-4b60-ab6d-90c62baa41a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 108).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '32c33f6fbd2187e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e9f24f-b213-4755-b960-d68c5eb77feb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.54.42.0/24 network (variant 108).', '[{"id": "A", "text": "access-list 100 permit ip 10.101.7.0 0.10.159.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.101.7.0 255.178.160.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.101.7.0 0.10.159.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.101.7.0 0.10.159.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.10.159.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '42e8de25f0829085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa14625c-91bc-422e-a408-6f545f9d93cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 108).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '04c45f10b4ce3a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f239d4-0e75-4630-869e-8d46cac50be6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 108).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3f2b130b66d2ffc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0257d7d4-b6d4-4e2d-bccf-3739bc5d10eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 108).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0052a73f8fed5ecc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fde7620-cd41-438b-ae87-a6152187ce9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 108).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'bde168b20e02654a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3bb16d-1b2d-489e-876d-2099a68159be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP?', '[{"id": "A", "text": "Confederation", "is_correct": false}, {"id": "B", "text": "Add-path", "is_correct": false}, {"id": "C", "text": "Route reflection", "is_correct": true}, {"id": "D", "text": "Multiprotocol BGP", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '9997d140f10b1e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66376d59-c3a7-4aa7-b975-fecc0e8ef789', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute?', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "C", "text": "Selecting the best path", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '99a82f100bc80f3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b26f805d-f2ab-4b38-9685-f63b34d147b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution?', '[{"id": "A", "text": "MP-BGP", "is_correct": false}, {"id": "B", "text": "SR-MPLS", "is_correct": false}, {"id": "C", "text": "LDP", "is_correct": true}, {"id": "D", "text": "RSVP-TE", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'e659a6692d2b6e24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab5949d-7079-4445-b06a-6c68ffab57de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos?', '[{"id": "A", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "B", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '8577b1356f721bb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d13037d4-5e57-4216-90c6-8b2ed25fdede', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide?', '[{"id": "A", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "B", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "C", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'e043e99faaf5cefb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daa956c0-7b70-4778-b33a-5360313f8c1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct?', '[{"id": "A", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "B", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, 'fafa7574de112528_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47172bb4-400c-447e-a196-c4ef43104fe3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO)', '[{"id": "A", "text": "RSVP", "is_correct": false}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "D", "text": "MPLS-TE", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '4cb87798365c5868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e9e7a78-d3a3-4104-beae-853cdbb34b4c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos?', '[{"id": "A", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "B", "text": "MPLS label range", "is_correct": false}, {"id": "C", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "D", "text": "BGP community 100:1", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '85d2c1e183faa922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67d12f0d-5bb7-4f58-ac41-4eba4225ab22', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection''?', '[{"id": "A", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "B", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "C", "text": "Client-to-client reflection is disabled by default", "is_correct": false}, {"id": "D", "text": "RR only reflects routes from non-clients", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '45aab0a72378d73b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2500ba43-eb6b-4367-b183-bdaa5037ab0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos?', '[{"id": "A", "text": "show ldp neighbor", "is_correct": false}, {"id": "B", "text": "show protocols ldp status", "is_correct": false}, {"id": "C", "text": "show mpls ldp session", "is_correct": false}, {"id": "D", "text": "show ldp session", "is_correct": true}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '22cc63b98e6554e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2758195-1d52-45a5-9cbc-5aef6e89412d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 2).', '[{"id": "A", "text": "Confederation", "is_correct": false}, {"id": "B", "text": "Add-path", "is_correct": false}, {"id": "C", "text": "Route reflection", "is_correct": true}, {"id": "D", "text": "Multiprotocol BGP", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'b295a99336fe3ef6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ca9e87-828c-49bd-9ebb-64bbbe78df63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 2).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Signaling MPLS labels", "is_correct": false}, {"id": "C", "text": "Selecting the best path", "is_correct": false}, {"id": "D", "text": "Influencing outbound traffic", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '1c207d5f0715ebe6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c9dc650-c10e-4e38-a66b-b67c196f1a73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 2).', '[{"id": "A", "text": "SR-MPLS", "is_correct": false}, {"id": "B", "text": "LDP", "is_correct": true}, {"id": "C", "text": "RSVP-TE", "is_correct": false}, {"id": "D", "text": "MP-BGP", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '7cf1847cbc16dbdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c32646d-a08d-4d15-9ca6-ebb2161fcc09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 2).', '[{"id": "A", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "B", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "D", "text": "set vrf CUSTOMER-1", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '72891c6d19d622a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
