INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa51846f-df21-4c48-9f61-63e9e4457f77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 7).', '[{"id": "A", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "D", "text": "FRR is only available with LDP", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '122e5c0d5e2357f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37581c2b-169d-4ed3-92b5-80d3e9043f72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 7).', '[{"id": "A", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "B", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'd45040b62341c9a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('548a6825-d32a-4540-9bc9-6c37fb7c7398', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 7).', '[{"id": "A", "text": "BGP community 100:1", "is_correct": false}, {"id": "B", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "C", "text": "MPLS label range", "is_correct": false}, {"id": "D", "text": "MSDP mesh group identifier", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '53033d672cb4d7eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ed2bfdc-c300-4356-aa0c-57b9150ad5e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 7).', '[{"id": "A", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "B", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "C", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, 'c940fa397253023a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f69c3c8f-9ea4-4c46-a537-f7de9d62a59b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 7).', '[{"id": "A", "text": "show ldp neighbor", "is_correct": false}, {"id": "B", "text": "show protocols ldp status", "is_correct": false}, {"id": "C", "text": "show mpls ldp session", "is_correct": false}, {"id": "D", "text": "show ldp session", "is_correct": true}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, 'aa7038bf4224344f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac73cac4-f8fc-42d0-b81f-b7c453c5b78a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 8).', '[{"id": "A", "text": "Add-path", "is_correct": false}, {"id": "B", "text": "Route reflection", "is_correct": true}, {"id": "C", "text": "Confederation", "is_correct": false}, {"id": "D", "text": "Multiprotocol BGP", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'dfc39873b7595d48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04031b7b-25a0-4add-899a-a6a495746bbc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 8).', '[{"id": "A", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "B", "text": "Signaling MPLS labels", "is_correct": false}, {"id": "C", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "D", "text": "Selecting the best path", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '711768217b054b49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4be689d2-082d-42c3-8b51-435320ee7966', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 8).', '[{"id": "A", "text": "SR-MPLS", "is_correct": false}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "LDP", "is_correct": true}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'b775003b1294b72d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f6e1713-d738-4bfb-9359-d1cef5a07d35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 8).', '[{"id": "A", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "B", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "C", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'ea78514684af4865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45d500af-b8aa-4136-bfca-5786edbdea6e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 8).', '[{"id": "A", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "B", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "C", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '469281f564750001_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9124de77-3bef-40c9-9758-8302d7745f2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 8).', '[{"id": "A", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "B", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "C", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "D", "text": "FRR is only available with LDP", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, 'b07652b01cd5bb9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ef7d59b-7b13-4ef1-b7e2-1edb6f3782ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 8).', '[{"id": "A", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "B", "text": "RSVP", "is_correct": false}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '81a03dea30db3337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
