INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('784061ef-a629-427a-9fc4-6982104735c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 18).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "C", "text": "Confederation", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ecf94162910fe383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13151c74-4396-4eae-8596-114573b612d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 18).', '[{"id": "A", "text": "Selecting the best path", "is_correct": false}, {"id": "B", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "C", "text": "Signaling MPLS labels", "is_correct": false}, {"id": "D", "text": "Influencing outbound traffic", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, 'a12149ff74fcf839_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e9b1a11-b2b4-4d8d-821c-770264b799e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 18).', '[{"id": "A", "text": "RSVP-TE", "is_correct": false}, {"id": "B", "text": "MP-BGP", "is_correct": false}, {"id": "C", "text": "SR-MPLS", "is_correct": false}, {"id": "D", "text": "LDP", "is_correct": true}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'caeeb31448de6276_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7829f4f6-ac59-4d64-ac41-a8a79f9c3bcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 18).', '[{"id": "A", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "B", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "C", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "D", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'a575e4412b35a502_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39b4751b-2d72-4398-90a9-e5be3633780a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 18).', '[{"id": "A", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "B", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "C", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '863dc268276ce6f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aadf5ac-535b-461e-9bc8-9b54d32ec2ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 18).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "C", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '208eb5afa02e3dbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efd7c0c8-1fcf-4500-97f5-afe5b6c4be1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 18).', '[{"id": "A", "text": "RSVP", "is_correct": false}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "D", "text": "MPLS-TE", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'e73aac2d90cd9c01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de18ec64-296b-4533-b65d-75ffd2afc041', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 18).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "C", "text": "BGP community 100:1", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '405b85854f31443b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0935a45f-0927-4bf0-bf08-5e5d30548167', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 18).', '[{"id": "A", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "B", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "C", "text": "Client-to-client reflection is disabled by default", "is_correct": false}, {"id": "D", "text": "RR reflects routes between its clients by default", "is_correct": true}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, 'c0341e595391572e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c296ef-3367-492b-95cb-55e964ef3900', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 18).', '[{"id": "A", "text": "show protocols ldp status", "is_correct": false}, {"id": "B", "text": "show ldp neighbor", "is_correct": false}, {"id": "C", "text": "show ldp session", "is_correct": true}, {"id": "D", "text": "show mpls ldp session", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, 'b133387f34cf9f29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d5f9fc8-e04f-4a65-8e8e-fd20575c03ba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 19).', '[{"id": "A", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "B", "text": "Add-path", "is_correct": false}, {"id": "C", "text": "Route reflection", "is_correct": true}, {"id": "D", "text": "Confederation", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '1271948d96273444_gen_v4', true) ON CONFLICT (id) DO NOTHING;
