INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e589c26-ac66-4c58-af99-b2ffd93388dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 87).', '[{"id": "A", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "B", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "C", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'e5219468b278a81c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('117c02a7-1c49-4892-b284-2c9691ae292b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 87).', '[{"id": "A", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "B", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "C", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '4bec1c6c972ae3aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ed57f74-d2af-4fcf-a762-5f4e84b6c320', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 87).', '[{"id": "A", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "B", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "C", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "D", "text": "FRR is only available with LDP", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '60d6914920856d26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('956b8528-f36f-4009-8473-13b69130a121', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 87).', '[{"id": "A", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "B", "text": "MPLS-TE", "is_correct": false}, {"id": "C", "text": "RSVP", "is_correct": false}, {"id": "D", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'ecee92d8cb097496_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4878131d-7563-45fe-8ae2-bad7ffa6f831', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 87).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "C", "text": "MPLS label range", "is_correct": false}, {"id": "D", "text": "BGP community 100:1", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '5886538cfc1faac2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5f37152-3144-485a-94c5-2a1da4acbe36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 87).', '[{"id": "A", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "B", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "C", "text": "Client-to-client reflection is disabled by default", "is_correct": false}, {"id": "D", "text": "RR reflects routes between its clients by default", "is_correct": true}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '5b925080dfab04fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12321ae6-c906-4dbf-9299-97fbfcb4e6d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 87).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show protocols ldp status", "is_correct": false}, {"id": "D", "text": "show ldp neighbor", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '9977845a526a0226_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a40bc548-59c4-499b-ba39-84422c7b5152', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 88).', '[{"id": "A", "text": "Add-path", "is_correct": false}, {"id": "B", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "C", "text": "Route reflection", "is_correct": true}, {"id": "D", "text": "Confederation", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '21cfecd9f0449c8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8341c0d3-6509-472b-aed1-5b606b19aeb3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 88).', '[{"id": "A", "text": "Signaling MPLS labels", "is_correct": false}, {"id": "B", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "C", "text": "Selecting the best path", "is_correct": false}, {"id": "D", "text": "Loop prevention among route reflectors", "is_correct": true}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '4c0354f7e45f02d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1e4c40-f592-40e8-89d8-f576cf9e1fc7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 88).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "SR-MPLS", "is_correct": false}, {"id": "C", "text": "RSVP-TE", "is_correct": false}, {"id": "D", "text": "MP-BGP", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '45b49d0c5c0925ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a193f859-e7ee-4a58-8d77-1fca4392eacd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 88).', '[{"id": "A", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "B", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "D", "text": "set vrf CUSTOMER-1", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '1c4e0911842bdd2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0da691e-2fff-442a-a54a-6a1ac691871f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 88).', '[{"id": "A", "text": "Defines the VRF export policy", "is_correct": false}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'ccc0a9455192f1c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
