INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ea519a3-58ca-46fd-b573-cc818bb709f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 89).', '[{"id": "A", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "B", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "C", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'dbc8de79bcae2b9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e65f91e3-bdea-44c5-9775-433eab25af2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 89).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "C", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "D", "text": "FRR is only available with LDP", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '238445620906747c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e1521eb-cb41-4b30-8189-0defadc96736', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 89).', '[{"id": "A", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "B", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "C", "text": "RSVP", "is_correct": false}, {"id": "D", "text": "MPLS-TE", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '2fd67659dd236804_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da1e42b-e41d-48dc-963b-d9de96af4d5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 89).', '[{"id": "A", "text": "BGP community 100:1", "is_correct": false}, {"id": "B", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "C", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '9e8aa5408cf67b06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc7d2f90-50ab-49b6-a084-e8139d3a74b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 89).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Client-to-client reflection is disabled by default", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Clients must peer directly with each other", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '3be20618f58c9629_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce13b590-02e2-474f-a9dd-683273635cf0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 89).', '[{"id": "A", "text": "show mpls ldp session", "is_correct": false}, {"id": "B", "text": "show ldp neighbor", "is_correct": false}, {"id": "C", "text": "show ldp session", "is_correct": true}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '059a5ae9ac97b2a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0924a684-0f52-41a6-b4eb-03c6f1e0e538', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 90).', '[{"id": "A", "text": "Add-path", "is_correct": false}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Route reflection", "is_correct": true}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ec47864443fd2c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c392f661-a085-40d7-bfc4-b7da78e73d14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 90).', '[{"id": "A", "text": "Signaling MPLS labels", "is_correct": false}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "D", "text": "Influencing outbound traffic", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '6ad0ada0b047e9b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0e5adeb-48c0-4533-9daf-927f1ce90d93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 90).', '[{"id": "A", "text": "MP-BGP", "is_correct": false}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "SR-MPLS", "is_correct": false}, {"id": "D", "text": "LDP", "is_correct": true}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'a66c8515a53afb22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b3802c1-a499-4c24-b112-97233d448aaf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 90).', '[{"id": "A", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "B", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "C", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "D", "text": "set vrf CUSTOMER-1", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '8ae3f7c6ec605fd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f0035c3-5c56-42b1-9eb0-b5ff8d9e4cc4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 90).', '[{"id": "A", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'ec6a94ee53e86711_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8ce0b68-7cef-4a48-994b-661c0ccee1b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 90).', '[{"id": "A", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "B", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR requires BGP to function", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '83a0093cbbd12c97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
