INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e22beec3-cbe1-4062-81bc-d9c365c2f095', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 95).', '[{"id": "A", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "B", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "C", "text": "MPLS label range", "is_correct": false}, {"id": "D", "text": "BGP community 100:1", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '91fceac59ef10327_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ee7d474-24f6-40ab-a14d-1fb20c126e60', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 95).', '[{"id": "A", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "B", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "C", "text": "Client-to-client reflection is disabled by default", "is_correct": false}, {"id": "D", "text": "RR only reflects routes from non-clients", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '287117ec929cd42f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ae9f43-cb27-4d4c-a03c-b95bbf2d0278', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 95).', '[{"id": "A", "text": "show ldp neighbor", "is_correct": false}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp session", "is_correct": true}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '0ef85f5d04ce9681_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f18bff0-30b8-4fda-8f25-bd7ab87ef397', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 96).', '[{"id": "A", "text": "Add-path", "is_correct": false}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Route reflection", "is_correct": true}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '8ad827288def0e92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7eeff8f-6d0b-4de7-9ec0-a53e915a2f55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 96).', '[{"id": "A", "text": "Selecting the best path", "is_correct": false}, {"id": "B", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "C", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '3ba3d11dd95f1d06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf88443c-1cbf-49b1-a8df-034c9ddbbb69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 96).', '[{"id": "A", "text": "SR-MPLS", "is_correct": false}, {"id": "B", "text": "LDP", "is_correct": true}, {"id": "C", "text": "RSVP-TE", "is_correct": false}, {"id": "D", "text": "MP-BGP", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'efc8bac665d27be2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9caaeb7c-a85a-4739-ae14-65432030f1c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 96).', '[{"id": "A", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}, {"id": "B", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "D", "text": "set vrf CUSTOMER-1", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '1e906ff136d99771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb54dbd8-09d5-456c-b7f1-194cbaabcc21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 96).', '[{"id": "A", "text": "Defines the VRF export policy", "is_correct": false}, {"id": "B", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "C", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "D", "text": "Identifies the VPN target community", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'c05a4d1edb6de002_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fef834d-bab2-497b-9cce-f158b1620233', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 96).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "C", "text": "FRR protects against node failures only", "is_correct": false}, {"id": "D", "text": "FRR requires BGP to function", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '9124a3c1272079a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f3857e-b9b2-4835-8b44-db8e38566eee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 96).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "MPLS-TE", "is_correct": false}, {"id": "C", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '9fc0611efe457e03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59c89618-3493-4595-96e1-bb43d321b0eb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 96).', '[{"id": "A", "text": "MPLS label range", "is_correct": false}, {"id": "B", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "BGP community 100:1", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '72e922c6aa3c197a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
