INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e83bde5c-0f1c-4350-9d04-655a5209d73c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 33).', '[{"id": "A", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "B", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}, {"id": "C", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "D", "text": "Adds a new BGP path to the routing table", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, '8cccd96177722cf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62dc9540-edf4-490b-9df6-4eb4490f4ff8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 34).', '[{"id": "A", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "B", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "C", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '9c266eaff93d1eb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d84bc332-ec51-4477-9feb-898cb17fc31b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 34).', '[{"id": "A", "text": "LDP between ASBRs", "is_correct": false}, {"id": "B", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "C", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "D", "text": "Static MPLS labels", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '00b1932aeada0eef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40bc6758-1d40-44eb-8a72-2cadd417ee09', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 34).', '[{"id": "A", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "B", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "C", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "D", "text": "Sets the BGP AS number globally", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'cf6d516da02aebe2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba6ffd22-7153-4c09-8b7a-36c3fe010ecd', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 34).', '[{"id": "A", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "B", "text": "MVPN is not supported in Junos", "is_correct": false}, {"id": "C", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "D", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, '23d71e6f5b73d8cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75aed490-16ea-4970-b065-9a861f0b3912', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 34).', '[{"id": "A", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "B", "text": "Identifies the node itself", "is_correct": false}, {"id": "C", "text": "Represents a prefix in the IGP", "is_correct": false}, {"id": "D", "text": "Carries MPLS EXP bits", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, 'a7cff697e22c0271_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2301e46e-02bf-4aff-a89c-fde2ea7642b2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 34).', '[{"id": "A", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "B", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "C", "text": "LDP session between ASBRs", "is_correct": false}, {"id": "D", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '6fcab8ce06faaf4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0f56854-65bb-497f-b16e-5cecfd9677c5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 34).', '[{"id": "A", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "B", "text": "Adds a new BGP path to the routing table", "is_correct": false}, {"id": "C", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "D", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, 'e525f600512199df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
