INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9770878-a855-4373-8143-8211737fa67b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 8).', '[{"id": "A", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "B", "text": "Configures IPsec VPN forwarding", "is_correct": false}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '1436df7d2fdeaf21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('690b65fe-16bb-4d72-bc55-c2e8da1da570', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 9).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "C", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "D", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '9d0b7dc6999a9c54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f82ece6-e081-461d-903b-38897a95f5c2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 9).', '[{"id": "A", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "B", "text": "Fabric link for session replication", "is_correct": true}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "A dedicated spanning-tree interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '89d52101c8bff095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a5f99b-eff0-45ca-9185-f998a4f1e752', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 9).', '[{"id": "A", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "B", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "C", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "D", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, '42f966c20c4aad4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6834098-95ed-4257-88c3-7d3af3e73042', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 9).', '[{"id": "A", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "B", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "C", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "D", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'aa27abf51e9c5132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
