INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('897f1cea-3ba8-4357-9401-fc7ff0758252', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 18).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "C", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "D", "text": "Load balancing between two independent firewalls", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'da2a30adce3c1e18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e16cd075-8c47-40df-adbd-2ef2a8d40ec8', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 18).', '[{"id": "A", "text": "Fabric link for session replication", "is_correct": true}, {"id": "B", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "C", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "D", "text": "Out-of-band management interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '675a23f8b3894925_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6f20f3-8915-4358-b0d6-8a2d2e6933fc', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 18).', '[{"id": "A", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "B", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "C", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "D", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, '62404c0d71d38bc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3625dede-86b5-4a24-8082-217f6226018e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 18).', '[{"id": "A", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "B", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "C", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "D", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '56a7c0171fa3724e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85513e36-81be-4a07-be6e-a3a4d9720e7f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 18).', '[{"id": "A", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "B", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "C", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, '9212354e981806f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
