INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('680a003c-4505-4c7e-812c-f15fd3a93638', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 27).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "C", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "D", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '638ebc7885b68fb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb4358fa-3f5b-4167-979c-d8105a73e455', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 27).', '[{"id": "A", "text": "Fabric link for session replication", "is_correct": true}, {"id": "B", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '48e0253b8425494a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c73c947d-f4e8-45b8-a07b-6ace85c166ef', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 27).', '[{"id": "A", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "B", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "C", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "D", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'c2e734bdd31ab853_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f2b0401-1f45-4033-86b0-28c1d1656bf2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 27).', '[{"id": "A", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "B", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "C", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "D", "text": "Geo-IP based blocking", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '9e33efbc2a0b366a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57eb2f46-7dd0-4b38-842f-2e64b616d2a2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 27).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "All of the above are supported", "is_correct": true}, {"id": "D", "text": "NPB (Network Packet Broker) mode", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'b2f31d2ae7beba8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
