INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49aea57c-830c-41c9-afb3-1cb98570cb46', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 45).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "C", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "D", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '2182a449e4338f8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62347c37-e053-4e70-943a-1bcf2e7ec8e2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 45).', '[{"id": "A", "text": "Fabric link for session replication", "is_correct": true}, {"id": "B", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '883643d0d605c9ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b73f2b91-34b9-4d6c-91fc-20b03e77b6d7', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 45).', '[{"id": "A", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "B", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "C", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "D", "text": "Logical grouping of security policies", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'ccaa7fda1f15a831_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a202cfb5-9d65-4cc0-9b98-b861351850de', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 45).', '[{"id": "A", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "B", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "C", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "D", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '42107dcfd534ceff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03372e53-d323-420a-96fd-b9041c78b912', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 45).', '[{"id": "A", "text": "All of the above are supported", "is_correct": true}, {"id": "B", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "C", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "D", "text": "Route mode (Layer 3)", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'a8704b978198f725_gen_v4', true) ON CONFLICT (id) DO NOTHING;
