INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14525e44-b81b-4cb8-ae1e-5b6672cbea25', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 66).', '[{"id": "A", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "B", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "Fabric link for session replication", "is_correct": true}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '13d67a78934d8e13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df89ebb0-b6f9-4922-88cc-e048a0c1f5fc', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 66).', '[{"id": "A", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "B", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "C", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "D", "text": "A logging subsystem on SRX", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'ca737f9255a5ac70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41f6ee38-de06-4345-a95d-6589bdcc9c86', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 66).', '[{"id": "A", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "D", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '015e5271e5007612_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da20943-cea6-4b5f-be53-5c370d2734aa', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 66).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "All of the above are supported", "is_correct": true}, {"id": "D", "text": "NPB (Network Packet Broker) mode", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, '84d2d0a22812e08f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cffe60b5-30ab-49ab-aac8-d9602a07ad98', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'Which SRX feature enables inter-chassis communication in an active-active cluster (variant 66).', '[{"id": "A", "text": "Spanning Tree Protocol", "is_correct": false}, {"id": "B", "text": "Chassis cluster control link for session state synchronization", "is_correct": true}, {"id": "C", "text": "LACP between cluster members", "is_correct": false}, {"id": "D", "text": "VRRP between cluster members", "is_correct": false}]', 'Active-active clustering requires the control link for IPC and fabric link for session state synchronization between the two cluster members.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster Advanced', 14.0, 'f8b890b32c061df7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb9149f9-6734-4349-a482-ac28eb4238f3', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 66).', '[{"id": "A", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "B", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "C", "text": "Configures IPsec VPN forwarding", "is_correct": false}, {"id": "D", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, 'a616d1eda2b11672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
