INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1eb2293-c94e-46d8-9813-80d76c4cfe71', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 72).', '[{"id": "A", "text": "Fabric link for session replication", "is_correct": true}, {"id": "B", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "C", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "D", "text": "Out-of-band management interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '7d9fa7ff3ec3748b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb86d09a-5223-47c7-8443-e155741355b5', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 72).', '[{"id": "A", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "B", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "C", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "D", "text": "A logging subsystem on SRX", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'dce177db30f43360_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('798325d5-1a22-4def-b8cb-79690aaa4c05', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 72).', '[{"id": "A", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "D", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '737c5760e483c6fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ed888ab-9e8e-4106-8a43-7f5630780e71', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 72).', '[{"id": "A", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "B", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "C", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, '899d22ddf5fea5ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c1a757d-129d-4c6d-bda7-1dc5e4d12cb1', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'Which SRX feature enables inter-chassis communication in an active-active cluster (variant 72).', '[{"id": "A", "text": "VRRP between cluster members", "is_correct": false}, {"id": "B", "text": "Spanning Tree Protocol", "is_correct": false}, {"id": "C", "text": "Chassis cluster control link for session state synchronization", "is_correct": true}, {"id": "D", "text": "LACP between cluster members", "is_correct": false}]', 'Active-active clustering requires the control link for IPC and fabric link for session state synchronization between the two cluster members.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster Advanced', 14.0, '0971263d1994fed3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d50f82-345d-4ac9-b13d-295d44a3f020', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 72).', '[{"id": "A", "text": "Configures IPsec VPN forwarding", "is_correct": false}, {"id": "B", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Sets routing preferences for security zones", "is_correct": false}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '52561c4a48b3750f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
