INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f67e20c4-d003-4b92-96f1-e6e82151a603', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 80).', '[{"id": "A", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "B", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Configures IPsec VPN forwarding", "is_correct": false}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '392888200b483322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb8c5e98-1e95-409a-8624-b39c2b7de973', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route)?', '[{"id": "A", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "B", "text": "Signals IP prefix routes", "is_correct": false}, {"id": "C", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "D", "text": "Carries VXLAN tunnel information", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, 'cf172f1b6e43fdf2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaabae21-6fd8-4487-be2c-3f0aec36b067', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO)', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "MAC learning", "is_correct": false}, {"id": "C", "text": "External network connectivity", "is_correct": true}, {"id": "D", "text": "DF election", "is_correct": false}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, '55ef785e301bb982_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24ed5cd0-de8d-408c-b774-9507bb8a49ce', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model?', '[{"id": "A", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "B", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "D", "text": "Only the ingress VTEP performs routing", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, 'd5c8557af6a687a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42791c2b-9f9b-4dd7-b354-89cae530962f', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode?', '[{"id": "A", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "B", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "C", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "D", "text": "CE connects to a single PE with redundant links", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '6fad2893fd96d185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b83d7b28-fcc7-423e-8ca9-00222c0f0287', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN?', '[{"id": "A", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "B", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "C", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '5f5c6af0828349ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b618276-77ff-4791-ae95-080ae35ca88b', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 2).', '[{"id": "A", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "B", "text": "Signals IP prefix routes", "is_correct": false}, {"id": "C", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "D", "text": "Carries VXLAN tunnel information", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, '384d5d74c3620933_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06653e3d-1455-444f-af5c-fed7e3b8803a', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 2).', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "DF election", "is_correct": false}, {"id": "C", "text": "External network connectivity", "is_correct": true}, {"id": "D", "text": "MAC learning", "is_correct": false}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, 'a024e6094cd767ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b8d97bc-97f9-4793-a3e6-264a6a15fd31', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 2).', '[{"id": "A", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "C", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "D", "text": "Routing is done on a central gateway", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '79038c7e81f2a501_gen_v4', true) ON CONFLICT (id) DO NOTHING;
