INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('087cb5d6-19c4-409c-b20c-fdc1f29642e8', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 21).', '[{"id": "A", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "C", "text": "Signals IP prefix routes", "is_correct": false}, {"id": "D", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, '22622d12e449a8a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c9a8b93-0969-4eb9-b9c0-a43682b96f82', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 21).', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "MAC learning", "is_correct": false}, {"id": "C", "text": "External network connectivity", "is_correct": true}, {"id": "D", "text": "DF election", "is_correct": false}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, '89dabdfc2bde4d7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a87d83c-8107-4b76-b8e4-42ef485e7b17', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 21).', '[{"id": "A", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "B", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "D", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, 'acde0094e216d69a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('525b3ec7-6a8d-4b61-9408-a2e6dd98d421', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 21).', '[{"id": "A", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "B", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "C", "text": "CE connects to a single PE with redundant links", "is_correct": false}, {"id": "D", "text": "Only one PE is active; others are standby", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, 'ff078d7a48598d6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af53a0a7-ef36-421b-b3c2-7a048a21ab74', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 21).', '[{"id": "A", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "B", "text": "LDP-based MPLS between DC gateways", "is_correct": false}, {"id": "C", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "D", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '609eff3059dde37d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
