INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df25465c-25b7-4d95-bf95-833aec23619a', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 77).', '[{"id": "A", "text": "DF election", "is_correct": false}, {"id": "B", "text": "MAC learning", "is_correct": false}, {"id": "C", "text": "External network connectivity", "is_correct": true}, {"id": "D", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, 'ea467ebe4697c30b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aba9c34a-0adf-4f74-ab36-d5607bedaa27', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 77).', '[{"id": "A", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "B", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "C", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "D", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '540a2598c30d06ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31397be6-81ab-4731-b77d-f6da68dd6520', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 77).', '[{"id": "A", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "B", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "C", "text": "CE connects to a single PE with redundant links", "is_correct": false}, {"id": "D", "text": "All traffic is duplicated to all PEs", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '9f564968cacdf230_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8723ceb7-e44d-47e7-8df4-9fb4266939b7', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 77).', '[{"id": "A", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "B", "text": "LDP-based MPLS between DC gateways", "is_correct": false}, {"id": "C", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "D", "text": "VPLS over GRE between DCs", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, 'b8bfcec03fbc6b2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
