INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98567ea-5000-4dc6-a690-b2f794fd5f5c', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 14).', '[{"id": "A", "text": "SNMP MIB walker", "is_correct": false}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "D", "text": "Syslog-ng", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'e64b6b61863c5d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c77619d-23d9-4a90-8a3a-f08a58f7b8b5', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 14).', '[{"id": "A", "text": "SNMP traps", "is_correct": false}, {"id": "B", "text": "CRON scheduler", "is_correct": false}, {"id": "C", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "D", "text": "Manual CLI monitoring", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '5e16b5c6482597b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b130fbd4-5b4b-4ecd-8edc-6f47bf241c0f', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 14).', '[{"id": "A", "text": "Displays the commit history", "is_correct": false}, {"id": "B", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "C", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "D", "text": "Checks configuration syntax only", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'b94e0ee9ceb70592_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e0fbb9d-013b-4db2-a663-f590e4af98ca', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 15).', '[{"id": "A", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, 'e9bc3b6b1258dbd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
