INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80a56dd5-64b0-4dc1-bff2-0e4279b97b42', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 23).', '[{"id": "A", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "B", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "C", "text": "A syslog collector", "is_correct": false}, {"id": "D", "text": "A physical temperature sensor on the device", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '24a084d9e64f174e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2584ddbd-24aa-40be-957e-1a1087815aba', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 23).', '[{"id": "A", "text": "Syslog-ng", "is_correct": false}, {"id": "B", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "C", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "D", "text": "SNMP MIB walker", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'b950d2b03b7fe20b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e71dee86-ca89-41d8-9d0f-49f12e4703c2', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 23).', '[{"id": "A", "text": "SNMP traps", "is_correct": false}, {"id": "B", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "C", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "D", "text": "CRON scheduler", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, 'e7b25bb8e84d64d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
