INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f37fd695-9a8b-47fc-b77a-f344931cef94', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 36).', '[{"id": "A", "text": "Syslog-ng", "is_correct": false}, {"id": "B", "text": "SNMP MIB walker", "is_correct": false}, {"id": "C", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "D", "text": "OpenConfig telemetry", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '28ea2c9ae8631a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8b600d3-f26e-49be-9b28-21dc0c0409fa', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 36).', '[{"id": "A", "text": "SNMP traps", "is_correct": false}, {"id": "B", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "C", "text": "CRON scheduler", "is_correct": false}, {"id": "D", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '8636c0e14b525133_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('271151b3-0b1e-401a-baf0-0ab89b3d60ee', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 36).', '[{"id": "A", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "B", "text": "Displays the commit history", "is_correct": false}, {"id": "C", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "D", "text": "Commits the configuration permanently", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '3a95c9c4e467b501_gen_v4', true) ON CONFLICT (id) DO NOTHING;
