INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25733ab5-7e24-4dec-b7c9-ca71c7fe4f2b', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 40).', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Displays the commit history", "is_correct": false}, {"id": "C", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "D", "text": "Commits the configuration permanently", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '744147e4abdbdb23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5d2ab0f-2a6f-49cb-baa3-3c1bf80db4aa', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 41).', '[{"id": "A", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "B", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "C", "text": "Directly push configuration to production", "is_correct": false}, {"id": "D", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '2ea62a917daca239_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f04380b-860b-4718-b127-01e1b4754894', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 41).', '[{"id": "A", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "B", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A syslog collector", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, 'b29d08d48554f4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
