INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('436bc608-d2ee-42b7-a0b9-b3da3ed39602', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 45).', '[{"id": "A", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "B", "text": "A syslog collector", "is_correct": false}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '45a7b9b54a690040_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef65055-8205-47a4-b4b3-0f7b0c51a6d4', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 45).', '[{"id": "A", "text": "SNMP MIB walker", "is_correct": false}, {"id": "B", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "C", "text": "Syslog-ng", "is_correct": false}, {"id": "D", "text": "OpenConfig telemetry", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '90e53c0162603479_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a48aa68d-07c9-4200-a583-6cadfc50236f', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 45).', '[{"id": "A", "text": "CRON scheduler", "is_correct": false}, {"id": "B", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "C", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "D", "text": "SNMP traps", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '6f376d9d5af68c3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
