INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dfae83e-485a-4b86-bce4-69508a41eddf', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 49).', '[{"id": "A", "text": "SNMP traps", "is_correct": false}, {"id": "B", "text": "CRON scheduler", "is_correct": false}, {"id": "C", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "D", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '0f79177b75a325cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a16a60e3-c701-4e7a-ba2b-c0b9f1d302d3', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 49).', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "C", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "D", "text": "Displays the commit history", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'a5d8c76bca809f79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('792dcd75-d0ce-4a3b-ae40-d6ceae81602f', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 50).', '[{"id": "A", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "B", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "C", "text": "Directly push configuration to production", "is_correct": false}, {"id": "D", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, 'c204760e029ad5f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
