INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('621b0739-e492-4d84-8442-d4a601b657c2', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 54).', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '395a7d6bc863cfad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c54895-5b1c-4ebf-8fab-23a029d15d4d', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 54).', '[{"id": "A", "text": "A syslog collector", "is_correct": false}, {"id": "B", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "C", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "D", "text": "A SNMP trap receiver", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, 'b3b6869bccd608d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f38c150-6ba7-4ddf-8898-9365ca735141', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 54).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "SNMP MIB walker", "is_correct": false}, {"id": "C", "text": "Syslog-ng", "is_correct": false}, {"id": "D", "text": "OpenConfig telemetry", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'b986f7d8b6727fde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
