INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55cb947b-16f4-4cd3-805b-462000fa93cd', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 67).', '[{"id": "A", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "B", "text": "A syslog collector", "is_correct": false}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '2dd9cb9c8770e817_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11bad634-5b74-459f-80e1-71faf3e3df64', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 67).', '[{"id": "A", "text": "Syslog-ng", "is_correct": false}, {"id": "B", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "OpenConfig telemetry", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '5fc29c5dd0f413fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f74b01-ebb9-4083-9bd3-8aa96f900e99', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 67).', '[{"id": "A", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "B", "text": "SNMP traps", "is_correct": false}, {"id": "C", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "D", "text": "CRON scheduler", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '08888188db80db55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
