INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7cfd7f4-bedb-42eb-ace0-0635a83a3365', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 80).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "Syslog-ng", "is_correct": false}, {"id": "C", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "D", "text": "SNMP MIB walker", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'c7a1ea2835c3e0b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dee710f3-1850-4e79-b446-f81eeece897f', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 80).', '[{"id": "A", "text": "CRON scheduler", "is_correct": false}, {"id": "B", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "C", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "D", "text": "SNMP traps", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '830b2ef051ecb5e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8025d4df-ca52-4222-8543-b6cadead26ec', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 80).', '[{"id": "A", "text": "Displays the commit history", "is_correct": false}, {"id": "B", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "C", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "D", "text": "Commits the configuration permanently", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '9ee147146bbf4ad5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
